// Contenido original de los 20 cursos de Fluent (generado desde content/uNN.json).
window.COURSES=[{"id":1,"title_es":"Saludos y presentaciones","title_en":"Greetings and introductions","level":"A1","goal_es":"Al terminar podrás saludar, despedirte, decir tu nombre, deletrearlo y hablar con cortesía.","lessons":[{"id":"1-1","title_es":"Hola y adiós","words":[{"en":"hello","es":"hola","pos":"interj","ex_en":"Hello, Ana.","ex_es":"Hola, Ana."},{"en":"hi","es":"hola (informal)","pos":"interj","ex_en":"Hi, Tom!","ex_es":"¡Hola, Tom!"},{"en":"goodbye","es":"adiós","pos":"interj","ex_en":"Goodbye, Carlos.","ex_es":"Adiós, Carlos."},{"en":"bye","es":"adiós, bye (informal)","pos":"interj","ex_en":"Bye, Sara!","ex_es":"¡Bye, Sara!"},{"en":"good morning","es":"buenos días","pos":"phrase","ex_en":"Good morning, Luis.","ex_es":"Buenos días, Luis."},{"en":"good afternoon","es":"buenas tardes","pos":"phrase","ex_en":"Good afternoon, Emma.","ex_es":"Buenas tardes, Emma."},{"en":"good night","es":"buenas noches (al despedirse)","pos":"phrase","ex_en":"Good night, Mom.","ex_es":"Buenas noches, mamá."},{"en":"see you later","es":"nos vemos luego","pos":"phrase","ex_en":"Bye, Tom. See you later!","ex_es":"Adiós, Tom. ¡Nos vemos luego!"}],"sentences":[{"en":"Hello, Luis!","es":"¡Hola, Luis!"},{"en":"Hi, good morning!","es":"¡Hola, buenos días!"},{"en":"Good afternoon, Ana.","es":"Buenas tardes, Ana."},{"en":"Goodbye, Carlos. Good night!","es":"Adiós, Carlos. ¡Buenas noches!"},{"en":"Bye, Emma! See you later.","es":"¡Adiós, Emma! Nos vemos luego."}],"tip_es":"Good night solo se usa para despedirse o antes de dormir. Si llegas a un lugar en la noche, saluda con good evening. Hi y bye son informales, perfectos con amigos."},{"id":"1-2","title_es":"¿Cómo te llamas?","words":[{"en":"name","es":"nombre","pos":"noun","ex_en":"My name is Luis.","ex_es":"Me llamo Luis."},{"en":"my","es":"mi","pos":"pron","ex_en":"My name is Sara.","ex_es":"Mi nombre es Sara."},{"en":"I","es":"yo","pos":"pron","ex_en":"I am Tom.","ex_es":"Yo soy Tom."},{"en":"I'm","es":"yo soy, yo estoy","pos":"phrase","ex_en":"I'm Carlos.","ex_es":"Soy Carlos."},{"en":"you","es":"tú, usted","pos":"pron","ex_en":"And you?","ex_es":"¿Y tú?"},{"en":"what","es":"qué, cuál","pos":"pron","ex_en":"What is your name?","ex_es":"¿Cuál es tu nombre?"},{"en":"nice to meet you","es":"mucho gusto","pos":"phrase","ex_en":"Nice to meet you, Ana.","ex_es":"Mucho gusto, Ana."},{"en":"too","es":"también","pos":"adv","ex_en":"I'm Ana too!","ex_es":"¡Yo también soy Ana!"}],"sentences":[{"en":"Hi, I'm Carlos.","es":"Hola, soy Carlos."},{"en":"My name is Sara.","es":"Me llamo Sara."},{"en":"What's your name?","es":"¿Cómo te llamas?"},{"en":"I'm Luis. And you?","es":"Soy Luis. ¿Y tú?"},{"en":"Nice to meet you too, Emma.","es":"Igualmente, Emma. Mucho gusto."}],"tip_es":"I'm es la forma corta de I am y es la más común al hablar. En inglés nunca se omite el sujeto: se dice I'm Carlos, no solo am Carlos. Además, I (yo) siempre se escribe con mayúscula."},{"id":"1-3","title_es":"¿Cómo estás?","words":[{"en":"how are you","es":"cómo estás","pos":"phrase","ex_en":"Hi, Ana! How are you?","ex_es":"¡Hola, Ana! ¿Cómo estás?"},{"en":"fine","es":"bien","pos":"adj","ex_en":"I'm fine.","ex_es":"Estoy bien."},{"en":"good","es":"bien, bueno","pos":"adj","ex_en":"I'm good. And you?","ex_es":"Estoy bien. ¿Y tú?"},{"en":"great","es":"muy bien, excelente","pos":"adj","ex_en":"I'm great!","ex_es":"¡Estoy muy bien!"},{"en":"okay","es":"bien, normal","pos":"adj","ex_en":"I'm okay.","ex_es":"Estoy bien, normal."},{"en":"not bad","es":"nada mal","pos":"phrase","ex_en":"Not bad. And you?","ex_es":"Nada mal. ¿Y tú?"},{"en":"tired","es":"cansado, cansada","pos":"adj","ex_en":"I'm tired.","ex_es":"Estoy cansado."},{"en":"very","es":"muy","pos":"adv","ex_en":"I'm very tired.","ex_es":"Estoy muy cansada."}],"sentences":[{"en":"Good morning! How are you?","es":"¡Buenos días! ¿Cómo estás?"},{"en":"I'm fine. And you?","es":"Estoy bien. ¿Y tú?"},{"en":"I'm great, Luis!","es":"¡Estoy muy bien, Luis!"},{"en":"Not bad. I'm very tired.","es":"Nada mal. Estoy muy cansado."},{"en":"Hi, Tom! I'm good. How are you?","es":"¡Hola, Tom! Estoy bien. ¿Cómo estás?"}],"tip_es":"I'm sirve para soy y para estoy: I'm Ana (soy Ana), I'm tired (estoy cansada). Los adjetivos en inglés no cambian por género, así que tired es igual para hombre o mujer."},{"id":"1-4","title_es":"El alfabeto y deletrear","words":[{"en":"letter","es":"letra","pos":"noun","ex_en":"What letter is it?","ex_es":"¿Qué letra es?"},{"en":"alphabet","es":"abecedario, alfabeto","pos":"noun","ex_en":"The English alphabet has 26 letters.","ex_es":"El alfabeto inglés tiene 26 letras."},{"en":"spell","es":"deletrear","pos":"verb","ex_en":"How do you spell it?","ex_es":"¿Cómo se escribe?"},{"en":"first name","es":"nombre (de pila)","pos":"phrase","ex_en":"My first name is Laura.","ex_es":"Mi nombre es Laura."},{"en":"last name","es":"apellido","pos":"phrase","ex_en":"My last name is Ruiz.","ex_es":"Mi apellido es Ruiz."},{"en":"again","es":"otra vez, de nuevo","pos":"adv","ex_en":"Spell it again.","ex_es":"Deletréalo otra vez."},{"en":"slowly","es":"despacio","pos":"adv","ex_en":"Spell your name slowly.","ex_es":"Deletrea tu nombre despacio."},{"en":"repeat","es":"repetir","pos":"verb","ex_en":"Repeat the letter.","ex_es":"Repite la letra."}],"sentences":[{"en":"What's your last name?","es":"¿Cuál es tu apellido?"},{"en":"My last name is Ruiz. R, U, I, Z.","es":"Mi apellido es Ruiz. R, U, I, Z."},{"en":"How do you spell your first name?","es":"¿Cómo se escribe tu nombre?"},{"en":"Is it B or V?","es":"¿Es B o V?"},{"en":"Repeat it again slowly.","es":"Repítelo otra vez, despacio."}],"tip_es":"Ojo con las vocales: en inglés la A se dice ei, la E se dice i y la I se dice ai. Son las letras que más confunden al deletrear, así que practica tu nombre con ellas."},{"id":"1-5","title_es":"Por favor y gracias","words":[{"en":"please","es":"por favor","pos":"adv","ex_en":"Slowly, please.","ex_es":"Despacio, por favor."},{"en":"thank you","es":"gracias","pos":"phrase","ex_en":"Thank you, Ana.","ex_es":"Gracias, Ana."},{"en":"thanks","es":"gracias (informal)","pos":"interj","ex_en":"Thanks, Tom!","ex_es":"¡Gracias, Tom!"},{"en":"you're welcome","es":"de nada","pos":"phrase","ex_en":"You're welcome, Luis.","ex_es":"De nada, Luis."},{"en":"excuse me","es":"disculpe, con permiso","pos":"phrase","ex_en":"Excuse me, what's your name?","ex_es":"Disculpe, ¿cómo se llama?"},{"en":"sorry","es":"perdón, lo siento","pos":"interj","ex_en":"Sorry, Emma!","ex_es":"¡Perdón, Emma!"},{"en":"no problem","es":"no hay problema","pos":"phrase","ex_en":"No problem, Carlos.","ex_es":"No hay problema, Carlos."},{"en":"of course","es":"claro, por supuesto","pos":"phrase","ex_en":"Of course, Sara.","ex_es":"Claro, Sara."}],"sentences":[{"en":"Thank you very much, Emma!","es":"¡Muchas gracias, Emma!"},{"en":"Excuse me, how do you spell it?","es":"Disculpe, ¿cómo se escribe?"},{"en":"Sorry, repeat it slowly, please.","es":"Perdón, repítalo despacio, por favor."},{"en":"No problem. You're welcome.","es":"No hay problema. De nada."},{"en":"Thanks, Carlos. See you later!","es":"Gracias, Carlos. ¡Nos vemos luego!"}],"tip_es":"Usa excuse me antes de interrumpir o pedir algo, como disculpe. Usa sorry después de un error, como perdón. Si no escuchaste bien, di Sorry? con tono de pregunta."},{"id":"1-6","title_es":"Conocer gente","words":[{"en":"friend","es":"amigo, amiga","pos":"noun","ex_en":"Tom is my friend.","ex_es":"Tom es mi amigo."},{"en":"teacher","es":"maestro, maestra","pos":"noun","ex_en":"Ana is my teacher.","ex_es":"Ana es mi maestra."},{"en":"student","es":"estudiante, alumno","pos":"noun","ex_en":"I'm a student.","ex_es":"Soy estudiante."},{"en":"Mr.","es":"señor (Sr.)","pos":"noun","ex_en":"Good morning, Mr. Brown.","ex_es":"Buenos días, señor Brown."},{"en":"Mrs.","es":"señora (Sra.)","pos":"noun","ex_en":"Thank you, Mrs. Clark.","ex_es":"Gracias, señora Clark."},{"en":"this is","es":"este es, esta es","pos":"phrase","ex_en":"This is my friend Luis.","ex_es":"Él es mi amigo Luis."},{"en":"yes","es":"sí","pos":"adv","ex_en":"Yes, I'm Sara.","ex_es":"Sí, soy Sara."},{"en":"no","es":"no","pos":"adv","ex_en":"No, I'm Emma.","ex_es":"No, soy Emma."}],"sentences":[{"en":"This is my friend Carlos.","es":"Él es mi amigo Carlos."},{"en":"Are you a student? Yes.","es":"¿Eres estudiante? Sí."},{"en":"No, I'm a teacher.","es":"No, soy maestra."},{"en":"Good morning, Mrs. Clark. How are you?","es":"Buenos días, señora Clark. ¿Cómo está?"},{"en":"Mr. Brown, this is my friend Ana.","es":"Señor Brown, le presento a mi amiga Ana."}],"tip_es":"En inglés se pone a antes de una profesión: I'm a student, I'm a teacher. En español decimos soy estudiante sin artículo, pero en inglés no se puede quitar."},{"id":"1-7","title_es":"¿Cómo te sientes?","words":[{"en":"happy","es":"feliz, contento","pos":"adj","ex_en":"I'm very happy!","ex_es":"¡Estoy muy feliz!"},{"en":"sad","es":"triste","pos":"adj","ex_en":"Are you sad, Luis?","ex_es":"¿Estás triste, Luis?"},{"en":"sick","es":"enfermo, enferma","pos":"adj","ex_en":"Sorry, I'm sick.","ex_es":"Perdón, estoy enferma."},{"en":"hungry","es":"con hambre","pos":"adj","ex_en":"I'm hungry.","ex_es":"Tengo hambre."},{"en":"thirsty","es":"con sed","pos":"adj","ex_en":"Are you thirsty?","ex_es":"¿Tienes sed?"},{"en":"busy","es":"ocupado, ocupada","pos":"adj","ex_en":"I'm busy, sorry.","ex_es":"Estoy ocupado, perdón."},{"en":"bored","es":"aburrido, aburrida","pos":"adj","ex_en":"I'm bored.","ex_es":"Estoy aburrida."},{"en":"excited","es":"emocionado, emocionada","pos":"adj","ex_en":"I'm very excited!","ex_es":"¡Estoy muy emocionado!"}],"sentences":[{"en":"Hi, Ana! Are you happy?","es":"¡Hola, Ana! ¿Estás contenta?"},{"en":"I'm not sad, I'm tired.","es":"No estoy triste, estoy cansado."},{"en":"Are you sick? No, I'm fine.","es":"¿Estás enfermo? No, estoy bien."},{"en":"Sorry, I'm very busy.","es":"Perdón, estoy muy ocupada."},{"en":"I'm hungry and thirsty. And you?","es":"Tengo hambre y sed. ¿Y tú?"}],"tip_es":"En español decimos tengo hambre y tengo sed, pero en inglés se usa el verbo to be. Se dice I'm hungry, nunca I have hungry."},{"id":"1-8","title_es":"Frases para la clase","words":[{"en":"understand","es":"entender","pos":"verb","ex_en":"I don't understand.","ex_es":"No entiendo."},{"en":"know","es":"saber, conocer","pos":"verb","ex_en":"I don't know.","ex_es":"No sé."},{"en":"question","es":"pregunta","pos":"noun","ex_en":"I have a question.","ex_es":"Tengo una pregunta."},{"en":"answer","es":"respuesta","pos":"noun","ex_en":"What's the answer?","ex_es":"¿Cuál es la respuesta?"},{"en":"word","es":"palabra","pos":"noun","ex_en":"Spell the word, please.","ex_es":"Deletrea la palabra, por favor."},{"en":"mean","es":"significar, querer decir","pos":"verb","ex_en":"What does tired mean?","ex_es":"¿Qué significa tired?"},{"en":"English","es":"inglés","pos":"noun","ex_en":"Do you speak English?","ex_es":"¿Hablas inglés?"},{"en":"Spanish","es":"español","pos":"noun","ex_en":"I speak Spanish.","ex_es":"Hablo español."}],"sentences":[{"en":"Sorry, I don't understand.","es":"Perdón, no entiendo."},{"en":"What does this word mean?","es":"¿Qué significa esta palabra?"},{"en":"How do you say gracias in English?","es":"¿Cómo se dice gracias en inglés?"},{"en":"Excuse me, teacher. I have a question.","es":"Disculpe, maestra. Tengo una pregunta."},{"en":"I don't know the answer. Repeat, please.","es":"No sé la respuesta. Repita, por favor."}],"tip_es":"I don't understand significa no entiendo y I don't know significa no sé. Para preguntar qué significa una palabra di What does tired mean? Los idiomas siempre llevan mayúscula en inglés, como English y Spanish."},{"id":"1-9","title_es":"Saludos formales e informales","words":[{"en":"what's up","es":"qué onda","pos":"phrase","ex_en":"Hey, Tom! What's up?","ex_es":"¡Oye, Tom! ¿Qué onda?"},{"en":"how's it going","es":"cómo te va","pos":"phrase","ex_en":"Hi, Ana! How's it going?","ex_es":"¡Hola, Ana! ¿Cómo te va?"},{"en":"good evening","es":"buenas noches (al llegar)","pos":"phrase","ex_en":"Good evening, Mrs. Clark.","ex_es":"Buenas noches, señora Clark."},{"en":"welcome","es":"bienvenido, bienvenida","pos":"interj","ex_en":"Welcome, Carlos!","ex_es":"¡Bienvenido, Carlos!"},{"en":"take care","es":"cuídate","pos":"phrase","ex_en":"Bye, Luis. Take care!","ex_es":"Adiós, Luis. ¡Cuídate!"},{"en":"have a nice day","es":"que tengas un buen día","pos":"phrase","ex_en":"Thanks! Have a nice day.","ex_es":"¡Gracias! Que tengas un buen día."},{"en":"see you tomorrow","es":"nos vemos mañana","pos":"phrase","ex_en":"Good night! See you tomorrow.","ex_es":"¡Buenas noches! Nos vemos mañana."},{"en":"nice to see you","es":"qué gusto verte","pos":"phrase","ex_en":"Nice to see you again, Emma!","ex_es":"¡Qué gusto verte otra vez, Emma!"}],"sentences":[{"en":"Hey, Luis! What's up?","es":"¡Oye, Luis! ¿Qué onda?"},{"en":"Good evening, Mr. Brown. Welcome!","es":"Buenas noches, señor Brown. ¡Bienvenido!"},{"en":"How's it going, Sara? Not bad, thanks.","es":"¿Cómo te va, Sara? Nada mal, gracias."},{"en":"Nice to see you too, Carlos.","es":"Qué gusto verte también, Carlos."},{"en":"Thank you, Mrs. Clark. Have a nice day!","es":"Gracias, señora Clark. ¡Que tenga un buen día!"}],"tip_es":"What's up y how's it going son muy informales, úsalos con amigos. Con tu jefe o una persona mayor usa good morning o how are you. Nice to meet you es para la primera vez y nice to see you es para alguien que ya conoces."},{"id":"1-10","title_es":"En la vida real, tu primer día","words":[{"en":"classmate","es":"compañero de clase, compañera de clase","pos":"noun","ex_en":"Ana is my classmate.","ex_es":"Ana es mi compañera de clase."},{"en":"coworker","es":"compañero de trabajo, compañera de trabajo","pos":"noun","ex_en":"This is my coworker, Tom.","ex_es":"Él es mi compañero de trabajo, Tom."},{"en":"boss","es":"jefe, jefa","pos":"noun","ex_en":"Mrs. Clark is my boss.","ex_es":"La señora Clark es mi jefa."},{"en":"everyone","es":"todos, todas","pos":"pron","ex_en":"Good morning, everyone!","ex_es":"¡Buenos días a todos!"},{"en":"here","es":"aquí","pos":"adv","ex_en":"I'm here, teacher!","ex_es":"¡Aquí estoy, maestra!"},{"en":"meet","es":"conocer (a alguien)","pos":"verb","ex_en":"Come and meet my boss.","ex_es":"Ven a conocer a mi jefe."},{"en":"call","es":"llamar, decirle a alguien","pos":"verb","ex_en":"Call me Lupita, please.","ex_es":"Dime Lupita, por favor."},{"en":"sure","es":"claro, seguro","pos":"adv","ex_en":"Can you spell it? Sure!","ex_es":"¿Lo puedes deletrear? ¡Claro!"}],"sentences":[{"en":"Good morning, everyone. My name is Carlos Ruiz.","es":"Buenos días a todos. Me llamo Carlos Ruiz."},{"en":"I'm your new classmate. Call me Charlie.","es":"Soy su nuevo compañero. Díganme Charlie."},{"en":"Mrs. Clark, this is my coworker Ana.","es":"Señora Clark, ella es mi compañera de trabajo Ana."},{"en":"Excuse me, how do you spell your last name?","es":"Disculpe, ¿cómo se deletrea su apellido?"},{"en":"Sure! R, U, I, Z. Nice to meet you.","es":"¡Claro! R, U, I, Z. Mucho gusto."}],"tip_es":"En inglés es muy común presentarse con un nombre corto o apodo, por ejemplo Call me Charlie. Para saludar a un grupo agrega everyone, como Hi, everyone o Good morning, everyone."}],"dialogue":{"title_es":"El primer día de clase","setting_es":"Es tu primer día en la clase de inglés y una compañera te saluda.","lines":[{"who":"A","en":"Hi! Good morning. I'm Emma.","es":"¡Hola! Buenos días. Soy Emma."},{"who":"B","en":"Hello, Emma. My name is Carlos.","es":"Hola, Emma. Me llamo Carlos."},{"who":"A","en":"Nice to meet you, Carlos. How are you?","es":"Mucho gusto, Carlos. ¿Cómo estás?"},{"who":"B","en":"I'm fine, thanks. And you?","es":"Estoy bien, gracias. ¿Y tú?"},{"who":"A","en":"I'm great! What's your last name?","es":"¡Muy bien! ¿Cuál es tu apellido?"},{"who":"B","en":"Ruiz. R, U, I, Z.","es":"Ruiz. R, U, I, Z."},{"who":"A","en":"Sorry? Spell it slowly, please.","es":"¿Perdón? Deletréalo despacio, por favor."},{"who":"B","en":"Of course. R, U, I, Z.","es":"Claro. R, U, I, Z."},{"who":"A","en":"Thank you! Are you a student?","es":"¡Gracias! ¿Eres estudiante?"},{"who":"B","en":"Yes, I am. See you later, Emma!","es":"Sí. ¡Nos vemos luego, Emma!"}]}},{"id":2,"title_es":"Números, edad y datos personales","title_en":"Numbers and personal information","level":"A1","goal_es":"Al terminar podrás contar hasta 100, decir tu edad, tu teléfono, tu correo y de dónde eres, usando el verbo to be.","lessons":[{"id":"2-1","title_es":"Del cero al siete","words":[{"en":"zero","es":"cero","pos":"num","ex_en":"The number is zero.","ex_es":"El número es cero."},{"en":"one","es":"uno","pos":"num","ex_en":"One coffee, please.","ex_es":"Un café, por favor."},{"en":"two","es":"dos","pos":"num","ex_en":"Two, please.","ex_es":"Dos, por favor."},{"en":"three","es":"tres","pos":"num","ex_en":"Number three, please.","ex_es":"El número tres, por favor."},{"en":"four","es":"cuatro","pos":"num","ex_en":"My name has four letters.","ex_es":"Mi nombre tiene cuatro letras."},{"en":"five","es":"cinco","pos":"num","ex_en":"Five, four, three, two, one!","ex_es":"¡Cinco, cuatro, tres, dos, uno!"},{"en":"six","es":"seis","pos":"num","ex_en":"Lesson six is easy.","ex_es":"La lección seis es fácil."},{"en":"seven","es":"siete","pos":"num","ex_en":"Seven is my number.","ex_es":"El siete es mi número."}],"sentences":[{"en":"One, two, three, four, five.","es":"Uno, dos, tres, cuatro, cinco."},{"en":"Number seven, please.","es":"El número siete, por favor."},{"en":"Is it six or seven?","es":"¿Es seis o siete?"},{"en":"It's zero, not six.","es":"Es cero, no seis."},{"en":"Two, three, or four?","es":"¿Dos, tres o cuatro?"}],"tip_es":"Para decir three pon la punta de la lengua entre los dientes y sopla suave, no digas tri. En números de teléfono el cero muchas veces se dice o, como la letra: 502 se dice five, o, two."},{"id":"2-2","title_es":"Del ocho al veinte","words":[{"en":"eight","es":"ocho","pos":"num","ex_en":"My number is eight.","ex_es":"Mi número es el ocho."},{"en":"nine","es":"nueve","pos":"num","ex_en":"Lesson nine, please.","ex_es":"Lección nueve, por favor."},{"en":"ten","es":"diez","pos":"num","ex_en":"I have ten friends.","ex_es":"Tengo diez amigos."},{"en":"eleven","es":"once","pos":"num","ex_en":"Eleven is a good number.","ex_es":"El once es un buen número."},{"en":"twelve","es":"doce","pos":"num","ex_en":"I'm twelve.","ex_es":"Tengo doce años."},{"en":"thirteen","es":"trece","pos":"num","ex_en":"Thirteen, not thirty.","ex_es":"Trece, no treinta."},{"en":"fifteen","es":"quince","pos":"num","ex_en":"Ana is fifteen.","ex_es":"Ana tiene quince años."},{"en":"twenty","es":"veinte","pos":"num","ex_en":"Twenty letters? No, twenty-six!","ex_es":"¿Veinte letras? ¡No, veintiséis!"}],"sentences":[{"en":"Eight, nine, ten, eleven, twelve.","es":"Ocho, nueve, diez, once, doce."},{"en":"Is it thirteen or fifteen?","es":"¿Es trece o quince?"},{"en":"I'm fifteen. And you?","es":"Tengo quince años. ¿Y tú?"},{"en":"Sixteen, seventeen, eighteen, nineteen, twenty!","es":"¡Dieciséis, diecisiete, dieciocho, diecinueve, veinte!"},{"en":"The number is eleven, not seven.","es":"El número es once, no siete."}],"tip_es":"Del 13 al 19 los números terminan en teen: thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen. Ojo, se dice fifteen y no fiveteen, y thirteen y no threeteen."},{"id":"2-3","title_es":"Las decenas hasta el cien","words":[{"en":"thirty","es":"treinta","pos":"num","ex_en":"I'm thirty years old.","ex_es":"Tengo treinta años."},{"en":"forty","es":"cuarenta","pos":"num","ex_en":"My teacher is forty.","ex_es":"Mi maestro tiene cuarenta años."},{"en":"fifty","es":"cincuenta","pos":"num","ex_en":"Mr. Brown is fifty.","ex_es":"El señor Brown tiene cincuenta años."},{"en":"sixty","es":"sesenta","pos":"num","ex_en":"Sixty is not old!","ex_es":"¡Sesenta no es ser viejo!"},{"en":"seventy","es":"setenta","pos":"num","ex_en":"Mrs. Clark is seventy.","ex_es":"La señora Clark tiene setenta años."},{"en":"eighty","es":"ochenta","pos":"num","ex_en":"Eighty, not eighteen.","ex_es":"Ochenta, no dieciocho."},{"en":"ninety","es":"noventa","pos":"num","ex_en":"Ninety, ninety-one, ninety-two.","ex_es":"Noventa, noventa y uno, noventa y dos."},{"en":"one hundred","es":"cien","pos":"num","ex_en":"From one to one hundred.","ex_es":"Del uno al cien."}],"sentences":[{"en":"Twenty-one, twenty-two, twenty-three.","es":"Veintiuno, veintidós, veintitrés."},{"en":"Is it forty or fourteen?","es":"¿Es cuarenta o catorce?"},{"en":"Mr. Brown is fifty-five.","es":"El señor Brown tiene cincuenta y cinco años."},{"en":"I'm thirty-seven. And you?","es":"Tengo treinta y siete años. ¿Y tú?"},{"en":"Ninety-eight, ninety-nine, one hundred!","es":"¡Noventa y ocho, noventa y nueve, cien!"}],"tip_es":"Para formar números como 21 o 99 se unen las dos palabras con un guion: twenty-one, ninety-nine. Fíjate en la fuerza de la voz: thirTEEN lleva el acento al final y THIRty al inicio, así no los confundes."},{"id":"2-4","title_es":"El verbo to be","words":[{"en":"he","es":"él","pos":"pron","ex_en":"He is my friend.","ex_es":"Él es mi amigo."},{"en":"she","es":"ella","pos":"pron","ex_en":"She is a teacher.","ex_es":"Ella es maestra."},{"en":"it","es":"eso (para cosas y animales)","pos":"pron","ex_en":"Is it seven? Yes, it is.","ex_es":"¿Es el siete? Sí."},{"en":"we","es":"nosotros, nosotras","pos":"pron","ex_en":"We are students.","ex_es":"Somos estudiantes."},{"en":"they","es":"ellos, ellas","pos":"pron","ex_en":"They are my friends.","ex_es":"Ellos son mis amigos."},{"en":"is","es":"es, está","pos":"verb","ex_en":"Luis is tired.","ex_es":"Luis está cansado."},{"en":"are","es":"eres, son, están","pos":"verb","ex_en":"Are you okay?","ex_es":"¿Estás bien?"},{"en":"not","es":"no","pos":"adv","ex_en":"I'm not tired.","ex_es":"No estoy cansado."}],"sentences":[{"en":"He's my friend Tom.","es":"Él es mi amigo Tom."},{"en":"She's a teacher, not a student.","es":"Ella es maestra, no estudiante."},{"en":"We're students. Are you a teacher?","es":"Somos estudiantes. ¿Tú eres maestro?"},{"en":"They aren't tired. They're great!","es":"No están cansados. ¡Están muy bien!"},{"en":"What is it? It's a number.","es":"¿Qué es? Es un número."}],"tip_es":"Formas cortas: he's, she's, it's, we're, they're. Para negar agrega not: he isn't, we aren't. En inglés nunca se omite el sujeto, así que es maestra se dice she's a teacher."},{"id":"2-5","title_es":"Edad, teléfono y correo","words":[{"en":"how old","es":"qué edad, cuántos años","pos":"phrase","ex_en":"How old are you?","ex_es":"¿Cuántos años tienes?"},{"en":"years old","es":"años (de edad)","pos":"phrase","ex_en":"I'm twenty years old.","ex_es":"Tengo veinte años."},{"en":"age","es":"edad","pos":"noun","ex_en":"Age: thirty-two.","ex_es":"Edad: treinta y dos."},{"en":"phone number","es":"número de teléfono","pos":"phrase","ex_en":"What's your phone number?","ex_es":"¿Cuál es tu número de teléfono?"},{"en":"cell phone","es":"celular","pos":"noun","ex_en":"Is this your cell phone?","ex_es":"¿Este es tu celular?"},{"en":"email","es":"correo electrónico","pos":"noun","ex_en":"What's your email?","ex_es":"¿Cuál es tu correo?"},{"en":"address","es":"dirección","pos":"noun","ex_en":"My address is forty Oak Street.","ex_es":"Mi dirección es calle Oak número cuarenta."},{"en":"birthday","es":"cumpleaños","pos":"noun","ex_en":"Today is my birthday!","ex_es":"¡Hoy es mi cumpleaños!"}],"sentences":[{"en":"How old are you? I'm nineteen.","es":"¿Cuántos años tienes? Tengo diecinueve."},{"en":"She's twenty-four years old.","es":"Ella tiene veinticuatro años."},{"en":"What's your cell phone number?","es":"¿Cuál es tu número de celular?"},{"en":"It's five, five, five, eight, one, zero.","es":"Es cinco, cinco, cinco, ocho, uno, cero."},{"en":"My email is ana at fluent dot com.","es":"Mi correo es ana arroba fluent punto com."}],"tip_es":"Para decir tu edad se usa to be, no tener: I'm 20 o I'm 20 years old, nunca I have 20 years. Al dictar un correo, la arroba se dice at y el punto se dice dot."},{"id":"2-6","title_es":"¿De dónde eres?","words":[{"en":"where","es":"dónde","pos":"adv","ex_en":"Where is Tom?","ex_es":"¿Dónde está Tom?"},{"en":"from","es":"de (origen)","pos":"prep","ex_en":"I'm from Puebla.","ex_es":"Soy de Puebla."},{"en":"country","es":"país","pos":"noun","ex_en":"Mexico is a big country.","ex_es":"México es un país grande."},{"en":"city","es":"ciudad","pos":"noun","ex_en":"My city is Monterrey.","ex_es":"Mi ciudad es Monterrey."},{"en":"Mexico","es":"México","pos":"noun","ex_en":"I'm from Mexico.","ex_es":"Soy de México."},{"en":"the United States","es":"Estados Unidos","pos":"noun","ex_en":"Tom is from the United States.","ex_es":"Tom es de Estados Unidos."},{"en":"Mexican","es":"mexicano, mexicana","pos":"adj","ex_en":"We're Mexican.","ex_es":"Somos mexicanos."},{"en":"American","es":"estadounidense","pos":"adj","ex_en":"Emma is American.","ex_es":"Emma es estadounidense."}],"sentences":[{"en":"Where are you from?","es":"¿De dónde eres?"},{"en":"I'm from Guadalajara, Mexico.","es":"Soy de Guadalajara, México."},{"en":"Where is she from?","es":"¿De dónde es ella?"},{"en":"He's American, from Chicago.","es":"Él es estadounidense, de Chicago."},{"en":"We're Mexican. What city are you from?","es":"Somos mexicanos. ¿De qué ciudad eres?"}],"tip_es":"Países y nacionalidades siempre llevan mayúscula en inglés: Mexico, Mexican, American. La pregunta termina con from: Where are you from?, que literalmente es dónde eres de."},{"id":"2-7","title_es":"Países y nacionalidades","words":[{"en":"Canada","es":"Canadá","pos":"noun","ex_en":"Emma is from Canada.","ex_es":"Emma es de Canadá."},{"en":"Canadian","es":"canadiense","pos":"adj","ex_en":"He's Canadian.","ex_es":"Él es canadiense."},{"en":"Spain","es":"España","pos":"noun","ex_en":"My teacher is from Spain.","ex_es":"Mi maestro es de España."},{"en":"Spanish","es":"español, española","pos":"adj","ex_en":"She's Spanish, from Madrid.","ex_es":"Ella es española, de Madrid."},{"en":"Colombia","es":"Colombia","pos":"noun","ex_en":"Are you from Colombia?","ex_es":"¿Eres de Colombia?"},{"en":"Colombian","es":"colombiano, colombiana","pos":"adj","ex_en":"We're Colombian.","ex_es":"Somos colombianos."},{"en":"Brazil","es":"Brasil","pos":"noun","ex_en":"They're from Brazil.","ex_es":"Ellos son de Brasil."},{"en":"Brazilian","es":"brasileño, brasileña","pos":"adj","ex_en":"Is your friend Brazilian?","ex_es":"¿Tu amigo es brasileño?"}],"sentences":[{"en":"Is she Canadian or American?","es":"¿Ella es canadiense o estadounidense?"},{"en":"They aren't Spanish. They're Mexican.","es":"No son españoles. Son mexicanos."},{"en":"Where is he from? He's from Brazil.","es":"¿De dónde es él? Es de Brasil."},{"en":"My friend is Colombian, from Bogotá.","es":"Mi amiga es colombiana, de Bogotá."},{"en":"We're from Spain, but we live in Mexico.","es":"Somos de España, pero vivimos en México."}],"tip_es":"Muchas veces el idioma y la nacionalidad son la misma palabra. Spanish es el idioma español y también una persona española. Recuerda que países y nacionalidades siempre llevan mayúscula."},{"id":"2-8","title_es":"Meses y fechas","words":[{"en":"month","es":"mes","pos":"noun","ex_en":"My birthday is this month.","ex_es":"Mi cumpleaños es este mes."},{"en":"year","es":"año","pos":"noun","ex_en":"It's a new year!","ex_es":"¡Es un año nuevo!"},{"en":"date","es":"fecha","pos":"noun","ex_en":"What's the date today?","ex_es":"¿Qué fecha es hoy?"},{"en":"today","es":"hoy","pos":"adv","ex_en":"Today is my birthday!","ex_es":"¡Hoy es mi cumpleaños!"},{"en":"January","es":"enero","pos":"noun","ex_en":"My birthday is in January.","ex_es":"Mi cumpleaños es en enero."},{"en":"April","es":"abril","pos":"noun","ex_en":"Is it April or May?","ex_es":"¿Es abril o mayo?"},{"en":"August","es":"agosto","pos":"noun","ex_en":"We're in Mexico in August.","ex_es":"Estamos en México en agosto."},{"en":"December","es":"diciembre","pos":"noun","ex_en":"Her birthday is in December.","ex_es":"Su cumpleaños es en diciembre."}],"sentences":[{"en":"When is your birthday?","es":"¿Cuándo es tu cumpleaños?"},{"en":"My birthday is in April.","es":"Mi cumpleaños es en abril."},{"en":"Is your birthday in January or August?","es":"¿Tu cumpleaños es en enero o en agosto?"},{"en":"Today is my birthday. I'm twenty!","es":"Hoy es mi cumpleaños. ¡Cumplo veinte!"},{"en":"A year has twelve months.","es":"Un año tiene doce meses."}],"tip_es":"Los meses en inglés siempre se escriben con mayúscula, como January o December. Para decir en qué mes pasa algo usa in, por ejemplo in April o in August."},{"id":"2-9","title_es":"Datos personales y formularios","words":[{"en":"married","es":"casado, casada","pos":"adj","ex_en":"Are you married?","ex_es":"¿Eres casado?"},{"en":"single","es":"soltero, soltera","pos":"adj","ex_en":"No, I'm single.","ex_es":"No, soy soltera."},{"en":"job","es":"trabajo, empleo","pos":"noun","ex_en":"What's your job?","ex_es":"¿Cuál es tu trabajo?"},{"en":"street","es":"calle","pos":"noun","ex_en":"I live on Juárez Street.","ex_es":"Vivo en la calle Juárez."},{"en":"zip code","es":"código postal","pos":"phrase","ex_en":"What's your zip code?","ex_es":"¿Cuál es tu código postal?"},{"en":"form","es":"formulario","pos":"noun","ex_en":"Here is the form.","ex_es":"Aquí está el formulario."},{"en":"information","es":"información, datos","pos":"noun","ex_en":"Your information, please.","ex_es":"Sus datos, por favor."},{"en":"sign","es":"firmar","pos":"verb","ex_en":"Sign here, please.","ex_es":"Firme aquí, por favor."}],"sentences":[{"en":"Are you married or single?","es":"¿Es casado o soltero?"},{"en":"What's your job? I'm a teacher.","es":"¿A qué se dedica? Soy maestra."},{"en":"My address is forty Juárez Street.","es":"Mi dirección es calle Juárez número cuarenta."},{"en":"My zip code is four, four, one, zero, zero.","es":"Mi código postal es cuatro, cuatro, uno, cero, cero."},{"en":"Please sign the form here.","es":"Por favor, firme el formulario aquí."}],"tip_es":"En los formularios de Estados Unidos te piden first name, last name y zip code. La dirección se escribe al revés que en México, primero el número y luego la calle, como 40 Juárez Street."},{"id":"2-10","title_es":"En la vida real, en la recepción","words":[{"en":"help","es":"ayudar","pos":"verb","ex_en":"Can I help you?","ex_es":"¿Le puedo ayudar?"},{"en":"ID","es":"identificación, INE","pos":"noun","ex_en":"Your ID, please.","ex_es":"Su identificación, por favor."},{"en":"card","es":"tarjeta","pos":"noun","ex_en":"Here's your card.","ex_es":"Aquí está su tarjeta."},{"en":"member","es":"socio, miembro","pos":"noun","ex_en":"Are you a member?","ex_es":"¿Es usted socio?"},{"en":"correct","es":"correcto, correcta","pos":"adj","ex_en":"Is your email correct?","ex_es":"¿Su correo es correcto?"},{"en":"wrong","es":"equivocado, mal","pos":"adj","ex_en":"Sorry, the number is wrong.","ex_es":"Perdón, el número está mal."},{"en":"moment","es":"momento","pos":"noun","ex_en":"One moment, please.","ex_es":"Un momento, por favor."},{"en":"ready","es":"listo, lista","pos":"adj","ex_en":"Your card is ready.","ex_es":"Su tarjeta está lista."}],"sentences":[{"en":"Hi! Can I help you?","es":"¡Hola! ¿Le puedo ayudar?"},{"en":"Yes, I'm a new member.","es":"Sí, soy socia nueva."},{"en":"What's your phone number and email?","es":"¿Cuál es su teléfono y su correo?"},{"en":"Sorry, that's wrong. It's sixty, not sixteen.","es":"Perdón, eso está mal. Es sesenta, no dieciséis."},{"en":"One moment, please. Your card is ready.","es":"Un momento, por favor. Su tarjeta está lista."}],"tip_es":"Can I help you? es lo que te dicen en una recepción o en una tienda. Para corregir un dato usa not, como It's sixty, not sixteen. Di los números despacio, porque sixty y sixteen se confunden mucho."}],"dialogue":{"title_es":"Inscripción en el gimnasio","setting_es":"Te inscribes en un gimnasio y la recepcionista te pide tus datos.","lines":[{"who":"A","en":"Hi! What's your name, please?","es":"¡Hola! ¿Cómo te llamas, por favor?"},{"who":"B","en":"My name is Laura Ortiz.","es":"Me llamo Laura Ortiz."},{"who":"A","en":"Nice to meet you. How old are you?","es":"Mucho gusto. ¿Cuántos años tienes?"},{"who":"B","en":"I'm twenty-eight years old.","es":"Tengo veintiocho años."},{"who":"A","en":"Great. Where are you from?","es":"Muy bien. ¿De dónde eres?"},{"who":"B","en":"I'm from Mexico, from Puebla.","es":"Soy de México, de Puebla."},{"who":"A","en":"What's your phone number?","es":"¿Cuál es tu número de teléfono?"},{"who":"B","en":"It's five, five, five, zero, one, four, nine.","es":"Es cinco, cinco, cinco, cero, uno, cuatro, nueve."},{"who":"A","en":"Thanks. And your email?","es":"Gracias. ¿Y tu correo?"},{"who":"B","en":"It's laura at fluent dot com.","es":"Es laura arroba fluent punto com."}]}},{"id":3,"title_es":"Familia y personas","title_en":"Family and people","level":"A1","goal_es":"Al terminar podrás hablar de tu familia, describir cómo son las personas por fuera y por dentro, y usar his, her, our y their.","lessons":[{"id":"3-1","title_es":"Mi familia","words":[{"en":"family","es":"familia","pos":"noun","ex_en":"This is my family.","ex_es":"Esta es mi familia."},{"en":"mother","es":"madre","pos":"noun","ex_en":"My mother is fifty.","ex_es":"Mi madre tiene cincuenta años."},{"en":"father","es":"padre","pos":"noun","ex_en":"My father is from Oaxaca.","ex_es":"Mi padre es de Oaxaca."},{"en":"mom","es":"mamá","pos":"noun","ex_en":"Hi, Mom!","ex_es":"¡Hola, mamá!"},{"en":"dad","es":"papá","pos":"noun","ex_en":"Thanks, Dad!","ex_es":"¡Gracias, papá!"},{"en":"brother","es":"hermano","pos":"noun","ex_en":"Luis is my brother.","ex_es":"Luis es mi hermano."},{"en":"sister","es":"hermana","pos":"noun","ex_en":"My sister is a student.","ex_es":"Mi hermana es estudiante."},{"en":"parents","es":"papás, padres","pos":"noun","ex_en":"My parents are sixty.","ex_es":"Mis papás tienen sesenta años."}],"sentences":[{"en":"This is my mom, Rosa.","es":"Ella es mi mamá, Rosa."},{"en":"My dad is a teacher.","es":"Mi papá es maestro."},{"en":"Are they your parents?","es":"¿Son tus papás?"},{"en":"My brother is twenty-two.","es":"Mi hermano tiene veintidós años."},{"en":"My sister and I are students.","es":"Mi hermana y yo somos estudiantes."}],"tip_es":"Parents significa papás (mamá y papá juntos), no parientes. Para parientes en general se dice relatives. Es un falso amigo muy común."},{"id":"3-2","title_es":"Hijos, pareja y abuelos","words":[{"en":"son","es":"hijo","pos":"noun","ex_en":"My son is a student.","ex_es":"Mi hijo es estudiante."},{"en":"daughter","es":"hija","pos":"noun","ex_en":"My daughter is twelve years old.","ex_es":"Mi hija tiene doce años."},{"en":"husband","es":"esposo","pos":"noun","ex_en":"My husband is from Texas.","ex_es":"Mi esposo es de Texas."},{"en":"wife","es":"esposa","pos":"noun","ex_en":"This is my wife, Laura.","ex_es":"Ella es mi esposa, Laura."},{"en":"grandmother","es":"abuela","pos":"noun","ex_en":"My grandmother is eighty.","ex_es":"Mi abuela tiene ochenta años."},{"en":"grandfather","es":"abuelo","pos":"noun","ex_en":"My grandfather is ninety-one.","ex_es":"Mi abuelo tiene noventa y un años."},{"en":"uncle","es":"tío","pos":"noun","ex_en":"My uncle is American.","ex_es":"Mi tío es estadounidense."},{"en":"aunt","es":"tía","pos":"noun","ex_en":"Aunt Carmen is my mom's sister.","ex_es":"La tía Carmen es hermana de mi mamá."}],"sentences":[{"en":"Is he your son?","es":"¿Es tu hijo?"},{"en":"My wife and I are from Monterrey.","es":"Mi esposa y yo somos de Monterrey."},{"en":"My grandmother is my dad's mother.","es":"Mi abuela es la mamá de mi papá."},{"en":"My uncle Pedro is my mom's brother.","es":"Mi tío Pedro es hermano de mi mamá."},{"en":"My husband is forty-three years old.","es":"Mi esposo tiene cuarenta y tres años."}],"tip_es":"Para decir de quién es algo se usa 's: my mom's sister es la hermana de mi mamá. El orden es al revés que en español, primero el dueño y luego la cosa. De cariño se dice grandma y grandpa."},{"id":"3-3","title_es":"Su, nuestro y tener","words":[{"en":"your","es":"tu, su (de usted)","pos":"pron","ex_en":"Is she your sister?","ex_es":"¿Ella es tu hermana?"},{"en":"his","es":"su (de él)","pos":"pron","ex_en":"His name is Pedro.","ex_es":"Su nombre es Pedro."},{"en":"her","es":"su (de ella)","pos":"pron","ex_en":"Her name is Carmen.","ex_es":"Su nombre es Carmen."},{"en":"our","es":"nuestro, nuestra","pos":"pron","ex_en":"Our mom is a teacher.","ex_es":"Nuestra mamá es maestra."},{"en":"their","es":"su (de ellos)","pos":"pron","ex_en":"Their son is six.","ex_es":"Su hijo tiene seis años."},{"en":"have","es":"tener","pos":"verb","ex_en":"I have two sisters.","ex_es":"Tengo dos hermanas."},{"en":"has","es":"tiene","pos":"verb","ex_en":"She has a son.","ex_es":"Ella tiene un hijo."},{"en":"cousin","es":"primo, prima","pos":"noun","ex_en":"My cousin is from Chicago.","ex_es":"Mi primo es de Chicago."}],"sentences":[{"en":"Her brother is my friend.","es":"Su hermano es mi amigo."},{"en":"His wife has two brothers.","es":"Su esposa tiene dos hermanos."},{"en":"We have three cousins.","es":"Tenemos tres primos."},{"en":"Their parents are from Mexico.","es":"Sus papás son de México."},{"en":"What's your cousin's name?","es":"¿Cómo se llama tu primo?"}],"tip_es":"His es su cuando el dueño es hombre y her cuando es mujer: his mom (la mamá de él), her mom (la mamá de ella). Con he, she e it, el verbo have cambia a has."},{"id":"3-4","title_es":"Alto, bajo, joven y grande","words":[{"en":"tall","es":"alto, alta","pos":"adj","ex_en":"My brother is very tall.","ex_es":"Mi hermano es muy alto."},{"en":"short","es":"bajo, chaparro","pos":"adj","ex_en":"My grandmother is short.","ex_es":"Mi abuela es chaparrita."},{"en":"young","es":"joven","pos":"adj","ex_en":"Her mom is very young.","ex_es":"Su mamá es muy joven."},{"en":"old","es":"viejo, grande (de edad)","pos":"adj","ex_en":"My grandfather is old.","ex_es":"Mi abuelo ya está grande."},{"en":"big","es":"grande","pos":"adj","ex_en":"Our family is big.","ex_es":"Nuestra familia es grande."},{"en":"small","es":"pequeño, chico","pos":"adj","ex_en":"Their baby is small.","ex_es":"Su bebé es chiquito."},{"en":"thin","es":"delgado, delgada","pos":"adj","ex_en":"My uncle is tall and thin.","ex_es":"Mi tío es alto y delgado."},{"en":"strong","es":"fuerte","pos":"adj","ex_en":"My dad is strong.","ex_es":"Mi papá es fuerte."}],"sentences":[{"en":"Is your sister tall or short?","es":"¿Tu hermana es alta o bajita?"},{"en":"He's young, but he's very strong.","es":"Es joven, pero es muy fuerte."},{"en":"My parents aren't old.","es":"Mis papás no están grandes."},{"en":"We have a big family.","es":"Tenemos una familia grande."},{"en":"Her cousin is short and thin.","es":"Su prima es bajita y delgada."}],"tip_es":"El adjetivo va antes del sustantivo: a big family es una familia grande. Además, nunca cambia por género ni número: tall sirve para alto, alta, altos y altas."},{"id":"3-5","title_es":"Pelo, ojos y apariencia","words":[{"en":"hair","es":"pelo, cabello","pos":"noun","ex_en":"She has long hair.","ex_es":"Ella tiene el pelo largo."},{"en":"eyes","es":"ojos","pos":"noun","ex_en":"He has big eyes.","ex_es":"Tiene los ojos grandes."},{"en":"long","es":"largo, larga","pos":"adj","ex_en":"My sister's hair is long.","ex_es":"Mi hermana tiene el pelo largo."},{"en":"curly","es":"chino, rizado","pos":"adj","ex_en":"Her hair is curly.","ex_es":"Ella tiene el pelo chino."},{"en":"beard","es":"barba","pos":"noun","ex_en":"My grandfather has a beard.","ex_es":"Mi abuelo tiene barba."},{"en":"glasses","es":"lentes","pos":"noun","ex_en":"My aunt has glasses.","ex_es":"Mi tía usa lentes."},{"en":"pretty","es":"bonita, bonito","pos":"adj","ex_en":"Your daughter is very pretty.","ex_es":"Tu hija está muy bonita."},{"en":"handsome","es":"guapo","pos":"adj","ex_en":"Her husband is handsome.","ex_es":"Su esposo es guapo."}],"sentences":[{"en":"She has long, curly hair.","es":"Ella tiene el pelo largo y chino."},{"en":"My dad has a beard and glasses.","es":"Mi papá tiene barba y usa lentes."},{"en":"Your mom is very pretty.","es":"Tu mamá es muy bonita."},{"en":"He's tall and handsome.","es":"Es alto y guapo."},{"en":"Their son has big eyes.","es":"Su hijo tiene los ojos grandes."}],"tip_es":"Para describir el pelo y los ojos se usa have o has: she has long hair (tiene el pelo largo). Ojo, hair va en singular cuando hablas de todo el pelo, nunca hairs."},{"id":"3-6","title_es":"La personalidad","words":[{"en":"nice","es":"buena onda, amable","pos":"adj","ex_en":"Your parents are very nice.","ex_es":"Tus papás son muy buena onda."},{"en":"funny","es":"chistoso, divertido","pos":"adj","ex_en":"My uncle is funny.","ex_es":"Mi tío es chistoso."},{"en":"kind","es":"amable, bondadoso","pos":"adj","ex_en":"Thank you, you're very kind.","ex_es":"Gracias, eres muy amable."},{"en":"smart","es":"inteligente, listo","pos":"adj","ex_en":"Our daughter is smart.","ex_es":"Nuestra hija es inteligente."},{"en":"shy","es":"tímido, tímida","pos":"adj","ex_en":"My brother is a little shy.","ex_es":"Mi hermano es un poco tímido."},{"en":"friendly","es":"amigable, amistoso","pos":"adj","ex_en":"The students are friendly.","ex_es":"Los estudiantes son amigables."},{"en":"serious","es":"serio, seria","pos":"adj","ex_en":"My dad is very serious.","ex_es":"Mi papá es muy serio."},{"en":"lazy","es":"flojo, floja","pos":"adj","ex_en":"My cousin is lazy.","ex_es":"Mi primo es flojo."}],"sentences":[{"en":"My sister is smart and funny.","es":"Mi hermana es inteligente y chistosa."},{"en":"Is your teacher nice or serious?","es":"¿Tu maestro es buena onda o serio?"},{"en":"He isn't lazy, he's tired!","es":"¡No es flojo, está cansado!"},{"en":"Our grandmother is very kind.","es":"Nuestra abuela es muy amable."},{"en":"My son is shy, but friendly.","es":"Mi hijo es tímido, pero amigable."}],"tip_es":"Cuidado con este falso amigo: sensible en inglés significa sensato. Si quieres decir que alguien es sensible, usa sensitive. Para decir que alguien es simpático o buena onda, lo más natural es nice."},{"id":"3-7","title_es":"Más familia","words":[{"en":"baby","es":"bebé","pos":"noun","ex_en":"Their baby is very small.","ex_es":"Su bebé es muy chiquito."},{"en":"children","es":"hijos, niños","pos":"noun","ex_en":"They have three children.","ex_es":"Tienen tres hijos."},{"en":"grandparents","es":"abuelos","pos":"noun","ex_en":"My grandparents are from Puebla.","ex_es":"Mis abuelos son de Puebla."},{"en":"nephew","es":"sobrino","pos":"noun","ex_en":"My nephew is ten.","ex_es":"Mi sobrino tiene diez años."},{"en":"niece","es":"sobrina","pos":"noun","ex_en":"Her niece is very funny.","ex_es":"Su sobrina es muy chistosa."},{"en":"boyfriend","es":"novio","pos":"noun","ex_en":"Is he your boyfriend?","ex_es":"¿Él es tu novio?"},{"en":"girlfriend","es":"novia","pos":"noun","ex_en":"His girlfriend is from Canada.","ex_es":"Su novia es de Canadá."},{"en":"twins","es":"gemelos, cuates","pos":"noun","ex_en":"My sisters are twins.","ex_es":"Mis hermanas son gemelas."}],"sentences":[{"en":"My sister has a baby girl.","es":"Mi hermana tiene una bebé."},{"en":"Their children are twins.","es":"Sus hijos son gemelos."},{"en":"My nephew and niece are very young.","es":"Mi sobrino y mi sobrina son muy chicos."},{"en":"His girlfriend is tall and smart.","es":"Su novia es alta e inteligente."},{"en":"Our grandparents have five children.","es":"Nuestros abuelos tienen cinco hijos."}],"tip_es":"Children es el plural irregular de child, que significa niño o hijo. En inglés se dice twins tanto para gemelos como para los que en México llamamos cuates."},{"id":"3-8","title_es":"Hombres, mujeres y niños","words":[{"en":"man","es":"hombre, señor","pos":"noun","ex_en":"He's a nice man.","ex_es":"Es un señor muy amable."},{"en":"woman","es":"mujer, señora","pos":"noun","ex_en":"My grandmother is a strong woman.","ex_es":"Mi abuela es una mujer fuerte."},{"en":"boy","es":"niño, muchacho","pos":"noun","ex_en":"The boy is my son.","ex_es":"El niño es mi hijo."},{"en":"girl","es":"niña, muchacha","pos":"noun","ex_en":"Is the girl your daughter?","ex_es":"¿La niña es tu hija?"},{"en":"person","es":"persona","pos":"noun","ex_en":"She's a kind person.","ex_es":"Es una persona bondadosa."},{"en":"people","es":"personas, gente","pos":"noun","ex_en":"Those people are my family.","ex_es":"Esas personas son mi familia."},{"en":"kid","es":"niño, chamaco","pos":"noun","ex_en":"Their kid is very funny.","ex_es":"Su niño es muy chistoso."},{"en":"teenager","es":"adolescente","pos":"noun","ex_en":"My son is a teenager.","ex_es":"Mi hijo es adolescente."}],"sentences":[{"en":"The tall man is my uncle.","es":"El señor alto es mi tío."},{"en":"That woman is my aunt Lupe.","es":"Esa señora es mi tía Lupe."},{"en":"The boy has curly hair.","es":"El niño tiene el pelo chino."},{"en":"My daughter is a teenager now.","es":"Mi hija ya es adolescente."},{"en":"Her parents are very friendly people.","es":"Sus papás son personas muy amigables."}],"tip_es":"People es el plural de person y siempre va con are, por ejemplo the people are nice. Kid es una forma informal de decir child, como cuando decimos chamaco."},{"id":"3-9","title_es":"¿A quién te pareces?","words":[{"en":"blond","es":"rubio, güero","pos":"adj","ex_en":"My son has blond hair.","ex_es":"Mi hijo tiene el pelo güero."},{"en":"brown","es":"café","pos":"adj","ex_en":"She has brown eyes.","ex_es":"Tiene los ojos cafés."},{"en":"straight","es":"lacio","pos":"adj","ex_en":"Her hair is long and straight.","ex_es":"Su pelo es largo y lacio."},{"en":"mustache","es":"bigote","pos":"noun","ex_en":"My grandfather has a mustache.","ex_es":"Mi abuelo tiene bigote."},{"en":"look like","es":"parecerse a","pos":"phrase","ex_en":"You look like your mom.","ex_es":"Te pareces a tu mamá."},{"en":"same","es":"mismo, misma","pos":"adj","ex_en":"We have the same eyes.","ex_es":"Tenemos los mismos ojos."},{"en":"different","es":"diferente","pos":"adj","ex_en":"My brothers are very different.","ex_es":"Mis hermanos son muy diferentes."},{"en":"both","es":"los dos, ambos","pos":"pron","ex_en":"They're both tall.","ex_es":"Los dos son altos."}],"sentences":[{"en":"My dad has brown eyes and a mustache.","es":"Mi papá tiene ojos cafés y bigote."},{"en":"Her daughter has long, straight hair.","es":"Su hija tiene el pelo largo y lacio."},{"en":"You look like your grandmother.","es":"Te pareces a tu abuela."},{"en":"The twins are both blond.","es":"Los gemelos son güeros los dos."},{"en":"We're sisters, but we're very different.","es":"Somos hermanas, pero somos muy diferentes."}],"tip_es":"Para decir a quién te pareces usa look like, por ejemplo I look like my dad, me parezco a mi papá. Los colores también van antes del sustantivo y no cambian, como brown eyes o blond hair."},{"id":"3-10","title_es":"En la vida real, fotos de familia","words":[{"en":"photo","es":"foto","pos":"noun","ex_en":"Look, a photo of my family.","ex_es":"Mira, una foto de mi familia."},{"en":"who","es":"quién","pos":"pron","ex_en":"Who is he?","ex_es":"¿Quién es él?"},{"en":"best friend","es":"mejor amigo, mejor amiga","pos":"phrase","ex_en":"Ana is my best friend.","ex_es":"Ana es mi mejor amiga."},{"en":"older","es":"mayor","pos":"adj","ex_en":"I have an older sister.","ex_es":"Tengo una hermana mayor."},{"en":"younger","es":"menor","pos":"adj","ex_en":"My younger brother is shy.","ex_es":"Mi hermano menor es tímido."},{"en":"love","es":"querer, amar","pos":"verb","ex_en":"I love my family.","ex_es":"Quiero mucho a mi familia."},{"en":"live","es":"vivir","pos":"verb","ex_en":"My parents live in Mérida.","ex_es":"Mis papás viven en Mérida."},{"en":"together","es":"juntos, juntas","pos":"adv","ex_en":"We live together.","ex_es":"Vivimos juntos."}],"sentences":[{"en":"Look, this is a photo of my family.","es":"Mira, esta es una foto de mi familia."},{"en":"Who is the tall man with glasses?","es":"¿Quién es el señor alto de lentes?"},{"en":"That's my older brother, Daniel. He's very funny.","es":"Es mi hermano mayor, Daniel. Es muy chistoso."},{"en":"My younger sister lives with our grandparents.","es":"Mi hermana menor vive con nuestros abuelos."},{"en":"Her husband is my best friend's cousin.","es":"Su esposo es primo de mi mejor amiga."}],"tip_es":"Older y younger sirven para hermanos mayores y menores, como my older sister, mi hermana mayor. Con he y she el verbo lleva s al final, por eso se dice I live pero she lives."}],"dialogue":{"title_es":"Fotos de familia","setting_es":"Una amiga ve las fotos de tu familia en tu celular.","lines":[{"who":"A","en":"Is this your family?","es":"¿Es tu familia?"},{"who":"B","en":"Yes! This is my mom, Rosa.","es":"¡Sí! Ella es mi mamá, Rosa."},{"who":"A","en":"She's very pretty. Who is the tall man?","es":"Es muy bonita. ¿Quién es el señor alto?"},{"who":"B","en":"That's my brother, Daniel. He's thirty.","es":"Es mi hermano Daniel. Tiene treinta años."},{"who":"A","en":"He's handsome! Is he nice?","es":"¡Es guapo! ¿Es buena onda?"},{"who":"B","en":"Yes, he's very funny. He's a teacher.","es":"Sí, es muy chistoso. Es maestro."},{"who":"A","en":"And the girl with curly hair?","es":"¿Y la niña de pelo chino?"},{"who":"B","en":"That's Sofia, my brother's daughter.","es":"Es Sofía, la hija de mi hermano."},{"who":"A","en":"How old is she?","es":"¿Cuántos años tiene?"},{"who":"B","en":"She's six. She's shy, but very smart.","es":"Tiene seis años. Es tímida, pero muy inteligente."}]}},{"id":4,"title_es":"La casa y los objetos","title_en":"Home and things","level":"A1","goal_es":"Al terminar podrás describir tu casa, decir qué hay en cada cuarto con there is y there are, y explicar dónde están las cosas.","lessons":[{"id":"4-1","title_es":"Los cuartos de la casa","words":[{"en":"house","es":"casa","pos":"noun","ex_en":"My house is small.","ex_es":"Mi casa es chica."},{"en":"apartment","es":"departamento","pos":"noun","ex_en":"We live in an apartment.","ex_es":"Vivimos en un departamento."},{"en":"room","es":"cuarto","pos":"noun","ex_en":"My house has five rooms.","ex_es":"Mi casa tiene cinco cuartos."},{"en":"bedroom","es":"recámara","pos":"noun","ex_en":"My bedroom is big.","ex_es":"Mi recámara es grande."},{"en":"bathroom","es":"baño","pos":"noun","ex_en":"Where is the bathroom?","ex_es":"¿Dónde está el baño?"},{"en":"kitchen","es":"cocina","pos":"noun","ex_en":"Mom is in the kitchen.","ex_es":"Mamá está en la cocina."},{"en":"living room","es":"sala","pos":"noun","ex_en":"The living room is very big.","ex_es":"La sala es muy grande."},{"en":"yard","es":"patio, jardín","pos":"noun","ex_en":"The dog is in the yard.","ex_es":"El perro está en el patio."}],"sentences":[{"en":"This is my house.","es":"Esta es mi casa."},{"en":"Our apartment has two bedrooms.","es":"Nuestro departamento tiene dos recámaras."},{"en":"Excuse me, where is the bathroom?","es":"Disculpe, ¿dónde está el baño?"},{"en":"My grandmother is in the kitchen.","es":"Mi abuela está en la cocina."},{"en":"The yard is big, the house is small.","es":"El patio es grande y la casa es chica."}],"tip_es":"En México decimos recámara, pero en inglés es bedroom: bed (cama) más room (cuarto). Muchos cuartos se forman igual: bathroom, living room, dining room (comedor)."},{"id":"4-2","title_es":"Los muebles","words":[{"en":"bed","es":"cama","pos":"noun","ex_en":"The bed is big.","ex_es":"La cama es grande."},{"en":"table","es":"mesa","pos":"noun","ex_en":"The table is in the kitchen.","ex_es":"La mesa está en la cocina."},{"en":"chair","es":"silla","pos":"noun","ex_en":"We have six chairs.","ex_es":"Tenemos seis sillas."},{"en":"couch","es":"sillón, sofá","pos":"noun","ex_en":"The couch is in the living room.","ex_es":"El sillón está en la sala."},{"en":"desk","es":"escritorio","pos":"noun","ex_en":"My desk is in my bedroom.","ex_es":"Mi escritorio está en mi recámara."},{"en":"closet","es":"clóset","pos":"noun","ex_en":"My closet is small.","ex_es":"Mi clóset es chico."},{"en":"lamp","es":"lámpara","pos":"noun","ex_en":"My sister has a pretty lamp.","ex_es":"Mi hermana tiene una lámpara bonita."},{"en":"shelf","es":"repisa, estante","pos":"noun","ex_en":"My shelf has ten books.","ex_es":"Mi repisa tiene diez libros."}],"sentences":[{"en":"The bed is in the bedroom.","es":"La cama está en la recámara."},{"en":"We have a table and four chairs.","es":"Tenemos una mesa y cuatro sillas."},{"en":"Is your desk big or small?","es":"¿Tu escritorio es grande o chico?"},{"en":"Her closet is very big.","es":"Su clóset es muy grande."},{"en":"Their couch is old, but nice.","es":"Su sillón es viejo, pero bonito."}],"tip_es":"Usa the para algo específico y a para algo en general: a chair (una silla), the chair (la silla). Antes de un sonido de vocal, a cambia a an: an apartment."},{"id":"4-3","title_es":"Objetos de la casa","words":[{"en":"door","es":"puerta","pos":"noun","ex_en":"Where is the door?","ex_es":"¿Dónde está la puerta?"},{"en":"window","es":"ventana","pos":"noun","ex_en":"My bedroom has a big window.","ex_es":"Mi recámara tiene una ventana grande."},{"en":"key","es":"llave","pos":"noun","ex_en":"Where is my key?","ex_es":"¿Dónde está mi llave?"},{"en":"TV","es":"tele, televisión","pos":"noun","ex_en":"The TV is in the living room.","ex_es":"La tele está en la sala."},{"en":"mirror","es":"espejo","pos":"noun","ex_en":"The bathroom has a mirror.","ex_es":"El baño tiene un espejo."},{"en":"clock","es":"reloj (de pared)","pos":"noun","ex_en":"The kitchen clock is old.","ex_es":"El reloj de la cocina es viejo."},{"en":"book","es":"libro","pos":"noun","ex_en":"This book is very good.","ex_es":"Este libro es muy bueno."},{"en":"plant","es":"planta","pos":"noun","ex_en":"My mom has ten plants.","ex_es":"Mi mamá tiene diez plantas."}],"sentences":[{"en":"Where are my keys?","es":"¿Dónde están mis llaves?"},{"en":"The window is very big.","es":"La ventana es muy grande."},{"en":"We have a TV in the kitchen.","es":"Tenemos una tele en la cocina."},{"en":"Her bedroom has a mirror and a clock.","es":"Su recámara tiene un espejo y un reloj."},{"en":"Our house has plants and books.","es":"Nuestra casa tiene plantas y libros."}],"tip_es":"Para el plural casi siempre se agrega s: book, books. Si la palabra termina en sh, ch o x se agrega es: watch, watches. Y algunas cambian, como shelf, que en plural es shelves."},{"id":"4-4","title_es":"Hay: there is y there are","words":[{"en":"there is","es":"hay (una cosa)","pos":"phrase","ex_en":"There is a TV in my room.","ex_es":"Hay una tele en mi cuarto."},{"en":"there are","es":"hay (varias cosas)","pos":"phrase","ex_en":"There are two bathrooms.","ex_es":"Hay dos baños."},{"en":"is there","es":"¿hay? (una cosa)","pos":"phrase","ex_en":"Is there a bathroom?","ex_es":"¿Hay baño?"},{"en":"are there","es":"¿hay? (varias cosas)","pos":"phrase","ex_en":"Are there chairs in the kitchen?","ex_es":"¿Hay sillas en la cocina?"},{"en":"how many","es":"cuántos, cuántas","pos":"phrase","ex_en":"How many rooms are there?","ex_es":"¿Cuántos cuartos hay?"},{"en":"floor","es":"piso","pos":"noun","ex_en":"There are books on the floor.","ex_es":"Hay libros en el piso."},{"en":"stairs","es":"escaleras","pos":"noun","ex_en":"The stairs are next to the kitchen.","ex_es":"Las escaleras están junto a la cocina."},{"en":"garage","es":"cochera","pos":"noun","ex_en":"Our house has a garage.","ex_es":"Nuestra casa tiene cochera."}],"sentences":[{"en":"There's a bed and a desk.","es":"Hay una cama y un escritorio."},{"en":"There are three plants in the kitchen.","es":"Hay tres plantas en la cocina."},{"en":"Is there a TV in the bedroom?","es":"¿Hay tele en la recámara?"},{"en":"Are there stairs in your house?","es":"¿Hay escaleras en tu casa?"},{"en":"How many chairs are there? There are six.","es":"¿Cuántas sillas hay? Hay seis."}],"tip_es":"En español hay sirve para todo, pero en inglés se dice there is con una cosa y there are con varias. Para preguntar se cambia el orden: is there, are there. La forma corta de there is es there's."},{"id":"4-5","title_es":"¿Dónde está?","words":[{"en":"in","es":"en, dentro de","pos":"prep","ex_en":"The keys are in the kitchen.","ex_es":"Las llaves están en la cocina."},{"en":"on","es":"sobre, encima de","pos":"prep","ex_en":"The book is on the table.","ex_es":"El libro está en la mesa."},{"en":"under","es":"debajo de","pos":"prep","ex_en":"The cat is under the bed.","ex_es":"El gato está debajo de la cama."},{"en":"next to","es":"junto a, al lado de","pos":"prep","ex_en":"The lamp is next to the bed.","ex_es":"La lámpara está junto a la cama."},{"en":"behind","es":"detrás de","pos":"prep","ex_en":"The yard is behind the house.","ex_es":"El patio está detrás de la casa."},{"en":"in front of","es":"enfrente de","pos":"prep","ex_en":"The TV is in front of the couch.","ex_es":"La tele está enfrente del sillón."},{"en":"between","es":"entre","pos":"prep","ex_en":"The bathroom is between the bedrooms.","ex_es":"El baño está entre las recámaras."},{"en":"near","es":"cerca de","pos":"prep","ex_en":"Is the bathroom near the kitchen?","ex_es":"¿El baño está cerca de la cocina?"}],"sentences":[{"en":"My cell phone is on the desk.","es":"Mi celular está en el escritorio."},{"en":"There's a dog under the table.","es":"Hay un perro debajo de la mesa."},{"en":"The mirror is behind the door.","es":"El espejo está detrás de la puerta."},{"en":"Is the clock between the windows?","es":"¿El reloj está entre las ventanas?"},{"en":"My keys are in front of the TV.","es":"Mis llaves están enfrente de la tele."}],"tip_es":"En español decimos en para todo, pero en inglés in es dentro de algo y on es encima de algo: the keys are in the closet, the keys are on the table. Piensa si la cosa está adentro o arriba."},{"id":"4-6","title_es":"Cómo es tu casa","words":[{"en":"new","es":"nuevo, nueva","pos":"adj","ex_en":"Our apartment is new.","ex_es":"Nuestro departamento es nuevo."},{"en":"clean","es":"limpio, limpia","pos":"adj","ex_en":"The kitchen is very clean.","ex_es":"La cocina está muy limpia."},{"en":"dirty","es":"sucio, sucia","pos":"adj","ex_en":"The floor is dirty.","ex_es":"El piso está sucio."},{"en":"messy","es":"desordenado, tirado","pos":"adj","ex_en":"My brother's room is messy.","ex_es":"El cuarto de mi hermano está desordenado."},{"en":"comfortable","es":"cómodo, cómoda","pos":"adj","ex_en":"This couch is very comfortable.","ex_es":"Este sillón es muy cómodo."},{"en":"beautiful","es":"hermoso, precioso","pos":"adj","ex_en":"Your house is beautiful!","ex_es":"¡Tu casa está preciosa!"},{"en":"quiet","es":"tranquilo, silencioso","pos":"adj","ex_en":"My street is quiet.","ex_es":"Mi calle es tranquila."},{"en":"noisy","es":"ruidoso, ruidosa","pos":"adj","ex_en":"The city is very noisy.","ex_es":"La ciudad es muy ruidosa."}],"sentences":[{"en":"My bedroom is small, but comfortable.","es":"Mi recámara es chica, pero cómoda."},{"en":"Is the kitchen clean or dirty?","es":"¿La cocina está limpia o sucia?"},{"en":"Sorry, my apartment is very messy!","es":"¡Perdón, mi departamento está muy desordenado!"},{"en":"There's a beautiful window in the living room.","es":"Hay una ventana preciosa en la sala."},{"en":"Our new house isn't noisy, it's quiet.","es":"Nuestra casa nueva no es ruidosa, es tranquila."}],"tip_es":"Comfortable se dice en tres sílabas, algo como KÓMF-ter-bol, no com-for-ta-ble. Y recuerda que el adjetivo va antes del sustantivo: a new house es una casa nueva."},{"id":"4-7","title_es":"En la cocina","words":[{"en":"fridge","es":"refri, refrigerador","pos":"noun","ex_en":"Our fridge is new.","ex_es":"Nuestro refri es nuevo."},{"en":"stove","es":"estufa","pos":"noun","ex_en":"The stove is dirty.","ex_es":"La estufa está sucia."},{"en":"sink","es":"fregadero, lavabo","pos":"noun","ex_en":"The plates are in the sink.","ex_es":"Los platos están en el fregadero."},{"en":"microwave","es":"microondas","pos":"noun","ex_en":"Is there a microwave?","ex_es":"¿Hay microondas?"},{"en":"plate","es":"plato","pos":"noun","ex_en":"There are four plates.","ex_es":"Hay cuatro platos."},{"en":"cup","es":"taza","pos":"noun","ex_en":"My cup is on the table.","ex_es":"Mi taza está en la mesa."},{"en":"glass","es":"vaso","pos":"noun","ex_en":"There's a glass on the desk.","ex_es":"Hay un vaso en el escritorio."},{"en":"spoon","es":"cuchara","pos":"noun","ex_en":"Where are the spoons?","ex_es":"¿Dónde están las cucharas?"}],"sentences":[{"en":"There's a microwave in the kitchen.","es":"Hay un microondas en la cocina."},{"en":"The dirty plates are in the sink.","es":"Los platos sucios están en el fregadero."},{"en":"Is there a glass on the table?","es":"¿Hay un vaso en la mesa?"},{"en":"The fridge is between the stove and the window.","es":"El refri está entre la estufa y la ventana."},{"en":"How many cups are there? There are five.","es":"¿Cuántas tazas hay? Hay cinco."}],"tip_es":"Glass es vaso y cup es taza, para bebidas calientes. Ojo, glasses en plural también significa lentes. Fridge es la forma corta de refrigerator, igual que decir refri."},{"id":"4-8","title_es":"El baño y la recámara","words":[{"en":"shower","es":"regadera","pos":"noun","ex_en":"The shower is very small.","ex_es":"La regadera es muy chica."},{"en":"bathtub","es":"tina","pos":"noun","ex_en":"Is there a bathtub?","ex_es":"¿Hay tina?"},{"en":"toilet","es":"excusado, taza del baño","pos":"noun","ex_en":"The toilet is clean.","ex_es":"El excusado está limpio."},{"en":"towel","es":"toalla","pos":"noun","ex_en":"Your towel is behind the door.","ex_es":"Tu toalla está detrás de la puerta."},{"en":"soap","es":"jabón","pos":"noun","ex_en":"There's no soap.","ex_es":"No hay jabón."},{"en":"pillow","es":"almohada","pos":"noun","ex_en":"My pillow is very comfortable.","ex_es":"Mi almohada es muy cómoda."},{"en":"blanket","es":"cobija","pos":"noun","ex_en":"There's a blanket on the bed.","ex_es":"Hay una cobija en la cama."},{"en":"rug","es":"tapete","pos":"noun","ex_en":"The rug is under the bed.","ex_es":"El tapete está debajo de la cama."}],"sentences":[{"en":"The bathroom has a shower, not a bathtub.","es":"El baño tiene regadera, no tina."},{"en":"Is there soap next to the sink?","es":"¿Hay jabón junto al lavabo?"},{"en":"There are two towels in the closet.","es":"Hay dos toallas en el clóset."},{"en":"My blanket and pillows are on the floor.","es":"Mi cobija y mis almohadas están en el piso."},{"en":"There's a small rug in front of the toilet.","es":"Hay un tapete chico enfrente del excusado."}],"tip_es":"En una casa el baño es bathroom, pero en un lugar público en Estados Unidos se dice restroom. Para decir que no hay algo usa there's no, por ejemplo there's no soap."},{"id":"4-9","title_es":"Arriba, abajo, adentro y afuera","words":[{"en":"upstairs","es":"arriba (en el piso de arriba)","pos":"adv","ex_en":"The bedrooms are upstairs.","ex_es":"Las recámaras están arriba."},{"en":"downstairs","es":"abajo (en el piso de abajo)","pos":"adv","ex_en":"The kitchen is downstairs.","ex_es":"La cocina está abajo."},{"en":"wall","es":"pared","pos":"noun","ex_en":"There's a clock on the wall.","ex_es":"Hay un reloj en la pared."},{"en":"corner","es":"rincón, esquina","pos":"noun","ex_en":"The lamp is in the corner.","ex_es":"La lámpara está en el rincón."},{"en":"ceiling","es":"techo (por dentro)","pos":"noun","ex_en":"The ceiling is very high.","ex_es":"El techo está muy alto."},{"en":"above","es":"arriba de, encima de","pos":"prep","ex_en":"The mirror is above the sink.","ex_es":"El espejo está arriba del lavabo."},{"en":"inside","es":"adentro","pos":"adv","ex_en":"The dog is inside.","ex_es":"El perro está adentro."},{"en":"outside","es":"afuera","pos":"adv","ex_en":"The kids are outside.","ex_es":"Los niños están afuera."}],"sentences":[{"en":"Is the bathroom upstairs or downstairs?","es":"¿El baño está arriba o abajo?"},{"en":"There are three mirrors on the wall.","es":"Hay tres espejos en la pared."},{"en":"The plant is in the corner, near the window.","es":"La planta está en el rincón, cerca de la ventana."},{"en":"There's a lamp above the table.","es":"Hay una lámpara arriba de la mesa."},{"en":"The dog isn't inside. He's outside in the yard.","es":"El perro no está adentro. Está afuera en el patio."}],"tip_es":"Se dice on the wall porque la cosa está pegada a la pared, e in the corner para el rincón de un cuarto. Upstairs y downstairs no llevan in ni on, así que se dice the kitchen is downstairs."},{"id":"4-10","title_es":"En la vida real, buscar departamento","words":[{"en":"rent","es":"renta","pos":"noun","ex_en":"How much is the rent?","ex_es":"¿Cuánto es la renta?"},{"en":"building","es":"edificio","pos":"noun","ex_en":"The building is new.","ex_es":"El edificio es nuevo."},{"en":"elevator","es":"elevador","pos":"noun","ex_en":"Is there an elevator?","ex_es":"¿Hay elevador?"},{"en":"neighborhood","es":"colonia, barrio","pos":"noun","ex_en":"It's a quiet neighborhood.","ex_es":"Es una colonia tranquila."},{"en":"parking","es":"estacionamiento","pos":"noun","ex_en":"There's parking for two cars.","ex_es":"Hay estacionamiento para dos coches."},{"en":"furnished","es":"amueblado, amueblada","pos":"adj","ex_en":"The apartment is furnished.","ex_es":"El departamento está amueblado."},{"en":"sunny","es":"soleado, con mucho sol","pos":"adj","ex_en":"The living room is very sunny.","ex_es":"A la sala le entra mucho sol."},{"en":"cheap","es":"barato, barata","pos":"adj","ex_en":"The rent isn't cheap.","ex_es":"La renta no es barata."}],"sentences":[{"en":"Hi! Is there an apartment for rent?","es":"¡Hola! ¿Hay un departamento en renta?"},{"en":"Yes. It has two bedrooms and one bathroom.","es":"Sí. Tiene dos recámaras y un baño."},{"en":"Is there an elevator in the building?","es":"¿Hay elevador en el edificio?"},{"en":"The kitchen is small, but it's furnished.","es":"La cocina es chica, pero está amueblada."},{"en":"It's a quiet neighborhood, and the rent is cheap.","es":"Es una colonia tranquila y la renta es barata."}],"tip_es":"For rent significa en renta y es lo que ves en los letreros en Estados Unidos. Para preguntar si hay algo usa is there o are there, por ejemplo Is there parking?"}],"dialogue":{"title_es":"Buscando departamento","setting_es":"Visitas un departamento en renta y el dueño te lo enseña.","lines":[{"who":"A","en":"Hi! Welcome. This is the apartment.","es":"¡Hola! Bienvenido. Este es el departamento."},{"who":"B","en":"It's beautiful! How many bedrooms are there?","es":"¡Está precioso! ¿Cuántas recámaras hay?"},{"who":"A","en":"There are two bedrooms and one bathroom.","es":"Hay dos recámaras y un baño."},{"who":"B","en":"Is there a closet in the bedroom?","es":"¿Hay clóset en la recámara?"},{"who":"A","en":"Yes, there's a big closet next to the bed.","es":"Sí, hay un clóset grande junto a la cama."},{"who":"B","en":"Great. And where is the kitchen?","es":"Muy bien. ¿Y dónde está la cocina?"},{"who":"A","en":"It's behind the living room. It's new.","es":"Está detrás de la sala. Es nueva."},{"who":"B","en":"Is the street noisy?","es":"¿La calle es ruidosa?"},{"who":"A","en":"No, it's very quiet. There's a park near here.","es":"No, es muy tranquila. Hay un parque cerca."},{"who":"B","en":"Perfect! I like it.","es":"¡Perfecto! Me gusta."}]}},{"id":5,"title_es":"Comida y restaurante","title_en":"Food and eating out","level":"A1","goal_es":"Al terminar podrás hablar de la comida que te gusta y pedir en un restaurante.","lessons":[{"id":"5-1","title_es":"Comida básica","words":[{"en":"bread","es":"pan","pos":"noun","ex_en":"The bread is fresh.","ex_es":"El pan está fresco."},{"en":"rice","es":"arroz","pos":"noun","ex_en":"I like rice with beans.","ex_es":"Me gusta el arroz con frijoles."},{"en":"egg","es":"huevo","pos":"noun","ex_en":"I want two eggs, please.","ex_es":"Quiero dos huevos, por favor."},{"en":"chicken","es":"pollo","pos":"noun","ex_en":"The chicken is very good.","ex_es":"El pollo está muy bueno."},{"en":"beef","es":"carne de res","pos":"noun","ex_en":"We don't eat beef.","ex_es":"No comemos carne de res."},{"en":"fish","es":"pescado","pos":"noun","ex_en":"My mom makes fish on Fridays.","ex_es":"Mi mamá hace pescado los viernes."},{"en":"cheese","es":"queso","pos":"noun","ex_en":"Do you want cheese on your tacos?","ex_es":"¿Quieres queso en tus tacos?"},{"en":"beans","es":"frijoles","pos":"noun","ex_en":"Beans are cheap and healthy.","ex_es":"Los frijoles son baratos y saludables."}],"sentences":[{"en":"I like chicken.","es":"Me gusta el pollo."},{"en":"I don't like fish.","es":"No me gusta el pescado."},{"en":"Do you like eggs?","es":"¿Te gustan los huevos?"},{"en":"We eat rice and beans every day.","es":"Comemos arroz y frijoles todos los días."},{"en":"My brother loves bread with cheese.","es":"A mi hermano le encanta el pan con queso."}],"tip_es":"Cuando hablas de comida en general, en inglés no se usa artículo: I like chicken, no I like the chicken. Además, like no cambia con el plural: Me gustan los huevos se dice I like eggs."},{"id":"5-2","title_es":"Frutas y verduras","words":[{"en":"apple","es":"manzana","pos":"noun","ex_en":"I eat an apple every morning.","ex_es":"Como una manzana cada mañana."},{"en":"banana","es":"plátano","pos":"noun","ex_en":"This banana is very sweet.","ex_es":"Este plátano está muy dulce."},{"en":"orange","es":"naranja","pos":"noun","ex_en":"The oranges are from Veracruz.","ex_es":"Las naranjas son de Veracruz."},{"en":"strawberry","es":"fresa","pos":"noun","ex_en":"She loves strawberry ice cream.","ex_es":"A ella le encanta el helado de fresa."},{"en":"tomato","es":"jitomate","pos":"noun","ex_en":"We need tomatoes for the salsa.","ex_es":"Necesitamos jitomates para la salsa."},{"en":"onion","es":"cebolla","pos":"noun","ex_en":"Do you want onion on your burger?","ex_es":"¿Quieres cebolla en tu hamburguesa?"},{"en":"potato","es":"papa","pos":"noun","ex_en":"The potatoes are in the kitchen.","ex_es":"Las papas están en la cocina."},{"en":"avocado","es":"aguacate","pos":"noun","ex_en":"I put avocado on my eggs.","ex_es":"Le pongo aguacate a mis huevos."}],"sentences":[{"en":"I like apples and bananas.","es":"Me gustan las manzanas y los plátanos."},{"en":"Are there oranges in the kitchen?","es":"¿Hay naranjas en la cocina?"},{"en":"Strawberries are my favorite fruit.","es":"Las fresas son mi fruta favorita."},{"en":"I don't eat onion.","es":"No como cebolla."},{"en":"We need tomatoes, onions and avocados.","es":"Necesitamos jitomates, cebollas y aguacates."}],"tip_es":"Ojo con los plurales: tomato y potato agregan -es (tomatoes, potatoes). Si la palabra termina en consonante + y, cambia a -ies: strawberry, strawberries."},{"id":"5-3","title_es":"Bebidas","words":[{"en":"water","es":"agua","pos":"noun","ex_en":"I drink a lot of water.","ex_es":"Tomo mucha agua."},{"en":"juice","es":"jugo","pos":"noun","ex_en":"The kids want apple juice.","ex_es":"Los niños quieren jugo de manzana."},{"en":"coffee","es":"café","pos":"noun","ex_en":"I drink coffee in the morning.","ex_es":"Tomo café en la mañana."},{"en":"tea","es":"té","pos":"noun","ex_en":"My grandma drinks tea with honey.","ex_es":"Mi abuela toma té con miel."},{"en":"milk","es":"leche","pos":"noun","ex_en":"Is there milk in the fridge?","ex_es":"¿Hay leche en el refrigerador?"},{"en":"soda","es":"refresco","pos":"noun","ex_en":"Soda has a lot of sugar.","ex_es":"El refresco tiene mucha azúcar."},{"en":"beer","es":"cerveza","pos":"noun","ex_en":"Two beers, please.","ex_es":"Dos cervezas, por favor."},{"en":"cup","es":"taza","pos":"noun","ex_en":"Do you want a cup of coffee?","ex_es":"¿Quieres una taza de café?"}],"sentences":[{"en":"I want water, please.","es":"Quiero agua, por favor."},{"en":"Do you drink coffee or tea?","es":"¿Tomas café o té?"},{"en":"I don't drink soda.","es":"No tomo refresco."},{"en":"We want two cups of tea.","es":"Queremos dos tazas de té."},{"en":"Orange juice is good in the morning.","es":"El jugo de naranja es bueno en la mañana."}],"tip_es":"En México decimos tomar café, pero en inglés se dice drink coffee, no take coffee. Fíjate también en el orden: jugo de naranja es orange juice, porque la palabra que describe va primero."},{"id":"5-4","title_es":"Las comidas del día","words":[{"en":"breakfast","es":"desayuno","pos":"noun","ex_en":"Breakfast is at eight.","ex_es":"El desayuno es a las ocho."},{"en":"lunch","es":"comida","pos":"noun","ex_en":"We have lunch at two.","ex_es":"Comemos a las dos."},{"en":"dinner","es":"cena","pos":"noun","ex_en":"Dinner is ready!","ex_es":"¡La cena está lista!"},{"en":"hungry","es":"con hambre","pos":"adj","ex_en":"I'm very hungry.","ex_es":"Tengo mucha hambre."},{"en":"thirsty","es":"con sed","pos":"adj","ex_en":"Are you thirsty?","ex_es":"¿Tienes sed?"},{"en":"delicious","es":"delicioso","pos":"adj","ex_en":"This soup is delicious.","ex_es":"Esta sopa está deliciosa."},{"en":"eat","es":"comer","pos":"verb","ex_en":"What do you want to eat?","ex_es":"¿Qué quieres comer?"},{"en":"drink","es":"tomar, beber","pos":"verb","ex_en":"I want to drink something cold.","ex_es":"Quiero tomar algo frío."}],"sentences":[{"en":"I'm hungry. Let's eat!","es":"Tengo hambre. ¡Vamos a comer!"},{"en":"What do you have for breakfast?","es":"¿Qué desayunas?"},{"en":"I have eggs and coffee for breakfast.","es":"Desayuno huevos y café."},{"en":"We have dinner at nine.","es":"Cenamos a las nueve."},{"en":"The chicken soup is delicious.","es":"La sopa de pollo está deliciosa."}],"tip_es":"Tengo hambre se dice I'm hungry, con el verbo to be. Nunca digas I have hungry. Para desayunar, comer y cenar se usa have: have breakfast, have lunch, have dinner."},{"id":"5-5","title_es":"En el restaurante","words":[{"en":"menu","es":"menú","pos":"noun","ex_en":"Can we see the menu, please?","ex_es":"¿Podemos ver el menú, por favor?"},{"en":"waiter","es":"mesero","pos":"noun","ex_en":"The waiter is very friendly.","ex_es":"El mesero es muy amable."},{"en":"reservation","es":"reservación","pos":"noun","ex_en":"We have a reservation for four.","ex_es":"Tenemos una reservación para cuatro."},{"en":"order","es":"ordenar, pedir","pos":"verb","ex_en":"Are you ready to order?","ex_es":"¿Están listos para ordenar?"},{"en":"I'd like","es":"quisiera, me gustaría","pos":"phrase","ex_en":"I'd like the fish tacos, please.","ex_es":"Quisiera los tacos de pescado, por favor."},{"en":"can I have","es":"me da","pos":"phrase","ex_en":"Can I have more water, please?","ex_es":"¿Me da más agua, por favor?"},{"en":"check","es":"cuenta","pos":"noun","ex_en":"Can we have the check, please?","ex_es":"¿Nos trae la cuenta, por favor?"},{"en":"tip","es":"propina","pos":"noun","ex_en":"Don't forget the tip.","ex_es":"No olvides la propina."}],"sentences":[{"en":"A table for two, please.","es":"Una mesa para dos, por favor."},{"en":"I'd like a coffee, please.","es":"Quisiera un café, por favor."},{"en":"Can I have the chicken with rice?","es":"¿Me da el pollo con arroz?"},{"en":"What do you recommend?","es":"¿Qué me recomienda?"},{"en":"Excuse me, can we have the check?","es":"Disculpe, ¿nos trae la cuenta?"}],"tip_es":"I'd like es la forma corta de I would like y suena más amable que I want. Evita Give me, que en inglés suena brusco. En EE. UU. la cuenta es the check y se acostumbra dejar entre 15 y 20 por ciento de propina."},{"id":"5-6","title_es":"Some y any en la mesa","words":[{"en":"some","es":"un poco de, unos","pos":"adj","ex_en":"I want some water.","ex_es":"Quiero un poco de agua."},{"en":"any","es":"nada de, ningún","pos":"adj","ex_en":"We don't have any milk.","ex_es":"No tenemos nada de leche."},{"en":"sugar","es":"azúcar","pos":"noun","ex_en":"Is there any sugar?","ex_es":"¿Hay azúcar?"},{"en":"salt","es":"sal","pos":"noun","ex_en":"Can you pass the salt, please?","ex_es":"¿Me pasas la sal, por favor?"},{"en":"spoon","es":"cuchara","pos":"noun","ex_en":"I need a spoon for my soup.","ex_es":"Necesito una cuchara para mi sopa."},{"en":"fork","es":"tenedor","pos":"noun","ex_en":"Can I have a fork, please?","ex_es":"¿Me da un tenedor, por favor?"},{"en":"knife","es":"cuchillo","pos":"noun","ex_en":"This knife is dirty.","ex_es":"Este cuchillo está sucio."},{"en":"napkin","es":"servilleta","pos":"noun","ex_en":"Here are some napkins.","ex_es":"Aquí hay unas servilletas."}],"sentences":[{"en":"I'd like some bread, please.","es":"Quisiera un poco de pan, por favor."},{"en":"Do you have any orange juice?","es":"¿Tiene jugo de naranja?"},{"en":"There isn't any salt on the table.","es":"No hay sal en la mesa."},{"en":"Can I have some more napkins?","es":"¿Me da más servilletas?"},{"en":"We don't need any forks, thanks.","es":"No necesitamos tenedores, gracias."}],"tip_es":"Usa some en oraciones afirmativas y al pedir u ofrecer algo (Can I have some water?). Usa any en negativas y preguntas (We don't have any milk). Agua, azúcar y sal no se cuentan: no digas a sugar ni sugars."},{"id":"5-7","title_es":"Cocinar en casa","words":[{"en":"kitchen","es":"cocina","pos":"noun","ex_en":"My mom is in the kitchen.","ex_es":"Mi mamá está en la cocina."},{"en":"recipe","es":"receta","pos":"noun","ex_en":"This is my grandma's recipe.","ex_es":"Esta es la receta de mi abuela."},{"en":"boil","es":"hervir","pos":"verb","ex_en":"Boil the water first.","ex_es":"Primero hierve el agua."},{"en":"fry","es":"freír","pos":"verb","ex_en":"I fry the eggs in a little oil.","ex_es":"Frío los huevos en poco aceite."},{"en":"cut","es":"cortar","pos":"verb","ex_en":"Cut the onion, please.","ex_es":"Corta la cebolla, por favor."},{"en":"mix","es":"mezclar","pos":"verb","ex_en":"Mix the milk and the sugar.","ex_es":"Mezcla la leche y el azúcar."},{"en":"pan","es":"sartén","pos":"noun","ex_en":"The pan is very hot.","ex_es":"La sartén está muy caliente."},{"en":"oven","es":"horno","pos":"noun","ex_en":"The chicken is in the oven.","ex_es":"El pollo está en el horno."}],"sentences":[{"en":"Boil the potatoes for twenty minutes.","es":"Hierve las papas veinte minutos."},{"en":"Cut the tomatoes and the onion.","es":"Corta los jitomates y la cebolla."},{"en":"Do you have a good recipe for soup?","es":"¿Tienes una buena receta de sopa?"},{"en":"I fry the fish in a big pan.","es":"Frío el pescado en una sartén grande."},{"en":"Mix the rice with the beans and serve.","es":"Mezcla el arroz con los frijoles y sirve."}],"tip_es":"Las recetas usan el imperativo, que es el verbo sin sujeto: Cut the onion, Boil the water. Ojo, en inglés tomato es jitomate y pan es sartén, no pan de comer, que es bread."},{"id":"5-8","title_es":"Sabores","words":[{"en":"sweet","es":"dulce","pos":"adj","ex_en":"This cake is very sweet.","ex_es":"Este pastel está muy dulce."},{"en":"salty","es":"salado","pos":"adj","ex_en":"The soup is too salty.","ex_es":"La sopa está demasiado salada."},{"en":"spicy","es":"picante","pos":"adj","ex_en":"I love spicy food.","ex_es":"Me encanta la comida picante."},{"en":"sour","es":"ácido","pos":"adj","ex_en":"Lemons are sour.","ex_es":"Los limones son ácidos."},{"en":"fresh","es":"fresco","pos":"adj","ex_en":"The fish is very fresh.","ex_es":"El pescado está muy fresco."},{"en":"taste","es":"saber","pos":"verb","ex_en":"The chicken tastes great.","ex_es":"El pollo sabe muy rico."},{"en":"hot sauce","es":"salsa picante","pos":"noun","ex_en":"Can I have some hot sauce?","ex_es":"¿Me da salsa picante?"},{"en":"soup","es":"sopa","pos":"noun","ex_en":"I have soup for lunch.","ex_es":"Como sopa en la comida."}],"sentences":[{"en":"Is this salsa spicy?","es":"¿Esta salsa pica?"},{"en":"The coffee tastes bitter without sugar.","es":"El café sabe amargo sin azúcar."},{"en":"I don't like sweet drinks.","es":"No me gustan las bebidas dulces."},{"en":"Do you put hot sauce on your eggs?","es":"¿Le pones salsa picante a tus huevos?"},{"en":"This soup tastes good, but it's a little salty.","es":"Esta sopa sabe rica, pero está un poco salada."}],"tip_es":"Para picante usa spicy, porque hot casi siempre significa caliente. Con taste se usa un adjetivo, no un adverbio: It tastes good, nunca It tastes well."},{"id":"5-9","title_es":"Postres y antojitos","words":[{"en":"dessert","es":"postre","pos":"noun","ex_en":"What's for dessert?","ex_es":"¿Qué hay de postre?"},{"en":"cake","es":"pastel","pos":"noun","ex_en":"We have chocolate cake today.","ex_es":"Hoy tenemos pastel de chocolate."},{"en":"ice cream","es":"helado","pos":"noun","ex_en":"My kids love ice cream.","ex_es":"A mis hijos les encanta el helado."},{"en":"cookie","es":"galleta","pos":"noun","ex_en":"Do you want a cookie?","ex_es":"¿Quieres una galleta?"},{"en":"sandwich","es":"sándwich","pos":"noun","ex_en":"I make a sandwich for lunch.","ex_es":"Hago un sándwich para la comida."},{"en":"French fries","es":"papas a la francesa","pos":"noun","ex_en":"Can I have French fries with that?","ex_es":"¿Me da papas a la francesa con eso?"},{"en":"snack","es":"botana","pos":"noun","ex_en":"I eat a snack at five.","ex_es":"Como una botana a las cinco."},{"en":"would you like","es":"te gustaría, quieres","pos":"phrase","ex_en":"Would you like some coffee?","ex_es":"¿Gustas un café?"}],"sentences":[{"en":"Would you like some dessert?","es":"¿Gustas algo de postre?"},{"en":"Yes, please. I'd like the chocolate cake.","es":"Sí, por favor. Quiero el pastel de chocolate."},{"en":"Would you like ice cream or cookies?","es":"¿Quieres helado o galletas?"},{"en":"No, thanks. I'm not hungry.","es":"No, gracias. No tengo hambre."},{"en":"We usually have a snack in the afternoon.","es":"Normalmente comemos una botana en la tarde."}],"tip_es":"Would you like...? es la forma amable de ofrecer algo. Contesta Yes, please o No, thanks. No lo confundas con Do you like...?, que pregunta si algo te gusta en general."},{"id":"5-10","title_es":"En la vida real: comer fuera","words":[{"en":"for here","es":"para comer aquí","pos":"phrase","ex_en":"Is that for here?","ex_es":"¿Es para comer aquí?"},{"en":"to go","es":"para llevar","pos":"phrase","ex_en":"Two coffees to go, please.","ex_es":"Dos cafés para llevar, por favor."},{"en":"refill","es":"otro vaso, rellenar","pos":"noun","ex_en":"Can I have a refill?","ex_es":"¿Me puede rellenar el vaso?"},{"en":"allergic","es":"alérgico","pos":"adj","ex_en":"I'm allergic to fish.","ex_es":"Soy alérgico al pescado."},{"en":"vegetarian","es":"vegetariano","pos":"adj","ex_en":"My sister is vegetarian.","ex_es":"Mi hermana es vegetariana."},{"en":"without","es":"sin","pos":"prep","ex_en":"A burger without onion, please.","ex_es":"Una hamburguesa sin cebolla, por favor."},{"en":"split","es":"dividir","pos":"verb","ex_en":"Let's split the check.","ex_es":"Vamos a dividir la cuenta."},{"en":"box","es":"caja, recipiente","pos":"noun","ex_en":"Can I have a box, please?","ex_es":"¿Me da un recipiente, por favor?"}],"sentences":[{"en":"For here or to go?","es":"¿Para comer aquí o para llevar?"},{"en":"I'd like a sandwich to go, please.","es":"Quiero un sándwich para llevar, por favor."},{"en":"I'm vegetarian. Is there any meat in this?","es":"Soy vegetariano. ¿Esto tiene carne?"},{"en":"Can I have some water without ice?","es":"¿Me da agua sin hielo?"},{"en":"Can we split the check and get a box?","es":"¿Podemos dividir la cuenta y pedir un recipiente?"}],"tip_es":"Para llevar se dice to go, y para comer aquí for here. En muchos lugares de EE. UU. el refill de refresco o café es gratis. Si te sobra comida, pide a box, no es mal visto."}],"dialogue":{"title_es":"En el restaurante","setting_es":"Estás en un restaurante en Austin y el mesero te toma la orden.","lines":[{"who":"A","en":"Hi! Welcome. Are you ready to order?","es":"¡Hola! Bienvenido. ¿Está listo para ordenar?"},{"who":"B","en":"Yes. I'd like the chicken tacos, please.","es":"Sí. Quisiera los tacos de pollo, por favor."},{"who":"A","en":"Sure. Do you want rice and beans?","es":"Claro. ¿Quiere arroz y frijoles?"},{"who":"B","en":"Just beans, please. No onion.","es":"Solo frijoles, por favor. Sin cebolla."},{"who":"A","en":"No problem. And to drink?","es":"No hay problema. ¿Y de tomar?"},{"who":"B","en":"Can I have an orange juice?","es":"¿Me da un jugo de naranja?"},{"who":"A","en":"Sorry, we don't have any orange juice.","es":"Lo siento, no tenemos jugo de naranja."},{"who":"B","en":"That's OK. Some water, please.","es":"Está bien. Agua, por favor."},{"who":"A","en":"Here you go. Enjoy your meal!","es":"Aquí tiene. ¡Buen provecho!"},{"who":"B","en":"Thank you! It looks delicious.","es":"¡Gracias! Se ve delicioso."}]}},{"id":6,"title_es":"Rutina diaria y la hora","title_en":"My daily routine","level":"A1","goal_es":"Al terminar podrás describir tu rutina, decir la hora y hablar de qué tan seguido haces las cosas.","lessons":[{"id":"6-1","title_es":"Por la mañana","words":[{"en":"wake up","es":"despertarse","pos":"verb","ex_en":"I wake up at six.","ex_es":"Me despierto a las seis."},{"en":"get up","es":"levantarse","pos":"verb","ex_en":"I get up at six fifteen.","ex_es":"Me levanto a las seis y cuarto."},{"en":"take a shower","es":"bañarse","pos":"phrase","ex_en":"I take a shower every morning.","ex_es":"Me baño todas las mañanas."},{"en":"brush","es":"cepillarse, lavarse","pos":"verb","ex_en":"I brush my teeth after breakfast.","ex_es":"Me lavo los dientes después del desayuno."},{"en":"get dressed","es":"vestirse","pos":"verb","ex_en":"I get dressed in my room.","ex_es":"Me visto en mi cuarto."},{"en":"shave","es":"rasurarse","pos":"verb","ex_en":"I don't shave every day.","ex_es":"No me rasuro todos los días."},{"en":"leave","es":"salir, irse","pos":"verb","ex_en":"I leave the house at seven thirty.","ex_es":"Salgo de la casa a las siete y media."},{"en":"early","es":"temprano","pos":"adv","ex_en":"I go to work early.","ex_es":"Me voy a trabajar temprano."}],"sentences":[{"en":"I wake up early.","es":"Me despierto temprano."},{"en":"Then I take a shower.","es":"Luego me baño."},{"en":"I get dressed and brush my hair.","es":"Me visto y me cepillo el pelo."},{"en":"I don't have breakfast at home.","es":"No desayuno en casa."},{"en":"I leave the house at seven.","es":"Salgo de la casa a las siete."}],"tip_es":"Muchos verbos que en español son reflexivos (despertarse, vestirse) en inglés no llevan myself: se dice I get dressed, no I dress myself. Con partes del cuerpo usa el posesivo: I brush my teeth, no the teeth."},{"id":"6-2","title_es":"¿Qué hora es?","words":[{"en":"what time","es":"qué hora","pos":"phrase","ex_en":"What time is it?","ex_es":"¿Qué hora es?"},{"en":"o'clock","es":"en punto","pos":"adv","ex_en":"It's nine o'clock.","ex_es":"Son las nueve en punto."},{"en":"half past","es":"y media","pos":"phrase","ex_en":"It's half past four.","ex_es":"Son las cuatro y media."},{"en":"quarter","es":"cuarto","pos":"noun","ex_en":"It's a quarter to ten.","ex_es":"Son quince para las diez."},{"en":"minute","es":"minuto","pos":"noun","ex_en":"Wait five minutes, please.","ex_es":"Espera cinco minutos, por favor."},{"en":"hour","es":"hora","pos":"noun","ex_en":"The class is an hour long.","ex_es":"La clase dura una hora."},{"en":"noon","es":"mediodía","pos":"noun","ex_en":"We have lunch at noon.","ex_es":"Comemos al mediodía."},{"en":"midnight","es":"medianoche","pos":"noun","ex_en":"The party ends at midnight.","ex_es":"La fiesta termina a medianoche."}],"sentences":[{"en":"Excuse me, what time is it?","es":"Disculpa, ¿qué hora es?"},{"en":"It's ten thirty.","es":"Son las diez y media."},{"en":"It's a quarter past eight.","es":"Son las ocho y cuarto."},{"en":"My English class is at noon.","es":"Mi clase de inglés es al mediodía."},{"en":"What time do you get up?","es":"¿A qué hora te levantas?"}],"tip_es":"Para la hora siempre usa It's, aunque en español digas son las tres: It's three o'clock. Para decir a las usa at: at noon, at seven thirty. La h de hour no suena, por eso se dice an hour."},{"id":"6-3","title_es":"Él y ella: presente simple","words":[{"en":"work","es":"trabajar","pos":"verb","ex_en":"My sister works in a hospital.","ex_es":"Mi hermana trabaja en un hospital."},{"en":"study","es":"estudiar","pos":"verb","ex_en":"I study English at night.","ex_es":"Estudio inglés en la noche."},{"en":"start","es":"empezar","pos":"verb","ex_en":"Class starts at eight.","ex_es":"La clase empieza a las ocho."},{"en":"finish","es":"terminar","pos":"verb","ex_en":"She finishes work at five.","ex_es":"Ella termina de trabajar a las cinco."},{"en":"watch","es":"ver","pos":"verb","ex_en":"My dad watches TV after dinner.","ex_es":"Mi papá ve la tele después de cenar."},{"en":"cook","es":"cocinar","pos":"verb","ex_en":"My husband cooks every night.","ex_es":"Mi esposo cocina todas las noches."},{"en":"read","es":"leer","pos":"verb","ex_en":"She reads before bed.","ex_es":"Ella lee antes de dormir."},{"en":"walk","es":"caminar","pos":"verb","ex_en":"He walks to school.","ex_es":"Él se va caminando a la escuela."}],"sentences":[{"en":"I work, and my wife studies.","es":"Yo trabajo y mi esposa estudia."},{"en":"He starts work at nine.","es":"Él empieza a trabajar a las nueve."},{"en":"She watches the news in the morning.","es":"Ella ve las noticias en la mañana."},{"en":"My brother doesn't cook.","es":"Mi hermano no cocina."},{"en":"Does your son walk to school?","es":"¿Tu hijo camina a la escuela?"}],"tip_es":"Con he, she e it el verbo lleva -s: she works, he reads. Después de sh, ch, x u o se agrega -es: watches, finishes, goes. Si termina en consonante + y, cambia a -ies: studies. El error más común es decir she work."},{"id":"6-4","title_es":"Los días de la semana","words":[{"en":"Monday","es":"lunes","pos":"noun","ex_en":"I go to the gym on Mondays.","ex_es":"Voy al gimnasio los lunes."},{"en":"Tuesday","es":"martes","pos":"noun","ex_en":"My English class is on Tuesday.","ex_es":"Mi clase de inglés es el martes."},{"en":"Wednesday","es":"miércoles","pos":"noun","ex_en":"We play soccer on Wednesdays.","ex_es":"Jugamos futbol los miércoles."},{"en":"Thursday","es":"jueves","pos":"noun","ex_en":"She cooks pasta on Thursdays.","ex_es":"Ella cocina pasta los jueves."},{"en":"Friday","es":"viernes","pos":"noun","ex_en":"Friday is my favorite day.","ex_es":"El viernes es mi día favorito."},{"en":"Saturday","es":"sábado","pos":"noun","ex_en":"I clean the house on Saturdays.","ex_es":"Limpio la casa los sábados."},{"en":"Sunday","es":"domingo","pos":"noun","ex_en":"We visit my parents on Sundays.","ex_es":"Visitamos a mis papás los domingos."},{"en":"weekend","es":"fin de semana","pos":"noun","ex_en":"What do you do on the weekend?","ex_es":"¿Qué haces el fin de semana?"}],"sentences":[{"en":"Today is Monday.","es":"Hoy es lunes."},{"en":"I don't work on Saturdays.","es":"No trabajo los sábados."},{"en":"My new class starts on Tuesday.","es":"Mi nueva clase empieza el martes."},{"en":"He studies on Wednesdays and Fridays.","es":"Él estudia los miércoles y los viernes."},{"en":"What do you do on Sundays?","es":"¿Qué haces los domingos?"}],"tip_es":"En inglés los días siempre van con mayúscula y con la preposición on: on Monday. Para algo que haces cada semana usa el plural: on Mondays significa los lunes. En Wednesday la primera d no suena: se pronuncia wénz-dei."},{"id":"6-5","title_es":"¿Qué tan seguido?","words":[{"en":"always","es":"siempre","pos":"adv","ex_en":"I always drink coffee in the morning.","ex_es":"Siempre tomo café en la mañana."},{"en":"usually","es":"normalmente","pos":"adv","ex_en":"We usually eat at home.","ex_es":"Normalmente comemos en casa."},{"en":"often","es":"seguido","pos":"adv","ex_en":"Do you often walk to work?","ex_es":"¿Caminas seguido al trabajo?"},{"en":"sometimes","es":"a veces","pos":"adv","ex_en":"Sometimes I cook dinner.","ex_es":"A veces preparo la cena."},{"en":"rarely","es":"casi nunca","pos":"adv","ex_en":"She rarely watches TV.","ex_es":"Ella casi nunca ve la tele."},{"en":"never","es":"nunca","pos":"adv","ex_en":"I never get up late.","ex_es":"Nunca me levanto tarde."},{"en":"every day","es":"todos los días","pos":"phrase","ex_en":"He reads the news every day.","ex_es":"Él lee las noticias todos los días."},{"en":"once a week","es":"una vez a la semana","pos":"phrase","ex_en":"We go to the market once a week.","ex_es":"Vamos al mercado una vez a la semana."}],"sentences":[{"en":"I always wake up early.","es":"Siempre me despierto temprano."},{"en":"She usually takes a shower at night.","es":"Ella normalmente se baña en la noche."},{"en":"We sometimes eat out on Fridays.","es":"A veces comemos fuera los viernes."},{"en":"He never works on the weekend.","es":"Él nunca trabaja el fin de semana."},{"en":"How often do you go to the gym?","es":"¿Qué tan seguido vas al gimnasio?"}],"tip_es":"Los adverbios de frecuencia van antes del verbo principal (I always eat) pero después de to be (I am always tired). No digas I eat always. Las expresiones como every day y once a week van al final de la oración."},{"id":"6-6","title_es":"Por la tarde y la noche","words":[{"en":"get home","es":"llegar a casa","pos":"phrase","ex_en":"I get home at six.","ex_es":"Llego a casa a las seis."},{"en":"relax","es":"descansar, relajarse","pos":"verb","ex_en":"I relax on the sofa after work.","ex_es":"Descanso en el sillón después del trabajo."},{"en":"do homework","es":"hacer la tarea","pos":"phrase","ex_en":"The kids do homework after dinner.","ex_es":"Los niños hacen la tarea después de cenar."},{"en":"wash the dishes","es":"lavar los trastes","pos":"phrase","ex_en":"I wash the dishes every night.","ex_es":"Lavo los trastes todas las noches."},{"en":"go to bed","es":"acostarse","pos":"phrase","ex_en":"I go to bed at eleven.","ex_es":"Me acuesto a las once."},{"en":"sleep","es":"dormir","pos":"verb","ex_en":"I sleep seven hours a night.","ex_es":"Duermo siete horas cada noche."},{"en":"late","es":"tarde","pos":"adv","ex_en":"My husband gets home late.","ex_es":"Mi esposo llega tarde a casa."},{"en":"evening","es":"la tarde, la noche","pos":"noun","ex_en":"I study English in the evening.","ex_es":"Estudio inglés en la noche."}],"sentences":[{"en":"What time do you get home?","es":"¿A qué hora llegas a casa?"},{"en":"I do my homework in the evening.","es":"Hago mi tarea en la noche."},{"en":"He doesn't wash the dishes.","es":"Él no lava los trastes."},{"en":"Do you go to bed late?","es":"¿Te acuestas tarde?"},{"en":"She usually relaxes and reads before bed.","es":"Ella normalmente descansa y lee antes de dormir."}],"tip_es":"Para negar y preguntar en presente simple usa do o does con el verbo en forma base: She doesn't work, Does he cook? La -s pasa a does, así que nunca digas She doesn't works ni Does he cooks?"},{"id":"6-7","title_es":"Las tareas de la casa","words":[{"en":"chores","es":"quehaceres","pos":"noun","ex_en":"I do my chores on Saturday.","ex_es":"Hago mis quehaceres el sábado."},{"en":"clean","es":"limpiar","pos":"verb","ex_en":"We clean the house together.","ex_es":"Limpiamos la casa juntos."},{"en":"make the bed","es":"tender la cama","pos":"phrase","ex_en":"I make the bed every morning.","ex_es":"Tiendo la cama todas las mañanas."},{"en":"do the laundry","es":"lavar la ropa","pos":"phrase","ex_en":"I do the laundry on Mondays.","ex_es":"Lavo la ropa los lunes."},{"en":"vacuum","es":"aspirar","pos":"verb","ex_en":"He vacuums the living room.","ex_es":"Él aspira la sala."},{"en":"sweep","es":"barrer","pos":"verb","ex_en":"Can you sweep the kitchen?","ex_es":"¿Puedes barrer la cocina?"},{"en":"iron","es":"planchar","pos":"verb","ex_en":"I never iron my shirts.","ex_es":"Nunca plancho mis camisas."},{"en":"take out the trash","es":"sacar la basura","pos":"phrase","ex_en":"Please take out the trash.","ex_es":"Por favor, saca la basura."}],"sentences":[{"en":"I make the bed every day.","es":"Tiendo la cama todos los días."},{"en":"Who does the laundry in your house?","es":"¿Quién lava la ropa en tu casa?"},{"en":"My husband sweeps and I vacuum.","es":"Mi esposo barre y yo aspiro."},{"en":"She takes out the trash at night.","es":"Ella saca la basura en la noche."},{"en":"We usually clean the house on Saturdays.","es":"Normalmente limpiamos la casa los sábados."}],"tip_es":"Muchas tareas usan do o make. Se dice do the laundry y do the dishes, pero make the bed. Aprende cada frase completa, no palabra por palabra."},{"id":"6-8","title_es":"Partes del día","words":[{"en":"morning","es":"mañana","pos":"noun","ex_en":"I drink coffee in the morning.","ex_es":"Tomo café en la mañana."},{"en":"afternoon","es":"tarde","pos":"noun","ex_en":"She works in the afternoon.","ex_es":"Ella trabaja en la tarde."},{"en":"night","es":"noche","pos":"noun","ex_en":"I read at night.","ex_es":"Leo en la noche."},{"en":"tonight","es":"hoy en la noche","pos":"adv","ex_en":"Do you work tonight?","ex_es":"¿Trabajas hoy en la noche?"},{"en":"tomorrow","es":"mañana","pos":"adv","ex_en":"I start my new job tomorrow.","ex_es":"Empiezo mi nuevo trabajo mañana."},{"en":"before","es":"antes de","pos":"prep","ex_en":"I shower before breakfast.","ex_es":"Me baño antes de desayunar."},{"en":"after","es":"después de","pos":"prep","ex_en":"We walk after dinner.","ex_es":"Caminamos después de cenar."},{"en":"month","es":"mes","pos":"noun","ex_en":"I visit my parents once a month.","ex_es":"Visito a mis papás una vez al mes."}],"sentences":[{"en":"I study English in the morning.","es":"Estudio inglés en la mañana."},{"en":"He sleeps eight hours at night.","es":"Él duerme ocho horas en la noche."},{"en":"Do you watch TV after dinner?","es":"¿Ves la tele después de cenar?"},{"en":"I always brush my teeth before bed.","es":"Siempre me lavo los dientes antes de dormir."},{"en":"My class is tomorrow afternoon at four.","es":"Mi clase es mañana en la tarde a las cuatro."}],"tip_es":"Se dice in the morning, in the afternoon e in the evening, pero at night. Cuidado con mañana: morning es la parte del día y tomorrow es el día siguiente."},{"id":"6-9","title_es":"Tiempo libre y fin de semana","words":[{"en":"free time","es":"tiempo libre","pos":"noun","ex_en":"What do you do in your free time?","ex_es":"¿Qué haces en tu tiempo libre?"},{"en":"sleep in","es":"dormir hasta tarde","pos":"verb","ex_en":"I sleep in on Sundays.","ex_es":"Los domingos duermo hasta tarde."},{"en":"go out","es":"salir","pos":"verb","ex_en":"We go out on Friday nights.","ex_es":"Salimos los viernes en la noche."},{"en":"visit","es":"visitar","pos":"verb","ex_en":"I visit my grandma on Sundays.","ex_es":"Visito a mi abuela los domingos."},{"en":"play","es":"jugar, tocar","pos":"verb","ex_en":"My kids play soccer on Saturdays.","ex_es":"Mis hijos juegan futbol los sábados."},{"en":"exercise","es":"hacer ejercicio","pos":"verb","ex_en":"I exercise three times a week.","ex_es":"Hago ejercicio tres veces por semana."},{"en":"busy","es":"ocupado","pos":"adj","ex_en":"I'm very busy on Mondays.","ex_es":"Los lunes estoy muy ocupado."},{"en":"tired","es":"cansado","pos":"adj","ex_en":"She is always tired on Fridays.","ex_es":"Ella siempre está cansada los viernes."}],"sentences":[{"en":"I sleep in on the weekend.","es":"Duermo hasta tarde el fin de semana."},{"en":"Do you go out on Saturday nights?","es":"¿Sales los sábados en la noche?"},{"en":"He plays the guitar in his free time.","es":"Él toca la guitarra en su tiempo libre."},{"en":"We sometimes visit friends on Sundays.","es":"A veces visitamos a amigos los domingos."},{"en":"I'm too tired to exercise after work.","es":"Estoy muy cansado para hacer ejercicio después del trabajo."}],"tip_es":"Play sirve para deportes y también para instrumentos: play soccer, play the guitar. Con instrumentos sí se usa the. Para decir que algo te gusta hacer usa like con -ing: I like playing soccer."},{"id":"6-10","title_es":"En la vida real: mi día","words":[{"en":"alarm","es":"alarma, despertador","pos":"noun","ex_en":"My alarm rings at six.","ex_es":"Mi alarma suena a las seis."},{"en":"get ready","es":"arreglarse","pos":"phrase","ex_en":"I get ready in twenty minutes.","ex_es":"Me arreglo en veinte minutos."},{"en":"commute","es":"trayecto al trabajo","pos":"noun","ex_en":"My commute is one hour.","ex_es":"Hago una hora de camino al trabajo."},{"en":"on time","es":"a tiempo, puntual","pos":"phrase","ex_en":"The bus is never on time.","ex_es":"El camión nunca llega a tiempo."},{"en":"be late","es":"llegar tarde","pos":"phrase","ex_en":"Don't be late for class.","ex_es":"No llegues tarde a clase."},{"en":"lunch break","es":"hora de la comida","pos":"noun","ex_en":"My lunch break is at two.","ex_es":"Mi hora de comida es a las dos."},{"en":"take a nap","es":"tomar una siesta","pos":"phrase","ex_en":"I take a nap after lunch.","ex_es":"Tomo una siesta después de comer."},{"en":"schedule","es":"horario","pos":"noun","ex_en":"My schedule is very busy.","ex_es":"Mi horario está muy apretado."}],"sentences":[{"en":"My alarm rings at six every day.","es":"Mi alarma suena a las seis todos los días."},{"en":"How long is your commute?","es":"¿Cuánto haces de camino al trabajo?"},{"en":"She always gets to work on time.","es":"Ella siempre llega a tiempo al trabajo."},{"en":"I have lunch at my desk during my break.","es":"Como en mi escritorio durante mi descanso."},{"en":"On Sundays, he takes a nap after lunch.","es":"Los domingos, él toma una siesta después de comer."}],"tip_es":"On time significa puntual, a la hora exacta. Para llegar tarde usa be late: I'm late, Don't be late. En EE. UU. la comida fuerte es dinner, en la noche, y lunch es algo ligero al mediodía."}],"dialogue":{"title_es":"Una semana ocupada","setting_es":"Platicas con una amiga sobre tu rutina diaria.","lines":[{"who":"A","en":"You look tired. What time do you get up?","es":"Te ves cansado. ¿A qué hora te levantas?"},{"who":"B","en":"I get up at five thirty.","es":"Me levanto a las cinco y media."},{"who":"A","en":"Wow, that's early! Why?","es":"¡Guau, qué temprano! ¿Por qué?"},{"who":"B","en":"I start work at seven.","es":"Empiezo a trabajar a las siete."},{"who":"A","en":"And what time do you finish?","es":"¿Y a qué hora terminas?"},{"who":"B","en":"At four. Then I study English.","es":"A las cuatro. Luego estudio inglés."},{"who":"A","en":"Every day?","es":"¿Todos los días?"},{"who":"B","en":"No, on Mondays, Wednesdays and Fridays.","es":"No, los lunes, miércoles y viernes."},{"who":"A","en":"What do you do on the weekend?","es":"¿Qué haces el fin de semana?"},{"who":"B","en":"I relax and sleep late!","es":"¡Descanso y duermo hasta tarde!"}]}},{"id":7,"title_es":"Ropa, compras y precios","title_en":"Clothes and shopping","level":"A2","goal_es":"Al terminar podrás comprar ropa, preguntar tallas y precios, y pagar en una tienda.","lessons":[{"id":"7-1","title_es":"La ropa","words":[{"en":"shirt","es":"camisa","pos":"noun","ex_en":"I need a new shirt for work.","ex_es":"Necesito una camisa nueva para el trabajo."},{"en":"pants","es":"pantalones","pos":"noun","ex_en":"These pants are very comfortable.","ex_es":"Estos pantalones son muy cómodos."},{"en":"dress","es":"vestido","pos":"noun","ex_en":"She has a beautiful dress.","ex_es":"Ella tiene un vestido muy bonito."},{"en":"shoes","es":"zapatos","pos":"noun","ex_en":"My shoes are old.","ex_es":"Mis zapatos están viejos."},{"en":"jacket","es":"chamarra","pos":"noun","ex_en":"Take a jacket. It's cold.","ex_es":"Llévate una chamarra. Hace frío."},{"en":"sweater","es":"suéter","pos":"noun","ex_en":"This sweater is very warm.","ex_es":"Este suéter abriga mucho."},{"en":"socks","es":"calcetines","pos":"noun","ex_en":"I can't find my socks.","ex_es":"No encuentro mis calcetines."},{"en":"wear","es":"usar, traer puesto","pos":"verb","ex_en":"I wear a uniform at work.","ex_es":"Uso uniforme en el trabajo."}],"sentences":[{"en":"I wear pants and a shirt to work.","es":"Uso pantalón y camisa para ir al trabajo."},{"en":"She usually wears a dress on Sundays.","es":"Ella normalmente usa vestido los domingos."},{"en":"Where are my shoes?","es":"¿Dónde están mis zapatos?"},{"en":"Put on your jacket. It's cold outside.","es":"Ponte la chamarra. Hace frío afuera."},{"en":"I need new socks and a sweater.","es":"Necesito calcetines nuevos y un suéter."}],"tip_es":"Pants siempre es plural en inglés: My pants are new, no My pants is new. Para contarlos se dice a pair of pants. Wear es traer puesto, y put on es la acción de ponerse algo."},{"id":"7-2","title_es":"Los colores","words":[{"en":"red","es":"rojo","pos":"adj","ex_en":"She has a red dress.","ex_es":"Ella tiene un vestido rojo."},{"en":"blue","es":"azul","pos":"adj","ex_en":"My favorite color is blue.","ex_es":"Mi color favorito es el azul."},{"en":"green","es":"verde","pos":"adj","ex_en":"He wears a green jacket.","ex_es":"Él usa una chamarra verde."},{"en":"yellow","es":"amarillo","pos":"adj","ex_en":"The taxis in New York are yellow.","ex_es":"Los taxis de Nueva York son amarillos."},{"en":"black","es":"negro","pos":"adj","ex_en":"I need black shoes for the party.","ex_es":"Necesito zapatos negros para la fiesta."},{"en":"white","es":"blanco","pos":"adj","ex_en":"Do you have this shirt in white?","ex_es":"¿Tiene esta camisa en blanco?"},{"en":"gray","es":"gris","pos":"adj","ex_en":"My dad always wears gray pants.","ex_es":"Mi papá siempre usa pantalones grises."},{"en":"pink","es":"rosa","pos":"adj","ex_en":"The baby has pink socks.","ex_es":"La bebé trae calcetines rosas."}],"sentences":[{"en":"What color is your car?","es":"¿De qué color es tu coche?"},{"en":"I like the blue shirt.","es":"Me gusta la camisa azul."},{"en":"She's wearing a black dress and red shoes.","es":"Ella trae un vestido negro y zapatos rojos."},{"en":"Do you have it in green?","es":"¿Lo tiene en verde?"},{"en":"My new sweater is dark gray.","es":"Mi suéter nuevo es gris oscuro."}],"tip_es":"En inglés el color va antes de la cosa y nunca cambia: a red shirt, red shoes. No digas reds shoes ni shoes red. Para preguntar por el color se dice What color is it?"},{"id":"7-3","title_es":"Tallas y probadores","words":[{"en":"size","es":"talla","pos":"noun","ex_en":"What size are you?","ex_es":"¿Qué talla eres?"},{"en":"small","es":"chico","pos":"adj","ex_en":"I need a small, please.","ex_es":"Necesito talla chica, por favor."},{"en":"medium","es":"mediano","pos":"adj","ex_en":"Do you have a medium?","ex_es":"¿Tiene talla mediana?"},{"en":"large","es":"grande","pos":"adj","ex_en":"My husband wears a large.","ex_es":"Mi esposo usa talla grande."},{"en":"try on","es":"probarse","pos":"verb","ex_en":"Can I try on these pants?","ex_es":"¿Me puedo probar estos pantalones?"},{"en":"fitting room","es":"probador","pos":"noun","ex_en":"The fitting room is over there.","ex_es":"El probador está por allá."},{"en":"fit","es":"quedar","pos":"verb","ex_en":"These shoes don't fit me.","ex_es":"Estos zapatos no me quedan."},{"en":"tight","es":"apretado","pos":"adj","ex_en":"This shirt is too tight.","ex_es":"Esta camisa me queda muy apretada."}],"sentences":[{"en":"Excuse me, can I try this on?","es":"Disculpe, ¿me puedo probar esto?"},{"en":"Do you have this in a bigger size?","es":"¿Tiene esto en una talla más grande?"},{"en":"The jacket fits very well.","es":"La chamarra me queda muy bien."},{"en":"These pants are too tight.","es":"Estos pantalones me quedan muy apretados."},{"en":"Where's the fitting room, please?","es":"¿Dónde está el probador, por favor?"}],"tip_es":"Too significa demasiado y suena negativo: too tight, too big. Con try on, si usas it o them va en medio: try it on, nunca try on it."},{"id":"7-4","title_es":"¿Cuánto cuesta?","words":[{"en":"how much","es":"cuánto","pos":"phrase","ex_en":"How much is this jacket?","ex_es":"¿Cuánto cuesta esta chamarra?"},{"en":"cost","es":"costar","pos":"verb","ex_en":"How much do these shoes cost?","ex_es":"¿Cuánto cuestan estos zapatos?"},{"en":"price","es":"precio","pos":"noun","ex_en":"The price is on the tag.","ex_es":"El precio está en la etiqueta."},{"en":"dollar","es":"dólar","pos":"noun","ex_en":"It's twenty dollars.","ex_es":"Son veinte dólares."},{"en":"cheap","es":"barato","pos":"adj","ex_en":"This store is very cheap.","ex_es":"Esta tienda es muy barata."},{"en":"expensive","es":"caro","pos":"adj","ex_en":"That dress is too expensive.","ex_es":"Ese vestido está demasiado caro."},{"en":"sale","es":"oferta, rebaja","pos":"noun","ex_en":"Everything is on sale today.","ex_es":"Todo está en oferta hoy."},{"en":"discount","es":"descuento","pos":"noun","ex_en":"Is there a discount on shoes?","ex_es":"¿Hay descuento en zapatos?"}],"sentences":[{"en":"How much is it?","es":"¿Cuánto cuesta?"},{"en":"It's forty-nine ninety-nine.","es":"Son cuarenta y nueve con noventa y nueve."},{"en":"How much are these socks?","es":"¿Cuánto cuestan estos calcetines?"},{"en":"The sweater is on sale for twenty dollars.","es":"El suéter está en oferta a veinte dólares."},{"en":"It's nice, but it's very expensive.","es":"Está bonito, pero está muy caro."}],"tip_es":"Usa How much is...? para una cosa y How much are...? para varias. Con el verbo cost necesitas do o does: How much does it cost? Los precios se dicen en dos partes: 15.50 es fifteen fifty."},{"id":"7-5","title_es":"This, that, these, those","words":[{"en":"this","es":"este, esta","pos":"pron","ex_en":"This shirt is my size.","ex_es":"Esta camisa es de mi talla."},{"en":"that","es":"ese, esa","pos":"pron","ex_en":"Can I see that belt, please?","ex_es":"¿Me enseña ese cinturón, por favor?"},{"en":"these","es":"estos, estas","pos":"pron","ex_en":"These shoes are on sale.","ex_es":"Estos zapatos están en oferta."},{"en":"those","es":"esos, esas","pos":"pron","ex_en":"Those pants over there are cheap.","ex_es":"Esos pantalones de allá están baratos."},{"en":"pair","es":"par","pos":"noun","ex_en":"I need a new pair of shoes.","ex_es":"Necesito un par de zapatos nuevos."},{"en":"hat","es":"sombrero, gorra","pos":"noun","ex_en":"That hat looks good on you.","ex_es":"Ese sombrero se te ve bien."},{"en":"belt","es":"cinturón","pos":"noun","ex_en":"This belt is too short.","ex_es":"Este cinturón está muy corto."},{"en":"bag","es":"bolsa","pos":"noun","ex_en":"I like those black bags.","ex_es":"Me gustan esas bolsas negras."}],"sentences":[{"en":"I like this one.","es":"Me gusta este."},{"en":"How much are those hats?","es":"¿Cuánto cuestan esos sombreros?"},{"en":"Is that bag on sale?","es":"¿Esa bolsa está en oferta?"},{"en":"These socks are three dollars a pair.","es":"Estos calcetines cuestan tres dólares el par."},{"en":"Can I try on those pants, please?","es":"¿Me puedo probar esos pantalones, por favor?"}],"tip_es":"This y these son para lo que está cerca, y that y those para lo que está lejos. Cuida la pronunciación: this tiene una i corta y these una i larga, como iii. Para no repetir la cosa di this one o that one."},{"id":"7-6","title_es":"En la caja","words":[{"en":"store","es":"tienda","pos":"noun","ex_en":"The store opens at ten.","ex_es":"La tienda abre a las diez."},{"en":"cashier","es":"cajero","pos":"noun","ex_en":"Ask the cashier for a bag.","ex_es":"Pídele una bolsa al cajero."},{"en":"pay","es":"pagar","pos":"verb","ex_en":"Can I pay with my phone?","ex_es":"¿Puedo pagar con mi celular?"},{"en":"cash","es":"efectivo","pos":"noun","ex_en":"Do you have cash?","ex_es":"¿Traes efectivo?"},{"en":"credit card","es":"tarjeta de crédito","pos":"noun","ex_en":"Do you take credit cards?","ex_es":"¿Aceptan tarjeta de crédito?"},{"en":"receipt","es":"ticket, recibo","pos":"noun","ex_en":"Here's your receipt.","ex_es":"Aquí está su ticket."},{"en":"change","es":"cambio","pos":"noun","ex_en":"Here's your change.","ex_es":"Aquí tiene su cambio."},{"en":"return","es":"devolver","pos":"verb","ex_en":"I want to return these shoes.","ex_es":"Quiero devolver estos zapatos."}],"sentences":[{"en":"Cash or credit?","es":"¿Efectivo o tarjeta?"},{"en":"I'd like to pay with a credit card.","es":"Quisiera pagar con tarjeta de crédito."},{"en":"Do you need a bag?","es":"¿Necesita bolsa?"},{"en":"Can I return it if it doesn't fit?","es":"¿Lo puedo devolver si no me queda?"},{"en":"Keep your receipt, please.","es":"Guarde su ticket, por favor."}],"tip_es":"En receipt la p no suena: se pronuncia ri-sít. En México decimos ticket de compra, pero en inglés ticket es un boleto o una multa. Para el comprobante de pago di receipt."},{"id":"7-7","title_es":"Más ropa y accesorios","words":[{"en":"jeans","es":"pantalones de mezclilla","pos":"noun","ex_en":"These jeans are my favorite.","ex_es":"Estos pantalones de mezclilla son mis favoritos."},{"en":"skirt","es":"falda","pos":"noun","ex_en":"She's wearing a long skirt.","ex_es":"Ella trae una falda larga."},{"en":"shorts","es":"shorts","pos":"noun","ex_en":"I wear shorts in the summer.","ex_es":"Uso shorts en el verano."},{"en":"coat","es":"abrigo","pos":"noun","ex_en":"Take your coat. It's cold.","ex_es":"Llévate tu abrigo. Hace frío."},{"en":"boots","es":"botas","pos":"noun","ex_en":"I need new boots for winter.","ex_es":"Necesito botas nuevas para el invierno."},{"en":"sneakers","es":"tenis","pos":"noun","ex_en":"He always wears white sneakers.","ex_es":"Él siempre usa tenis blancos."},{"en":"scarf","es":"bufanda","pos":"noun","ex_en":"I wear a scarf in winter.","ex_es":"Uso bufanda en invierno."},{"en":"sunglasses","es":"lentes de sol","pos":"noun","ex_en":"Where are my sunglasses?","ex_es":"¿Dónde están mis lentes de sol?"}],"sentences":[{"en":"I usually wear jeans and sneakers.","es":"Normalmente uso pantalones de mezclilla y tenis."},{"en":"Are these boots on sale?","es":"¿Estas botas están en oferta?"},{"en":"She's wearing a black skirt today.","es":"Hoy ella trae una falda negra."},{"en":"Don't forget your coat and scarf.","es":"No olvides tu abrigo y tu bufanda."},{"en":"How much are those sunglasses?","es":"¿Cuánto cuestan esos lentes de sol?"}],"tip_es":"Igual que pants, las palabras jeans, shorts y sunglasses siempre son plurales: These jeans are new. Ojo, en México decimos tenis, pero en inglés son sneakers, y tennis es el deporte."},{"id":"7-8","title_es":"Cómo es la ropa","words":[{"en":"comfortable","es":"cómodo","pos":"adj","ex_en":"These shoes are very comfortable.","ex_es":"Estos zapatos son muy cómodos."},{"en":"loose","es":"holgado, flojo","pos":"adj","ex_en":"This shirt is a little loose.","ex_es":"Esta camisa me queda un poco floja."},{"en":"long","es":"largo","pos":"adj","ex_en":"I like long dresses.","ex_es":"Me gustan los vestidos largos."},{"en":"short","es":"corto","pos":"adj","ex_en":"The sleeves are too short.","ex_es":"Las mangas están demasiado cortas."},{"en":"cotton","es":"algodón","pos":"noun","ex_en":"I prefer cotton socks.","ex_es":"Prefiero los calcetines de algodón."},{"en":"pretty","es":"bonito","pos":"adj","ex_en":"What a pretty dress!","ex_es":"¡Qué vestido tan bonito!"},{"en":"plain","es":"liso","pos":"adj","ex_en":"I want a plain white shirt.","ex_es":"Quiero una camisa blanca lisa."},{"en":"striped","es":"a rayas","pos":"adj","ex_en":"He has a striped sweater.","ex_es":"Él tiene un suéter a rayas."}],"sentences":[{"en":"These sneakers are really comfortable.","es":"Estos tenis son muy cómodos."},{"en":"Is this shirt cotton?","es":"¿Esta camisa es de algodón?"},{"en":"The skirt is pretty, but it's too short.","es":"La falda está bonita, pero está demasiado corta."},{"en":"Do you have this in a plain color?","es":"¿Lo tiene en un color liso?"},{"en":"I like loose pants for the weekend.","es":"Me gustan los pantalones holgados para el fin de semana."}],"tip_es":"En comfortable la sílaba fuerte es la primera y suena como cámf-ter-bol. Cuando hay varios adjetivos, la opinión va primero y el material al final: a pretty cotton dress."},{"id":"7-9","title_es":"Comparar y escoger","words":[{"en":"bigger","es":"más grande","pos":"adj","ex_en":"I need a bigger size.","ex_es":"Necesito una talla más grande."},{"en":"smaller","es":"más chico","pos":"adj","ex_en":"Do you have a smaller one?","ex_es":"¿Tiene uno más chico?"},{"en":"cheaper","es":"más barato","pos":"adj","ex_en":"This bag is cheaper.","ex_es":"Esta bolsa es más barata."},{"en":"more expensive","es":"más caro","pos":"adj","ex_en":"The black coat is more expensive.","ex_es":"El abrigo negro es más caro."},{"en":"better","es":"mejor","pos":"adj","ex_en":"This color is better on you.","ex_es":"Este color se te ve mejor."},{"en":"than","es":"que","pos":"conj","ex_en":"Boots are warmer than sneakers.","ex_es":"Las botas son más calientitas que los tenis."},{"en":"prefer","es":"preferir","pos":"verb","ex_en":"I prefer the blue one.","ex_es":"Prefiero el azul."},{"en":"which one","es":"cuál","pos":"phrase","ex_en":"Which one do you like?","ex_es":"¿Cuál te gusta?"}],"sentences":[{"en":"Which one is cheaper?","es":"¿Cuál es más barato?"},{"en":"The red dress is prettier than the green one.","es":"El vestido rojo es más bonito que el verde."},{"en":"These jeans are more expensive than those.","es":"Estos pantalones son más caros que esos."},{"en":"I prefer this jacket. It's more comfortable.","es":"Prefiero esta chamarra. Es más cómoda."},{"en":"Do you have these shoes in a smaller size?","es":"¿Tiene estos zapatos en una talla más chica?"}],"tip_es":"Con adjetivos cortos agrega -er: cheap, cheaper. Con adjetivos largos usa more: more expensive. Good cambia a better. Para comparar dos cosas usa than, no that."},{"id":"7-10","title_es":"En la vida real: de compras","words":[{"en":"mall","es":"centro comercial","pos":"noun","ex_en":"Let's go to the mall on Saturday.","ex_es":"Vamos al centro comercial el sábado."},{"en":"online","es":"en línea","pos":"adv","ex_en":"I buy a lot of clothes online.","ex_es":"Compro mucha ropa en línea."},{"en":"buy","es":"comprar","pos":"verb","ex_en":"I want to buy a new dress.","ex_es":"Quiero comprar un vestido nuevo."},{"en":"look for","es":"buscar","pos":"verb","ex_en":"Can you help me look for my size?","ex_es":"¿Me ayuda a buscar mi talla?"},{"en":"just looking","es":"solo estoy viendo","pos":"phrase","ex_en":"No, thanks. I'm just looking.","ex_es":"No, gracias. Solo estoy viendo."},{"en":"gift","es":"regalo","pos":"noun","ex_en":"This is a gift for my sister.","ex_es":"Es un regalo para mi hermana."},{"en":"exchange","es":"cambiar","pos":"verb","ex_en":"Can I exchange these shoes?","ex_es":"¿Puedo cambiar estos zapatos?"},{"en":"refund","es":"reembolso","pos":"noun","ex_en":"I'd like a refund, please.","ex_es":"Quiero un reembolso, por favor."}],"sentences":[{"en":"Can I help you? No, thanks, I'm just looking.","es":"¿Le ayudo? No, gracias, solo estoy viendo."},{"en":"I'm looking for a gift for my mom.","es":"Busco un regalo para mi mamá."},{"en":"Is it cheaper online or at the mall?","es":"¿Es más barato en línea o en el centro comercial?"},{"en":"Can I exchange this for a bigger size?","es":"¿Puedo cambiar esto por una talla más grande?"},{"en":"Here's my receipt. Can I get a refund?","es":"Aquí está mi ticket. ¿Me pueden reembolsar?"}],"tip_es":"Si un vendedor te pregunta Can I help you? y no necesitas nada, contesta I'm just looking. Exchange es cambiar por otra cosa y refund es que te devuelvan el dinero."}],"dialogue":{"title_es":"En una tienda de ropa","setting_es":"Estás en un centro comercial y quieres comprar una chamarra.","lines":[{"who":"A","en":"Hi there! Can I help you?","es":"¡Hola! ¿En qué le puedo ayudar?"},{"who":"B","en":"Yes, how much is this jacket?","es":"Sí, ¿cuánto cuesta esta chamarra?"},{"who":"A","en":"It's sixty dollars, but it's on sale today.","es":"Cuesta sesenta dólares, pero hoy está en oferta."},{"who":"B","en":"Great! Do you have it in black?","es":"¡Qué bien! ¿La tiene en negro?"},{"who":"A","en":"Yes. What size are you?","es":"Sí. ¿Qué talla es?"},{"who":"B","en":"Medium, I think. Can I try it on?","es":"Mediana, creo. ¿Me la puedo probar?"},{"who":"A","en":"Sure. The fitting room is over there.","es":"Claro. El probador está por allá."},{"who":"B","en":"It fits well. I'll take it.","es":"Me queda bien. Me la llevo."},{"who":"A","en":"Perfect. Cash or credit card?","es":"Perfecto. ¿Efectivo o tarjeta de crédito?"},{"who":"B","en":"Credit card, please.","es":"Con tarjeta, por favor."}]}},{"id":8,"title_es":"Ciudad, direcciones y transporte","title_en":"Getting around the city","level":"A2","goal_es":"Al terminar podrás pedir y dar indicaciones, usar el transporte y decir qué está pasando ahora.","lessons":[{"id":"8-1","title_es":"Lugares de la ciudad","words":[{"en":"bank","es":"banco","pos":"noun","ex_en":"The bank closes at four.","ex_es":"El banco cierra a las cuatro."},{"en":"pharmacy","es":"farmacia","pos":"noun","ex_en":"Is there a pharmacy near here?","ex_es":"¿Hay una farmacia cerca de aquí?"},{"en":"supermarket","es":"supermercado","pos":"noun","ex_en":"I buy food at the supermarket.","ex_es":"Compro comida en el supermercado."},{"en":"hospital","es":"hospital","pos":"noun","ex_en":"The hospital is on Main Street.","ex_es":"El hospital está en la calle Main."},{"en":"park","es":"parque","pos":"noun","ex_en":"The kids play in the park.","ex_es":"Los niños juegan en el parque."},{"en":"museum","es":"museo","pos":"noun","ex_en":"The museum is free on Sundays.","ex_es":"El museo es gratis los domingos."},{"en":"post office","es":"oficina de correos","pos":"noun","ex_en":"Where's the post office?","ex_es":"¿Dónde está la oficina de correos?"},{"en":"gas station","es":"gasolinera","pos":"noun","ex_en":"There's a gas station on this street.","ex_es":"Hay una gasolinera en esta calle."}],"sentences":[{"en":"Where's the bank?","es":"¿Dónde está el banco?"},{"en":"The pharmacy is next to the supermarket.","es":"La farmacia está al lado del supermercado."},{"en":"Is there a park near your house?","es":"¿Hay un parque cerca de tu casa?"},{"en":"The post office is closed on Sundays.","es":"La oficina de correos cierra los domingos."},{"en":"We need gas. Is there a gas station nearby?","es":"Necesitamos gasolina. ¿Hay una gasolinera cerca?"}],"tip_es":"Con lugares de la ciudad se usa the: go to the bank, go to the park. Pero se dice go to work, go to school y go home sin artículo. En pharmacy, ph suena como f."},{"id":"8-2","title_es":"Izquierda, derecha y derecho","words":[{"en":"turn","es":"dar vuelta","pos":"verb","ex_en":"Turn at the next street.","ex_es":"Da vuelta en la siguiente calle."},{"en":"left","es":"izquierda","pos":"noun","ex_en":"Turn left at the bank.","ex_es":"Da vuelta a la izquierda en el banco."},{"en":"right","es":"derecha","pos":"noun","ex_en":"The museum is on your right.","ex_es":"El museo está a tu derecha."},{"en":"straight ahead","es":"derecho","pos":"adv","ex_en":"Go straight ahead for two blocks.","ex_es":"Sigue derecho dos cuadras."},{"en":"corner","es":"esquina","pos":"noun","ex_en":"The store is on the corner.","ex_es":"La tienda está en la esquina."},{"en":"block","es":"cuadra","pos":"noun","ex_en":"It's three blocks from here.","ex_es":"Está a tres cuadras de aquí."},{"en":"street","es":"calle","pos":"noun","ex_en":"What street is it on?","ex_es":"¿En qué calle está?"},{"en":"traffic light","es":"semáforo","pos":"noun","ex_en":"Turn right at the traffic light.","ex_es":"Da vuelta a la derecha en el semáforo."}],"sentences":[{"en":"Go straight ahead and turn left.","es":"Sigue derecho y da vuelta a la izquierda."},{"en":"The bank is on the corner.","es":"El banco está en la esquina."},{"en":"Turn right at the second traffic light.","es":"Da vuelta a la derecha en el segundo semáforo."},{"en":"The park is two blocks from here.","es":"El parque está a dos cuadras de aquí."},{"en":"The pharmacy is on the left.","es":"La farmacia está a la izquierda."}],"tip_es":"Cuidado: derecho (seguir sin dar vuelta) es straight, y derecha es right. Si dices go right, la persona va a dar vuelta. Recuerda las preposiciones: on the corner, at the traffic light, on your left."},{"id":"8-3","title_es":"El transporte","words":[{"en":"bus","es":"camión, autobús","pos":"noun","ex_en":"I take the bus to work.","ex_es":"Tomo el camión para ir al trabajo."},{"en":"subway","es":"metro","pos":"noun","ex_en":"The subway is fast and cheap.","ex_es":"El metro es rápido y barato."},{"en":"taxi","es":"taxi","pos":"noun","ex_en":"Let's take a taxi. It's late.","ex_es":"Tomemos un taxi. Ya es tarde."},{"en":"train","es":"tren","pos":"noun","ex_en":"The train leaves at nine.","ex_es":"El tren sale a las nueve."},{"en":"bike","es":"bici","pos":"noun","ex_en":"I go to work by bike.","ex_es":"Voy al trabajo en bici."},{"en":"bus stop","es":"parada del camión","pos":"noun","ex_en":"The bus stop is on the corner.","ex_es":"La parada del camión está en la esquina."},{"en":"ticket","es":"boleto","pos":"noun","ex_en":"How much is a train ticket?","ex_es":"¿Cuánto cuesta un boleto de tren?"},{"en":"by car","es":"en coche","pos":"phrase","ex_en":"We go to the beach by car.","ex_es":"Vamos a la playa en coche."}],"sentences":[{"en":"How do you get to work?","es":"¿Cómo te vas al trabajo?"},{"en":"I usually take the subway.","es":"Normalmente tomo el metro."},{"en":"She goes to school by bus.","es":"Ella va a la escuela en camión."},{"en":"Where can I buy a ticket?","es":"¿Dónde puedo comprar un boleto?"},{"en":"Does this bus go to the airport?","es":"¿Este camión va al aeropuerto?"}],"tip_es":"Con by no se usa artículo: by bus, by car, by train. Pero a pie es on foot, no by foot. Con take sí va the: take the bus, take the subway."},{"id":"8-4","title_es":"Pedir indicaciones","words":[{"en":"how do I get to","es":"cómo llego a","pos":"phrase","ex_en":"How do I get to the museum?","ex_es":"¿Cómo llego al museo?"},{"en":"cross","es":"cruzar","pos":"verb","ex_en":"Cross the street at the light.","ex_es":"Cruza la calle en el semáforo."},{"en":"follow","es":"seguir","pos":"verb","ex_en":"Follow this street to the park.","ex_es":"Sigue esta calle hasta el parque."},{"en":"stop","es":"parar, detenerse","pos":"verb","ex_en":"Stop at the corner, please.","ex_es":"Pare en la esquina, por favor."},{"en":"keep going","es":"seguir adelante","pos":"phrase","ex_en":"Keep going until you see the bank.","ex_es":"Sigue adelante hasta que veas el banco."},{"en":"map","es":"mapa","pos":"noun","ex_en":"Can you show me on the map?","ex_es":"¿Me lo puede enseñar en el mapa?"},{"en":"lost","es":"perdido","pos":"adj","ex_en":"Excuse me, I'm lost.","ex_es":"Disculpe, estoy perdido."},{"en":"directions","es":"indicaciones","pos":"noun","ex_en":"Can you give me directions?","ex_es":"¿Me puede dar indicaciones?"}],"sentences":[{"en":"Excuse me, how do I get to the bank?","es":"Disculpe, ¿cómo llego al banco?"},{"en":"Cross the street and turn right.","es":"Cruza la calle y da vuelta a la derecha."},{"en":"Don't turn here. Keep going.","es":"No des vuelta aquí. Sigue adelante."},{"en":"Follow the signs to the subway.","es":"Sigue los letreros hacia el metro."},{"en":"We're lost. Do you have a map?","es":"Estamos perdidos. ¿Tienes un mapa?"}],"tip_es":"El imperativo es el verbo en forma base sin sujeto: Turn left, Cross the street. Para negar usa Don't: Don't turn here. Ojo, falso amigo: directions son indicaciones, y dirección (de una casa) es address."},{"id":"8-5","title_es":"¿Qué estás haciendo ahorita?","words":[{"en":"right now","es":"ahorita, ahora mismo","pos":"adv","ex_en":"I'm driving right now.","ex_es":"Ahorita voy manejando."},{"en":"at the moment","es":"en este momento","pos":"phrase","ex_en":"He's working at the moment.","ex_es":"Él está trabajando en este momento."},{"en":"drive","es":"manejar","pos":"verb","ex_en":"I'm learning to drive.","ex_es":"Estoy aprendiendo a manejar."},{"en":"wait","es":"esperar","pos":"verb","ex_en":"I'm waiting for the bus.","ex_es":"Estoy esperando el camión."},{"en":"arrive","es":"llegar","pos":"verb","ex_en":"The train arrives at six.","ex_es":"El tren llega a las seis."},{"en":"ride","es":"andar en, viajar en","pos":"verb","ex_en":"Do you ride the subway every day?","ex_es":"¿Viajas en metro todos los días?"},{"en":"get on","es":"subirse a","pos":"phrase","ex_en":"Get on the bus at the front.","ex_es":"Súbete al camión por adelante."},{"en":"get off","es":"bajarse de","pos":"phrase","ex_en":"Get off at the next stop.","ex_es":"Bájate en la siguiente parada."}],"sentences":[{"en":"Where are you? I'm waiting for you.","es":"¿Dónde estás? Te estoy esperando."},{"en":"I'm riding the subway right now.","es":"Ahorita voy en el metro."},{"en":"We're getting off at the next stop.","es":"Nos bajamos en la siguiente parada."},{"en":"Is she driving or taking the train?","es":"¿Ella viene manejando o en tren?"},{"en":"The bus isn't coming. Let's take a taxi.","es":"El camión no viene. Vamos a tomar un taxi."}],"tip_es":"El presente continuo (am, is, are + verbo con -ing) es para lo que pasa ahora. Si el verbo termina en e, quítala: drive, driving. Si termina en vocal + consonante, dobla la consonante: get, getting. Para rutinas usa presente simple: I take the bus every day."},{"id":"8-6","title_es":"Por la ciudad","words":[{"en":"traffic","es":"tráfico","pos":"noun","ex_en":"There's a lot of traffic today.","ex_es":"Hay mucho tráfico hoy."},{"en":"rush hour","es":"hora pico","pos":"noun","ex_en":"Don't drive at rush hour.","ex_es":"No manejes en hora pico."},{"en":"station","es":"estación","pos":"noun","ex_en":"Meet me at the train station.","ex_es":"Te veo en la estación del tren."},{"en":"downtown","es":"el centro","pos":"adv","ex_en":"I work downtown.","ex_es":"Trabajo en el centro."},{"en":"neighborhood","es":"colonia, barrio","pos":"noun","ex_en":"My neighborhood is very quiet.","ex_es":"Mi colonia es muy tranquila."},{"en":"sidewalk","es":"banqueta","pos":"noun","ex_en":"Walk on the sidewalk, please.","ex_es":"Camina por la banqueta, por favor."},{"en":"bridge","es":"puente","pos":"noun","ex_en":"Cross the bridge and turn left.","ex_es":"Cruza el puente y da vuelta a la izquierda."},{"en":"crowded","es":"lleno de gente","pos":"adj","ex_en":"The subway is crowded at eight.","ex_es":"El metro va lleno a las ocho."}],"sentences":[{"en":"The traffic is terrible right now.","es":"El tráfico está horrible ahorita."},{"en":"Is the station far from downtown?","es":"¿La estación está lejos del centro?"},{"en":"The bus is very crowded at rush hour.","es":"El camión va muy lleno en hora pico."},{"en":"I live in a quiet neighborhood near the park.","es":"Vivo en una colonia tranquila cerca del parque."},{"en":"We're crossing the bridge. We're almost there!","es":"Estamos cruzando el puente. ¡Ya casi llegamos!"}],"tip_es":"Downtown no lleva the ni to: I go downtown es voy al centro, no I go to the downtown. Traffic no se cuenta: di a lot of traffic, nunca traffics."},{"id":"8-7","title_es":"¿Dónde está?","words":[{"en":"next to","es":"al lado de","pos":"prep","ex_en":"The bank is next to the park.","ex_es":"El banco está al lado del parque."},{"en":"across from","es":"enfrente de","pos":"prep","ex_en":"The pharmacy is across from the bank.","ex_es":"La farmacia está enfrente del banco."},{"en":"between","es":"entre","pos":"prep","ex_en":"The café is between two stores.","ex_es":"La cafetería está entre dos tiendas."},{"en":"behind","es":"detrás de","pos":"prep","ex_en":"The parking is behind the hospital.","ex_es":"El estacionamiento está detrás del hospital."},{"en":"in front of","es":"delante de","pos":"prep","ex_en":"I'm in front of the museum.","ex_es":"Estoy delante del museo."},{"en":"near","es":"cerca de","pos":"prep","ex_en":"Is there a bank near here?","ex_es":"¿Hay un banco cerca de aquí?"},{"en":"far","es":"lejos","pos":"adj","ex_en":"The airport is far from downtown.","ex_es":"El aeropuerto está lejos del centro."},{"en":"around the corner","es":"a la vuelta","pos":"phrase","ex_en":"The bus stop is around the corner.","ex_es":"La parada está a la vuelta."}],"sentences":[{"en":"Is the museum far from here?","es":"¿El museo está lejos de aquí?"},{"en":"The hotel is across from the station.","es":"El hotel está enfrente de la estación."},{"en":"There's a pharmacy around the corner.","es":"Hay una farmacia a la vuelta."},{"en":"The bank is between the park and the hospital.","es":"El banco está entre el parque y el hospital."},{"en":"I'm waiting in front of the post office.","es":"Estoy esperando delante de la oficina de correos."}],"tip_es":"Para enfrente, cruzando la calle, usa across from. In front of es delante de, pegado a algo. Near y far from te ayudan a decir la distancia: near the park, far from here."},{"id":"8-8","title_es":"En el aeropuerto","words":[{"en":"airport","es":"aeropuerto","pos":"noun","ex_en":"The airport is very big.","ex_es":"El aeropuerto es muy grande."},{"en":"plane","es":"avión","pos":"noun","ex_en":"The plane is full today.","ex_es":"El avión va lleno hoy."},{"en":"flight","es":"vuelo","pos":"noun","ex_en":"My flight is at ten.","ex_es":"Mi vuelo es a las diez."},{"en":"suitcase","es":"maleta","pos":"noun","ex_en":"My suitcase is very heavy.","ex_es":"Mi maleta está muy pesada."},{"en":"passport","es":"pasaporte","pos":"noun","ex_en":"Don't forget your passport.","ex_es":"No olvides tu pasaporte."},{"en":"gate","es":"sala, puerta de abordaje","pos":"noun","ex_en":"Our gate is number twelve.","ex_es":"Nuestra sala es la número doce."},{"en":"boarding pass","es":"pase de abordar","pos":"noun","ex_en":"Can I see your boarding pass?","ex_es":"¿Me permite su pase de abordar?"},{"en":"delayed","es":"retrasado","pos":"adj","ex_en":"Our flight is delayed.","ex_es":"Nuestro vuelo está retrasado."}],"sentences":[{"en":"Excuse me, where is gate five?","es":"Disculpe, ¿dónde está la sala cinco?"},{"en":"Your passport and boarding pass, please.","es":"Su pasaporte y pase de abordar, por favor."},{"en":"The flight to Chicago is delayed.","es":"El vuelo a Chicago está retrasado."},{"en":"We're waiting for our suitcases right now.","es":"Ahorita estamos esperando nuestras maletas."},{"en":"Is this the bus to the airport?","es":"¿Este es el camión al aeropuerto?"}],"tip_es":"Plane es el avión y flight es el vuelo, el viaje. Se dice by plane o take a plane. En los aeropuertos de EE. UU. escucharás mucho boarding, que significa abordando."},{"id":"8-9","title_es":"En el coche","words":[{"en":"parking lot","es":"estacionamiento","pos":"noun","ex_en":"The parking lot is full.","ex_es":"El estacionamiento está lleno."},{"en":"highway","es":"carretera","pos":"noun","ex_en":"Take the highway to the airport.","ex_es":"Toma la carretera al aeropuerto."},{"en":"seat belt","es":"cinturón de seguridad","pos":"noun","ex_en":"Put on your seat belt.","ex_es":"Ponte el cinturón de seguridad."},{"en":"slow down","es":"bajar la velocidad","pos":"verb","ex_en":"Slow down, please!","ex_es":"¡Baja la velocidad, por favor!"},{"en":"hurry up","es":"apurarse","pos":"verb","ex_en":"Hurry up! We're late.","ex_es":"¡Apúrate! Vamos tarde."},{"en":"fast","es":"rápido","pos":"adv","ex_en":"Don't drive so fast.","ex_es":"No manejes tan rápido."},{"en":"careful","es":"cuidadoso","pos":"adj","ex_en":"Be careful on the highway.","ex_es":"Ten cuidado en la carretera."},{"en":"accident","es":"accidente","pos":"noun","ex_en":"There's an accident on the bridge.","ex_es":"Hay un accidente en el puente."}],"sentences":[{"en":"Put on your seat belt, please.","es":"Ponte el cinturón, por favor."},{"en":"Slow down! You're driving too fast.","es":"¡Baja la velocidad! Vas manejando muy rápido."},{"en":"Is there a parking lot near the museum?","es":"¿Hay un estacionamiento cerca del museo?"},{"en":"Be careful. The highway is very crowded.","es":"Ten cuidado. La carretera está muy llena."},{"en":"There's an accident, so we're taking another street.","es":"Hay un accidente, así que vamos por otra calle."}],"tip_es":"Para advertir a alguien usa el imperativo: Slow down, Hurry up, Be careful. Fíjate que be careful necesita be, porque careful es adjetivo. Parking lot es el estacionamiento al aire libre."},{"id":"8-10","title_es":"En la vida real: moverse por la ciudad","words":[{"en":"how far","es":"qué tan lejos","pos":"phrase","ex_en":"How far is the hotel?","ex_es":"¿Qué tan lejos está el hotel?"},{"en":"how long","es":"cuánto tiempo","pos":"phrase","ex_en":"How long is the trip?","ex_es":"¿Cuánto dura el viaje?"},{"en":"it takes","es":"se hace, tarda","pos":"phrase","ex_en":"It takes an hour by bus.","ex_es":"Se hace una hora en camión."},{"en":"on foot","es":"a pie","pos":"phrase","ex_en":"The park is ten minutes on foot.","ex_es":"El parque está a diez minutos a pie."},{"en":"miss","es":"perder","pos":"verb","ex_en":"I don't want to miss my flight.","ex_es":"No quiero perder mi vuelo."},{"en":"next","es":"siguiente, próximo","pos":"adj","ex_en":"Get off at the next stop.","ex_es":"Bájate en la siguiente parada."},{"en":"transfer","es":"transbordar","pos":"verb","ex_en":"Transfer to the green line here.","ex_es":"Transborda a la línea verde aquí."},{"en":"fare","es":"pasaje, tarifa","pos":"noun","ex_en":"The bus fare is two dollars.","ex_es":"El pasaje del camión cuesta dos dólares."}],"sentences":[{"en":"How far is the museum from here?","es":"¿Qué tan lejos está el museo de aquí?"},{"en":"It takes about ten minutes on foot.","es":"Se hace como diez minutos a pie."},{"en":"How long does it take by subway?","es":"¿Cuánto se hace en metro?"},{"en":"Transfer to the blue line at the next station.","es":"Transborda a la línea azul en la siguiente estación."},{"en":"Don't miss the last train. It leaves at midnight.","es":"No pierdas el último tren. Sale a la medianoche."}],"tip_es":"How far pregunta por la distancia y how long por el tiempo. Para contestar usa It takes más el tiempo: It takes twenty minutes. Recuerda que a pie es on foot, no by foot."}],"dialogue":{"title_es":"¿Cómo llego al museo?","setting_es":"Estás de visita en Chicago y una señora te ayuda a llegar al museo.","lines":[{"who":"A","en":"Hi! Are you OK? You look lost.","es":"¡Hola! ¿Estás bien? Te ves perdido."},{"who":"B","en":"Yes. How do I get to the museum?","es":"Sí. ¿Cómo llego al museo?"},{"who":"A","en":"It's far. You can take the subway.","es":"Está lejos. Puedes tomar el metro."},{"who":"B","en":"Where is the subway station?","es":"¿Dónde está la estación del metro?"},{"who":"A","en":"Go straight ahead and turn left at the light.","es":"Sigue derecho y da vuelta a la izquierda en el semáforo."},{"who":"B","en":"And then?","es":"¿Y luego?"},{"who":"A","en":"The station is on the corner, by a bank.","es":"La estación está en la esquina, junto a un banco."},{"who":"B","en":"Great. Where do I get off?","es":"Perfecto. ¿Dónde me bajo?"},{"who":"A","en":"Get off at Lake Street. It's three stops.","es":"Bájate en Lake Street. Son tres paradas."},{"who":"B","en":"Thank you so much!","es":"¡Muchísimas gracias!"}]}},{"id":9,"title_es":"El pasado: fin de semana y vacaciones","title_en":"Last weekend","level":"A2","goal_es":"Al terminar podrás contar qué hiciste ayer, el fin de semana y en tus vacaciones.","lessons":[{"id":"9-1","title_es":"Ayer: was y were","words":[{"en":"yesterday","es":"ayer","pos":"adv","ex_en":"I was very busy yesterday.","ex_es":"Ayer estuve muy ocupado."},{"en":"last night","es":"anoche","pos":"phrase","ex_en":"Where were you last night?","ex_es":"¿Dónde estabas anoche?"},{"en":"last week","es":"la semana pasada","pos":"phrase","ex_en":"We were in Puebla last week.","ex_es":"Estuvimos en Puebla la semana pasada."},{"en":"last month","es":"el mes pasado","pos":"phrase","ex_en":"My cousin was here last month.","ex_es":"Mi primo estuvo aquí el mes pasado."},{"en":"ago","es":"hace (tiempo)","pos":"adv","ex_en":"I was in Cancún two years ago.","ex_es":"Estuve en Cancún hace dos años."},{"en":"the day before yesterday","es":"antier","pos":"phrase","ex_en":"The day before yesterday was my birthday.","ex_es":"Antier fue mi cumpleaños."},{"en":"born","es":"nacido","pos":"adj","ex_en":"I was born in Monterrey.","ex_es":"Nací en Monterrey."},{"en":"bored","es":"aburrido","pos":"adj","ex_en":"The kids were bored at home.","ex_es":"Los niños estaban aburridos en casa."}],"sentences":[{"en":"I was at home last night.","es":"Estuve en casa anoche."},{"en":"Were you tired yesterday?","es":"¿Estabas cansado ayer?"},{"en":"The movie was very good.","es":"La película estuvo muy buena."},{"en":"We weren't at school last week.","es":"No estuvimos en la escuela la semana pasada."},{"en":"Where was your sister born?","es":"¿Dónde nació tu hermana?"}],"tip_es":"El pasado de to be tiene dos formas: was (con I, he, she, it) y were (con you, we, they). Para decir hace dos años, ago va después del tiempo: two years ago, nunca ago two years. Y para decir nací se usa I was born."},{"id":"9-2","title_es":"Verbos regulares con -ed","words":[{"en":"watch / watched","es":"ver / vi","pos":"verb","ex_en":"We watched a movie last night.","ex_es":"Vimos una película anoche."},{"en":"visit / visited","es":"visitar / visité","pos":"verb","ex_en":"I visited my grandma on Sunday.","ex_es":"Visité a mi abuela el domingo."},{"en":"play / played","es":"jugar / jugué","pos":"verb","ex_en":"They played soccer in the park.","ex_es":"Jugaron futbol en el parque."},{"en":"stay / stayed","es":"quedarse / me quedé","pos":"verb","ex_en":"She stayed home all weekend.","ex_es":"Se quedó en casa todo el fin de semana."},{"en":"clean / cleaned","es":"limpiar / limpié","pos":"verb","ex_en":"I cleaned my room yesterday.","ex_es":"Limpié mi cuarto ayer."},{"en":"cook / cooked","es":"cocinar / cociné","pos":"verb","ex_en":"My dad cooked enchiladas for us.","ex_es":"Mi papá nos cocinó enchiladas."},{"en":"study / studied","es":"estudiar / estudié","pos":"verb","ex_en":"Luis studied English last night.","ex_es":"Luis estudió inglés anoche."},{"en":"call / called","es":"llamar / llamé","pos":"verb","ex_en":"I called my mom this morning.","ex_es":"Le hablé a mi mamá esta mañana."}],"sentences":[{"en":"I worked late on Friday.","es":"Trabajé tarde el viernes."},{"en":"We walked to the market.","es":"Caminamos al mercado."},{"en":"She listened to music all afternoon.","es":"Escuchó música toda la tarde."},{"en":"They watched TV and cooked dinner.","es":"Vieron la tele y cocinaron la cena."},{"en":"I visited Oaxaca with my family last summer.","es":"Visité Oaxaca con mi familia el verano pasado."}],"tip_es":"Los verbos regulares forman el pasado con -ed y es igual para todas las personas: I played, she played. Si terminan en consonante + y, cambian a -ied (study, studied), pero play y stay solo agregan -ed. Ojo: en worked y cooked la -ed suena como una t, no como sílaba extra."},{"id":"9-3","title_es":"Verbos irregulares","words":[{"en":"go / went","es":"ir / fui","pos":"verb","ex_en":"We went to the movies on Saturday.","ex_es":"Fuimos al cine el sábado."},{"en":"have / had","es":"tener / tuve","pos":"verb","ex_en":"I had a great weekend.","ex_es":"Tuve un fin de semana excelente."},{"en":"eat / ate","es":"comer / comí","pos":"verb","ex_en":"They ate tacos al pastor last night.","ex_es":"Comieron tacos al pastor anoche."},{"en":"see / saw","es":"ver / vi","pos":"verb","ex_en":"I saw your brother at the mall.","ex_es":"Vi a tu hermano en la plaza."},{"en":"buy / bought","es":"comprar / compré","pos":"verb","ex_en":"She bought new shoes yesterday.","ex_es":"Compró zapatos nuevos ayer."},{"en":"get / got","es":"llegar, conseguir / llegué","pos":"verb","ex_en":"I got home at eleven.","ex_es":"Llegué a casa a las once."},{"en":"make / made","es":"hacer / hice","pos":"verb","ex_en":"My grandma made tamales for everyone.","ex_es":"Mi abuela hizo tamales para todos."},{"en":"drink / drank","es":"tomar, beber / tomé","pos":"verb","ex_en":"We drank coffee after lunch.","ex_es":"Tomamos café después de comer."}],"sentences":[{"en":"I went to bed early.","es":"Me fui a dormir temprano."},{"en":"We had breakfast at a café.","es":"Desayunamos en un café."},{"en":"He bought a gift for his wife.","es":"Compró un regalo para su esposa."},{"en":"I saw a great movie last weekend.","es":"Vi una película muy buena el fin de semana pasado."},{"en":"My friends came over and we made pizza.","es":"Mis amigos vinieron y hicimos pizza."}],"tip_es":"Los verbos irregulares no usan -ed y hay que memorizarlos: go se vuelve went, eat se vuelve ate y buy se vuelve bought. La buena noticia es que la forma es igual para todas las personas: I went, she went, they went."},{"id":"9-4","title_es":"Preguntas y negativos con did","words":[{"en":"did","es":"auxiliar del pasado","pos":"verb","ex_en":"Did you have a good weekend?","ex_es":"¿Pasaste un buen fin de semana?"},{"en":"didn't","es":"no (en pasado)","pos":"verb","ex_en":"I didn't go to the party.","ex_es":"No fui a la fiesta."},{"en":"what did you do","es":"qué hiciste","pos":"phrase","ex_en":"What did you do on Sunday?","ex_es":"¿Qué hiciste el domingo?"},{"en":"how was","es":"qué tal estuvo","pos":"phrase","ex_en":"How was your trip to Guadalajara?","ex_es":"¿Qué tal tu viaje a Guadalajara?"},{"en":"fun","es":"divertido","pos":"adj","ex_en":"The party was really fun.","ex_es":"La fiesta estuvo muy divertida."},{"en":"boring","es":"aburrido","pos":"adj","ex_en":"The class was long and boring.","ex_es":"La clase fue larga y aburrida."},{"en":"relax / relaxed","es":"relajarse / me relajé","pos":"verb","ex_en":"We relaxed at home on Sunday.","ex_es":"Nos relajamos en casa el domingo."},{"en":"sleep / slept","es":"dormir / dormí","pos":"verb","ex_en":"I slept ten hours last night.","ex_es":"Dormí diez horas anoche."}],"sentences":[{"en":"Did you sleep well?","es":"¿Dormiste bien?"},{"en":"She didn't call me yesterday.","es":"No me habló ayer."},{"en":"Where did you go last weekend?","es":"¿A dónde fuiste el fin de semana pasado?"},{"en":"We didn't eat at home last night.","es":"No cenamos en casa anoche."},{"en":"Did they like the movie? Yes, they did.","es":"¿Les gustó la película? Sí, les gustó."}],"tip_es":"En preguntas y negativos el verbo regresa a su forma base, porque did ya marca el pasado: Did you go? I didn't go. Un error muy común es decir Did you went? o I didn't went. Ojo también: bored es cómo te sientes y boring es cómo es algo."},{"id":"9-5","title_es":"De vacaciones","words":[{"en":"vacation","es":"vacaciones","pos":"noun","ex_en":"We were on vacation in July.","ex_es":"Estuvimos de vacaciones en julio."},{"en":"beach","es":"playa","pos":"noun","ex_en":"The beach in Mazatlán was beautiful.","ex_es":"La playa de Mazatlán estaba hermosa."},{"en":"trip","es":"viaje","pos":"noun","ex_en":"Our trip to Chiapas was amazing.","ex_es":"Nuestro viaje a Chiapas fue increíble."},{"en":"travel / traveled","es":"viajar / viajé","pos":"verb","ex_en":"They traveled by bus to Mérida.","ex_es":"Viajaron en camión a Mérida."},{"en":"swim / swam","es":"nadar / nadé","pos":"verb","ex_en":"The kids swam in the ocean every day.","ex_es":"Los niños nadaron en el mar todos los días."},{"en":"take / took","es":"tomar / tomé","pos":"verb","ex_en":"I took a lot of pictures.","ex_es":"Tomé muchas fotos."},{"en":"souvenir","es":"recuerdo (de viaje)","pos":"noun","ex_en":"I bought a souvenir for my sister.","ex_es":"Compré un recuerdo para mi hermana."},{"en":"mountain","es":"montaña","pos":"noun","ex_en":"We climbed a mountain near the town.","ex_es":"Subimos una montaña cerca del pueblo."}],"sentences":[{"en":"How was your vacation?","es":"¿Qué tal tus vacaciones?"},{"en":"We stayed near the beach.","es":"Nos quedamos cerca de la playa."},{"en":"I didn't swim because the water was cold.","es":"No nadé porque el agua estaba fría."},{"en":"They took a trip to the mountains.","es":"Hicieron un viaje a las montañas."},{"en":"Last summer we traveled to Baja California by car.","es":"El verano pasado viajamos a Baja California en carro."}],"tip_es":"En inglés vacation casi siempre va en singular: my vacation was great, no my vacations were great. Además, en Estados Unidos se escribe traveled con una sola l, y travelled es la forma británica."},{"id":"9-6","title_es":"Contar una historia","words":[{"en":"first","es":"primero","pos":"adv","ex_en":"First, we had breakfast at the hotel.","ex_es":"Primero desayunamos en el hotel."},{"en":"then","es":"luego","pos":"adv","ex_en":"Then we walked to the museum.","ex_es":"Luego caminamos al museo."},{"en":"after that","es":"después de eso","pos":"phrase","ex_en":"After that, we ate lunch downtown.","ex_es":"Después de eso, comimos en el centro."},{"en":"finally","es":"al final, por fin","pos":"adv","ex_en":"Finally, we got home at midnight.","ex_es":"Al final, llegamos a casa a medianoche."},{"en":"suddenly","es":"de repente","pos":"adv","ex_en":"Suddenly, it started to rain.","ex_es":"De repente empezó a llover."},{"en":"lose / lost","es":"perder / perdí","pos":"verb","ex_en":"I lost my phone on the bus.","ex_es":"Perdí mi celular en el camión."},{"en":"find / found","es":"encontrar / encontré","pos":"verb","ex_en":"A nice man found my wallet.","ex_es":"Un señor amable encontró mi cartera."},{"en":"meet / met","es":"conocer / conocí","pos":"verb","ex_en":"I met my best friend in college.","ex_es":"Conocí a mi mejor amiga en la universidad."}],"sentences":[{"en":"First, I took a shower.","es":"Primero me bañé."},{"en":"Then I met Ana for coffee.","es":"Luego vi a Ana para tomar un café."},{"en":"Suddenly, the lights went out.","es":"De repente se fue la luz."},{"en":"After that, we looked for a taxi.","es":"Después de eso, buscamos un taxi."},{"en":"Finally, I found my wallet under the bed.","es":"Al final, encontré mi cartera debajo de la cama."}],"tip_es":"Para contar una historia en orden usa first, then, after that y finally. Ojo: meet en pasado (met) significa conocer a alguien por primera vez, no conocer un lugar. Para lugares se usa visit: I visited Oaxaca."},{"id":"9-7","title_es":"El fin de semana","words":[{"en":"weekend","es":"fin de semana","pos":"noun","ex_en":"We stayed home last weekend.","ex_es":"Nos quedamos en casa el fin de semana pasado."},{"en":"party","es":"fiesta","pos":"noun","ex_en":"The party was really fun.","ex_es":"La fiesta estuvo muy divertida."},{"en":"dance / danced","es":"bailar / bailé","pos":"verb","ex_en":"We danced all night at the wedding.","ex_es":"Bailamos toda la noche en la boda."},{"en":"listen / listened","es":"escuchar / escuché","pos":"verb","ex_en":"I listened to music in the car.","ex_es":"Escuché música en el carro."},{"en":"walk / walked","es":"caminar / caminé","pos":"verb","ex_en":"She walked to the park on Sunday.","ex_es":"Ella caminó al parque el domingo."},{"en":"read / read","es":"leer / leí","pos":"verb","ex_en":"I read a good book on Saturday.","ex_es":"Leí un buen libro el sábado."},{"en":"write / wrote","es":"escribir / escribí","pos":"verb","ex_en":"He wrote a letter to his grandma.","ex_es":"Él le escribió una carta a su abuela."},{"en":"come / came","es":"venir / vine","pos":"verb","ex_en":"My friends came to my house.","ex_es":"Mis amigos vinieron a mi casa."}],"sentences":[{"en":"What did you do last weekend?","es":"¿Qué hiciste el fin de semana pasado?"},{"en":"I walked my dog on Saturday morning.","es":"Paseé a mi perro el sábado en la mañana."},{"en":"We listened to music and danced.","es":"Escuchamos música y bailamos."},{"en":"My cousins came to the party.","es":"Mis primos vinieron a la fiesta."},{"en":"I didn't read or write anything all weekend.","es":"No leí ni escribí nada en todo el fin de semana."}],"tip_es":"Read se escribe igual en presente y en pasado, pero en pasado se pronuncia red. Listen siempre lleva to antes de lo que escuchas: I listened to music. Write y come son irregulares: wrote y came."},{"id":"9-8","title_es":"Preguntas: when, why y who","words":[{"en":"when","es":"cuándo","pos":"adv","ex_en":"When did you go to Mexico City?","ex_es":"¿Cuándo fuiste a la Ciudad de México?"},{"en":"why","es":"por qué","pos":"adv","ex_en":"Why were you sad yesterday?","ex_es":"¿Por qué estabas triste ayer?"},{"en":"because","es":"porque","pos":"conj","ex_en":"I stayed home because I was sick.","ex_es":"Me quedé en casa porque estaba enfermo."},{"en":"who","es":"quién","pos":"pron","ex_en":"Who did you see at the mall?","ex_es":"¿A quién viste en la plaza?"},{"en":"how long","es":"cuánto tiempo","pos":"phrase","ex_en":"How long was the trip?","ex_es":"¿Cuánto duró el viaje?"},{"en":"early","es":"temprano","pos":"adv","ex_en":"I got up early on Monday.","ex_es":"Me levanté temprano el lunes."},{"en":"late","es":"tarde","pos":"adv","ex_en":"The bus came late again.","ex_es":"El camión llegó tarde otra vez."},{"en":"the whole day","es":"todo el día","pos":"phrase","ex_en":"We were at the beach the whole day.","ex_es":"Estuvimos en la playa todo el día."}],"sentences":[{"en":"When did you get home?","es":"¿Cuándo llegaste a casa?"},{"en":"Who did you go with?","es":"¿Con quién fuiste?"},{"en":"Why didn't you call me?","es":"¿Por qué no me llamaste?"},{"en":"I was late because the traffic was really bad.","es":"Llegué tarde porque el tráfico estaba muy pesado."},{"en":"How long did you stay in Guadalajara?","es":"¿Cuánto tiempo te quedaste en Guadalajara?"}],"tip_es":"En preguntas con did el verbo regresa a su forma base: When did you go?, no When did you went? Con was y were no se usa did: Why were you late? Para responder a why se usa because."},{"id":"9-9","title_es":"¿Cómo te sentiste?","words":[{"en":"surprised","es":"sorprendido","pos":"adj","ex_en":"I was surprised by the gift.","ex_es":"Me sorprendió el regalo."},{"en":"excited","es":"emocionado","pos":"adj","ex_en":"The kids were excited about the trip.","ex_es":"Los niños estaban emocionados por el viaje."},{"en":"scared","es":"asustado","pos":"adj","ex_en":"She was scared during the storm.","ex_es":"Ella tenía miedo durante la tormenta."},{"en":"worried","es":"preocupado","pos":"adj","ex_en":"My mom was worried about me.","ex_es":"Mi mamá estaba preocupada por mí."},{"en":"amazing","es":"increíble","pos":"adj","ex_en":"The concert was amazing!","ex_es":"¡El concierto estuvo increíble!"},{"en":"terrible","es":"horrible, terrible","pos":"adj","ex_en":"The food at the hotel was terrible.","ex_es":"La comida del hotel estuvo horrible."},{"en":"laugh / laughed","es":"reír / me reí","pos":"verb","ex_en":"We laughed a lot at the movie.","ex_es":"Nos reímos mucho en la película."},{"en":"cry / cried","es":"llorar / lloré","pos":"verb","ex_en":"The baby cried all night.","ex_es":"El bebé lloró toda la noche."}],"sentences":[{"en":"I was so excited before the trip.","es":"Estaba muy emocionado antes del viaje."},{"en":"Were you scared on the plane?","es":"¿Tuviste miedo en el avión?"},{"en":"The show was amazing and we laughed a lot.","es":"El show estuvo increíble y nos reímos mucho."},{"en":"She cried because she lost her phone.","es":"Ella lloró porque perdió su celular."},{"en":"We were worried, but everything was fine.","es":"Estábamos preocupados, pero todo salió bien."}],"tip_es":"Los adjetivos con -ed describen cómo te sientes: I was bored, I was excited. Los que terminan en -ing describen lo que causa el sentimiento: The movie was boring. Cry en pasado cambia la y por i: cried."},{"id":"9-10","title_es":"En la vida real: ¿Qué pasó?","words":[{"en":"leave / left","es":"salir, dejar / salí, dejé","pos":"verb","ex_en":"I left my keys in the office.","ex_es":"Dejé mis llaves en la oficina."},{"en":"arrive / arrived","es":"llegar / llegué","pos":"verb","ex_en":"We arrived at the hotel at midnight.","ex_es":"Llegamos al hotel a medianoche."},{"en":"forget / forgot","es":"olvidar / olvidé","pos":"verb","ex_en":"I forgot my wallet at home.","ex_es":"Olvidé mi cartera en casa."},{"en":"bring / brought","es":"traer / traje","pos":"verb","ex_en":"She brought tamales to the party.","ex_es":"Ella trajo tamales a la fiesta."},{"en":"tell / told","es":"decir, contar / dije, conté","pos":"verb","ex_en":"He told me about his new job.","ex_es":"Él me contó de su nuevo trabajo."},{"en":"say / said","es":"decir / dije","pos":"verb","ex_en":"What did the teacher say?","ex_es":"¿Qué dijo la maestra?"},{"en":"hear / heard","es":"oír / oí","pos":"verb","ex_en":"Did you hear the news?","ex_es":"¿Escuchaste la noticia?"},{"en":"happen / happened","es":"pasar, suceder / pasó","pos":"verb","ex_en":"What happened at work today?","ex_es":"¿Qué pasó hoy en el trabajo?"}],"sentences":[{"en":"Sorry I'm late, I forgot my phone at home.","es":"Perdón por llegar tarde, olvidé mi celular en casa."},{"en":"What happened? I heard a loud noise.","es":"¿Qué pasó? Escuché un ruido fuerte."},{"en":"We left early, but we arrived late.","es":"Salimos temprano, pero llegamos tarde."},{"en":"Did you bring the cake for the party?","es":"¿Trajiste el pastel para la fiesta?"},{"en":"She told me she was very happy there.","es":"Me dijo que estaba muy feliz ahí."}],"tip_es":"Say y tell significan decir, pero tell necesita a quién: She told me. Con say no se pone la persona directamente: She said hello. Para preguntar qué pasó usa What happened?, sin did."}],"dialogue":{"title_es":"El lunes en la oficina","setting_es":"Un compañero te pregunta qué hiciste el fin de semana.","lines":[{"who":"A","en":"Hi! How was your weekend?","es":"¡Hola! ¿Qué tal tu fin de semana?"},{"who":"B","en":"It was great, thanks. I went to Tepoztlán.","es":"Estuvo muy bien, gracias. Fui a Tepoztlán."},{"who":"A","en":"Nice! Did you go with your family?","es":"¡Qué bien! ¿Fuiste con tu familia?"},{"who":"B","en":"No, I went with two friends from college.","es":"No, fui con dos amigos de la universidad."},{"who":"A","en":"What did you do there?","es":"¿Qué hicieron allá?"},{"who":"B","en":"First, we climbed the mountain. Then we ate quesadillas.","es":"Primero subimos el cerro. Luego comimos quesadillas."},{"who":"A","en":"Sounds fun. Did you take any pictures?","es":"Suena divertido. ¿Tomaste fotos?"},{"who":"B","en":"Yes, I took a lot. Look!","es":"Sí, tomé muchas. ¡Mira!"},{"who":"A","en":"Beautiful! I stayed home and slept all weekend.","es":"¡Qué bonito! Yo me quedé en casa y dormí todo el fin de semana."},{"who":"B","en":"That sounds good too!","es":"¡Eso también suena bien!"}]}},{"id":10,"title_es":"Trabajo y escuela","title_en":"Work and school","level":"A2","goal_es":"Al terminar podrás hablar de tu trabajo o tu escuela, de lo que sabes hacer y de tus obligaciones.","lessons":[{"id":"10-1","title_es":"Profesiones","words":[{"en":"job","es":"trabajo, empleo","pos":"noun","ex_en":"I like my new job a lot.","ex_es":"Me gusta mucho mi nuevo trabajo."},{"en":"engineer","es":"ingeniero","pos":"noun","ex_en":"My sister is an engineer.","ex_es":"Mi hermana es ingeniera."},{"en":"lawyer","es":"abogado","pos":"noun","ex_en":"He works as a lawyer downtown.","ex_es":"Trabaja como abogado en el centro."},{"en":"accountant","es":"contador","pos":"noun","ex_en":"An accountant helps me with my taxes.","ex_es":"Un contador me ayuda con mis impuestos."},{"en":"mechanic","es":"mecánico","pos":"noun","ex_en":"The mechanic is fixing my car.","ex_es":"El mecánico está arreglando mi carro."},{"en":"police officer","es":"policía","pos":"noun","ex_en":"The police officer is very friendly.","ex_es":"El policía es muy amable."},{"en":"firefighter","es":"bombero","pos":"noun","ex_en":"My uncle was a firefighter for twenty years.","ex_es":"Mi tío fue bombero durante veinte años."},{"en":"salesperson","es":"vendedor","pos":"noun","ex_en":"The salesperson showed me three phones.","ex_es":"El vendedor me enseñó tres celulares."}],"sentences":[{"en":"What do you do?","es":"¿A qué te dedicas?"},{"en":"I'm an accountant at a bank.","es":"Soy contador en un banco."},{"en":"She works in a hospital.","es":"Trabaja en un hospital."},{"en":"My mom wants to be a lawyer.","es":"Mi mamá quiere ser abogada."},{"en":"Before, I was a salesperson in a store.","es":"Antes era vendedor en una tienda."}],"tip_es":"En inglés siempre se pone a o an antes de la profesión: I am an engineer, she is a lawyer. Decir I am engineer es un error muy común. Para preguntar a qué se dedica alguien, lo más natural es What do you do?"},{"id":"10-2","title_es":"En la oficina","words":[{"en":"meeting","es":"junta, reunión","pos":"noun","ex_en":"We have a meeting at ten.","ex_es":"Tenemos una junta a las diez."},{"en":"boss","es":"jefe","pos":"noun","ex_en":"My boss is very patient.","ex_es":"Mi jefe es muy paciente."},{"en":"coworker","es":"compañero de trabajo","pos":"noun","ex_en":"I have lunch with my coworkers.","ex_es":"Como con mis compañeros de trabajo."},{"en":"email","es":"correo electrónico","pos":"noun","ex_en":"I send about fifty emails a day.","ex_es":"Mando como cincuenta correos al día."},{"en":"printer","es":"impresora","pos":"noun","ex_en":"The printer isn't working again.","ex_es":"La impresora no funciona otra vez."},{"en":"report","es":"reporte, informe","pos":"noun","ex_en":"I'm writing a report for my boss.","ex_es":"Estoy escribiendo un reporte para mi jefe."},{"en":"deadline","es":"fecha límite","pos":"noun","ex_en":"The deadline is next Friday.","ex_es":"La fecha límite es el próximo viernes."},{"en":"schedule","es":"horario","pos":"noun","ex_en":"My schedule is from nine to six.","ex_es":"Mi horario es de nueve a seis."}],"sentences":[{"en":"My office is on the third floor.","es":"Mi oficina está en el tercer piso."},{"en":"The meeting starts at nine.","es":"La junta empieza a las nueve."},{"en":"I answer emails every morning.","es":"Contesto correos todas las mañanas."},{"en":"My coworker is helping me with the report.","es":"Mi compañero me está ayudando con el reporte."},{"en":"Yesterday the meeting was very long and boring.","es":"Ayer la junta fue muy larga y aburrida."}],"tip_es":"Junta de trabajo se dice meeting, pero una reunión con amigos es get-together. Además, compañero de trabajo es coworker y compañero de clase es classmate. Para decir mando un correo se usa send: I send an email."},{"id":"10-3","title_es":"En la escuela","words":[{"en":"classroom","es":"salón de clases","pos":"noun","ex_en":"Our classroom has big windows.","ex_es":"Nuestro salón tiene ventanas grandes."},{"en":"homework","es":"tarea","pos":"noun","ex_en":"I do my homework after dinner.","ex_es":"Hago mi tarea después de cenar."},{"en":"exam","es":"examen","pos":"noun","ex_en":"We have a math exam tomorrow.","ex_es":"Mañana tenemos examen de matemáticas."},{"en":"grade","es":"calificación","pos":"noun","ex_en":"She got a good grade in English.","ex_es":"Sacó buena calificación en inglés."},{"en":"subject","es":"materia","pos":"noun","ex_en":"My favorite subject is history.","ex_es":"Mi materia favorita es historia."},{"en":"math","es":"matemáticas","pos":"noun","ex_en":"Math is difficult for me.","ex_es":"Las matemáticas son difíciles para mí."},{"en":"notebook","es":"cuaderno","pos":"noun","ex_en":"Write the new words in your notebook.","ex_es":"Escribe las palabras nuevas en tu cuaderno."},{"en":"pass","es":"pasar, aprobar","pos":"verb","ex_en":"I studied a lot and passed the exam.","ex_es":"Estudié mucho y pasé el examen."}],"sentences":[{"en":"Do you have homework today?","es":"¿Tienes tarea hoy?"},{"en":"The exam was very easy.","es":"El examen estuvo muy fácil."},{"en":"I didn't do my homework last night.","es":"No hice mi tarea anoche."},{"en":"What subject do you like the most?","es":"¿Qué materia te gusta más?"},{"en":"He got a bad grade because he didn't study.","es":"Sacó mala calificación porque no estudió."}],"tip_es":"Con homework se usa do, no make: I do my homework. Homework no tiene plural, así que nunca digas homeworks. Para presentar un examen se dice take an exam, y pass an exam significa pasarlo o aprobarlo."},{"id":"10-4","title_es":"Habilidades: can y can't","words":[{"en":"can","es":"poder, saber hacer","pos":"verb","ex_en":"I can speak two languages.","ex_es":"Sé hablar dos idiomas."},{"en":"can't","es":"no poder, no saber","pos":"verb","ex_en":"My brother can't swim.","ex_es":"Mi hermano no sabe nadar."},{"en":"drive","es":"manejar","pos":"verb","ex_en":"Can you drive a truck?","ex_es":"¿Sabes manejar un camión?"},{"en":"fix","es":"arreglar","pos":"verb","ex_en":"My dad can fix almost anything.","ex_es":"Mi papá puede arreglar casi cualquier cosa."},{"en":"draw","es":"dibujar","pos":"verb","ex_en":"She can draw really well.","ex_es":"Ella sabe dibujar muy bien."},{"en":"sing","es":"cantar","pos":"verb","ex_en":"I can't sing, but I can dance.","ex_es":"No sé cantar, pero sé bailar."},{"en":"well","es":"bien","pos":"adv","ex_en":"He speaks English very well.","ex_es":"Habla inglés muy bien."},{"en":"skill","es":"habilidad","pos":"noun","ex_en":"Cooking is a useful skill.","ex_es":"Cocinar es una habilidad útil."}],"sentences":[{"en":"Can you speak English?","es":"¿Hablas inglés?"},{"en":"I can type very fast.","es":"Escribo muy rápido en la computadora."},{"en":"She can't come to the meeting today.","es":"Ella no puede venir a la junta hoy."},{"en":"Can you help me with this report?","es":"¿Me puedes ayudar con este reporte?"},{"en":"My grandpa can fix cars, but he can't drive.","es":"Mi abuelo sabe arreglar carros, pero no sabe manejar."}],"tip_es":"Can sirve para poder y también para saber hacer algo: I can swim significa sé nadar. Después de can el verbo va sin to y sin -s: she can drive, nunca she can to drive ni she cans drive."},{"id":"10-5","title_es":"Obligaciones: have to","words":[{"en":"have to","es":"tener que","pos":"phrase","ex_en":"I have to work on Saturday.","ex_es":"Tengo que trabajar el sábado."},{"en":"has to","es":"tiene que","pos":"phrase","ex_en":"She has to wake up at five.","ex_es":"Ella tiene que despertarse a las cinco."},{"en":"don't have to","es":"no tener que","pos":"phrase","ex_en":"We don't have to wear a tie.","ex_es":"No tenemos que usar corbata."},{"en":"uniform","es":"uniforme","pos":"noun","ex_en":"Nurses have to wear a uniform.","ex_es":"Las enfermeras tienen que usar uniforme."},{"en":"on time","es":"a tiempo","pos":"phrase","ex_en":"You have to arrive on time.","ex_es":"Tienes que llegar a tiempo."},{"en":"rule","es":"regla","pos":"noun","ex_en":"The school has a lot of rules.","ex_es":"La escuela tiene muchas reglas."},{"en":"finish","es":"terminar","pos":"verb","ex_en":"I have to finish this report today.","ex_es":"Tengo que terminar este reporte hoy."},{"en":"shift","es":"turno","pos":"noun","ex_en":"My shift starts at seven.","ex_es":"Mi turno empieza a las siete."}],"sentences":[{"en":"Do you have to work tomorrow?","es":"¿Tienes que trabajar mañana?"},{"en":"He has to take the bus to work.","es":"Tiene que tomar el camión al trabajo."},{"en":"Students don't have to wear a uniform here.","es":"Aquí los alumnos no tienen que usar uniforme."},{"en":"I had to stay late at the office.","es":"Tuve que quedarme tarde en la oficina."},{"en":"Does she have to work the night shift?","es":"¿Ella tiene que trabajar en el turno de noche?"}],"tip_es":"Have to expresa obligación y cambia a has to con he, she e it. Don't have to significa que no es necesario, no que está prohibido. En pasado se dice had to: I had to work."},{"id":"10-6","title_es":"Buscar trabajo","words":[{"en":"apply","es":"postularse, solicitar","pos":"verb","ex_en":"I want to apply for that job.","ex_es":"Quiero postularme para ese trabajo."},{"en":"interview","es":"entrevista","pos":"noun","ex_en":"I have a job interview on Monday.","ex_es":"Tengo una entrevista de trabajo el lunes."},{"en":"salary","es":"sueldo","pos":"noun","ex_en":"The salary is good, but the hours are long.","ex_es":"El sueldo es bueno, pero el horario es largo."},{"en":"part-time","es":"de medio tiempo","pos":"adj","ex_en":"She has a part-time job at a café.","ex_es":"Tiene un trabajo de medio tiempo en un café."},{"en":"full-time","es":"de tiempo completo","pos":"adj","ex_en":"I'm looking for a full-time job.","ex_es":"Busco un trabajo de tiempo completo."},{"en":"experience","es":"experiencia","pos":"noun","ex_en":"Do you have experience in sales?","ex_es":"¿Tienes experiencia en ventas?"},{"en":"hire","es":"contratar","pos":"verb","ex_en":"The company wants to hire ten people.","ex_es":"La empresa quiere contratar a diez personas."},{"en":"resume","es":"currículum","pos":"noun","ex_en":"Send your resume by email.","ex_es":"Manda tu currículum por correo."}],"sentences":[{"en":"I'm looking for a new job.","es":"Estoy buscando un trabajo nuevo."},{"en":"How was your interview?","es":"¿Cómo te fue en tu entrevista?"},{"en":"They hired me last week!","es":"¡Me contrataron la semana pasada!"},{"en":"I have three years of experience as an accountant.","es":"Tengo tres años de experiencia como contador."},{"en":"Do I have to send my resume first?","es":"¿Tengo que mandar mi currículum primero?"}],"tip_es":"Para solicitar un empleo se usa apply for: I applied for the job. Experience en el sentido laboral no lleva a: I have experience, no I have an experience. En Estados Unidos el currículum se llama resume."},{"id":"10-7","title_es":"Lugares y personas en el trabajo","words":[{"en":"architect","es":"arquitecto","pos":"noun","ex_en":"My sister is an architect in Querétaro.","ex_es":"Mi hermana es arquitecta en Querétaro."},{"en":"cashier","es":"cajero","pos":"noun","ex_en":"The cashier gave me the change.","ex_es":"La cajera me dio el cambio."},{"en":"chef","es":"chef, cocinero","pos":"noun","ex_en":"The chef can cook amazing tacos.","ex_es":"El chef sabe cocinar tacos increíbles."},{"en":"nurse","es":"enfermero","pos":"noun","ex_en":"The nurse works the night shift.","ex_es":"La enfermera trabaja en el turno de noche."},{"en":"factory","es":"fábrica","pos":"noun","ex_en":"My dad works in a car factory.","ex_es":"Mi papá trabaja en una fábrica de carros."},{"en":"work from home","es":"trabajar desde casa","pos":"phrase","ex_en":"I work from home on Fridays.","ex_es":"Trabajo desde casa los viernes."},{"en":"company","es":"empresa","pos":"noun","ex_en":"She works for a big company.","ex_es":"Ella trabaja para una empresa grande."},{"en":"customer","es":"cliente","pos":"noun","ex_en":"The customer wants to talk to the manager.","ex_es":"El cliente quiere hablar con el gerente."}],"sentences":[{"en":"What does your brother do?","es":"¿A qué se dedica tu hermano?"},{"en":"He's a chef at a hotel.","es":"Es chef en un hotel."},{"en":"I work for a small company downtown.","es":"Trabajo para una empresa pequeña en el centro."},{"en":"Nurses have to work long shifts.","es":"Las enfermeras tienen que trabajar turnos largos."},{"en":"Do you work from home or at the office?","es":"¿Trabajas desde casa o en la oficina?"}],"tip_es":"Para preguntar a qué se dedica alguien se dice What do you do?, no What is your work? Antes de una profesión se usa a o an: She's a nurse, he's an architect. Work for va con la empresa y work at con el lugar."},{"id":"10-8","title_es":"En la universidad","words":[{"en":"college","es":"universidad","pos":"noun","ex_en":"My son is in college now.","ex_es":"Mi hijo ya está en la universidad."},{"en":"semester","es":"semestre","pos":"noun","ex_en":"The semester starts in August.","ex_es":"El semestre empieza en agosto."},{"en":"degree","es":"título universitario","pos":"noun","ex_en":"He has a degree in engineering.","ex_es":"Él tiene un título de ingeniería."},{"en":"major","es":"carrera, especialidad","pos":"noun","ex_en":"My major is computer science.","ex_es":"Mi carrera es ciencias de la computación."},{"en":"scholarship","es":"beca","pos":"noun","ex_en":"I got a scholarship for next year.","ex_es":"Conseguí una beca para el próximo año."},{"en":"graduate","es":"graduarse","pos":"verb","ex_en":"We graduate in June.","ex_es":"Nos graduamos en junio."},{"en":"library","es":"biblioteca","pos":"noun","ex_en":"Let's study at the library after class.","ex_es":"Vamos a estudiar en la biblioteca después de clase."},{"en":"take notes","es":"tomar apuntes","pos":"phrase","ex_en":"Always take notes in class.","ex_es":"Siempre toma apuntes en clase."}],"sentences":[{"en":"What's your major?","es":"¿Qué carrera estudias?"},{"en":"I study at the library every afternoon.","es":"Estudio en la biblioteca todas las tardes."},{"en":"She can't pay for college without a scholarship.","es":"Ella no puede pagar la universidad sin una beca."},{"en":"You have to take notes in this class.","es":"Tienes que tomar apuntes en esta clase."},{"en":"I want to graduate next semester.","es":"Quiero graduarme el próximo semestre."}],"tip_es":"En Estados Unidos college se usa para hablar de la universidad en general: I'm in college. Major es la carrera que estudias y degree es el título que recibes al terminar."},{"id":"10-9","title_es":"Tareas de todos los días","words":[{"en":"send","es":"mandar, enviar","pos":"verb","ex_en":"Can you send me the report today?","ex_es":"¿Me puedes mandar el reporte hoy?"},{"en":"answer the phone","es":"contestar el teléfono","pos":"phrase","ex_en":"Please answer the phone, I'm busy.","ex_es":"Por favor contesta el teléfono, estoy ocupado."},{"en":"make copies","es":"sacar copias","pos":"phrase","ex_en":"I have to make copies for the meeting.","ex_es":"Tengo que sacar copias para la junta."},{"en":"busy","es":"ocupado","pos":"adj","ex_en":"Mondays are always busy at the office.","ex_es":"Los lunes siempre hay mucho trabajo en la oficina."},{"en":"break","es":"descanso","pos":"noun","ex_en":"Let's take a break for ten minutes.","ex_es":"Tomemos un descanso de diez minutos."},{"en":"overtime","es":"horas extra","pos":"noun","ex_en":"He works overtime on weekends.","ex_es":"Él trabaja horas extra los fines de semana."},{"en":"day off","es":"día de descanso","pos":"phrase","ex_en":"Tomorrow is my day off.","ex_es":"Mañana es mi día de descanso."},{"en":"team","es":"equipo","pos":"noun","ex_en":"Our team finished the project early.","ex_es":"Nuestro equipo terminó el proyecto temprano."}],"sentences":[{"en":"Can you make copies of this report?","es":"¿Puedes sacar copias de este reporte?"},{"en":"I'm sorry, I can't talk now. I'm busy.","es":"Perdón, no puedo hablar ahora. Estoy ocupado."},{"en":"We have a break at eleven.","es":"Tenemos un descanso a las once."},{"en":"Do you have to work overtime this week?","es":"¿Tienes que trabajar horas extra esta semana?"},{"en":"My boss wants the whole team at the meeting.","es":"Mi jefe quiere a todo el equipo en la junta."}],"tip_es":"Take a break significa tomar un descanso. Para pedir algo en el trabajo de forma amable usa Can you o Could you al inicio. Overtime no lleva artículo: I work overtime."},{"id":"10-10","title_es":"En la vida real: crecer en el trabajo","words":[{"en":"promotion","es":"ascenso","pos":"noun","ex_en":"She got a promotion last month.","ex_es":"Le dieron un ascenso el mes pasado."},{"en":"raise","es":"aumento de sueldo","pos":"noun","ex_en":"I want to ask for a raise.","ex_es":"Quiero pedir un aumento de sueldo."},{"en":"quit","es":"renunciar","pos":"verb","ex_en":"He quit his job last week.","ex_es":"Él renunció a su trabajo la semana pasada."},{"en":"retire","es":"jubilarse","pos":"verb","ex_en":"My grandpa wants to retire next year.","ex_es":"Mi abuelo quiere jubilarse el próximo año."},{"en":"earn","es":"ganar (dinero)","pos":"verb","ex_en":"Nurses earn good money here.","ex_es":"Las enfermeras ganan buen dinero aquí."},{"en":"training","es":"capacitación","pos":"noun","ex_en":"New employees have training on Monday.","ex_es":"Los empleados nuevos tienen capacitación el lunes."},{"en":"goal","es":"meta","pos":"noun","ex_en":"My goal is to be a manager.","ex_es":"Mi meta es ser gerente."},{"en":"hardworking","es":"trabajador","pos":"adj","ex_en":"Our new coworker is very hardworking.","ex_es":"Nuestro compañero nuevo es muy trabajador."}],"sentences":[{"en":"I can speak English and I have experience.","es":"Hablo inglés y tengo experiencia."},{"en":"You have to finish the training first.","es":"Primero tienes que terminar la capacitación."},{"en":"She's hardworking, so she got a promotion.","es":"Es muy trabajadora, por eso le dieron un ascenso."},{"en":"I don't earn much, but I love my team.","es":"No gano mucho, pero me encanta mi equipo."},{"en":"My goal is to get a raise this year.","es":"Mi meta es conseguir un aumento este año."}],"tip_es":"Quit es irregular y no cambia en pasado: I quit my job yesterday. Earn es ganar dinero trabajando y win es ganar un premio o un partido. Ask for a raise significa pedir un aumento."}],"dialogue":{"title_es":"Primer día de trabajo","setting_es":"Es tu primer día en una empresa y una compañera te da la bienvenida.","lines":[{"who":"A","en":"Hi, you're the new engineer, right?","es":"Hola, tú eres el nuevo ingeniero, ¿verdad?"},{"who":"B","en":"Yes, I'm Carlos. Nice to meet you.","es":"Sí, soy Carlos. Mucho gusto."},{"who":"A","en":"I'm Laura. I work in accounting.","es":"Soy Laura. Trabajo en contabilidad."},{"who":"B","en":"Nice! What time do we have to arrive?","es":"¡Qué bien! ¿A qué hora tenemos que llegar?"},{"who":"A","en":"At eight thirty, but the schedule is flexible.","es":"A las ocho y media, pero el horario es flexible."},{"who":"B","en":"Great. Do I have to wear a uniform?","es":"Perfecto. ¿Tengo que usar uniforme?"},{"who":"A","en":"No. Can you come to a meeting at ten?","es":"No. ¿Puedes venir a una junta a las diez?"},{"who":"B","en":"Sure. Where is the meeting room?","es":"Claro. ¿Dónde está la sala de juntas?"},{"who":"A","en":"It's on the second floor, next to the printer.","es":"Está en el segundo piso, junto a la impresora."},{"who":"B","en":"Perfect. Thanks for your help, Laura!","es":"Perfecto. ¡Gracias por tu ayuda, Laura!"}]}},{"id":11,"title_es":"Salud y cuerpo","title_en":"Health and the body","level":"A2","goal_es":"Al terminar podrás nombrar las partes del cuerpo, describir síntomas, ir al doctor y dar consejos de salud.","lessons":[{"id":"11-1","title_es":"El cuerpo","words":[{"en":"head","es":"cabeza","pos":"noun","ex_en":"I hit my head on the door.","ex_es":"Me pegué en la cabeza con la puerta."},{"en":"arm","es":"brazo","pos":"noun","ex_en":"My arm is very tired.","ex_es":"Tengo el brazo muy cansado."},{"en":"leg","es":"pierna","pos":"noun","ex_en":"He has long legs.","ex_es":"Tiene las piernas largas."},{"en":"hand","es":"mano","pos":"noun","ex_en":"Raise your hand, please.","ex_es":"Levanta la mano, por favor."},{"en":"foot","es":"pie","pos":"noun","ex_en":"My left foot is cold.","ex_es":"Tengo el pie izquierdo frío."},{"en":"back","es":"espalda","pos":"noun","ex_en":"Carrying heavy boxes is bad for your back.","ex_es":"Cargar cajas pesadas es malo para la espalda."},{"en":"neck","es":"cuello","pos":"noun","ex_en":"The giraffe has a very long neck.","ex_es":"La jirafa tiene el cuello muy largo."},{"en":"shoulder","es":"hombro","pos":"noun","ex_en":"Put the bag on your shoulder.","ex_es":"Ponte la bolsa en el hombro."}],"sentences":[{"en":"Wash your hands before dinner.","es":"Lávate las manos antes de cenar."},{"en":"My feet are tired.","es":"Tengo los pies cansados."},{"en":"Touch your head with your right hand.","es":"Tócate la cabeza con la mano derecha."},{"en":"I walked a lot and my legs are tired.","es":"Caminé mucho y tengo las piernas cansadas."},{"en":"He carried his son on his shoulders.","es":"Cargó a su hijo en los hombros."}],"tip_es":"En inglés se usa el posesivo con las partes del cuerpo: wash your hands, I hit my head. En español decimos la mano, pero en inglés the hand suena raro en estos casos. Ojo con el plural irregular: one foot, two feet."},{"id":"11-2","title_es":"Más partes del cuerpo","words":[{"en":"knee","es":"rodilla","pos":"noun","ex_en":"I hit my knee on the table.","ex_es":"Me pegué en la rodilla con la mesa."},{"en":"finger","es":"dedo (de la mano)","pos":"noun","ex_en":"She has a ring on every finger.","ex_es":"Tiene un anillo en cada dedo."},{"en":"toe","es":"dedo del pie","pos":"noun","ex_en":"I hit my toe on the bed.","ex_es":"Me pegué en el dedo del pie con la cama."},{"en":"stomach","es":"estómago","pos":"noun","ex_en":"My stomach is making noise.","ex_es":"Me está sonando el estómago."},{"en":"tooth","es":"diente","pos":"noun","ex_en":"My son lost his first tooth.","ex_es":"A mi hijo se le cayó su primer diente."},{"en":"ear","es":"oreja, oído","pos":"noun","ex_en":"She has small ears.","ex_es":"Tiene las orejas pequeñas."},{"en":"nose","es":"nariz","pos":"noun","ex_en":"My nose is red because of the cold.","ex_es":"Tengo la nariz roja por el frío."},{"en":"chest","es":"pecho","pos":"noun","ex_en":"The ball hit him in the chest.","ex_es":"La pelota le pegó en el pecho."}],"sentences":[{"en":"Brush your teeth after every meal.","es":"Lávate los dientes después de cada comida."},{"en":"Babies have very small fingers.","es":"Los bebés tienen dedos muy pequeños."},{"en":"Close your eyes and touch your nose.","es":"Cierra los ojos y tócate la nariz."},{"en":"The dentist checked all my teeth.","es":"El dentista revisó todos mis dientes."},{"en":"Wear a hat to cover your ears.","es":"Ponte un gorro para taparte las orejas."}],"tip_es":"Tooth tiene plural irregular: one tooth, two teeth (igual que foot, feet). Finger son los dedos de la mano y toe los del pie. Ear puede ser oreja u oído, según el contexto."},{"id":"11-3","title_es":"¿Cómo te sientes? Síntomas","words":[{"en":"sick","es":"enfermo","pos":"adj","ex_en":"I feel sick today.","ex_es":"Hoy me siento enfermo."},{"en":"headache","es":"dolor de cabeza","pos":"noun","ex_en":"I have a terrible headache.","ex_es":"Tengo un dolor de cabeza terrible."},{"en":"fever","es":"fiebre","pos":"noun","ex_en":"The baby has a fever.","ex_es":"El bebé tiene fiebre."},{"en":"cough","es":"tos","pos":"noun","ex_en":"My cough is worse at night.","ex_es":"Mi tos empeora en la noche."},{"en":"cold","es":"gripa, resfriado","pos":"noun","ex_en":"I think I have a cold.","ex_es":"Creo que tengo gripa."},{"en":"sore throat","es":"dolor de garganta","pos":"noun","ex_en":"I have a sore throat and I can't talk.","ex_es":"Me duele la garganta y no puedo hablar."},{"en":"hurt","es":"doler","pos":"verb","ex_en":"My back hurts a lot.","ex_es":"Me duele mucho la espalda."},{"en":"dizzy","es":"mareado","pos":"adj","ex_en":"I feel dizzy when I stand up.","ex_es":"Me mareo cuando me paro."}],"sentences":[{"en":"What's wrong?","es":"¿Qué tienes?"},{"en":"How do you feel today?","es":"¿Cómo te sientes hoy?"},{"en":"My head hurts and I feel dizzy.","es":"Me duele la cabeza y me siento mareado."},{"en":"She stayed home because she had a fever.","es":"Se quedó en casa porque tenía fiebre."},{"en":"I have a bad cough and a sore throat.","es":"Tengo mucha tos y me duele la garganta."}],"tip_es":"Para los síntomas se usa have: I have a headache, I have a fever, nunca I am fever. Con hurt, la parte del cuerpo es el sujeto: my head hurts, my feet hurt. No digas me hurts the head."},{"id":"11-4","title_es":"En el doctor","words":[{"en":"appointment","es":"cita","pos":"noun","ex_en":"I have a doctor's appointment at four.","ex_es":"Tengo cita con el doctor a las cuatro."},{"en":"patient","es":"paciente","pos":"noun","ex_en":"The doctor has many patients today.","ex_es":"El doctor tiene muchos pacientes hoy."},{"en":"medicine","es":"medicina","pos":"noun","ex_en":"Take this medicine after meals.","ex_es":"Tómate esta medicina después de las comidas."},{"en":"pill","es":"pastilla","pos":"noun","ex_en":"Take one pill every eight hours.","ex_es":"Tómate una pastilla cada ocho horas."},{"en":"prescription","es":"receta médica","pos":"noun","ex_en":"You need a prescription for this medicine.","ex_es":"Necesitas receta para esta medicina."},{"en":"pharmacy","es":"farmacia","pos":"noun","ex_en":"Is there a pharmacy near here?","ex_es":"¿Hay una farmacia cerca de aquí?"},{"en":"temperature","es":"temperatura","pos":"noun","ex_en":"The nurse took my temperature.","ex_es":"La enfermera me tomó la temperatura."},{"en":"allergic","es":"alérgico","pos":"adj","ex_en":"I'm allergic to penicillin.","ex_es":"Soy alérgico a la penicilina."}],"sentences":[{"en":"I'd like to make an appointment, please.","es":"Quisiera hacer una cita, por favor."},{"en":"What are your symptoms?","es":"¿Cuáles son sus síntomas?"},{"en":"Are you allergic to any medicine?","es":"¿Es alérgico a alguna medicina?"},{"en":"The doctor gave me a prescription for my cough.","es":"El doctor me dio una receta para la tos."},{"en":"I bought the pills at the pharmacy yesterday.","es":"Compré las pastillas en la farmacia ayer."}],"tip_es":"Ojo con este falso amigo: la receta del doctor es prescription, y la receta de cocina es recipe. Con medicinas se usa el verbo take: take a pill, take this medicine. Y alérgico a se dice allergic to."},{"id":"11-5","title_es":"Consejos: should y shouldn't","words":[{"en":"should","es":"deberías, debería","pos":"verb","ex_en":"You should see a doctor.","ex_es":"Deberías ir al doctor."},{"en":"shouldn't","es":"no deberías","pos":"verb","ex_en":"You shouldn't eat so much sugar.","ex_es":"No deberías comer tanta azúcar."},{"en":"rest","es":"descansar","pos":"verb","ex_en":"You should rest for two days.","ex_es":"Deberías descansar dos días."},{"en":"advice","es":"consejo","pos":"noun","ex_en":"Can I give you some advice?","ex_es":"¿Te puedo dar un consejo?"},{"en":"healthy","es":"saludable, sano","pos":"adj","ex_en":"Fruit and vegetables are healthy.","ex_es":"Las frutas y verduras son saludables."},{"en":"exercise","es":"hacer ejercicio","pos":"verb","ex_en":"I exercise three times a week.","ex_es":"Hago ejercicio tres veces por semana."},{"en":"stay in bed","es":"quedarse en cama","pos":"phrase","ex_en":"The doctor told me to stay in bed.","ex_es":"El doctor me dijo que me quedara en cama."},{"en":"junk food","es":"comida chatarra","pos":"noun","ex_en":"Kids shouldn't eat a lot of junk food.","ex_es":"Los niños no deberían comer mucha comida chatarra."}],"sentences":[{"en":"You should drink more water.","es":"Deberías tomar más agua."},{"en":"What should I do?","es":"¿Qué debería hacer?"},{"en":"You shouldn't go to work with a fever.","es":"No deberías ir a trabajar con fiebre."},{"en":"Should I take this medicine with food?","es":"¿Debo tomar esta medicina con comida?"},{"en":"My doctor gave me good advice about healthy food.","es":"Mi doctor me dio buenos consejos sobre comida saludable."}],"tip_es":"Should sirve para dar consejos y va seguido del verbo sin to: you should rest, no you should to rest. Advice es incontable: se dice some advice o a piece of advice, nunca an advice ni advices."},{"id":"11-6","title_es":"Accidentes y emergencias","words":[{"en":"emergency","es":"emergencia","pos":"noun","ex_en":"Call 911, it's an emergency!","ex_es":"¡Llama al 911, es una emergencia!"},{"en":"ambulance","es":"ambulancia","pos":"noun","ex_en":"The ambulance arrived in ten minutes.","ex_es":"La ambulancia llegó en diez minutos."},{"en":"hospital","es":"hospital","pos":"noun","ex_en":"They took him to the hospital.","ex_es":"Lo llevaron al hospital."},{"en":"break / broke","es":"romper / me rompí","pos":"verb","ex_en":"I broke my arm playing soccer.","ex_es":"Me rompí el brazo jugando futbol."},{"en":"cut","es":"cortar, cortarse","pos":"verb","ex_en":"Be careful, you can cut your finger.","ex_es":"Cuidado, te puedes cortar el dedo."},{"en":"fall / fell","es":"caerse / me caí","pos":"verb","ex_en":"My grandpa fell down the stairs.","ex_es":"Mi abuelo se cayó de las escaleras."},{"en":"burn","es":"quemar, quemarse","pos":"verb","ex_en":"Don't touch the pan, you can burn your hand.","ex_es":"No toques el sartén, te puedes quemar la mano."},{"en":"bandage","es":"venda, curita","pos":"noun","ex_en":"Put a bandage on that cut.","ex_es":"Ponte una venda en esa cortada."}],"sentences":[{"en":"Help! Call an ambulance!","es":"¡Ayuda! ¡Llamen a una ambulancia!"},{"en":"Are you OK? Did you fall?","es":"¿Estás bien? ¿Te caíste?"},{"en":"I cut my finger with a knife.","es":"Me corté el dedo con un cuchillo."},{"en":"You should go to the hospital right now.","es":"Deberías ir al hospital ahora mismo."},{"en":"She fell off her bike and broke her wrist.","es":"Se cayó de la bici y se rompió la muñeca."}],"tip_es":"Break, fall y cut son verbos irregulares: broke, fell y cut (cut no cambia en pasado). Para decir me rompí el brazo se usa el posesivo: I broke my arm. En Estados Unidos el número de emergencias también es 911."},{"id":"11-7","title_es":"Malestares comunes","words":[{"en":"stomachache","es":"dolor de estómago","pos":"noun","ex_en":"I have a stomachache after lunch.","ex_es":"Me duele el estómago después de la comida."},{"en":"toothache","es":"dolor de muelas","pos":"noun","ex_en":"He has a bad toothache.","ex_es":"Él tiene un dolor de muelas muy fuerte."},{"en":"runny nose","es":"escurrimiento nasal","pos":"phrase","ex_en":"My daughter has a runny nose.","ex_es":"A mi hija le escurre la nariz."},{"en":"sneeze","es":"estornudar","pos":"verb","ex_en":"I sneeze a lot in the spring.","ex_es":"Estornudo mucho en primavera."},{"en":"itchy","es":"que da comezón","pos":"adj","ex_en":"My eyes are red and itchy.","ex_es":"Tengo los ojos rojos y con comezón."},{"en":"swollen","es":"hinchado","pos":"adj","ex_en":"My ankle is swollen.","ex_es":"Tengo el tobillo hinchado."},{"en":"rash","es":"ronchas, sarpullido","pos":"noun","ex_en":"The baby has a rash on her arm.","ex_es":"La bebé tiene ronchas en el brazo."},{"en":"throw up","es":"vomitar","pos":"verb","ex_en":"I feel like I'm going to throw up.","ex_es":"Siento que voy a vomitar."}],"sentences":[{"en":"I have a stomachache and a fever.","es":"Tengo dolor de estómago y fiebre."},{"en":"Do you have a runny nose?","es":"¿Te escurre la nariz?"},{"en":"My skin is itchy because of the rash.","es":"Me da comezón la piel por las ronchas."},{"en":"You should take something for that toothache.","es":"Deberías tomar algo para ese dolor de muelas."},{"en":"My knee is swollen and it hurts a lot.","es":"Tengo la rodilla hinchada y me duele mucho."}],"tip_es":"Muchos dolores se forman con ache: stomachache, toothache, headache. Para decir que tienes un síntoma se usa have: I have a rash. Con adjetivos como itchy o swollen se usa to be: My eyes are itchy."},{"id":"11-8","title_es":"En el dentista y el oculista","words":[{"en":"dentist","es":"dentista","pos":"noun","ex_en":"I have an appointment with the dentist.","ex_es":"Tengo cita con el dentista."},{"en":"cavity","es":"caries","pos":"noun","ex_en":"The dentist found a cavity.","ex_es":"El dentista encontró una caries."},{"en":"brush","es":"cepillar, lavarse (los dientes)","pos":"verb","ex_en":"Brush your teeth after every meal.","ex_es":"Lávate los dientes después de cada comida."},{"en":"floss","es":"usar hilo dental","pos":"verb","ex_en":"You should floss every night.","ex_es":"Deberías usar hilo dental todas las noches."},{"en":"eye doctor","es":"oculista","pos":"noun","ex_en":"I need to see an eye doctor.","ex_es":"Necesito ir al oculista."},{"en":"glasses","es":"lentes","pos":"noun","ex_en":"She wears glasses to read.","ex_es":"Ella usa lentes para leer."},{"en":"blurry","es":"borroso","pos":"adj","ex_en":"Everything looks blurry without my glasses.","ex_es":"Todo se ve borroso sin mis lentes."},{"en":"check-up","es":"chequeo, revisión","pos":"noun","ex_en":"It's time for your yearly check-up.","ex_es":"Ya te toca tu revisión anual."}],"sentences":[{"en":"How often do you brush your teeth?","es":"¿Cada cuánto te lavas los dientes?"},{"en":"I think I have a cavity.","es":"Creo que tengo una caries."},{"en":"My vision is blurry, so I need glasses.","es":"Veo borroso, así que necesito lentes."},{"en":"You should get a check-up every year.","es":"Deberías hacerte un chequeo cada año."},{"en":"The eye doctor gave me a new prescription.","es":"El oculista me dio una nueva receta."}],"tip_es":"En México decimos lentes, y en inglés de Estados Unidos se dice glasses, siempre en plural: My glasses are new. Brush your teeth es lavarse los dientes. Floss también es verbo: I floss every day."},{"id":"11-9","title_es":"Hábitos saludables","words":[{"en":"diet","es":"alimentación, dieta","pos":"noun","ex_en":"Her diet has a lot of vegetables.","ex_es":"Su alimentación tiene muchas verduras."},{"en":"sugar","es":"azúcar","pos":"noun","ex_en":"This soda has too much sugar.","ex_es":"Este refresco tiene demasiada azúcar."},{"en":"gym","es":"gimnasio","pos":"noun","ex_en":"I go to the gym three times a week.","ex_es":"Voy al gimnasio tres veces por semana."},{"en":"stretch","es":"estirarse","pos":"verb","ex_en":"Stretch your legs before you run.","ex_es":"Estira las piernas antes de correr."},{"en":"lose weight","es":"bajar de peso","pos":"phrase","ex_en":"My doctor says I should lose weight.","ex_es":"Mi doctor dice que debería bajar de peso."},{"en":"stress","es":"estrés","pos":"noun","ex_en":"Work gives me a lot of stress.","ex_es":"El trabajo me da mucho estrés."},{"en":"quit smoking","es":"dejar de fumar","pos":"phrase","ex_en":"My uncle wants to quit smoking.","ex_es":"Mi tío quiere dejar de fumar."},{"en":"get enough sleep","es":"dormir lo suficiente","pos":"phrase","ex_en":"Teenagers need to get enough sleep.","ex_es":"Los adolescentes necesitan dormir lo suficiente."}],"sentences":[{"en":"You should eat less sugar.","es":"Deberías comer menos azúcar."},{"en":"I stretch every morning before work.","es":"Me estiro todas las mañanas antes del trabajo."},{"en":"Exercise is good for stress.","es":"El ejercicio es bueno contra el estrés."},{"en":"He quit smoking and feels much better.","es":"Dejó de fumar y se siente mucho mejor."},{"en":"To lose weight, change your diet and exercise.","es":"Para bajar de peso, cambia tu alimentación y haz ejercicio."}],"tip_es":"Después de quit y stop el verbo va con ing: quit smoking, stop eating junk food. Lose weight es bajar de peso y gain weight es subir de peso. Sugar es incontable, por eso se dice too much sugar."},{"id":"11-10","title_es":"En la vida real: en el consultorio","words":[{"en":"how do you feel","es":"cómo te sientes","pos":"phrase","ex_en":"How do you feel today?","ex_es":"¿Cómo te sientes hoy?"},{"en":"feel better","es":"sentirse mejor","pos":"phrase","ex_en":"I hope you feel better soon.","ex_es":"Espero que te sientas mejor pronto."},{"en":"get well soon","es":"que te mejores pronto","pos":"phrase","ex_en":"Get well soon, Grandma!","ex_es":"¡Que te mejores pronto, abuelita!"},{"en":"health insurance","es":"seguro médico","pos":"noun","ex_en":"Do you have health insurance?","ex_es":"¿Tienes seguro médico?"},{"en":"blood pressure","es":"presión arterial","pos":"noun","ex_en":"The nurse checked my blood pressure.","ex_es":"La enfermera me tomó la presión."},{"en":"side effect","es":"efecto secundario","pos":"noun","ex_en":"Sleepiness is a side effect of this pill.","ex_es":"La somnolencia es un efecto secundario de esta pastilla."},{"en":"twice a day","es":"dos veces al día","pos":"phrase","ex_en":"Take this pill twice a day.","ex_es":"Toma esta pastilla dos veces al día."},{"en":"waiting room","es":"sala de espera","pos":"noun","ex_en":"Please wait in the waiting room.","ex_es":"Por favor espere en la sala de espera."}],"sentences":[{"en":"Good morning, I have an appointment at ten.","es":"Buenos días, tengo cita a las diez."},{"en":"Your blood pressure is a little high.","es":"Su presión está un poco alta."},{"en":"Take this medicine twice a day for a week.","es":"Tome esta medicina dos veces al día por una semana."},{"en":"You shouldn't drive. It can make you dizzy.","es":"No debería manejar. Le puede causar mareo."},{"en":"Rest at home and you'll feel better soon.","es":"Descanse en casa y pronto se sentirá mejor."}],"tip_es":"El doctor puede preguntar How do you feel? o What's wrong? Para despedirte de alguien enfermo se dice Get well soon! En los consultorios de Estados Unidos casi siempre te piden tu health insurance al llegar."}],"dialogue":{"title_es":"En el consultorio","setting_es":"No te sientes bien y vas con el doctor.","lines":[{"who":"A","en":"Good morning. What's wrong?","es":"Buenos días. ¿Qué tiene?"},{"who":"B","en":"I feel sick. I have a headache and fever.","es":"Me siento mal. Tengo dolor de cabeza y fiebre."},{"who":"A","en":"When did it start?","es":"¿Cuándo empezó?"},{"who":"B","en":"Two days ago. I also have a bad cough.","es":"Hace dos días. También tengo mucha tos."},{"who":"A","en":"Let me check your throat. Does it hurt?","es":"Déjeme revisarle la garganta. ¿Le duele?"},{"who":"B","en":"Yes, a little. Is it serious?","es":"Sí, un poco. ¿Es grave?"},{"who":"A","en":"No, it's just a bad cold.","es":"No, es solo una gripa fuerte."},{"who":"B","en":"What should I do?","es":"¿Qué debo hacer?"},{"who":"A","en":"You should rest and drink a lot of water.","es":"Debe descansar y tomar mucha agua."},{"who":"B","en":"OK. Do I need a prescription?","es":"Está bien. ¿Necesito receta?"}]}},{"id":12,"title_es":"Viajes: aeropuerto y hotel","title_en":"Airports and hotels","level":"B1","goal_es":"Al terminar podrás moverte en un aeropuerto, reservar un hotel, resolver problemas y pedir favores con amabilidad.","lessons":[{"id":"12-1","title_es":"En el aeropuerto","words":[{"en":"flight","es":"vuelo","pos":"noun","ex_en":"Our flight to Chicago leaves at six in the morning.","ex_es":"Nuestro vuelo a Chicago sale a las seis de la mañana."},{"en":"passport","es":"pasaporte","pos":"noun","ex_en":"Don't forget your passport, you need it for international flights.","ex_es":"No olvides tu pasaporte, lo necesitas para vuelos internacionales."},{"en":"boarding pass","es":"pase de abordar","pos":"noun","ex_en":"You can download your boarding pass on your phone.","ex_es":"Puedes descargar tu pase de abordar en tu celular."},{"en":"gate","es":"puerta (de embarque)","pos":"noun","ex_en":"Our flight is now boarding at gate twelve.","ex_es":"Nuestro vuelo ya está abordando en la puerta doce."},{"en":"check in","es":"registrarse, hacer check-in","pos":"phrase","ex_en":"We have to check in two hours before the flight.","ex_es":"Tenemos que hacer el check-in dos horas antes del vuelo."},{"en":"luggage","es":"equipaje","pos":"noun","ex_en":"How much luggage can I bring on this flight?","ex_es":"¿Cuánto equipaje puedo llevar en este vuelo?"},{"en":"carry-on","es":"maleta de mano","pos":"noun","ex_en":"My carry-on is too big for the overhead bin.","ex_es":"Mi maleta de mano es demasiado grande para el compartimento."},{"en":"departure","es":"salida","pos":"noun","ex_en":"Check the departure time on the screen.","ex_es":"Revisa la hora de salida en la pantalla."}],"sentences":[{"en":"Excuse me, where is gate twenty?","es":"Disculpe, ¿dónde está la puerta veinte?"},{"en":"Can I see your passport and boarding pass, please?","es":"¿Me permite su pasaporte y su pase de abordar, por favor?"},{"en":"Do you have any luggage to check?","es":"¿Tiene equipaje para documentar?"},{"en":"I only have a carry-on and a small backpack.","es":"Solo traigo una maleta de mano y una mochila pequeña."},{"en":"The departures board says our flight is on time.","es":"La pantalla de salidas dice que nuestro vuelo va a tiempo."}],"tip_es":"Check in significa registrarse, en el aeropuerto o en el hotel. Luggage y baggage son incontables: se dice two pieces of luggage o two bags, nunca two luggages."},{"id":"12-2","title_es":"En el avión","words":[{"en":"security","es":"control de seguridad","pos":"noun","ex_en":"The line at security was very long this morning.","ex_es":"La fila en el control de seguridad estaba muy larga esta mañana."},{"en":"delayed","es":"retrasado","pos":"adj","ex_en":"Our flight was delayed because of the storm.","ex_es":"Nuestro vuelo se retrasó por la tormenta."},{"en":"aisle seat","es":"asiento de pasillo","pos":"noun","ex_en":"I prefer an aisle seat on long flights.","ex_es":"Prefiero un asiento de pasillo en vuelos largos."},{"en":"window seat","es":"asiento de ventanilla","pos":"noun","ex_en":"My son always wants the window seat.","ex_es":"Mi hijo siempre quiere el asiento de ventanilla."},{"en":"take off","es":"despegar","pos":"phrase","ex_en":"The plane can't take off because of the snow.","ex_es":"El avión no puede despegar por la nieve."},{"en":"land","es":"aterrizar","pos":"verb","ex_en":"We landed in Los Angeles at midnight.","ex_es":"Aterrizamos en Los Ángeles a medianoche."},{"en":"seat belt","es":"cinturón de seguridad","pos":"noun","ex_en":"Please fasten your seat belt.","ex_es":"Por favor, abróchese el cinturón de seguridad."},{"en":"flight attendant","es":"sobrecargo","pos":"noun","ex_en":"The flight attendant brought me a glass of water.","ex_es":"La sobrecargo me trajo un vaso de agua."}],"sentences":[{"en":"Please put your laptop in a separate tray.","es":"Por favor, ponga su laptop en una charola aparte."},{"en":"Our flight is delayed two hours.","es":"Nuestro vuelo tiene dos horas de retraso."},{"en":"I asked for an aisle seat, but they gave me the middle seat.","es":"Pedí un asiento de pasillo, pero me dieron el de en medio."},{"en":"Keep your seat belt on until the plane stops.","es":"Mantenga el cinturón abrochado hasta que el avión se detenga."},{"en":"The flight attendant told us to turn off our phones.","es":"La sobrecargo nos dijo que apagáramos los celulares."}],"tip_es":"Para hablar de retrasos se usa be delayed: my flight is delayed two hours. Take off (despegar) es un phrasal verb y en pasado es took off. Su opuesto es land (aterrizar), que es regular: landed."},{"id":"12-3","title_es":"Reservar un hotel","words":[{"en":"reservation","es":"reservación","pos":"noun","ex_en":"I'd like to make a reservation for three nights.","ex_es":"Quisiera hacer una reservación para tres noches."},{"en":"book","es":"reservar","pos":"verb","ex_en":"We booked the hotel online last month.","ex_es":"Reservamos el hotel en línea el mes pasado."},{"en":"single room","es":"habitación sencilla","pos":"noun","ex_en":"A single room costs eighty dollars a night.","ex_es":"Una habitación sencilla cuesta ochenta dólares la noche."},{"en":"double room","es":"habitación doble","pos":"noun","ex_en":"Do you have a double room for this weekend?","ex_es":"¿Tienen una habitación doble para este fin de semana?"},{"en":"available","es":"disponible","pos":"adj","ex_en":"Sorry, we don't have any rooms available tonight.","ex_es":"Lo siento, no tenemos habitaciones disponibles esta noche."},{"en":"per night","es":"por noche","pos":"phrase","ex_en":"How much is the room per night?","ex_es":"¿Cuánto cuesta la habitación por noche?"},{"en":"check out","es":"entregar la habitación","pos":"phrase","ex_en":"What time do we have to check out?","ex_es":"¿A qué hora tenemos que entregar la habitación?"},{"en":"front desk","es":"recepción","pos":"noun","ex_en":"Please leave your key at the front desk.","ex_es":"Por favor, deje su llave en la recepción."}],"sentences":[{"en":"Is breakfast included in the price?","es":"¿El desayuno está incluido en el precio?"},{"en":"I booked a double room for two nights.","es":"Reservé una habitación doble para dos noches."},{"en":"Do you have any rooms available for next Friday?","es":"¿Tienen habitaciones disponibles para el próximo viernes?"},{"en":"Check out is at noon, but you can leave your bags here.","es":"La salida es a mediodía, pero puede dejar sus maletas aquí."},{"en":"Your reservation is under the name Martínez, is that correct?","es":"Su reservación está a nombre de Martínez, ¿es correcto?"}],"tip_es":"En el habla diaria se usa book mucho más que reserve: I booked a room. Para decir a nombre de se usa under: the reservation is under Martínez. Ojo: una habitación doble es double room, no double habitation."},{"id":"12-4","title_es":"En el hotel","words":[{"en":"key card","es":"tarjeta de la habitación","pos":"noun","ex_en":"My key card doesn't open the door.","ex_es":"Mi tarjeta no abre la puerta."},{"en":"towel","es":"toalla","pos":"noun","ex_en":"We need two more towels, please.","ex_es":"Necesitamos dos toallas más, por favor."},{"en":"elevator","es":"elevador","pos":"noun","ex_en":"The elevator is at the end of the hall.","ex_es":"El elevador está al final del pasillo."},{"en":"room service","es":"servicio a la habitación","pos":"noun","ex_en":"We ordered room service because we were very tired.","ex_es":"Pedimos servicio a la habitación porque estábamos muy cansados."},{"en":"wake-up call","es":"llamada para despertar","pos":"noun","ex_en":"I asked for a wake-up call at six.","ex_es":"Pedí una llamada para despertarme a las seis."},{"en":"password","es":"contraseña","pos":"noun","ex_en":"What's the password for the Wi-Fi?","ex_es":"¿Cuál es la contraseña del wifi?"},{"en":"pool","es":"alberca","pos":"noun","ex_en":"The pool is open from eight to ten.","ex_es":"La alberca está abierta de ocho a diez."},{"en":"guest","es":"huésped","pos":"noun","ex_en":"Hotel guests get a free breakfast every morning.","ex_es":"Los huéspedes del hotel tienen desayuno gratis todas las mañanas."}],"sentences":[{"en":"Your room is on the fifth floor.","es":"Su habitación está en el quinto piso."},{"en":"Take the elevator and turn left.","es":"Tome el elevador y dé vuelta a la izquierda."},{"en":"Here is your key card and the Wi-Fi password.","es":"Aquí tiene su tarjeta y la contraseña del wifi."},{"en":"Is the pool open for guests after nine at night?","es":"¿La alberca está abierta para los huéspedes después de las nueve de la noche?"},{"en":"I'd like to order room service for breakfast tomorrow.","es":"Quisiera pedir servicio a la habitación para el desayuno de mañana."}],"tip_es":"En Estados Unidos se dice elevator, no lift, que es británico. Ojo con los pisos: en EE. UU. la planta baja es el first floor, así que su second floor es nuestro primer piso."},{"id":"12-5","title_es":"Problemas y quejas","words":[{"en":"complaint","es":"queja","pos":"noun","ex_en":"I'd like to make a complaint about my room.","ex_es":"Quisiera poner una queja sobre mi habitación."},{"en":"noisy","es":"ruidoso","pos":"adj","ex_en":"The room next to ours was very noisy all night.","ex_es":"El cuarto de al lado estuvo muy ruidoso toda la noche."},{"en":"dirty","es":"sucio","pos":"adj","ex_en":"The bathroom was dirty when we arrived.","ex_es":"El baño estaba sucio cuando llegamos."},{"en":"refund","es":"reembolso","pos":"noun","ex_en":"The airline gave me a full refund.","ex_es":"La aerolínea me dio un reembolso completo."},{"en":"air conditioning","es":"aire acondicionado","pos":"noun","ex_en":"The air conditioning in our room doesn't work.","ex_es":"El aire acondicionado de nuestro cuarto no funciona."},{"en":"miss","es":"perder (un vuelo, un camión)","pos":"verb","ex_en":"We missed our connecting flight in Dallas.","ex_es":"Perdimos nuestro vuelo de conexión en Dallas."},{"en":"upgrade","es":"mejora de categoría","pos":"noun","ex_en":"They gave us a free upgrade to a suite.","ex_es":"Nos subieron gratis de categoría a una suite."},{"en":"apologize","es":"disculparse","pos":"verb","ex_en":"The manager apologized for the problem.","ex_es":"El gerente se disculpó por el problema."}],"sentences":[{"en":"There's no hot water in my room.","es":"No hay agua caliente en mi cuarto."},{"en":"The towels in the bathroom are dirty.","es":"Las toallas del baño están sucias."},{"en":"I'm sorry, but the room is too noisy to sleep.","es":"Lo siento, pero el cuarto es demasiado ruidoso para dormir."},{"en":"The airline lost my luggage and I need help.","es":"La aerolínea perdió mi equipaje y necesito ayuda."},{"en":"We missed our flight, so we asked for a refund.","es":"Perdimos el vuelo, así que pedimos un reembolso."}],"tip_es":"Para perder un vuelo o un camión se usa miss, no lose: I missed my flight. Lose es perder un objeto: I lost my passport. Una queja amable suele empezar con I'm sorry, but y luego el problema."},{"id":"12-6","title_es":"Pedir favores con could you","words":[{"en":"could you","es":"podría usted, podrías","pos":"phrase","ex_en":"Could you help me with my bags, please?","ex_es":"¿Podría ayudarme con mis maletas, por favor?"},{"en":"could I","es":"podría yo","pos":"phrase","ex_en":"Could I have a map of the city?","ex_es":"¿Me podría dar un mapa de la ciudad?"},{"en":"would you mind","es":"le molestaría","pos":"phrase","ex_en":"Would you mind taking a picture of us?","ex_es":"¿Le molestaría tomarnos una foto?"},{"en":"recommend","es":"recomendar","pos":"verb","ex_en":"Can you recommend a good restaurant near the hotel?","ex_es":"¿Me puede recomendar un buen restaurante cerca del hotel?"},{"en":"store","es":"guardar","pos":"verb","ex_en":"Could you store our bags until three?","ex_es":"¿Nos podría guardar las maletas hasta las tres?"},{"en":"call a taxi","es":"pedir un taxi","pos":"phrase","ex_en":"The receptionist can call a taxi for you.","ex_es":"La recepcionista le puede pedir un taxi."},{"en":"sightseeing","es":"turismo, conocer lugares","pos":"noun","ex_en":"We spent the whole day sightseeing downtown.","ex_es":"Pasamos todo el día conociendo el centro."},{"en":"tip","es":"propina","pos":"noun","ex_en":"In the United States, people usually leave a tip of twenty percent.","ex_es":"En Estados Unidos, la gente normalmente deja veinte por ciento de propina."}],"sentences":[{"en":"Could you speak more slowly, please?","es":"¿Podría hablar más despacio, por favor?"},{"en":"Could I check out a little later tomorrow?","es":"¿Podría entregar la habitación un poco más tarde mañana?"},{"en":"Would you mind waiting five minutes?","es":"¿Le molestaría esperar cinco minutos?"},{"en":"What places do you recommend for sightseeing in the city?","es":"¿Qué lugares me recomienda para conocer la ciudad?"},{"en":"Could you call a taxi to take us to the airport?","es":"¿Podría pedirnos un taxi para ir al aeropuerto?"}],"tip_es":"Could you es más amable que can you y es ideal con desconocidos. Después de would you mind el verbo va con -ing: would you mind waiting? Para aceptar se responde no, not at all, porque significa no me molesta."},{"id":"12-7","title_es":"Moverse por la ciudad","words":[{"en":"subway","es":"metro","pos":"noun","ex_en":"The subway is the fastest way to get downtown.","ex_es":"El metro es la forma más rápida de llegar al centro."},{"en":"bus stop","es":"parada de camión","pos":"noun","ex_en":"Excuse me, where is the nearest bus stop?","ex_es":"Disculpe, ¿dónde está la parada de camión más cercana?"},{"en":"round-trip ticket","es":"boleto redondo","pos":"noun","ex_en":"I'd like a round-trip ticket to Boston, please.","ex_es":"Quisiera un boleto redondo a Boston, por favor."},{"en":"directions","es":"indicaciones","pos":"noun","ex_en":"Could you give me directions to the museum?","ex_es":"¿Me podría decir cómo llegar al museo?"},{"en":"turn left","es":"dar vuelta a la izquierda","pos":"phrase","ex_en":"Turn left at the second traffic light.","ex_es":"Dé vuelta a la izquierda en el segundo semáforo."},{"en":"go straight","es":"seguir derecho","pos":"phrase","ex_en":"Go straight for two blocks.","ex_es":"Siga derecho dos cuadras."},{"en":"block","es":"cuadra","pos":"noun","ex_en":"The hotel is three blocks from here.","ex_es":"El hotel está a tres cuadras de aquí."},{"en":"get lost","es":"perderse","pos":"phrase","ex_en":"It's easy to get lost in this neighborhood.","ex_es":"Es fácil perderse en esta colonia."}],"sentences":[{"en":"Excuse me, could you tell me how to get to the station?","es":"Disculpe, ¿me podría decir cómo llegar a la estación?"},{"en":"Go straight for three blocks and turn left at the bank.","es":"Siga derecho tres cuadras y dé vuelta a la izquierda en el banco."},{"en":"Is it better to take the subway or a taxi?","es":"¿Es mejor tomar el metro o un taxi?"},{"en":"We got lost because the map on my phone wasn't working.","es":"Nos perdimos porque el mapa de mi celular no funcionaba."},{"en":"Would you mind showing me the bus stop on this map?","es":"¿Le molestaría mostrarme la parada del camión en este mapa?"}],"tip_es":"Para pedir indicaciones de forma amable empieza con Excuse me y usa could you. Directions en plural significa indicaciones para llegar a un lugar. En Estados Unidos las distancias en la ciudad se miden en blocks, que son cuadras."},{"id":"12-8","title_es":"En carretera: rentar un carro","words":[{"en":"rent a car","es":"rentar un carro","pos":"phrase","ex_en":"We want to rent a car for the weekend.","ex_es":"Queremos rentar un carro para el fin de semana."},{"en":"driver's license","es":"licencia de manejo","pos":"noun","ex_en":"Can I see your driver's license, please?","ex_es":"¿Me permite su licencia de manejo, por favor?"},{"en":"gas station","es":"gasolinera","pos":"noun","ex_en":"Let's stop at the next gas station.","ex_es":"Paremos en la próxima gasolinera."},{"en":"highway","es":"carretera, autopista","pos":"noun","ex_en":"The highway was full of trucks this morning.","ex_es":"La carretera estaba llena de tráileres esta mañana."},{"en":"toll","es":"caseta, peaje","pos":"noun","ex_en":"How much is the toll to Acapulco?","ex_es":"¿Cuánto cuesta la caseta a Acapulco?"},{"en":"parking lot","es":"estacionamiento","pos":"noun","ex_en":"The hotel has a free parking lot.","ex_es":"El hotel tiene estacionamiento gratis."},{"en":"fill up","es":"llenar (el tanque)","pos":"phrase","ex_en":"Could you fill up the tank, please?","ex_es":"¿Me llena el tanque, por favor?"},{"en":"flat tire","es":"llanta ponchada","pos":"noun","ex_en":"We had a flat tire on the way to the beach.","ex_es":"Se nos ponchó una llanta camino a la playa."}],"sentences":[{"en":"I'd like to rent a car for three days, please.","es":"Quisiera rentar un carro por tres días, por favor."},{"en":"Do I need an international driver's license to drive here?","es":"¿Necesito una licencia internacional para manejar aquí?"},{"en":"The highway is faster, but you have to pay two tolls.","es":"La autopista es más rápida, pero tienes que pagar dos casetas."},{"en":"Could you recommend a safe parking lot near the center?","es":"¿Me podría recomendar un estacionamiento seguro cerca del centro?"},{"en":"We got a flat tire, so we called the rental company.","es":"Se nos ponchó una llanta, así que llamamos a la arrendadora."}],"tip_es":"En inglés de Estados Unidos se dice gas station y gas, no gasoline station. Rent a car es rentar un carro, y la empresa se llama car rental company. Fill up the tank significa llenar el tanque."},{"id":"12-9","title_es":"Aduana, equipaje y cambios de plan","words":[{"en":"customs","es":"aduana","pos":"noun","ex_en":"We spent an hour waiting at customs.","ex_es":"Pasamos una hora esperando en la aduana."},{"en":"declare","es":"declarar","pos":"verb","ex_en":"Do you have anything to declare?","ex_es":"¿Tiene algo que declarar?"},{"en":"baggage claim","es":"reclamo de equipaje","pos":"noun","ex_en":"Our suitcases are at baggage claim number four.","ex_es":"Nuestras maletas están en la banda de equipaje número cuatro."},{"en":"suitcase","es":"maleta","pos":"noun","ex_en":"My suitcase is too heavy.","ex_es":"Mi maleta pesa demasiado."},{"en":"connecting flight","es":"vuelo de conexión","pos":"noun","ex_en":"I almost missed my connecting flight in Dallas.","ex_es":"Casi pierdo mi vuelo de conexión en Dallas."},{"en":"exchange rate","es":"tipo de cambio","pos":"noun","ex_en":"What's the exchange rate for pesos today?","ex_es":"¿A cómo está el tipo de cambio del peso hoy?"},{"en":"lost and found","es":"objetos perdidos","pos":"noun","ex_en":"Ask at the lost and found office.","ex_es":"Pregunte en la oficina de objetos perdidos."},{"en":"cancel","es":"cancelar","pos":"verb","ex_en":"The airline had to cancel our flight.","ex_es":"La aerolínea tuvo que cancelar nuestro vuelo."}],"sentences":[{"en":"I don't have anything to declare, just clothes and gifts.","es":"No tengo nada que declarar, solo ropa y regalos."},{"en":"Excuse me, where can I find baggage claim?","es":"Disculpe, ¿dónde está el reclamo de equipaje?"},{"en":"My suitcase didn't arrive, could you help me find it?","es":"Mi maleta no llegó, ¿me podría ayudar a encontrarla?"},{"en":"They canceled my connecting flight, so I need another one.","es":"Cancelaron mi vuelo de conexión, así que necesito otro."},{"en":"The exchange rate at the airport is usually worse than downtown.","es":"El tipo de cambio en el aeropuerto suele ser peor que en el centro."}],"tip_es":"Customs es la aduana y siempre termina en s. En Estados Unidos se escribe canceled con una sola l. Si pierdes algo, busca la oficina de lost and found, que es objetos perdidos."},{"id":"12-10","title_es":"En la vida real: un viaje completo","words":[{"en":"itinerary","es":"itinerario","pos":"noun","ex_en":"Could you email me the itinerary for the trip?","ex_es":"¿Me podría mandar el itinerario del viaje por correo?"},{"en":"tour guide","es":"guía de turistas","pos":"noun","ex_en":"Our tour guide spoke English and Spanish.","ex_es":"Nuestro guía hablaba inglés y español."},{"en":"jet lag","es":"jet lag, desfase de horario","pos":"noun","ex_en":"I had terrible jet lag after the flight to Madrid.","ex_es":"Tuve un jet lag horrible después del vuelo a Madrid."},{"en":"local","es":"persona del lugar","pos":"noun","ex_en":"Ask a local for a good place to eat.","ex_es":"Pregúntale a alguien de ahí por un buen lugar para comer."},{"en":"backpack","es":"mochila","pos":"noun","ex_en":"I only took a backpack for the weekend.","ex_es":"Solo llevé una mochila para el fin de semana."},{"en":"travel insurance","es":"seguro de viaje","pos":"noun","ex_en":"Travel insurance paid for my lost luggage.","ex_es":"El seguro de viaje pagó mi equipaje perdido."},{"en":"pack","es":"empacar, hacer la maleta","pos":"verb","ex_en":"I always pack the night before a trip.","ex_es":"Siempre empaco la noche antes de un viaje."},{"en":"unforgettable","es":"inolvidable","pos":"adj","ex_en":"Our trip to Chiapas was unforgettable.","ex_es":"Nuestro viaje a Chiapas fue inolvidable."}],"sentences":[{"en":"I booked a double room and checked the itinerary twice.","es":"Reservé una habitación doble y revisé el itinerario dos veces."},{"en":"Our flight was delayed, so we arrived with terrible jet lag.","es":"Nuestro vuelo se retrasó y llegamos con un jet lag horrible."},{"en":"Would you mind taking a picture of us, please?","es":"¿Le molestaría tomarnos una foto, por favor?"},{"en":"The tour guide recommended a small restaurant where the locals eat.","es":"El guía nos recomendó un restaurante pequeño donde come la gente local."},{"en":"It was an unforgettable trip, and I can't wait to go back.","es":"Fue un viaje inolvidable y ya quiero regresar."}],"tip_es":"Pack es empacar o hacer la maleta: I need to pack tonight. Local como sustantivo significa una persona del lugar: Ask a local. Para pedir favores a desconocidos durante el viaje, recuerda usar could you y would you mind."}],"dialogue":{"title_es":"Llegada al hotel","setting_es":"Llegas a tu hotel en San Francisco después de un vuelo largo.","lines":[{"who":"A","en":"Good evening and welcome. How can I help you?","es":"Buenas noches y bienvenido. ¿En qué le puedo ayudar?"},{"who":"B","en":"Hi, I have a reservation under the name Ramírez.","es":"Hola, tengo una reservación a nombre de Ramírez."},{"who":"A","en":"Let me check. Yes, a double room for three nights.","es":"Déjeme revisar. Sí, una habitación doble por tres noches."},{"who":"B","en":"That's right. Is breakfast included?","es":"Así es. ¿El desayuno está incluido?"},{"who":"A","en":"Yes, it's served from seven to ten in the restaurant.","es":"Sí, se sirve de siete a diez en el restaurante."},{"who":"B","en":"Great. Could I check out at one on Sunday?","es":"Perfecto. ¿Podría entregar la habitación a la una el domingo?"},{"who":"A","en":"Sure, no problem. Here is your key card. You're in room 504.","es":"Claro, sin problema. Aquí tiene su tarjeta. Está en la habitación 504."},{"who":"B","en":"Thank you. What's the password for the Wi-Fi?","es":"Gracias. ¿Cuál es la contraseña del wifi?"},{"who":"A","en":"It's on the card, next to your room number.","es":"Está en la tarjeta, junto al número de su habitación."},{"who":"B","en":"Perfect. Thanks for your help!","es":"Perfecto. ¡Gracias por su ayuda!"}]}},{"id":13,"title_es":"Planes y futuro","title_en":"Plans and the future","level":"B1","goal_es":"Al terminar podrás hablar de tus planes, hacer predicciones, hacer promesas y aceptar o rechazar invitaciones.","lessons":[{"id":"13-1","title_es":"Planes con going to","words":[{"en":"going to","es":"ir a (futuro)","pos":"phrase","ex_en":"I'm going to visit my aunt next month.","ex_es":"Voy a visitar a mi tía el próximo mes."},{"en":"save up","es":"ahorrar","pos":"verb","ex_en":"We want to save up for a new car.","ex_es":"Queremos ahorrar para un coche nuevo."},{"en":"move out","es":"mudarse (dejar la casa)","pos":"verb","ex_en":"My brother is going to move out in June.","ex_es":"Mi hermano se va a mudar en junio."},{"en":"sign up","es":"inscribirse","pos":"verb","ex_en":"I'm going to sign up for a yoga class.","ex_es":"Me voy a inscribir a una clase de yoga."},{"en":"get married","es":"casarse","pos":"phrase","ex_en":"They're going to get married in December.","ex_es":"Se van a casar en diciembre."},{"en":"take a break","es":"tomar un descanso","pos":"phrase","ex_en":"After the exam, I'm going to take a break.","ex_es":"Después del examen, voy a tomar un descanso."},{"en":"remodel","es":"remodelar","pos":"verb","ex_en":"My parents are going to remodel the kitchen.","ex_es":"Mis papás van a remodelar la cocina."},{"en":"the day after tomorrow","es":"pasado mañana","pos":"phrase","ex_en":"We're leaving the day after tomorrow.","ex_es":"Nos vamos pasado mañana."}],"sentences":[{"en":"What are you going to do this weekend?","es":"¿Qué vas a hacer este fin de semana?"},{"en":"I'm going to stay home and relax.","es":"Me voy a quedar en casa a descansar."},{"en":"She isn't going to work tomorrow.","es":"Ella no va a trabajar mañana."},{"en":"Are you going to sign up for the English course?","es":"¿Te vas a inscribir al curso de inglés?"},{"en":"We're going to save up and travel to Oaxaca next year.","es":"Vamos a ahorrar y viajar a Oaxaca el próximo año."}],"tip_es":"Usa going to para planes que ya decidiste antes de hablar. La estructura es sujeto + am/is/are + going to + verbo base: I'm going to study. En conversación suena como gonna, pero no lo escribas en textos formales."},{"id":"13-2","title_es":"Decisiones y promesas con will","words":[{"en":"promise","es":"prometer","pos":"verb","ex_en":"I promise I'll call you tonight.","ex_es":"Te prometo que te llamo hoy en la noche."},{"en":"offer","es":"ofrecer","pos":"verb","ex_en":"He didn't offer to help us.","ex_es":"Él no se ofreció a ayudarnos."},{"en":"decide","es":"decidir","pos":"verb","ex_en":"I can't decide what to order.","ex_es":"No puedo decidir qué pedir."},{"en":"pick up","es":"recoger","pos":"verb","ex_en":"I'll pick up the kids after school.","ex_es":"Yo recojo a los niños después de la escuela."},{"en":"help out","es":"echar la mano","pos":"verb","ex_en":"I'll help out with the party on Saturday.","ex_es":"Yo echo la mano con la fiesta el sábado."},{"en":"right away","es":"de inmediato","pos":"adv","ex_en":"I'll send you the address right away.","ex_es":"Te mando la dirección de inmediato."},{"en":"on second thought","es":"pensándolo bien","pos":"phrase","ex_en":"On second thought, I'll have the soup.","ex_es":"Pensándolo bien, voy a pedir la sopa."},{"en":"I'll get it","es":"yo voy, yo contesto","pos":"phrase","ex_en":"Someone's at the door. I'll get it!","ex_es":"Alguien está tocando. ¡Yo voy!"}],"sentences":[{"en":"Don't worry, I'll help you with the boxes.","es":"No te preocupes, te ayudo con las cajas."},{"en":"I promise I won't be late again.","es":"Te prometo que no voy a llegar tarde otra vez."},{"en":"It's cold in here. I'll close the window.","es":"Hace frío aquí. Voy a cerrar la ventana."},{"en":"Will you pick me up at the station?","es":"¿Me recoges en la estación?"},{"en":"I think I'll take the bus today.","es":"Creo que hoy me voy a ir en camión."}],"tip_es":"Usa will para decisiones que tomas en el momento, promesas y ofrecimientos. La forma negativa es won't. Ojo: en español muchas veces usamos presente (te ayudo), pero en inglés necesitas I'll help you."},{"id":"13-3","title_es":"Predicciones","words":[{"en":"probably","es":"probablemente","pos":"adv","ex_en":"It will probably rain tonight.","ex_es":"Probablemente va a llover hoy en la noche."},{"en":"definitely","es":"definitivamente","pos":"adv","ex_en":"She will definitely love your gift.","ex_es":"Definitivamente le va a encantar tu regalo."},{"en":"forecast","es":"pronóstico","pos":"noun","ex_en":"The weather forecast says it will be sunny.","ex_es":"El pronóstico del clima dice que va a estar soleado."},{"en":"likely","es":"probable","pos":"adj","ex_en":"It's likely to snow in the mountains.","ex_es":"Es probable que nieve en las montañas."},{"en":"I bet","es":"apuesto a que","pos":"phrase","ex_en":"I bet they'll win the game.","ex_es":"Apuesto a que van a ganar el partido."},{"en":"go up","es":"subir","pos":"verb","ex_en":"Rent is going to go up next year.","ex_es":"La renta va a subir el próximo año."},{"en":"in the future","es":"en el futuro","pos":"phrase","ex_en":"In the future, cars will drive themselves.","ex_es":"En el futuro, los coches se van a manejar solos."},{"en":"doubt","es":"dudar","pos":"verb","ex_en":"I doubt he'll come to the meeting.","ex_es":"Dudo que venga a la junta."}],"sentences":[{"en":"I think robots will do many jobs in the future.","es":"Creo que los robots harán muchos trabajos en el futuro."},{"en":"According to the forecast, it's going to rain tomorrow.","es":"Según el pronóstico, va a llover mañana."},{"en":"Look at that sky! It's going to storm.","es":"¡Mira ese cielo! Va a haber tormenta."},{"en":"Mexico will probably win the next match.","es":"México probablemente va a ganar el próximo partido."},{"en":"I doubt prices will go down this year.","es":"Dudo que los precios bajen este año."}],"tip_es":"Para predicciones basadas en tu opinión usa will: I think it will rain. Si tienes una evidencia que ves ahora, usa going to: Look at those clouds, it's going to rain. Probably va después de will, pero antes de won't: it will probably, it probably won't."},{"id":"13-4","title_es":"Invitaciones","words":[{"en":"invite","es":"invitar","pos":"verb","ex_en":"I want to invite you to my birthday party.","ex_es":"Te quiero invitar a mi fiesta de cumpleaños."},{"en":"would you like to","es":"¿te gustaría...?","pos":"phrase","ex_en":"Would you like to go for a coffee?","ex_es":"¿Te gustaría ir por un café?"},{"en":"feel like","es":"tener ganas de","pos":"verb","ex_en":"I don't feel like cooking tonight.","ex_es":"No tengo ganas de cocinar hoy en la noche."},{"en":"I'd love to","es":"me encantaría","pos":"phrase","ex_en":"I'd love to, thanks for asking!","ex_es":"¡Me encantaría, gracias por preguntar!"},{"en":"take a rain check","es":"dejarlo para otra ocasión","pos":"phrase","ex_en":"Can I take a rain check on dinner?","ex_es":"¿Podemos dejar la cena para otra ocasión?"},{"en":"make it","es":"poder ir, lograr llegar","pos":"verb","ex_en":"Sorry, I can't make it on Friday.","ex_es":"Perdón, el viernes no voy a poder ir."},{"en":"get-together","es":"reunión","pos":"noun","ex_en":"We're having a small get-together on Saturday.","ex_es":"Vamos a hacer una pequeña reunión el sábado."},{"en":"join","es":"acompañar, unirse","pos":"verb","ex_en":"Why don't you join us for lunch?","ex_es":"¿Por qué no nos acompañas a comer?"}],"sentences":[{"en":"Would you like to come to my house for dinner?","es":"¿Te gustaría venir a cenar a mi casa?"},{"en":"I'd love to, but I have to work late.","es":"Me encantaría, pero tengo que trabajar hasta tarde."},{"en":"Do you feel like going for tacos tonight?","es":"¿Tienes ganas de ir por unos tacos hoy en la noche?"},{"en":"Thanks for the invitation, but I can't make it.","es":"Gracias por la invitación, pero no voy a poder ir."},{"en":"How about next weekend instead?","es":"¿Qué tal mejor el próximo fin de semana?"}],"tip_es":"Después de would you like usa to + verbo: Would you like to come? Pero después de feel like y how about usa el verbo con -ing: feel like going, how about meeting. Para rechazar con amabilidad di I'd love to, but... y da una razón."},{"id":"13-5","title_es":"Planes fijos y horarios","words":[{"en":"schedule","es":"agenda, horario","pos":"noun","ex_en":"My schedule is packed this week.","ex_es":"Mi agenda está llenísima esta semana."},{"en":"available","es":"disponible","pos":"adj","ex_en":"Are you available on Thursday morning?","ex_es":"¿Estás disponible el jueves en la mañana?"},{"en":"reschedule","es":"cambiar la fecha, reprogramar","pos":"verb","ex_en":"Can we reschedule the meeting for Monday?","ex_es":"¿Podemos cambiar la junta para el lunes?"},{"en":"call off","es":"cancelar","pos":"verb","ex_en":"They had to call off the concert because of the rain.","ex_es":"Tuvieron que cancelar el concierto por la lluvia."},{"en":"put off","es":"posponer, dejar para después","pos":"verb","ex_en":"Don't put off your homework until Sunday.","ex_es":"No dejes tu tarea para el domingo."},{"en":"deadline","es":"fecha límite","pos":"noun","ex_en":"The deadline for the project is next Friday.","ex_es":"La fecha límite del proyecto es el próximo viernes."},{"en":"set a date","es":"fijar una fecha","pos":"phrase","ex_en":"We still need to set a date for the trip.","ex_es":"Todavía tenemos que fijar una fecha para el viaje."},{"en":"pencil in","es":"apuntar tentativamente","pos":"verb","ex_en":"I'll pencil in our lunch for Tuesday.","ex_es":"Voy a apuntar nuestra comida para el martes, por si acaso."}],"sentences":[{"en":"I'm meeting my cousin at the airport tomorrow.","es":"Mañana voy a ver a mi primo en el aeropuerto."},{"en":"What are you doing on Saturday night?","es":"¿Qué vas a hacer el sábado en la noche?"},{"en":"We're having a barbecue on Sunday afternoon.","es":"Vamos a hacer una carne asada el domingo en la tarde."},{"en":"The train leaves at seven fifteen tomorrow morning.","es":"El tren sale mañana a las siete y cuarto de la mañana."},{"en":"Sorry, I'm not available on Monday. Can we reschedule?","es":"Perdón, no estoy disponible el lunes. ¿Lo podemos cambiar?"}],"tip_es":"Para planes fijos que ya acordaste con alguien, con hora o lugar, usa el presente continuo: I'm seeing the dentist on Friday. Para horarios oficiales como trenes, vuelos o clases, usa el presente simple: The flight leaves at six."},{"id":"13-6","title_es":"Metas y sueños","words":[{"en":"goal","es":"meta","pos":"noun","ex_en":"My goal is to run a marathon.","ex_es":"Mi meta es correr un maratón."},{"en":"achieve","es":"lograr","pos":"verb","ex_en":"You can achieve anything if you work hard.","ex_es":"Puedes lograr cualquier cosa si te esfuerzas."},{"en":"look forward to","es":"tener muchas ganas de","pos":"phrase","ex_en":"I look forward to our vacation every year.","ex_es":"Cada año espero con muchas ganas nuestras vacaciones."},{"en":"hope to","es":"esperar (con ilusión)","pos":"phrase","ex_en":"I hope to find a better job soon.","ex_es":"Espero encontrar un mejor trabajo pronto."},{"en":"about to","es":"a punto de","pos":"phrase","ex_en":"Hurry up, the movie is about to start.","ex_es":"Apúrate, la película está a punto de empezar."},{"en":"someday","es":"algún día","pos":"adv","ex_en":"Someday I'm going to open my own café.","ex_es":"Algún día voy a abrir mi propia cafetería."},{"en":"by the end of","es":"para finales de","pos":"phrase","ex_en":"I want to speak English well by the end of the year.","ex_es":"Quiero hablar bien inglés para finales del año."},{"en":"give up","es":"rendirse","pos":"verb","ex_en":"Don't give up on your dreams.","ex_es":"No te rindas con tus sueños."}],"sentences":[{"en":"My goal is to get a better job next year.","es":"Mi meta es conseguir un mejor trabajo el próximo año."},{"en":"I hope to visit Canada someday.","es":"Espero conocer Canadá algún día."},{"en":"We're looking forward to seeing you at the wedding.","es":"Tenemos muchas ganas de verte en la boda."},{"en":"By the end of the course, you'll understand movies in English.","es":"Para el final del curso, vas a entender películas en inglés."},{"en":"It won't be easy, but I'm not going to give up.","es":"No va a ser fácil, pero no me voy a rendir."}],"tip_es":"Después de look forward to va un verbo con -ing, porque aquí to es preposición: I'm looking forward to meeting you, no to meet you. Es un error muy común de los hispanohablantes, sobre todo en correos."},{"id":"13-7","title_es":"Planes de viaje","words":[{"en":"book","es":"reservar","pos":"verb","ex_en":"We're going to book the hotel tonight.","ex_es":"Vamos a reservar el hotel esta noche."},{"en":"itinerary","es":"itinerario","pos":"noun","ex_en":"I'll send you the itinerary tomorrow morning.","ex_es":"Te mando el itinerario mañana en la mañana."},{"en":"round trip","es":"viaje redondo","pos":"noun","ex_en":"A round trip to Cancún will cost about five thousand pesos.","ex_es":"Un viaje redondo a Cancún va a costar unos cinco mil pesos."},{"en":"set off","es":"salir, emprender el camino","pos":"verb","ex_en":"We're going to set off early to avoid traffic.","ex_es":"Vamos a salir temprano para evitar el tráfico."},{"en":"look into","es":"investigar, checar","pos":"verb","ex_en":"I'll look into cheaper flights this afternoon.","ex_es":"Voy a checar vuelos más baratos esta tarde."},{"en":"getaway","es":"escapada","pos":"noun","ex_en":"We're planning a weekend getaway to Valle de Bravo.","ex_es":"Estamos planeando una escapada de fin de semana a Valle de Bravo."},{"en":"layover","es":"escala","pos":"noun","ex_en":"Our flight has a long layover in Dallas.","ex_es":"Nuestro vuelo tiene una escala larga en Dallas."},{"en":"pack","es":"empacar, hacer la maleta","pos":"verb","ex_en":"I'm going to pack my suitcase the night before.","ex_es":"Voy a hacer la maleta la noche anterior."}],"sentences":[{"en":"We're going to book a round trip to Mérida next month.","es":"Vamos a reservar un viaje redondo a Mérida el próximo mes."},{"en":"I'll look into hotels near the beach tonight.","es":"Esta noche voy a buscar hoteles cerca de la playa."},{"en":"What time are you going to set off tomorrow?","es":"¿A qué hora van a salir mañana?"},{"en":"They're planning a short getaway after the exams.","es":"Están planeando una escapada corta después de los exámenes."},{"en":"Our flight has a layover, so we'll arrive late.","es":"Nuestro vuelo tiene escala, así que vamos a llegar tarde."}],"tip_es":"Para hablar de planes también puedes usar be planning to + verbo: We're planning to travel in May. Ojo: book como verbo significa reservar, no tiene nada que ver con libro. I'll book the tickets es Yo reservo los boletos."},{"id":"13-8","title_es":"Posibilidad y certeza","words":[{"en":"might","es":"podría, quizás","pos":"verb","ex_en":"I might go to the party, but I'm not sure.","ex_es":"Quizás vaya a la fiesta, pero no estoy seguro."},{"en":"may","es":"puede que, tal vez","pos":"verb","ex_en":"It may be difficult to find parking downtown.","ex_es":"Puede que sea difícil encontrar estacionamiento en el centro."},{"en":"chances are","es":"lo más probable es que","pos":"phrase","ex_en":"Chances are they'll be late again.","ex_es":"Lo más probable es que lleguen tarde otra vez."},{"en":"for sure","es":"seguro, sin falta","pos":"phrase","ex_en":"I'll be there for sure, don't worry.","ex_es":"Ahí estaré seguro, no te preocupes."},{"en":"unlikely","es":"poco probable","pos":"adj","ex_en":"It's unlikely that the store will open on Sunday.","ex_es":"Es poco probable que la tienda abra el domingo."},{"en":"turn out","es":"resultar, salir","pos":"verb","ex_en":"I hope everything will turn out well.","ex_es":"Espero que todo salga bien."},{"en":"bound to","es":"seguro que, tiene que","pos":"phrase","ex_en":"He's bound to notice the mistake.","ex_es":"Seguro que va a notar el error."},{"en":"hopefully","es":"ojalá, con suerte","pos":"adv","ex_en":"Hopefully, the weather will be nice on Saturday.","ex_es":"Ojalá que el clima esté bonito el sábado."}],"sentences":[{"en":"I might change jobs next year. I'm still thinking about it.","es":"Quizás cambie de trabajo el próximo año. Todavía lo estoy pensando."},{"en":"Chances are the traffic will be terrible on Friday.","es":"Lo más probable es que el tráfico esté terrible el viernes."},{"en":"It's unlikely that prices will go down soon.","es":"Es poco probable que los precios bajen pronto."},{"en":"Hopefully, everything will turn out fine.","es":"Ojalá que todo salga bien."},{"en":"Don't worry, she's bound to call you back.","es":"No te preocupes, seguro que te va a regresar la llamada."}],"tip_es":"Might y may expresan que algo es posible, pero menos seguro que will. Después de ellos va el verbo base sin to: I might go, nunca I might to go. Para ojalá, en inglés se usa mucho hopefully al inicio de la oración."},{"id":"13-9","title_es":"Mi vida en el futuro","words":[{"en":"this time next year","es":"el próximo año a estas alturas","pos":"phrase","ex_en":"This time next year, I'll be living in Guadalajara.","ex_es":"El próximo año a estas alturas, voy a estar viviendo en Guadalajara."},{"en":"by then","es":"para entonces","pos":"phrase","ex_en":"Call me at nine. I'll have finished dinner by then.","ex_es":"Llámame a las nueve. Para entonces ya habré terminado de cenar."},{"en":"retire","es":"jubilarse, retirarse","pos":"verb","ex_en":"My dad will retire in two years.","ex_es":"Mi papá se va a jubilar en dos años."},{"en":"settle down","es":"sentar cabeza, establecerse","pos":"verb","ex_en":"I think I'll settle down when I'm thirty.","ex_es":"Creo que voy a sentar cabeza cuando tenga treinta."},{"en":"career","es":"carrera profesional","pos":"noun","ex_en":"She's going to start a new career in design.","ex_es":"Ella va a empezar una nueva carrera en diseño."},{"en":"pay off","es":"terminar de pagar, liquidar","pos":"verb","ex_en":"We hope to pay off the car by December.","ex_es":"Esperamos terminar de pagar el coche para diciembre."},{"en":"own","es":"ser dueño de, tener propio","pos":"verb","ex_en":"I hope I'll own a small business someday.","ex_es":"Espero tener mi propio negocio algún día."},{"en":"relocate","es":"cambiar de sede, reubicar","pos":"verb","ex_en":"The company is going to relocate us to Querétaro.","ex_es":"La empresa nos va a cambiar a Querétaro."}],"sentences":[{"en":"This time tomorrow, I'll be flying to Tijuana.","es":"Mañana a esta hora voy a estar volando a Tijuana."},{"en":"By the end of the year, we'll have paid off the loan.","es":"Para fin de año, ya habremos liquidado el préstamo."},{"en":"Don't call at eight. I'll be having dinner then.","es":"No llames a las ocho. A esa hora voy a estar cenando."},{"en":"In ten years, I'll probably own my own house.","es":"En diez años, probablemente voy a tener mi propia casa."},{"en":"Will you have finished the project by Friday?","es":"¿Ya habrás terminado el proyecto para el viernes?"}],"tip_es":"Usa will be + verbo con -ing para una acción que estará en progreso en un momento del futuro: I'll be working at five. Usa will have + participio para algo que ya estará terminado antes de cierto momento: I'll have finished by then."},{"id":"13-10","title_es":"Planes en la vida real","words":[{"en":"make plans","es":"hacer planes","pos":"phrase","ex_en":"Let's make plans for the long weekend.","ex_es":"Hagamos planes para el puente."},{"en":"count on","es":"contar con","pos":"verb","ex_en":"You can count on me. I'll be there.","ex_es":"Puedes contar conmigo. Ahí estaré."},{"en":"running late","es":"ir tarde, ir retrasado","pos":"phrase","ex_en":"Sorry, I'm running late. I'll be there in ten minutes.","ex_es":"Perdón, voy tarde. Llego en diez minutos."},{"en":"head out","es":"salir, irse","pos":"verb","ex_en":"We're going to head out around six.","ex_es":"Vamos a salir como a las seis."},{"en":"on my way","es":"en camino","pos":"phrase","ex_en":"I'm on my way. I'll text you when I arrive.","ex_es":"Ya voy en camino. Te escribo cuando llegue."},{"en":"at the last minute","es":"a última hora","pos":"phrase","ex_en":"He canceled at the last minute again.","ex_es":"Volvió a cancelar a última hora."},{"en":"save the date","es":"aparta la fecha","pos":"phrase","ex_en":"Save the date! We're getting married in May.","ex_es":"¡Aparta la fecha! Nos casamos en mayo."},{"en":"keep me posted","es":"mantenme al tanto","pos":"phrase","ex_en":"Keep me posted about the trip, okay?","ex_es":"Mantenme al tanto del viaje, ¿sale?"}],"sentences":[{"en":"Are you going to come to Ana's party on Saturday?","es":"¿Vas a venir a la fiesta de Ana el sábado?"},{"en":"I'd love to, but I might be working that day.","es":"Me encantaría, pero quizás tenga que trabajar ese día."},{"en":"Don't worry, I'll call you if my plans change.","es":"No te preocupes, te llamo si cambian mis planes."},{"en":"We're meeting at seven, so I'll pick you up at six thirty.","es":"Quedamos a las siete, así que paso por ti a las seis y media."},{"en":"This time next week, we'll be relaxing on the beach.","es":"La próxima semana a esta hora, vamos a estar descansando en la playa."}],"tip_es":"En la vida real mezclas varias formas de futuro: going to para planes decididos, will para promesas y decisiones del momento, presente continuo para citas acordadas y might para lo que no es seguro. Elegir bien hace que suenes mucho más natural."}],"dialogue":{"title_es":"Planes para el puente","setting_es":"Un amigo te invita a un viaje para el fin de semana largo.","lines":[{"who":"A","en":"Hey! Do you have any plans for the long weekend?","es":"¡Hola! ¿Tienes planes para el puente?"},{"who":"B","en":"Not really. I think I'll just stay home and rest.","es":"No mucho. Creo que nada más me voy a quedar en casa a descansar."},{"who":"A","en":"Some friends and I are going to Valle de Bravo. Would you like to join us?","es":"Unos amigos y yo vamos a Valle de Bravo. ¿Te gustaría acompañarnos?"},{"who":"B","en":"I'd love to! When are you leaving?","es":"¡Me encantaría! ¿Cuándo se van?"},{"who":"A","en":"We're leaving on Friday at eight in the morning.","es":"Nos vamos el viernes a las ocho de la mañana."},{"who":"B","en":"Perfect. I'll ask my boss if I can take Friday off.","es":"Perfecto. Le voy a preguntar a mi jefe si me puedo tomar el viernes."},{"who":"A","en":"Great. The forecast says it's going to be sunny all weekend.","es":"Genial. El pronóstico dice que va a estar soleado todo el fin de semana."},{"who":"B","en":"Awesome. I'll bring snacks for the road.","es":"Qué padre. Yo llevo botanas para el camino."},{"who":"A","en":"Thanks! I'm really looking forward to it.","es":"¡Gracias! Tengo muchísimas ganas de ir."},{"who":"B","en":"Me too. I'll text you tonight to confirm.","es":"Yo también. Te mando mensaje hoy en la noche para confirmar."}]}},{"id":14,"title_es":"Experiencias","title_en":"Life experiences","level":"B1","goal_es":"Al terminar podrás hablar de lo que has vivido con el present perfect y usar already, yet, for y since sin confundirte.","lessons":[{"id":"14-1","title_es":"¿Alguna vez has...?","words":[{"en":"ever","es":"alguna vez","pos":"adv","ex_en":"Have you ever seen a ghost?","ex_es":"¿Alguna vez has visto un fantasma?"},{"en":"been to","es":"haber ido a, conocer (un lugar)","pos":"phrase","ex_en":"Have you ever been to Guadalajara?","ex_es":"¿Alguna vez has ido a Guadalajara?"},{"en":"go skydiving","es":"aventarse en paracaídas","pos":"phrase","ex_en":"I want to go skydiving before I turn forty.","ex_es":"Quiero aventarme en paracaídas antes de cumplir cuarenta."},{"en":"ride a horse","es":"montar a caballo","pos":"phrase","ex_en":"I learned to ride a horse at my grandpa's ranch.","ex_es":"Aprendí a montar a caballo en el rancho de mi abuelo."},{"en":"grasshopper","es":"chapulín","pos":"noun","ex_en":"Grasshoppers are a popular snack in Oaxaca.","ex_es":"Los chapulines son una botana muy popular en Oaxaca."},{"en":"celebrity","es":"celebridad, famoso","pos":"noun","ex_en":"Have you ever met a celebrity?","ex_es":"¿Alguna vez has conocido a un famoso?"},{"en":"once","es":"una vez","pos":"adv","ex_en":"I've been to New York once.","ex_es":"He ido a Nueva York una vez."},{"en":"twice","es":"dos veces","pos":"adv","ex_en":"She has visited Spain twice.","ex_es":"Ella ha visitado España dos veces."}],"sentences":[{"en":"Have you ever been to a baseball game?","es":"¿Alguna vez has ido a un partido de béisbol?"},{"en":"Yes, I have. I went to one last summer.","es":"Sí. Fui a uno el verano pasado."},{"en":"I've never eaten grasshoppers, but I want to try them.","es":"Nunca he comido chapulines, pero quiero probarlos."},{"en":"My sister has met two famous singers.","es":"Mi hermana ha conocido a dos cantantes famosos."},{"en":"How many times have you flown on a plane?","es":"¿Cuántas veces te has subido a un avión?"}],"tip_es":"Para hablar de experiencias de tu vida sin decir cuándo pasaron, usa have o has + participio: I have seen, she has gone. Responde corto con Yes, I have o No, I haven't, en lugar de solo Yes o No."},{"id":"14-2","title_es":"Already, yet y just","words":[{"en":"already","es":"ya","pos":"adv","ex_en":"I've already finished my homework.","ex_es":"Ya terminé mi tarea."},{"en":"yet","es":"todavía, ya (en preguntas)","pos":"adv","ex_en":"Have you had lunch yet?","ex_es":"¿Ya comiste?"},{"en":"just","es":"acabar de","pos":"adv","ex_en":"He's just arrived home.","ex_es":"Él acaba de llegar a la casa."},{"en":"still","es":"todavía, aún","pos":"adv","ex_en":"I still haven't called my mom.","ex_es":"Todavía no le he llamado a mi mamá."},{"en":"wrap up","es":"terminar, cerrar","pos":"verb","ex_en":"Let's wrap up the meeting in five minutes.","ex_es":"Cerremos la junta en cinco minutos."},{"en":"hand in","es":"entregar","pos":"verb","ex_en":"Don't forget to hand in your essay on Monday.","ex_es":"No olvides entregar tu ensayo el lunes."},{"en":"sort out","es":"resolver, arreglar","pos":"verb","ex_en":"I need to sort out my papers before the trip.","ex_es":"Necesito arreglar mis papeles antes del viaje."},{"en":"to-do list","es":"lista de pendientes","pos":"noun","ex_en":"My to-do list is very long today.","ex_es":"Mi lista de pendientes está muy larga hoy."}],"sentences":[{"en":"Have you finished the report yet?","es":"¿Ya terminaste el reporte?"},{"en":"No, I haven't finished it yet.","es":"No, todavía no lo he terminado."},{"en":"I've already sent the email to the client.","es":"Ya le mandé el correo al cliente."},{"en":"The bus has just left. We missed it!","es":"El camión acaba de irse. ¡Lo perdimos!"},{"en":"She still hasn't sorted out her visa.","es":"Ella todavía no ha resuelto lo de su visa."}],"tip_es":"Already va normalmente entre have y el participio: I've already eaten. Yet va al final en preguntas y negativas: Have you eaten yet? I haven't eaten yet. Just significa acabar de: I've just arrived es Acabo de llegar."},{"id":"14-3","title_es":"For y since","words":[{"en":"for","es":"durante, desde hace","pos":"prep","ex_en":"I've lived here for five years.","ex_es":"Llevo cinco años viviendo aquí."},{"en":"since","es":"desde","pos":"prep","ex_en":"She has worked here since 2019.","ex_es":"Ella trabaja aquí desde 2019."},{"en":"how long","es":"cuánto tiempo","pos":"phrase","ex_en":"How long have you known Pedro?","ex_es":"¿Desde hace cuánto conoces a Pedro?"},{"en":"decade","es":"década","pos":"noun","ex_en":"They've been friends for over a decade.","ex_es":"Han sido amigos por más de una década."},{"en":"childhood","es":"infancia","pos":"noun","ex_en":"We've known each other since childhood.","ex_es":"Nos conocemos desde la infancia."},{"en":"ages","es":"mucho tiempo, siglos","pos":"noun","ex_en":"I haven't seen you for ages!","ex_es":"¡Hace siglos que no te veo!"},{"en":"get to know","es":"conocer (a alguien poco a poco)","pos":"phrase","ex_en":"I'd like to get to know your family better.","ex_es":"Me gustaría conocer mejor a tu familia."},{"en":"lately","es":"últimamente","pos":"adv","ex_en":"Have you been busy lately?","ex_es":"¿Has estado ocupado últimamente?"}],"sentences":[{"en":"How long have you lived in Monterrey?","es":"¿Cuánto tiempo llevas viviendo en Monterrey?"},{"en":"I've lived here for almost ten years.","es":"Llevo casi diez años viviendo aquí."},{"en":"We've been married since 2015.","es":"Estamos casados desde 2015."},{"en":"I haven't seen my cousins since Christmas.","es":"No he visto a mis primos desde Navidad."},{"en":"She's been learning English for six months.","es":"Ella lleva seis meses aprendiendo inglés."}],"tip_es":"Usa for con periodos de tiempo (for two years, for a week) y since con el momento en que empezó (since Monday, since 2010). Error común: I live here since 2010. Lo correcto es I have lived here since 2010."},{"id":"14-4","title_es":"¿Present perfect o pasado simple?","words":[{"en":"recently","es":"recientemente","pos":"adv","ex_en":"Have you seen any good movies recently?","ex_es":"¿Has visto alguna película buena recientemente?"},{"en":"so far","es":"hasta ahora","pos":"phrase","ex_en":"So far, I've read three books this month.","ex_es":"Hasta ahora, he leído tres libros este mes."},{"en":"in my life","es":"en mi vida","pos":"phrase","ex_en":"I've never been so tired in my life.","ex_es":"Nunca he estado tan cansado en mi vida."},{"en":"once in a lifetime","es":"única en la vida","pos":"phrase","ex_en":"Seeing the whales was a once in a lifetime experience.","ex_es":"Ver las ballenas fue una experiencia única en la vida."},{"en":"unforgettable","es":"inolvidable","pos":"adj","ex_en":"Our trip to Chiapas was unforgettable.","ex_es":"Nuestro viaje a Chiapas fue inolvidable."},{"en":"go through","es":"pasar por, vivir","pos":"verb","ex_en":"Many students go through stress during exams.","ex_es":"Muchos estudiantes pasan por estrés durante los exámenes."},{"en":"experience","es":"experiencia","pos":"noun","ex_en":"Working in a hotel was a great experience.","ex_es":"Trabajar en un hotel fue una gran experiencia."},{"en":"the other day","es":"el otro día","pos":"phrase","ex_en":"I saw your brother the other day.","ex_es":"Vi a tu hermano el otro día."}],"sentences":[{"en":"I've been to Puerto Vallarta, but I went there years ago.","es":"He ido a Puerto Vallarta, pero fue hace años."},{"en":"Have you seen the new superhero movie? Yes, I saw it Sunday.","es":"¿Ya viste la nueva película de superhéroes? Sí, la vi el domingo."},{"en":"So far, this year has been really good.","es":"Hasta ahora, este año ha sido muy bueno."},{"en":"I've never had such an unforgettable experience in my life.","es":"Nunca he tenido una experiencia tan inolvidable en mi vida."},{"en":"When did you start working here?","es":"¿Cuándo empezaste a trabajar aquí?"}],"tip_es":"Si dices cuándo pasó (yesterday, in 2020, last week, the other day), usa past simple: I saw it yesterday. Si no importa cuándo o el periodo sigue abierto (this year, so far, ever), usa present perfect. Nunca digas I have seen it yesterday."},{"id":"14-5","title_es":"Logros y cambios","words":[{"en":"accomplish","es":"lograr, cumplir","pos":"verb","ex_en":"It feels great to accomplish a big goal.","ex_es":"Se siente increíble cumplir una meta grande."},{"en":"improve","es":"mejorar","pos":"verb","ex_en":"I want to improve my pronunciation.","ex_es":"Quiero mejorar mi pronunciación."},{"en":"graduate","es":"graduarse","pos":"verb","ex_en":"She has just graduated from college.","ex_es":"Ella acaba de graduarse de la universidad."},{"en":"get promoted","es":"recibir un ascenso","pos":"phrase","ex_en":"I hope to get promoted next year.","ex_es":"Espero recibir un ascenso el próximo año."},{"en":"quit","es":"dejar (un hábito o trabajo)","pos":"verb","ex_en":"My dad has quit smoking.","ex_es":"Mi papá ya dejó de fumar."},{"en":"take up","es":"empezar (un pasatiempo)","pos":"verb","ex_en":"I want to take up painting this year.","ex_es":"Quiero empezar a pintar este año."},{"en":"grow up","es":"crecer","pos":"verb","ex_en":"Where did you grow up?","ex_es":"¿Dónde creciste?"},{"en":"proud","es":"orgulloso","pos":"adj","ex_en":"I'm so proud of you!","ex_es":"¡Estoy muy orgulloso de ti!"}],"sentences":[{"en":"My English has improved a lot since I started this course.","es":"Mi inglés ha mejorado mucho desde que empecé este curso."},{"en":"Have you taken up any new hobbies lately?","es":"¿Has empezado algún pasatiempo nuevo últimamente?"},{"en":"He has just graduated, and his parents are very proud.","es":"Acaba de graduarse y sus papás están muy orgullosos."},{"en":"I've quit drinking soda, and I feel much better.","es":"Dejé de tomar refresco y me siento mucho mejor."},{"en":"How has your city changed since you were a kid?","es":"¿Cómo ha cambiado tu ciudad desde que eras niño?"}],"tip_es":"El present perfect es ideal para cambios con un resultado visible hoy: My English has improved. Aprende los participios irregulares más comunes: grow, grew, grown. take, took, taken. quit, quit, quit."},{"id":"14-6","title_es":"Viajes y aventuras","words":[{"en":"abroad","es":"en el extranjero","pos":"adv","ex_en":"Have you ever lived abroad?","ex_es":"¿Alguna vez has vivido en el extranjero?"},{"en":"sightseeing","es":"recorrido turístico","pos":"noun","ex_en":"We did a lot of sightseeing in Rome.","ex_es":"Hicimos muchos recorridos turísticos en Roma."},{"en":"bucket list","es":"lista de cosas por hacer en la vida","pos":"noun","ex_en":"Visiting Japan is on my bucket list.","ex_es":"Conocer Japón está en mi lista de cosas por hacer en la vida."},{"en":"breathtaking","es":"impresionante","pos":"adj","ex_en":"The view from the pyramid was breathtaking.","ex_es":"La vista desde la pirámide fue impresionante."},{"en":"get lost","es":"perderse","pos":"phrase","ex_en":"It's easy to get lost in Mexico City.","ex_es":"Es fácil perderse en la Ciudad de México."},{"en":"backpack","es":"viajar de mochilazo","pos":"verb","ex_en":"They want to backpack through South America.","ex_es":"Quieren viajar de mochilazo por Sudamérica."},{"en":"off the beaten path","es":"poco turístico","pos":"phrase","ex_en":"We like towns that are off the beaten path.","ex_es":"Nos gustan los pueblos poco turísticos."},{"en":"culture shock","es":"choque cultural","pos":"noun","ex_en":"I had a big culture shock when I moved to Canada.","ex_es":"Tuve un gran choque cultural cuando me mudé a Canadá."}],"sentences":[{"en":"Have you ever traveled abroad by yourself?","es":"¿Alguna vez has viajado solo al extranjero?"},{"en":"My parents have gone to Spain. They come back next week.","es":"Mis papás se fueron a España. Regresan la próxima semana."},{"en":"I've been to Spain twice, and I loved it.","es":"He ido a España dos veces y me encantó."},{"en":"We've gotten lost three times today!","es":"¡Nos hemos perdido tres veces hoy!"},{"en":"Seeing the northern lights is at the top of my bucket list.","es":"Ver la aurora boreal es lo primero en mi lista de sueños."}],"tip_es":"Has been to significa que la persona fue y ya regresó. Has gone to significa que se fue y sigue allá. She has been to Paris (ya volvió). She has gone to Paris (todavía está en París)."},{"id":"14-7","title_es":"¿Cuánto tiempo llevas haciéndolo?","words":[{"en":"all day","es":"todo el día","pos":"phrase","ex_en":"I've been studying all day, and my head hurts.","ex_es":"He estado estudiando todo el día y me duele la cabeza."},{"en":"worn out","es":"agotado, rendido","pos":"adj","ex_en":"You look worn out. Have you been working late?","ex_es":"Te ves agotado. ¿Has estado trabajando hasta tarde?"},{"en":"nonstop","es":"sin parar","pos":"adv","ex_en":"It has been raining nonstop since Tuesday.","ex_es":"Ha estado lloviendo sin parar desde el martes."},{"en":"wait in line","es":"hacer fila","pos":"verb","ex_en":"How long did you have to wait in line?","ex_es":"¿Cuánto tiempo tuviste que hacer fila?"},{"en":"work out","es":"hacer ejercicio","pos":"verb","ex_en":"I've started to work out three times a week.","ex_es":"Empecé a hacer ejercicio tres veces por semana."},{"en":"put on weight","es":"subir de peso","pos":"phrase","ex_en":"I've put on weight since I stopped running.","ex_es":"He subido de peso desde que dejé de correr."},{"en":"practice","es":"practicar","pos":"verb","ex_en":"I've been trying to practice every day.","ex_es":"He estado tratando de practicar todos los días."},{"en":"sore","es":"adolorido","pos":"adj","ex_en":"My legs are sore because I've been running a lot.","ex_es":"Tengo las piernas adoloridas porque he estado corriendo mucho."}],"sentences":[{"en":"I've been learning to play the guitar for a year.","es":"Llevo un año aprendiendo a tocar la guitarra."},{"en":"How long have you been waiting for the bus?","es":"¿Cuánto tiempo llevas esperando el camión?"},{"en":"She's tired because she's been working nonstop.","es":"Está cansada porque ha estado trabajando sin parar."},{"en":"We've been looking for an apartment since March.","es":"Llevamos buscando departamento desde marzo."},{"en":"My back is sore. I've been sitting all day.","es":"Me duele la espalda. He estado sentado todo el día."}],"tip_es":"El present perfect continuous se forma con have o has + been + verbo con -ing. Se usa para acciones que empezaron en el pasado y siguen, o que acaban de terminar y se nota el resultado. Llevo una hora esperando se dice I've been waiting for an hour."},{"id":"14-8","title_es":"Primeras veces y anécdotas","words":[{"en":"the first time","es":"la primera vez","pos":"phrase","ex_en":"This is the first time I've eaten mole.","ex_es":"Es la primera vez que como mole."},{"en":"by accident","es":"por accidente, sin querer","pos":"phrase","ex_en":"I've deleted all my photos by accident!","ex_es":"¡Borré todas mis fotos sin querer!"},{"en":"run into","es":"encontrarse con, toparse con","pos":"verb","ex_en":"I've just run into my old teacher at the mall.","ex_es":"Me acabo de encontrar a mi antigua maestra en la plaza."},{"en":"embarrassing","es":"vergonzoso","pos":"adj","ex_en":"The most embarrassing thing that has happened to me was at school.","ex_es":"Lo más vergonzoso que me ha pasado fue en la escuela."},{"en":"hilarious","es":"graciosísimo, chistosísimo","pos":"adj","ex_en":"Her story about the wedding was hilarious.","ex_es":"Su historia de la boda estuvo chistosísima."},{"en":"never forget","es":"nunca olvidar","pos":"phrase","ex_en":"I'll never forget the day I met her.","ex_es":"Nunca voy a olvidar el día que la conocí."},{"en":"story","es":"historia, anécdota","pos":"noun","ex_en":"Have you heard the story about my trip to Chiapas?","ex_es":"¿Ya oíste la anécdota de mi viaje a Chiapas?"},{"en":"scary","es":"aterrador, que da miedo","pos":"adj","ex_en":"The flight was really scary because of the storm.","ex_es":"El vuelo dio mucho miedo por la tormenta."}],"sentences":[{"en":"It's the first time I've driven on the highway.","es":"Es la primera vez que manejo en la carretera."},{"en":"Have you ever run into an ex at a party?","es":"¿Alguna vez te has topado con un ex en una fiesta?"},{"en":"I've sent a message to my boss by accident before.","es":"Ya me ha pasado mandarle un mensaje a mi jefe por accidente."},{"en":"That's the funniest story I've heard all week.","es":"Es la historia más chistosa que he oído en toda la semana."},{"en":"I'll never forget the first time I saw the ocean.","es":"Nunca voy a olvidar la primera vez que vi el mar."}],"tip_es":"Después de It's the first time se usa present perfect, aunque en español digamos presente: Es la primera vez que vengo se dice It's the first time I've come, no It's the first time I come."},{"id":"14-9","title_es":"Hábitos que han cambiado","words":[{"en":"used to","es":"solía","pos":"phrase","ex_en":"I used to live in Puebla, but I've moved.","ex_es":"Yo vivía en Puebla, pero ya me mudé."},{"en":"get used to","es":"acostumbrarse a","pos":"phrase","ex_en":"It took me months to get used to the cold.","ex_es":"Me tomó meses acostumbrarme al frío."},{"en":"anymore","es":"ya no","pos":"adv","ex_en":"I don't eat meat anymore.","ex_es":"Ya no como carne."},{"en":"no longer","es":"ya no","pos":"phrase","ex_en":"She no longer works here. She has retired.","ex_es":"Ella ya no trabaja aquí. Se jubiló."},{"en":"habit","es":"hábito, costumbre","pos":"noun","ex_en":"Reading before bed has become a good habit.","ex_es":"Leer antes de dormir se ha vuelto un buen hábito."},{"en":"cut down on","es":"reducir, bajarle a","pos":"verb","ex_en":"I've decided to cut down on sugar.","ex_es":"Decidí bajarle al azúcar."},{"en":"switch to","es":"cambiarse a","pos":"verb","ex_en":"Why did you switch to a new phone company?","ex_es":"¿Por qué te cambiaste a otra compañía de teléfono?"},{"en":"routine","es":"rutina","pos":"noun","ex_en":"My morning routine has changed a lot this year.","ex_es":"Mi rutina de la mañana ha cambiado mucho este año."}],"sentences":[{"en":"I used to smoke, but I haven't smoked since 2019.","es":"Antes fumaba, pero no he fumado desde 2019."},{"en":"Have you gotten used to living alone yet?","es":"¿Ya te acostumbraste a vivir solo?"},{"en":"He doesn't play soccer anymore because of his knee.","es":"Ya no juega futbol por su rodilla."},{"en":"I've cut down on coffee, and I sleep much better.","es":"Le he bajado al café y duermo mucho mejor."},{"en":"Exercise has become part of my daily routine.","es":"El ejercicio se ha vuelto parte de mi rutina diaria."}],"tip_es":"Used to + verbo base habla de hábitos del pasado que ya no ocurren: I used to smoke, antes fumaba. Get used to significa acostumbrarse y después lleva sustantivo o verbo con -ing: I got used to waking up early. Anymore va al final de una oración negativa."},{"id":"14-10","title_es":"Ponerse al día en la vida real","words":[{"en":"catch up","es":"ponerse al día","pos":"verb","ex_en":"Let's get coffee and catch up soon.","ex_es":"Vamos por un café para ponernos al día pronto."},{"en":"long time no see","es":"cuánto tiempo sin verte","pos":"phrase","ex_en":"Long time no see! How have you been?","ex_es":"¡Cuánto tiempo sin verte! ¿Cómo has estado?"},{"en":"what have you been up to","es":"qué has hecho, en qué andas","pos":"phrase","ex_en":"So, what have you been up to these days?","ex_es":"Bueno, ¿en qué andas estos días?"},{"en":"keep busy","es":"mantenerse ocupado","pos":"phrase","ex_en":"I've been trying to keep busy with work.","ex_es":"He tratado de mantenerme ocupado con el trabajo."},{"en":"change jobs","es":"cambiar de trabajo","pos":"phrase","ex_en":"I decided to change jobs last year.","ex_es":"Decidí cambiar de trabajo el año pasado."},{"en":"get engaged","es":"comprometerse","pos":"phrase","ex_en":"They're going to get engaged in December.","ex_es":"Se van a comprometer en diciembre."},{"en":"fill me in","es":"cuéntame, ponme al tanto","pos":"phrase","ex_en":"Come on, fill me in on everything!","ex_es":"¡Ándale, cuéntame todo!"},{"en":"since then","es":"desde entonces","pos":"phrase","ex_en":"We met in college, and we've been friends since then.","ex_es":"Nos conocimos en la universidad y desde entonces somos amigos."}],"sentences":[{"en":"Long time no see! You haven't changed at all.","es":"¡Cuánto tiempo sin verte! No has cambiado nada."},{"en":"What have you been up to since we graduated?","es":"¿Qué has hecho desde que nos graduamos?"},{"en":"I've changed jobs twice, and now I work from home.","es":"He cambiado de trabajo dos veces y ahora trabajo desde casa."},{"en":"Have you heard from Carlos? I haven't talked to him in ages.","es":"¿Has sabido algo de Carlos? Hace siglos que no hablo con él."},{"en":"We should catch up more often. It's been too long.","es":"Deberíamos ponernos al día más seguido. Ha pasado mucho tiempo."}],"tip_es":"Cuando ves a alguien después de mucho tiempo, pregunta How have you been? en lugar de How are you? porque hablas de todo el periodo. Hace mucho que no lo veo se dice I haven't seen him in a long time, con present perfect."}],"dialogue":{"title_es":"Reencuentro en el café","setting_es":"Te encuentras en un café a un amigo que no veías desde hace mucho.","lines":[{"who":"A","en":"Hey! I haven't seen you for ages!","es":"¡Hola! ¡Hace siglos que no te veo!"},{"who":"B","en":"I know! How have you been?","es":"¡Ya sé! ¿Cómo has estado?"},{"who":"A","en":"Great, thanks. I've just come back from Peru.","es":"Muy bien, gracias. Acabo de regresar de Perú."},{"who":"B","en":"Wow! Have you been to Machu Picchu?","es":"¡Órale! ¿Fuiste a Machu Picchu?"},{"who":"A","en":"Yes, I have. It was breathtaking. Have you ever been there?","es":"Sí. Fue impresionante. ¿Tú has ido alguna vez?"},{"who":"B","en":"No, I haven't, but it's on my bucket list.","es":"No, pero está en mi lista de sueños."},{"who":"A","en":"You should go. So, what's new with you?","es":"Deberías ir. ¿Y qué hay de nuevo contigo?"},{"who":"B","en":"I've changed jobs. I've worked at a bank since March.","es":"Cambié de trabajo. Trabajo en un banco desde marzo."},{"who":"A","en":"That's great! Do you like it?","es":"¡Qué bien! ¿Te gusta?"},{"who":"B","en":"Yes, so far it's been a great experience.","es":"Sí, hasta ahora ha sido una gran experiencia."}]}},{"id":15,"title_es":"Opiniones y sentimientos","title_en":"Opinions and feelings","level":"B1","goal_es":"Al terminar podrás expresar emociones, dar tu opinión, estar de acuerdo o en desacuerdo y comparar cosas.","lessons":[{"id":"15-1","title_es":"¿Cómo te sientes?","words":[{"en":"excited","es":"emocionado","pos":"adj","ex_en":"I'm so excited about the concert!","ex_es":"¡Estoy muy emocionado por el concierto!"},{"en":"disappointed","es":"decepcionado","pos":"adj","ex_en":"She was disappointed with her grade.","ex_es":"Ella estaba decepcionada con su calificación."},{"en":"worried","es":"preocupado","pos":"adj","ex_en":"My mom is worried because I came home late.","ex_es":"Mi mamá está preocupada porque llegué tarde a la casa."},{"en":"embarrassed","es":"apenado, avergonzado","pos":"adj","ex_en":"I was so embarrassed when I fell in the street.","ex_es":"Me dio muchísima pena cuando me caí en la calle."},{"en":"frustrated","es":"frustrado","pos":"adj","ex_en":"He gets frustrated when the internet is slow.","ex_es":"Se frustra cuando el internet está lento."},{"en":"relieved","es":"aliviado","pos":"adj","ex_en":"I felt relieved when the exam was over.","ex_es":"Me sentí aliviado cuando terminó el examen."},{"en":"annoyed","es":"molesto, irritado","pos":"adj","ex_en":"I'm annoyed because my neighbor's music is too loud.","ex_es":"Estoy molesto porque la música de mi vecino está muy fuerte."},{"en":"overwhelmed","es":"abrumado","pos":"adj","ex_en":"I feel overwhelmed with so much work.","ex_es":"Me siento abrumado con tanto trabajo."}],"sentences":[{"en":"The movie was boring, so I was bored.","es":"La película estaba aburrida, así que me aburrí."},{"en":"I'm really excited about my new job.","es":"Estoy muy emocionado por mi nuevo trabajo."},{"en":"Why do you look so worried?","es":"¿Por qué te ves tan preocupado?"},{"en":"It was an exhausting day, and now I'm exhausted.","es":"Fue un día agotador y ahora estoy agotado."},{"en":"She felt embarrassed when she forgot his name.","es":"Le dio pena cuando olvidó el nombre de él."}],"tip_es":"Los adjetivos con -ed describen cómo te sientes (I'm bored, estoy aburrido) y los de -ing describen lo que causa el sentimiento (The class is boring). Cuidado: embarrassed significa apenado, no embarazada, que en inglés es pregnant."},{"id":"15-2","title_es":"Dar tu opinión","words":[{"en":"in my opinion","es":"en mi opinión","pos":"phrase","ex_en":"In my opinion, the book is better than the movie.","ex_es":"En mi opinión, el libro es mejor que la película."},{"en":"personally","es":"personalmente","pos":"adv","ex_en":"Personally, I don't like spicy food.","ex_es":"Personalmente, no me gusta la comida picante."},{"en":"as far as I know","es":"que yo sepa","pos":"phrase","ex_en":"As far as I know, the store opens at nine.","ex_es":"Que yo sepa, la tienda abre a las nueve."},{"en":"it seems to me","es":"me parece que","pos":"phrase","ex_en":"It seems to me that he's very tired.","ex_es":"Me parece que él está muy cansado."},{"en":"point of view","es":"punto de vista","pos":"noun","ex_en":"From my point of view, it's a good idea.","ex_es":"Desde mi punto de vista, es una buena idea."},{"en":"believe","es":"creer","pos":"verb","ex_en":"I believe everyone deserves a second chance.","ex_es":"Creo que todos merecen una segunda oportunidad."},{"en":"honestly","es":"honestamente, la verdad","pos":"adv","ex_en":"Honestly, I didn't like the ending.","ex_es":"La verdad, no me gustó el final."},{"en":"make sense","es":"tener sentido","pos":"phrase","ex_en":"That doesn't make sense.","ex_es":"Eso no tiene sentido."}],"sentences":[{"en":"In my opinion, public transportation in this city needs to improve.","es":"En mi opinión, el transporte público de esta ciudad necesita mejorar."},{"en":"Personally, I prefer living in a small town.","es":"Personalmente, prefiero vivir en un pueblo."},{"en":"What do you think about working from home?","es":"¿Qué opinas de trabajar desde casa?"},{"en":"It seems to me that people are always in a hurry.","es":"Me parece que la gente siempre anda con prisa."},{"en":"Honestly, his plan doesn't make sense to me.","es":"Honestamente, su plan no tiene sentido para mí."}],"tip_es":"Para pedir una opinión se dice What do you think about...?, no How do you think...? Para dar la tuya usa I think..., In my opinion... o Personally... y evita traducir literal según yo como according to me."},{"id":"15-3","title_es":"De acuerdo y en desacuerdo","words":[{"en":"agree","es":"estar de acuerdo","pos":"verb","ex_en":"I agree with you about the new schedule.","ex_es":"Estoy de acuerdo contigo sobre el nuevo horario."},{"en":"disagree","es":"no estar de acuerdo","pos":"verb","ex_en":"My brother and I often disagree about politics.","ex_es":"Mi hermano y yo seguido no estamos de acuerdo sobre política."},{"en":"exactly","es":"exacto","pos":"adv","ex_en":"Exactly! That's what I was trying to say.","ex_es":"¡Exacto! Eso es lo que trataba de decir."},{"en":"I see your point","es":"entiendo tu punto","pos":"phrase","ex_en":"I see your point, but I still think it's expensive.","ex_es":"Entiendo tu punto, pero sigo pensando que es caro."},{"en":"on the other hand","es":"por otro lado","pos":"phrase","ex_en":"The city is noisy. On the other hand, there's a lot to do.","ex_es":"La ciudad es ruidosa. Por otro lado, hay mucho que hacer."},{"en":"fair enough","es":"es justo, está bien","pos":"phrase","ex_en":"You want to leave early? Fair enough.","ex_es":"¿Te quieres ir temprano? Está bien, es justo."},{"en":"not necessarily","es":"no necesariamente","pos":"phrase","ex_en":"Expensive things are not necessarily better.","ex_es":"Las cosas caras no necesariamente son mejores."},{"en":"argue","es":"discutir, pelear","pos":"verb","ex_en":"My parents argue about money sometimes.","ex_es":"Mis papás a veces discuten por dinero."}],"sentences":[{"en":"I totally agree with you.","es":"Estoy totalmente de acuerdo contigo."},{"en":"I'm sorry, but I don't agree with that idea.","es":"Perdón, pero no estoy de acuerdo con esa idea."},{"en":"You're right, but on the other hand, it's very far.","es":"Tienes razón, pero por otro lado, queda muy lejos."},{"en":"I see your point, but I think we need more time.","es":"Entiendo tu punto, pero creo que necesitamos más tiempo."},{"en":"We don't have to agree on everything.","es":"No tenemos que estar de acuerdo en todo."}],"tip_es":"Agree es un verbo, así que se dice I agree, nunca I am agree. En negativo di I don't agree o I disagree. Ojo: argue significa discutir o pelear con palabras, no argumentar de forma tranquila."},{"id":"15-4","title_es":"Comparar cosas","words":[{"en":"than","es":"que (en comparaciones)","pos":"conj","ex_en":"My new apartment is bigger than my old one.","ex_es":"Mi departamento nuevo es más grande que el anterior."},{"en":"less","es":"menos","pos":"adv","ex_en":"This phone is less expensive than that one.","ex_es":"Este celular es menos caro que ese."},{"en":"as good as","es":"tan bueno como","pos":"phrase","ex_en":"The sequel isn't as good as the first movie.","ex_es":"La secuela no es tan buena como la primera película."},{"en":"worse","es":"peor","pos":"adj","ex_en":"The traffic is worse on Fridays.","ex_es":"El tráfico está peor los viernes."},{"en":"crowded","es":"lleno de gente","pos":"adj","ex_en":"The subway is very crowded at rush hour.","ex_es":"El metro está muy lleno en hora pico."},{"en":"convenient","es":"práctico, conveniente","pos":"adj","ex_en":"Living near work is very convenient.","ex_es":"Vivir cerca del trabajo es muy práctico."},{"en":"affordable","es":"accesible (de precio)","pos":"adj","ex_en":"It's hard to find affordable housing downtown.","ex_es":"Es difícil encontrar vivienda accesible en el centro."},{"en":"similar","es":"parecido","pos":"adj","ex_en":"Your bag is similar to mine.","ex_es":"Tu bolsa es parecida a la mía."}],"sentences":[{"en":"Puebla is smaller than Mexico City, but it's very pretty.","es":"Puebla es más chica que la Ciudad de México, pero es muy bonita."},{"en":"Learning English is easier than I thought.","es":"Aprender inglés es más fácil de lo que pensaba."},{"en":"This restaurant is more affordable than the one downtown.","es":"Este restaurante es más accesible que el del centro."},{"en":"My cold is getting worse, not better.","es":"Mi gripa está cada vez peor, no mejor."},{"en":"The bus is cheaper, but the subway is more convenient.","es":"El camión es más barato, pero el metro es más práctico."}],"tip_es":"Los adjetivos cortos agregan -er (cheaper, bigger) y los largos usan more (more convenient). Irregulares: good, better y bad, worse. Error común: more better o more cheap. Nunca combines more con -er."},{"id":"15-5","title_es":"Lo mejor y lo peor","words":[{"en":"the best","es":"el mejor","pos":"phrase","ex_en":"This is the best taco place in town.","ex_es":"Esta es la mejor taquería de la ciudad."},{"en":"the worst","es":"el peor","pos":"phrase","ex_en":"Monday is the worst day of the week.","ex_es":"El lunes es el peor día de la semana."},{"en":"the most","es":"el más","pos":"phrase","ex_en":"What's the most beautiful place you've visited?","ex_es":"¿Cuál es el lugar más bonito que has visitado?"},{"en":"the least","es":"el menos","pos":"phrase","ex_en":"This is the least expensive option on the menu.","ex_es":"Esta es la opción menos cara del menú."},{"en":"by far","es":"por mucho","pos":"phrase","ex_en":"This is by far the hottest summer I remember.","ex_es":"Este es por mucho el verano más caluroso que recuerdo."},{"en":"one of the","es":"uno de los","pos":"phrase","ex_en":"Tokyo is one of the biggest cities in the world.","ex_es":"Tokio es una de las ciudades más grandes del mundo."},{"en":"talented","es":"talentoso","pos":"adj","ex_en":"My cousin is a very talented guitar player.","ex_es":"Mi primo es un guitarrista muy talentoso."},{"en":"impressive","es":"impresionante","pos":"adj","ex_en":"The view from the top was really impressive.","ex_es":"La vista desde arriba fue realmente impresionante."}],"sentences":[{"en":"What's the best movie you've ever seen?","es":"¿Cuál es la mejor película que has visto?"},{"en":"January is the coldest month of the year here.","es":"Enero es el mes más frío del año aquí."},{"en":"That was the worst meal I've ever had.","es":"Fue la peor comida que he probado en mi vida."},{"en":"She's the most talented singer in the band.","es":"Ella es la cantante más talentosa del grupo."},{"en":"Frida Kahlo is one of the most famous Mexican artists.","es":"Frida Kahlo es una de las artistas mexicanas más famosas."}],"tip_es":"El superlativo se forma con the + adjetivo con -est (the tallest) o the most + adjetivo largo (the most interesting). Para lugares o grupos usa in, no of: the best in the world. Se combina mucho con present perfect: the best I've ever seen."},{"id":"15-6","title_es":"Reaccionar y mostrar empatía","words":[{"en":"that's a shame","es":"qué lástima","pos":"phrase","ex_en":"You missed the concert? That's a shame.","ex_es":"¿Te perdiste el concierto? Qué lástima."},{"en":"I'm sorry to hear that","es":"lamento escuchar eso","pos":"phrase","ex_en":"Your dog is sick? I'm sorry to hear that.","ex_es":"¿Tu perro está enfermo? Lamento escuchar eso."},{"en":"no way","es":"¡no manches!, ¡no puede ser!","pos":"interj","ex_en":"No way! You won the lottery?","ex_es":"¡No manches! ¿Te ganaste la lotería?"},{"en":"cheer up","es":"animarse","pos":"verb","ex_en":"Cheer up! Tomorrow will be a better day.","ex_es":"¡Ánimo! Mañana va a ser un mejor día."},{"en":"hang in there","es":"aguanta, échale ganas","pos":"phrase","ex_en":"Hang in there. The semester is almost over.","ex_es":"Échale ganas. Ya casi se acaba el semestre."},{"en":"good for you","es":"qué bien por ti","pos":"phrase","ex_en":"You got the job? Good for you!","ex_es":"¿Te quedaste con el trabajo? ¡Qué bien por ti!"},{"en":"I know how you feel","es":"sé cómo te sientes","pos":"phrase","ex_en":"I know how you feel. I was nervous too.","ex_es":"Sé cómo te sientes. Yo también estaba nervioso."},{"en":"upset","es":"molesto, triste","pos":"adj","ex_en":"She was upset because nobody called her.","ex_es":"Ella estaba triste porque nadie le llamó."}],"sentences":[{"en":"I'm sorry to hear about your grandma.","es":"Lamento mucho lo de tu abuelita."},{"en":"That's great news! Congratulations!","es":"¡Qué buena noticia! ¡Felicidades!"},{"en":"Don't be so hard on yourself.","es":"No seas tan duro contigo mismo."},{"en":"What's wrong? You seem a little upset.","es":"¿Qué pasa? Te ves un poco triste."},{"en":"If you need to talk, I'm here for you.","es":"Si necesitas hablar, aquí estoy para ti."}],"tip_es":"En inglés se reacciona mucho con frases cortas como That's a shame, Good for you o No way! Ojo: I'm sorry no solo sirve para pedir perdón, también se usa para dar el pésame o mostrar compasión."},{"id":"15-7","title_es":"Emociones intensas","words":[{"en":"thrilled","es":"emocionadísimo, encantado","pos":"adj","ex_en":"I was thrilled when I got the job.","ex_es":"Me puse feliz de la vida cuando me dieron el trabajo."},{"en":"furious","es":"furioso","pos":"adj","ex_en":"My dad was furious about the broken window.","ex_es":"Mi papá estaba furioso por la ventana rota."},{"en":"jealous","es":"celoso, envidioso","pos":"adj","ex_en":"Are you jealous of your sister's success?","ex_es":"¿Le tienes envidia al éxito de tu hermana?"},{"en":"lonely","es":"solo, que se siente solo","pos":"adj","ex_en":"She felt lonely after she moved to a new city.","ex_es":"Se sintió sola después de mudarse a una ciudad nueva."},{"en":"nervous","es":"nervioso","pos":"adj","ex_en":"I always get nervous before an exam.","ex_es":"Siempre me pongo nervioso antes de un examen."},{"en":"grateful","es":"agradecido","pos":"adj","ex_en":"I'm really grateful for your help.","ex_es":"Te estoy muy agradecido por tu ayuda."},{"en":"homesick","es":"que extraña su casa","pos":"adj","ex_en":"Many students feel homesick during their first year.","ex_es":"Muchos estudiantes extrañan su casa durante el primer año."},{"en":"scared","es":"asustado, con miedo","pos":"adj","ex_en":"My son is scared of the dark.","ex_es":"A mi hijo le da miedo la oscuridad."}],"sentences":[{"en":"I'm so thrilled about the concert on Friday!","es":"¡Estoy emocionadísimo por el concierto del viernes!"},{"en":"He gets really jealous when his girlfriend talks to other guys.","es":"Se pone muy celoso cuando su novia habla con otros chavos."},{"en":"I felt lonely during my first months in Chicago.","es":"Me sentí solo durante mis primeros meses en Chicago."},{"en":"Why are you so nervous? You'll do great.","es":"¿Por qué estás tan nervioso? Te va a ir muy bien."},{"en":"I'm grateful to have such good friends.","es":"Estoy agradecido de tener tan buenos amigos."}],"tip_es":"Muchas emociones llevan una preposición fija: scared of, jealous of, nervous about, grateful for, furious about. Ojo: lonely significa sentirse solo y triste, mientras que alone solo significa estar sin compañía."},{"id":"15-8","title_es":"Gustos y preferencias","words":[{"en":"can't stand","es":"no soportar","pos":"phrase","ex_en":"I can't stand people who talk during movies.","ex_es":"No soporto a la gente que habla durante las películas."},{"en":"into","es":"clavado en, fan de","pos":"prep","ex_en":"I'm really into Korean dramas right now.","ex_es":"Ahorita estoy muy clavado con los doramas coreanos."},{"en":"would rather","es":"preferiría","pos":"phrase","ex_en":"I would rather walk than take a taxi.","ex_es":"Preferiría caminar que tomar un taxi."},{"en":"fond of","es":"encariñado con, aficionado a","pos":"adj","ex_en":"My grandma is very fond of her garden.","ex_es":"Mi abuela le tiene mucho cariño a su jardín."},{"en":"mind","es":"molestar, importar","pos":"verb","ex_en":"I don't mind waiting a few minutes.","ex_es":"No me molesta esperar unos minutos."},{"en":"crazy about","es":"loco por","pos":"phrase","ex_en":"My kids are crazy about dinosaurs.","ex_es":"Mis hijos están locos por los dinosaurios."},{"en":"not a big fan of","es":"no muy fan de","pos":"phrase","ex_en":"I'm not a big fan of spicy food, honestly.","ex_es":"La verdad, no soy muy fan de la comida picante."},{"en":"it depends","es":"depende","pos":"phrase","ex_en":"Do I like camping? Well, it depends.","ex_es":"¿Si me gusta acampar? Pues, depende."}],"sentences":[{"en":"I'd rather watch a movie than go to a club.","es":"Prefiero ver una película que ir a un antro."},{"en":"She can't stand waking up early on weekends.","es":"No soporta levantarse temprano los fines de semana."},{"en":"I don't mind cooking, but I hate washing the dishes.","es":"No me molesta cocinar, pero odio lavar los trastes."},{"en":"My brother is really into video games.","es":"Mi hermano está muy metido en los videojuegos."},{"en":"Which do you prefer, the beach or the mountains?","es":"¿Qué prefieres, la playa o la montaña?"}],"tip_es":"Después de can't stand, don't mind, love y hate puedes usar el verbo con -ing: I don't mind waiting. En cambio, would rather va con verbo base y sin to: I'd rather stay home, no I'd rather to stay."},{"id":"15-9","title_es":"Comparaciones más precisas","words":[{"en":"much","es":"mucho","pos":"adv","ex_en":"This phone is much faster than my old one.","ex_es":"Este celular es mucho más rápido que el que tenía."},{"en":"a bit","es":"un poco","pos":"phrase","ex_en":"Could you speak a bit slower, please?","ex_es":"¿Podrías hablar un poco más despacio, por favor?"},{"en":"far","es":"mucho, por mucho","pos":"adv","ex_en":"Your new apartment is far nicer than the old one.","ex_es":"Tu nuevo departamento es mucho más bonito que el anterior."},{"en":"twice as","es":"el doble de","pos":"phrase","ex_en":"The new bridge is twice as long as the old one.","ex_es":"El puente nuevo es el doble de largo que el viejo."},{"en":"the same as","es":"igual que","pos":"phrase","ex_en":"Your shoes are the same as mine!","ex_es":"¡Tus zapatos son iguales a los míos!"},{"en":"different from","es":"diferente de","pos":"phrase","ex_en":"Life in the city is very different from life in a village.","ex_es":"La vida en la ciudad es muy diferente de la vida en un pueblo."},{"en":"the more","es":"entre más","pos":"phrase","ex_en":"The more you practice, the better you get.","ex_es":"Entre más practicas, mejor te sale."},{"en":"nowhere near","es":"ni de lejos","pos":"phrase","ex_en":"This copy is nowhere near as good as the original.","ex_es":"Esta copia no es ni de lejos tan buena como la original."}],"sentences":[{"en":"The new mall is much bigger than the old one.","es":"La plaza nueva es mucho más grande que la vieja."},{"en":"My city isn't as dangerous as people think.","es":"Mi ciudad no es tan peligrosa como la gente cree."},{"en":"Prices are getting higher and higher every year.","es":"Los precios están cada vez más altos cada año."},{"en":"The more I read in English, the more I understand.","es":"Entre más leo en inglés, más entiendo."},{"en":"Tickets cost twice as much as last year.","es":"Los boletos cuestan el doble que el año pasado."}],"tip_es":"Para reforzar un comparativo usa much, a lot, far o a bit: much bigger, a bit cheaper. Nunca digas very bigger. Para decir cada vez más, repite el comparativo: higher and higher. Entre más..., más... se dice The more..., the more..."},{"id":"15-10","title_es":"Opinar en la vida real","words":[{"en":"to be honest","es":"la verdad, para ser honesto","pos":"phrase","ex_en":"To be honest, I didn't like the ending.","ex_es":"La verdad, no me gustó el final."},{"en":"sounds good","es":"suena bien, va","pos":"phrase","ex_en":"Pizza tonight? Sounds good to me.","ex_es":"¿Pizza hoy en la noche? Va, me late."},{"en":"it's up to you","es":"tú decides","pos":"phrase","ex_en":"Tacos or sushi? It's up to you.","ex_es":"¿Tacos o sushi? Tú decides."},{"en":"either way","es":"de cualquier forma","pos":"phrase","ex_en":"We can take the bus or a taxi. Either way is fine.","ex_es":"Podemos tomar el camión o un taxi. Cualquiera de las dos está bien."},{"en":"I'd go with","es":"yo me iría por","pos":"phrase","ex_en":"If I were you, I'd go with the blue one.","ex_es":"Yo que tú, me iría por el azul."},{"en":"overrated","es":"sobrevalorado","pos":"adj","ex_en":"In my opinion, that restaurant is overrated.","ex_es":"En mi opinión, ese restaurante está sobrevalorado."},{"en":"worth it","es":"valer la pena","pos":"phrase","ex_en":"The tickets were expensive, but the show was worth it.","ex_es":"Los boletos estaban caros, pero el show valió la pena."},{"en":"torn between","es":"indeciso entre","pos":"phrase","ex_en":"I'm torn between the two apartments.","ex_es":"Estoy indeciso entre los dos departamentos."}],"sentences":[{"en":"To be honest, I think the second option is better.","es":"La verdad, creo que la segunda opción es mejor."},{"en":"That place is the most popular, but I think it's overrated.","es":"Ese lugar es el más popular, pero creo que está sobrevalorado."},{"en":"I'm not sure. The beach is nice, but it's more expensive.","es":"No estoy seguro. La playa está bonita, pero es más cara."},{"en":"It was the longest line I've ever seen, but it was worth it.","es":"Fue la fila más larga que he visto, pero valió la pena."},{"en":"I agree with you. Let's go with the cheaper one.","es":"Estoy de acuerdo contigo. Vámonos por el más barato."}],"tip_es":"Para opinar sin sonar muy directo, empieza con To be honest o I think, y para recomendar usa I'd go with... Vale la pena se dice It's worth it. Si va un verbo después, usa -ing: It's worth visiting."}],"dialogue":{"title_es":"¿Ciudad grande o pequeña?","setting_es":"Platicas con un amigo de Querétaro sobre vivir en la capital.","lines":[{"who":"A","en":"So, how do you like living in Mexico City?","es":"Y qué tal, ¿te gusta vivir en la Ciudad de México?"},{"who":"B","en":"Honestly, I love it. There's always something to do.","es":"La verdad, me encanta. Siempre hay algo que hacer."},{"who":"A","en":"Really? I think it's too crowded and noisy.","es":"¿En serio? Yo creo que hay demasiada gente y mucho ruido."},{"who":"B","en":"I see your point, but the food is the best in the country.","es":"Entiendo tu punto, pero la comida es la mejor del país."},{"who":"A","en":"Fair enough. But the traffic is much worse than in Querétaro.","es":"Es justo. Pero el tráfico está mucho peor que en Querétaro."},{"who":"B","en":"That's true. On the other hand, the subway is very convenient.","es":"Es cierto. Por otro lado, el metro es muy práctico."},{"who":"A","en":"Maybe. Personally, I prefer a quieter life.","es":"Puede ser. Personalmente, prefiero una vida más tranquila."},{"who":"B","en":"I understand. Smaller cities are more relaxing.","es":"Te entiendo. Las ciudades más chicas son más relajantes."},{"who":"A","en":"Exactly! You should visit me in Querétaro sometime.","es":"¡Exacto! Deberías visitarme en Querétaro algún día."},{"who":"B","en":"I'd love to! I'm sure I'll be impressed.","es":"¡Me encantaría! Seguro me va a impresionar."}]}},{"id":16,"title_es":"Inglés profesional","title_en":"English for work","level":"B2","goal_es":"Al terminar podrás presentarte en una entrevista, escribir correos formales, participar en juntas y llamadas, y hacer peticiones con cortesía.","lessons":[{"id":"16-1","title_es":"La entrevista de trabajo","words":[{"en":"résumé","es":"currículum","pos":"noun","ex_en":"Please send your résumé before Friday.","ex_es":"Por favor, envíe su currículum antes del viernes."},{"en":"apply for","es":"solicitar, postularse a","pos":"verb","ex_en":"I'd like to apply for the sales job.","ex_es":"Me gustaría postularme al trabajo de ventas."},{"en":"position","es":"puesto","pos":"noun","ex_en":"The position requires three years of experience.","ex_es":"El puesto requiere tres años de experiencia."},{"en":"background","es":"formación, trayectoria","pos":"noun","ex_en":"My background is in accounting and finance.","ex_es":"Mi formación es en contabilidad y finanzas."},{"en":"strength","es":"fortaleza","pos":"noun","ex_en":"My biggest strength is solving problems quickly.","ex_es":"Mi mayor fortaleza es resolver problemas rápido."},{"en":"weakness","es":"debilidad","pos":"noun","ex_en":"One of my weaknesses is that I'm a perfectionist.","ex_es":"Una de mis debilidades es que soy perfeccionista."},{"en":"team player","es":"persona que trabaja bien en equipo","pos":"noun","ex_en":"I'm a team player, and I enjoy working with others.","ex_es":"Trabajo bien en equipo y me gusta colaborar con otros."},{"en":"hire","es":"contratar","pos":"verb","ex_en":"The company plans to hire ten new engineers.","ex_es":"La empresa planea contratar a diez ingenieros nuevos."}],"sentences":[{"en":"Tell me a little about yourself.","es":"Cuénteme un poco sobre usted."},{"en":"Why are you interested in this position?","es":"¿Por qué le interesa este puesto?"},{"en":"I have five years of experience in customer service.","es":"Tengo cinco años de experiencia en atención al cliente."},{"en":"Where do you see yourself in five years?","es":"¿Dónde se ve en cinco años?"},{"en":"What are your salary expectations for this role?","es":"¿Cuáles son sus expectativas salariales para este puesto?"}],"tip_es":"En una entrevista habla de tu experiencia con present perfect (I have worked in sales for five years) y de trabajos terminados con past simple (I worked at a bank in 2019). Error común: experience in sell. Lo correcto es experience in selling, con -ing después de in."},{"id":"16-2","title_es":"Correos formales","words":[{"en":"dear","es":"estimado","pos":"adj","ex_en":"Dear Ms. Johnson, thank you for your message.","ex_es":"Estimada Sra. Johnson, gracias por su mensaje."},{"en":"regarding","es":"respecto a, en relación con","pos":"prep","ex_en":"I'm writing regarding the invoice from last month.","ex_es":"Le escribo en relación con la factura del mes pasado."},{"en":"attach","es":"adjuntar","pos":"verb","ex_en":"I'll attach the contract to this email.","ex_es":"Voy a adjuntar el contrato a este correo."},{"en":"follow up","es":"dar seguimiento","pos":"verb","ex_en":"I'm writing to follow up on our meeting.","ex_es":"Le escribo para dar seguimiento a nuestra junta."},{"en":"best regards","es":"saludos cordiales","pos":"phrase","ex_en":"Best regards, Laura.","ex_es":"Saludos cordiales, Laura."},{"en":"as soon as possible","es":"lo antes posible","pos":"phrase","ex_en":"Please reply as soon as possible.","ex_es":"Por favor, responda lo antes posible."},{"en":"reach out","es":"contactar, escribir","pos":"verb","ex_en":"Feel free to reach out if you have any questions.","ex_es":"No dude en contactarme si tiene alguna pregunta."},{"en":"inquiry","es":"consulta","pos":"noun","ex_en":"Thank you for your inquiry about our services.","ex_es":"Gracias por su consulta sobre nuestros servicios."}],"sentences":[{"en":"I'm writing to ask about the job opening.","es":"Le escribo para preguntar sobre la vacante."},{"en":"Please find attached the documents you requested.","es":"Adjunto encontrará los documentos que solicitó."},{"en":"Thank you for getting back to me so quickly.","es":"Gracias por responderme tan rápido."},{"en":"Could you please confirm the date of the meeting?","es":"¿Podría confirmar la fecha de la junta, por favor?"},{"en":"I look forward to hearing from you.","es":"Quedo atento a su respuesta."}],"tip_es":"En correos formales empieza con Dear + título y apellido (Dear Mr. Smith) y cierra con Best regards o Sincerely. Quedo atento a su respuesta se dice I look forward to hearing from you, con -ing después de to."},{"id":"16-3","title_es":"Juntas de trabajo","words":[{"en":"agenda","es":"orden del día","pos":"noun","ex_en":"Let's look at the agenda for today's meeting.","ex_es":"Veamos el orden del día de la junta de hoy."},{"en":"minutes","es":"minuta","pos":"noun","ex_en":"Who is taking the minutes today?","ex_es":"¿Quién va a hacer la minuta hoy?"},{"en":"item","es":"punto (de una lista)","pos":"noun","ex_en":"The first item on the list is the budget.","ex_es":"El primer punto de la lista es el presupuesto."},{"en":"bring up","es":"mencionar, sacar un tema","pos":"verb","ex_en":"I'd like to bring up a problem with the delivery dates.","ex_es":"Me gustaría mencionar un problema con las fechas de entrega."},{"en":"move on","es":"pasar a otro tema","pos":"verb","ex_en":"If there are no more questions, let's move on.","ex_es":"Si no hay más preguntas, pasemos al siguiente tema."},{"en":"go over","es":"revisar, repasar","pos":"verb","ex_en":"Let's go over the numbers one more time.","ex_es":"Revisemos los números una vez más."},{"en":"point out","es":"señalar","pos":"verb","ex_en":"I'd like to point out that sales went up.","ex_es":"Me gustaría señalar que las ventas subieron."},{"en":"brainstorm","es":"hacer lluvia de ideas","pos":"verb","ex_en":"Let's brainstorm some ideas for the new campaign.","ex_es":"Hagamos una lluvia de ideas para la nueva campaña."}],"sentences":[{"en":"Let's get started. Thank you all for coming.","es":"Empecemos. Gracias a todos por venir."},{"en":"Sorry to interrupt, but could I add something?","es":"Perdón por interrumpir, pero ¿puedo agregar algo?"},{"en":"Could you clarify what you mean by that?","es":"¿Podrías aclarar a qué te refieres con eso?"},{"en":"Let's go over the main points before we finish.","es":"Repasemos los puntos principales antes de terminar."},{"en":"I'll send everyone the minutes after the meeting.","es":"Les mando la minuta a todos después de la junta."}],"tip_es":"Agenda es un falso amigo: en una junta, the agenda es el orden del día, y tu agenda personal se dice planner o calendar. Para pedir la palabra con cortesía usa Sorry to interrupt, but... o Could I add something?"},{"id":"16-4","title_es":"Llamadas y videollamadas","words":[{"en":"hold on","es":"espere un momento","pos":"verb","ex_en":"Hold on, please. I'll check.","ex_es":"Espere un momento, por favor. Lo reviso."},{"en":"put through","es":"comunicar, transferir (una llamada)","pos":"verb","ex_en":"Please hold while I put through your call.","ex_es":"Espere en la línea mientras le transfiero su llamada."},{"en":"take a message","es":"tomar un recado","pos":"phrase","ex_en":"She's not here. Can I take a message?","ex_es":"No se encuentra. ¿Le puedo tomar un recado?"},{"en":"call back","es":"devolver la llamada","pos":"verb","ex_en":"I'll call back in ten minutes.","ex_es":"Le regreso la llamada en diez minutos."},{"en":"speak up","es":"hablar más fuerte","pos":"verb","ex_en":"Could you speak up a little, please?","ex_es":"¿Podría hablar un poco más fuerte, por favor?"},{"en":"break up","es":"cortarse (la señal)","pos":"verb","ex_en":"The signal tends to break up in the elevator.","ex_es":"La señal se suele cortar en el elevador."},{"en":"mute","es":"silenciar","pos":"verb","ex_en":"Please mute your microphone when you're not speaking.","ex_es":"Por favor, silencien su micrófono cuando no estén hablando."},{"en":"extension","es":"extensión","pos":"noun","ex_en":"My extension is two one four.","ex_es":"Mi extensión es dos uno cuatro."}],"sentences":[{"en":"Good morning, this is Laura from Grupo Delta.","es":"Buenos días, habla Laura de Grupo Delta."},{"en":"May I speak with Mr. Ramírez, please?","es":"¿Puedo hablar con el señor Ramírez, por favor?"},{"en":"I'm afraid he's in a meeting right now.","es":"Me temo que está en una junta en este momento."},{"en":"Sorry, you're on mute. We can't hear you.","es":"Perdón, tienes el micrófono apagado. No te escuchamos."},{"en":"Could you repeat that? The connection is really bad.","es":"¿Podría repetir eso? Se escucha muy mal."}],"tip_es":"Al contestar el teléfono en inglés se dice This is Laura o Laura speaking, no I am Laura. Para pedir hablar con alguien usa May I speak with...? o Could you put me through to...?"},{"id":"16-5","title_es":"Peticiones con cortesía","words":[{"en":"would you mind","es":"¿le molestaría...?","pos":"phrase","ex_en":"Would you mind closing the door?","ex_es":"¿Le molestaría cerrar la puerta?"},{"en":"I was wondering if","es":"me preguntaba si","pos":"phrase","ex_en":"I was wondering if you could help me with this report.","ex_es":"Me preguntaba si me podría ayudar con este reporte."},{"en":"appreciate","es":"agradecer","pos":"verb","ex_en":"I'd appreciate it if you could reply today.","ex_es":"Le agradecería si pudiera responder hoy."},{"en":"approve","es":"aprobar","pos":"verb","ex_en":"We need the director to approve the budget.","ex_es":"Necesitamos que el director apruebe el presupuesto."},{"en":"feedback","es":"comentarios, retroalimentación","pos":"noun","ex_en":"Thanks for your feedback on my presentation.","ex_es":"Gracias por tus comentarios sobre mi presentación."},{"en":"on behalf of","es":"en nombre de","pos":"phrase","ex_en":"On behalf of the company, welcome to the team.","ex_es":"En nombre de la empresa, bienvenido al equipo."},{"en":"let me know","es":"avísame","pos":"phrase","ex_en":"Let me know if you need anything else.","ex_es":"Avísame si necesitas algo más."},{"en":"request","es":"solicitud","pos":"noun","ex_en":"I sent a request for two days off.","ex_es":"Mandé una solicitud para dos días libres."}],"sentences":[{"en":"Would you mind sending me the file again?","es":"¿Le molestaría enviarme el archivo otra vez?"},{"en":"I was wondering if we could move the call to Thursday.","es":"Me preguntaba si podríamos cambiar la llamada al jueves."},{"en":"I'd really appreciate your feedback on this proposal.","es":"Le agradecería mucho sus comentarios sobre esta propuesta."},{"en":"Could you possibly give me a little more time?","es":"¿Habría manera de que me diera un poco más de tiempo?"},{"en":"Please let me know if you have any questions.","es":"Por favor, avíseme si tiene alguna duda."}],"tip_es":"Después de Would you mind usa el verbo con -ing: Would you mind waiting? Si respondes No, not at all, significa que no te molesta, o sea que sí aceptas. I was wondering if... suena mucho más amable que Can you...?"},{"id":"16-6","title_es":"Condicionales en el trabajo","words":[{"en":"unless","es":"a menos que","pos":"conj","ex_en":"We won't finish on time unless we work on Saturday.","ex_es":"No vamos a terminar a tiempo a menos que trabajemos el sábado."},{"en":"as long as","es":"siempre y cuando","pos":"phrase","ex_en":"You can work from home as long as you finish your tasks.","ex_es":"Puedes trabajar desde casa siempre y cuando termines tus pendientes."},{"en":"in case","es":"por si acaso","pos":"phrase","ex_en":"Bring your laptop in case we need it.","ex_es":"Trae tu laptop por si la necesitamos."},{"en":"budget","es":"presupuesto","pos":"noun","ex_en":"We don't have enough budget for a new office.","ex_es":"No tenemos suficiente presupuesto para una oficina nueva."},{"en":"afford","es":"costear, darse el lujo de","pos":"verb","ex_en":"We can't afford to lose this client.","ex_es":"No nos podemos dar el lujo de perder a este cliente."},{"en":"raise","es":"aumento de sueldo","pos":"noun","ex_en":"If I get a raise, I'll buy a car.","ex_es":"Si me dan un aumento, me voy a comprar un coche."},{"en":"opportunity","es":"oportunidad","pos":"noun","ex_en":"This job is a great opportunity for me.","ex_es":"Este trabajo es una gran oportunidad para mí."},{"en":"turn down","es":"rechazar","pos":"verb","ex_en":"It's hard to turn down a good offer.","ex_es":"Es difícil rechazar una buena oferta."}],"sentences":[{"en":"If we finish the project early, the client will be happy.","es":"Si terminamos el proyecto antes, el cliente va a estar contento."},{"en":"If I were the manager, I would hire more people.","es":"Si yo fuera el gerente, contrataría a más gente."},{"en":"What would you do if you lost your job?","es":"¿Qué harías si perdieras tu trabajo?"},{"en":"If you need help, just let me know.","es":"Si necesitas ayuda, nada más avísame."},{"en":"I'll accept the offer as long as I can work remotely.","es":"Voy a aceptar la oferta siempre y cuando pueda trabajar a distancia."}],"tip_es":"Primer condicional, para situaciones reales: If + presente, will + verbo. Segundo condicional, para situaciones imaginarias: If + pasado, would + verbo. En inglés formal se dice If I were. Nunca pongas will después de if: If it rains, no If it will rain."},{"id":"16-7","title_es":"Negociar y llegar a acuerdos","words":[{"en":"negotiate","es":"negociar","pos":"verb","ex_en":"We need to negotiate a better price with the supplier.","ex_es":"Necesitamos negociar un mejor precio con el proveedor."},{"en":"deal","es":"trato, oferta","pos":"noun","ex_en":"If you sign today, we can offer you a great deal.","ex_es":"Si firma hoy, le podemos ofrecer un gran trato."},{"en":"compromise","es":"ceder, llegar a un punto medio","pos":"verb","ex_en":"Both teams had to compromise to finish on time.","ex_es":"Los dos equipos tuvieron que ceder para terminar a tiempo."},{"en":"terms","es":"condiciones, términos","pos":"noun","ex_en":"Please read the terms of the contract carefully.","ex_es":"Por favor, lea con cuidado las condiciones del contrato."},{"en":"meet halfway","es":"llegar a un punto medio","pos":"phrase","ex_en":"Let's meet halfway and split the cost.","ex_es":"Lleguemos a un punto medio y dividamos el costo."},{"en":"discount","es":"descuento","pos":"noun","ex_en":"Would you consider a ten percent discount?","ex_es":"¿Consideraría un descuento del diez por ciento?"},{"en":"agreement","es":"acuerdo","pos":"noun","ex_en":"We finally reached an agreement after three meetings.","ex_es":"Por fin llegamos a un acuerdo después de tres juntas."},{"en":"bottom line","es":"lo esencial, en resumidas cuentas","pos":"phrase","ex_en":"The bottom line is that we need more clients.","ex_es":"En resumidas cuentas, necesitamos más clientes."}],"sentences":[{"en":"If you order more units, we'll give you a better price.","es":"Si pide más unidades, le damos un mejor precio."},{"en":"Would you be willing to extend the payment period?","es":"¿Estaría dispuesto a ampliar el plazo de pago?"},{"en":"I'm afraid we can't go any lower than that.","es":"Me temo que no podemos bajar más de eso."},{"en":"If we agreed to those terms, we would lose money.","es":"Si aceptáramos esas condiciones, perderíamos dinero."},{"en":"I think we have a deal. Let's put it in writing.","es":"Creo que tenemos un trato. Pongámoslo por escrito."}],"tip_es":"Para negociar con cortesía usa Would you be willing to...? El segundo condicional suaviza una propuesta: If we ordered more, would you lower the price? Ojo: compromise significa ceder o llegar a un acuerdo, no comprometerse, que se dice commit."},{"id":"16-8","title_es":"Presentaciones en el trabajo","words":[{"en":"slide","es":"diapositiva","pos":"noun","ex_en":"Let's look at the next slide.","ex_es":"Veamos la siguiente diapositiva."},{"en":"overview","es":"panorama general","pos":"noun","ex_en":"First, I'll give you a quick overview of the project.","ex_es":"Primero, les daré un panorama general del proyecto."},{"en":"chart","es":"gráfica","pos":"noun","ex_en":"As you can see in this chart, sales went up.","ex_es":"Como pueden ver en esta gráfica, las ventas subieron."},{"en":"highlight","es":"destacar, resaltar","pos":"verb","ex_en":"I'd like to highlight three key results.","ex_es":"Me gustaría destacar tres resultados clave."},{"en":"sum up","es":"resumir","pos":"verb","ex_en":"To sum up, it was a very successful year.","ex_es":"En resumen, fue un año muy exitoso."},{"en":"figures","es":"cifras","pos":"noun","ex_en":"The figures for March are better than expected.","ex_es":"Las cifras de marzo son mejores de lo esperado."},{"en":"audience","es":"público, audiencia","pos":"noun","ex_en":"Try to make eye contact with the audience.","ex_es":"Trata de hacer contacto visual con el público."},{"en":"take questions","es":"responder preguntas","pos":"phrase","ex_en":"I'll be happy to take questions at the end.","ex_es":"Con gusto responderé preguntas al final."}],"sentences":[{"en":"Today I'm going to talk about our sales results.","es":"Hoy les voy a hablar de nuestros resultados de ventas."},{"en":"As you can see, profits have grown by twenty percent.","es":"Como pueden ver, las ganancias han crecido un veinte por ciento."},{"en":"Let's move on to the next point.","es":"Pasemos al siguiente punto."},{"en":"To sum up, we need to invest more in marketing.","es":"En resumen, necesitamos invertir más en marketing."},{"en":"Thank you for your attention. Are there any questions?","es":"Gracias por su atención. ¿Hay alguna pregunta?"}],"tip_es":"Organiza tu presentación con conectores claros: First, Then, Finally y To sum up. Para señalar datos usa As you can see. Ojo: en inglés no se dice I will present you the results, sino I will present the results to you."},{"id":"16-9","title_es":"Problemas y soluciones","words":[{"en":"delay","es":"retraso","pos":"noun","ex_en":"There has been a delay in the shipment.","ex_es":"Ha habido un retraso en el envío."},{"en":"issue","es":"problema, asunto","pos":"noun","ex_en":"We're having an issue with the payment system.","ex_es":"Estamos teniendo un problema con el sistema de pagos."},{"en":"apologize","es":"disculparse","pos":"verb","ex_en":"We apologize for any confusion.","ex_es":"Nos disculpamos por cualquier confusión."},{"en":"inconvenience","es":"molestia, inconveniente","pos":"noun","ex_en":"Sorry for the inconvenience. We'll fix it today.","ex_es":"Perdón por la molestia. Lo arreglamos hoy."},{"en":"solve","es":"resolver","pos":"verb","ex_en":"Let's work together to solve this problem.","ex_es":"Trabajemos juntos para resolver este problema."},{"en":"handle","es":"encargarse de, manejar","pos":"verb","ex_en":"Don't worry, I'll handle the client.","ex_es":"No te preocupes, yo me encargo del cliente."},{"en":"behind schedule","es":"retrasado, atrasado","pos":"phrase","ex_en":"The project is two weeks behind schedule.","ex_es":"El proyecto va dos semanas atrasado."},{"en":"workaround","es":"solución alternativa","pos":"noun","ex_en":"We found a workaround until the system is fixed.","ex_es":"Encontramos una solución alternativa mientras arreglan el sistema."}],"sentences":[{"en":"Unfortunately, the order won't arrive until next Monday.","es":"Desafortunadamente, el pedido no llegará sino hasta el próximo lunes."},{"en":"We apologize for the delay and any inconvenience it may cause.","es":"Nos disculpamos por el retraso y cualquier molestia que pueda causar."},{"en":"If the problem continues, please contact our support team.","es":"Si el problema continúa, por favor contacte a nuestro equipo de soporte."},{"en":"If we had tested it earlier, we would have found the error.","es":"Si lo hubiéramos probado antes, habríamos encontrado el error."},{"en":"I'll look into it and get back to you today.","es":"Lo voy a revisar y le respondo hoy mismo."}],"tip_es":"Para dar malas noticias con tacto empieza con Unfortunately o I'm afraid. Para hablar de lo que pudo ser diferente usa el tercer condicional: If + had + participio, would have + participio. Recuerda que se dice apologize for, no apologize of."},{"id":"16-10","title_es":"La oficina en la vida real","words":[{"en":"touch base","es":"ponerse en contacto, platicar brevemente","pos":"phrase","ex_en":"Let's touch base on Monday about the budget.","ex_es":"Platiquemos el lunes sobre el presupuesto."},{"en":"heads up","es":"aviso","pos":"noun","ex_en":"Thanks for the heads up about the meeting.","ex_es":"Gracias por el aviso de la junta."},{"en":"on the same page","es":"en la misma sintonía","pos":"phrase","ex_en":"I want to make sure we're on the same page.","ex_es":"Quiero asegurarme de que estemos en la misma sintonía."},{"en":"out of office","es":"fuera de la oficina","pos":"phrase","ex_en":"I'll be out of office until Wednesday.","ex_es":"Voy a estar fuera de la oficina hasta el miércoles."},{"en":"loop in","es":"incluir, copiar","pos":"verb","ex_en":"Can you loop in Sara on this email?","ex_es":"¿Puedes copiar a Sara en este correo?"},{"en":"keep track of","es":"llevar el control de","pos":"phrase","ex_en":"I use an app to keep track of my tasks.","ex_es":"Uso una app para llevar el control de mis pendientes."},{"en":"time off","es":"días libres, días de descanso","pos":"noun","ex_en":"I'm going to ask for some time off in December.","ex_es":"Voy a pedir unos días libres en diciembre."},{"en":"workload","es":"carga de trabajo","pos":"noun","ex_en":"My workload is really heavy this week.","ex_es":"Mi carga de trabajo está muy pesada esta semana."}],"sentences":[{"en":"Just a quick heads up, the client meeting has been moved.","es":"Solo un aviso rápido, la junta con el cliente se cambió."},{"en":"If you have a minute, could we touch base about the report?","es":"Si tienes un minuto, ¿podemos platicar sobre el reporte?"},{"en":"I'd appreciate it if you could loop me in on future emails.","es":"Te agradecería que me copiaras en los próximos correos."},{"en":"Unless there are any questions, let's wrap up for today.","es":"A menos que haya preguntas, cerremos por hoy."},{"en":"If I were you, I would ask for some time off.","es":"Yo que tú, pediría unos días libres."}],"tip_es":"En la oficina se usan muchas expresiones informales pero profesionales, como heads up, touch base o loop in. Combínalas con condicionales y frases corteses como I'd appreciate it if... para sonar natural sin perder formalidad."}],"dialogue":{"title_es":"La entrevista","setting_es":"Tienes una entrevista para un puesto de ventas en una empresa internacional.","lines":[{"who":"A","en":"Good morning. Thank you for coming in today.","es":"Buenos días. Gracias por venir hoy."},{"who":"B","en":"Good morning. Thank you for the opportunity.","es":"Buenos días. Gracias por la oportunidad."},{"who":"A","en":"So, tell me a little about your background.","es":"Bueno, cuénteme un poco sobre su trayectoria."},{"who":"B","en":"I studied business, and I've worked in sales for six years.","es":"Estudié administración y he trabajado en ventas durante seis años."},{"who":"A","en":"What would you say is your biggest strength?","es":"¿Cuál diría que es su mayor fortaleza?"},{"who":"B","en":"I'm a team player, and I'm very good with clients.","es":"Trabajo bien en equipo y soy muy bueno con los clientes."},{"who":"A","en":"Great. What would you do if a client was unhappy?","es":"Muy bien. ¿Qué haría si un cliente estuviera inconforme?"},{"who":"B","en":"I would listen carefully and try to find a solution quickly.","es":"Lo escucharía con atención y trataría de encontrar una solución rápido."},{"who":"A","en":"Excellent. We'll be in touch by the end of the week.","es":"Excelente. Nos comunicaremos con usted antes de que termine la semana."},{"who":"B","en":"Thank you. I look forward to hearing from you.","es":"Gracias. Quedo en espera de su respuesta."}]}},{"id":17,"title_es":"Tecnología, internet y redes sociales","title_en":"Technology and the internet","level":"B2","goal_es":"Al terminar podrás hablar de apps y dispositivos, resolver problemas técnicos, trabajar a distancia, cuidar tu privacidad y opinar sobre la tecnología.","lessons":[{"id":"17-1","title_es":"Apps y dispositivos","words":[{"en":"device","es":"dispositivo","pos":"noun","ex_en":"You can use the app on any device.","ex_es":"Puedes usar la app en cualquier dispositivo."},{"en":"download","es":"descargar","pos":"verb","ex_en":"Download the app and create a free account.","ex_es":"Descarga la app y crea una cuenta gratis."},{"en":"install","es":"instalar","pos":"verb","ex_en":"It only takes a minute to install the new version.","ex_es":"Solo toma un minuto instalar la nueva versión."},{"en":"update","es":"actualización","pos":"noun","ex_en":"My phone needs an update before I can use it.","ex_es":"Mi teléfono necesita una actualización antes de poder usarlo."},{"en":"storage","es":"almacenamiento","pos":"noun","ex_en":"I'm running out of storage on my phone.","ex_es":"Me estoy quedando sin almacenamiento en mi teléfono."},{"en":"charger","es":"cargador","pos":"noun","ex_en":"Can I borrow your charger? My battery is almost dead.","ex_es":"¿Me prestas tu cargador? Ya casi no tengo batería."},{"en":"intuitive","es":"intuitivo","pos":"adj","ex_en":"The new app is really intuitive and easy to use.","ex_es":"La nueva app es muy intuitiva y fácil de usar."},{"en":"settings","es":"configuración, ajustes","pos":"noun","ex_en":"You can change the language in the settings.","ex_es":"Puedes cambiar el idioma en la configuración."}],"sentences":[{"en":"Which apps do you use the most?","es":"¿Qué apps usas más?"},{"en":"I deleted some photos because my phone was full.","es":"Borré algunas fotos porque mi teléfono estaba lleno."},{"en":"Turn on notifications in the settings menu.","es":"Activa las notificaciones en el menú de configuración."},{"en":"This laptop is light, but the battery doesn't last long.","es":"Esta laptop es ligera, pero la batería no dura mucho."},{"en":"Is the app available for both iPhone and Android?","es":"¿La app está disponible para iPhone y Android?"}],"tip_es":"Download es bajar algo de internet e install es ponerlo a funcionar en tu dispositivo. App es contable, an app, two apps. Error común, decir my cellular. En EE. UU. se dice phone o cell phone, y la pila del celular es the battery."},{"id":"17-2","title_es":"Problemas técnicos","words":[{"en":"freeze","es":"trabarse, congelarse","pos":"verb","ex_en":"My laptop tends to freeze when I open too many tabs.","ex_es":"Mi laptop suele trabarse cuando abro demasiadas pestañas."},{"en":"crash","es":"fallar, cerrarse de golpe","pos":"verb","ex_en":"The app may crash if you don't update it.","ex_es":"La app puede cerrarse sola si no la actualizas."},{"en":"restart","es":"reiniciar","pos":"verb","ex_en":"Try to restart your computer and see if it works.","ex_es":"Intenta reiniciar tu computadora y ve si funciona."},{"en":"glitch","es":"falla, error menor","pos":"noun","ex_en":"There was a glitch, so the video stopped.","ex_es":"Hubo una falla y el video se detuvo."},{"en":"bug","es":"error de programa","pos":"noun","ex_en":"The developers fixed the bug in the latest version.","ex_es":"Los desarrolladores corrigieron el error en la última versión."},{"en":"connection","es":"conexión","pos":"noun","ex_en":"My connection keeps dropping during video calls.","ex_es":"Mi conexión se cae a cada rato en las videollamadas."},{"en":"tech support","es":"soporte técnico","pos":"noun","ex_en":"I called tech support, but nobody answered.","ex_es":"Llamé a soporte técnico, pero nadie contestó."},{"en":"troubleshoot","es":"buscar y resolver fallas","pos":"verb","ex_en":"Let me troubleshoot the problem before we call anyone.","ex_es":"Déjame revisar la falla antes de llamar a alguien."}],"sentences":[{"en":"Have you tried turning it off and on again?","es":"¿Ya intentaste apagarlo y volverlo a prender?"},{"en":"The screen went black and nothing happened.","es":"La pantalla se puso negra y no pasó nada."},{"en":"I think the problem is the router, not the laptop.","es":"Creo que el problema es el módem, no la laptop."},{"en":"The website is down for maintenance until tonight.","es":"El sitio está caído por mantenimiento hasta la noche."},{"en":"Every time I open the app, it crashes.","es":"Cada vez que abro la app, se cierra sola."}],"tip_es":"Para decir que un sistema no funciona se usa mucho is down, como en The server is down. Error común, decir The computer is broken cuando solo está trabada. Broken significa dañada. Si solo no responde, di It froze o It's not responding."},{"id":"17-3","title_es":"Trabajo remoto","words":[{"en":"work from home","es":"trabajar desde casa","pos":"phrase","ex_en":"I work from home three days a week.","ex_es":"Trabajo desde casa tres días a la semana."},{"en":"remote","es":"remoto, a distancia","pos":"adj","ex_en":"Our whole team is remote now.","ex_es":"Todo nuestro equipo trabaja a distancia ahora."},{"en":"video call","es":"videollamada","pos":"noun","ex_en":"Let's jump on a video call this afternoon.","ex_es":"Hagamos una videollamada en la tarde."},{"en":"mute","es":"silenciar","pos":"verb","ex_en":"Please mute your microphone when you're not speaking.","ex_es":"Por favor, silencia tu micrófono cuando no estés hablando."},{"en":"share your screen","es":"compartir tu pantalla","pos":"phrase","ex_en":"Can you share your screen so we can see it?","ex_es":"¿Puedes compartir tu pantalla para que lo veamos?"},{"en":"time zone","es":"zona horaria","pos":"noun","ex_en":"My boss lives in a different time zone.","ex_es":"Mi jefa vive en otra zona horaria."},{"en":"coworking space","es":"espacio de coworking","pos":"noun","ex_en":"I rent a desk at a coworking space downtown.","ex_es":"Rento un escritorio en un espacio de coworking del centro."},{"en":"commute","es":"trayecto al trabajo","pos":"noun","ex_en":"I don't miss my long commute at all.","ex_es":"No extraño para nada mi largo trayecto al trabajo."}],"sentences":[{"en":"You're on mute, we can't hear you.","es":"Estás en silencio, no te escuchamos."},{"en":"Sorry, my internet is unstable today.","es":"Perdón, mi internet está inestable hoy."},{"en":"Can everyone see my screen?","es":"¿Todos pueden ver mi pantalla?"},{"en":"Let's schedule the call for ten a.m. my time.","es":"Agendemos la llamada a las diez de la mañana, hora de aquí."},{"en":"Working remotely saves me a lot of time and money.","es":"Trabajar a distancia me ahorra mucho tiempo y dinero."}],"tip_es":"You're on mute es probablemente la frase más repetida en videollamadas. Para decir que trabajas desde casa usa work from home o work remotely. Error común, decir I work in my house. Lo natural es I work from home, con from."},{"id":"17-4","title_es":"Redes sociales","words":[{"en":"post","es":"publicar","pos":"verb","ex_en":"She likes to post photos of her trips.","ex_es":"A ella le gusta publicar fotos de sus viajes."},{"en":"follower","es":"seguidor","pos":"noun","ex_en":"He has more than ten thousand followers.","ex_es":"Tiene más de diez mil seguidores."},{"en":"go viral","es":"hacerse viral","pos":"phrase","ex_en":"Nobody expected that video to go viral.","ex_es":"Nadie esperaba que ese video se hiciera viral."},{"en":"comment","es":"comentario","pos":"noun","ex_en":"Some of the comments were really rude.","ex_es":"Algunos comentarios fueron muy groseros."},{"en":"feed","es":"inicio, muro","pos":"noun","ex_en":"My feed is full of ads lately.","ex_es":"Mi inicio está lleno de anuncios últimamente."},{"en":"influencer","es":"influencer","pos":"noun","ex_en":"That influencer promotes products she never uses.","ex_es":"Esa influencer promueve productos que nunca usa."},{"en":"tag","es":"etiquetar","pos":"verb","ex_en":"Please don't tag me in that photo.","ex_es":"Por favor, no me etiquetes en esa foto."},{"en":"scroll","es":"deslizar la pantalla","pos":"verb","ex_en":"I can scroll through videos for hours.","ex_es":"Puedo pasar horas deslizando videos."}],"sentences":[{"en":"Did you see what she posted last night?","es":"¿Viste lo que publicó anoche?"},{"en":"I unfollowed him because he only posts ads.","es":"Dejé de seguirlo porque solo publica anuncios."},{"en":"How many likes did your photo get?","es":"¿Cuántos likes tuvo tu foto?"},{"en":"I'm trying to spend less time on social media.","es":"Estoy tratando de pasar menos tiempo en redes sociales."},{"en":"Send me the link and I'll share it.","es":"Mándame el link y lo comparto."}],"tip_es":"En la conversación diaria se dice social media, no social networks. Con las plataformas se usa on, on Instagram, on social media. Error común, decir I saw it in Facebook. Lo correcto es I saw it on Facebook."},{"id":"17-5","title_es":"Privacidad y seguridad","words":[{"en":"password","es":"contraseña","pos":"noun","ex_en":"Use a strong password with numbers and symbols.","ex_es":"Usa una contraseña segura con números y símbolos."},{"en":"hack","es":"hackear","pos":"verb","ex_en":"Someone tried to hack my email account.","ex_es":"Alguien intentó hackear mi cuenta de correo."},{"en":"scam","es":"estafa, fraude","pos":"noun","ex_en":"That message about a prize is obviously a scam.","ex_es":"Ese mensaje sobre un premio obviamente es una estafa."},{"en":"personal data","es":"datos personales","pos":"noun","ex_en":"Many apps collect a lot of personal data.","ex_es":"Muchas apps recopilan muchos datos personales."},{"en":"verification code","es":"código de verificación","pos":"noun","ex_en":"Enter the verification code we sent to your phone.","ex_es":"Ingresa el código de verificación que enviamos a tu teléfono."},{"en":"privacy","es":"privacidad","pos":"noun","ex_en":"I'm worried about my privacy online.","ex_es":"Me preocupa mi privacidad en internet."},{"en":"suspicious","es":"sospechoso","pos":"adj","ex_en":"Never click on a suspicious link.","ex_es":"Nunca des clic en un enlace sospechoso."},{"en":"breach","es":"filtración, violación de seguridad","pos":"noun","ex_en":"The company admitted there was a data breach.","ex_es":"La empresa admitió que hubo una filtración de datos."}],"sentences":[{"en":"Never share your password with anyone.","es":"Nunca compartas tu contraseña con nadie."},{"en":"I think my account was hacked last night.","es":"Creo que hackearon mi cuenta anoche."},{"en":"Read the privacy policy before you accept.","es":"Lee el aviso de privacidad antes de aceptar."},{"en":"Banks will never ask for your PIN by email.","es":"Los bancos nunca te pedirán tu NIP por correo."},{"en":"Change your passwords every few months to stay safe.","es":"Cambia tus contraseñas cada pocos meses para estar seguro."}],"tip_es":"Data se usa como incontable en el habla diaria, the data is, nunca the datas. Para decir que te robaron la cuenta se usa la voz pasiva, My account was hacked, o la forma informal I got hacked. Error común, decir My account was hacking."},{"id":"17-6","title_es":"Phrasal verbs de tecnología","words":[{"en":"log in","es":"iniciar sesión","pos":"verb","ex_en":"I can't log in because I forgot my password.","ex_es":"No puedo iniciar sesión porque olvidé mi contraseña."},{"en":"log out","es":"cerrar sesión","pos":"verb","ex_en":"Always log out when you use a public computer.","ex_es":"Siempre cierra sesión cuando uses una computadora pública."},{"en":"sign up","es":"registrarse","pos":"verb","ex_en":"It's free to sign up for the newsletter.","ex_es":"Registrarse al boletín es gratis."},{"en":"back up","es":"respaldar","pos":"verb","ex_en":"Remember to back up your files every week.","ex_es":"Acuérdate de respaldar tus archivos cada semana."},{"en":"set up","es":"configurar, instalar","pos":"verb","ex_en":"Can you help me set up my new printer?","ex_es":"¿Me ayudas a configurar mi impresora nueva?"},{"en":"plug in","es":"conectar, enchufar","pos":"verb","ex_en":"Plug in your laptop before the battery dies.","ex_es":"Conecta tu laptop antes de que se acabe la batería."},{"en":"shut down","es":"apagar por completo","pos":"verb","ex_en":"Save your work before you shut down the computer.","ex_es":"Guarda tu trabajo antes de apagar la computadora."},{"en":"free up","es":"liberar","pos":"verb","ex_en":"Delete old videos to free up space.","ex_es":"Borra videos viejos para liberar espacio."}],"sentences":[{"en":"I signed up with my email address.","es":"Me registré con mi correo electrónico."},{"en":"Did you back up your photos before the update?","es":"¿Respaldaste tus fotos antes de la actualización?"},{"en":"It took me an hour to set everything up.","es":"Me tomó una hora configurar todo."},{"en":"Please log out of my account when you finish.","es":"Por favor, cierra sesión en mi cuenta cuando termines."},{"en":"The computer shut down by itself in the middle of my work.","es":"La computadora se apagó sola a la mitad de mi trabajo."}],"tip_es":"Muchos phrasal verbs tienen un sustantivo que se escribe junto. Log in es el verbo y login el sustantivo, back up es el verbo y backup el sustantivo. Error común, escribir I need to login. Como verbo va separado, I need to log in."},{"id":"17-7","title_es":"Inteligencia artificial","words":[{"en":"artificial intelligence","es":"inteligencia artificial","pos":"noun","ex_en":"Artificial intelligence is changing the way we work.","ex_es":"La inteligencia artificial está cambiando nuestra forma de trabajar."},{"en":"chatbot","es":"chatbot, asistente virtual","pos":"noun","ex_en":"I asked the chatbot to summarize the article.","ex_es":"Le pedí al chatbot que resumiera el artículo."},{"en":"automate","es":"automatizar","pos":"verb","ex_en":"We want to automate the boring parts of the job.","ex_es":"Queremos automatizar las partes aburridas del trabajo."},{"en":"replace","es":"reemplazar","pos":"verb","ex_en":"Do you think robots will replace teachers?","ex_es":"¿Crees que los robots van a reemplazar a los maestros?"},{"en":"tool","es":"herramienta","pos":"noun","ex_en":"This tool translates long documents in seconds.","ex_es":"Esta herramienta traduce documentos largos en segundos."},{"en":"accurate","es":"preciso, correcto","pos":"adj","ex_en":"The answer sounded good, but it wasn't accurate.","ex_es":"La respuesta sonaba bien, pero no era correcta."},{"en":"prompt","es":"instrucción, indicación","pos":"noun","ex_en":"If you write a clear prompt, you get better results.","ex_es":"Si escribes una instrucción clara, obtienes mejores resultados."},{"en":"breakthrough","es":"gran avance","pos":"noun","ex_en":"Scientists call it a major breakthrough in medicine.","ex_es":"Los científicos lo consideran un gran avance en la medicina."}],"sentences":[{"en":"AI can help you write, but you still need to check it.","es":"La IA te puede ayudar a escribir, pero tienes que revisarlo."},{"en":"Many jobs will change in the next ten years.","es":"Muchos trabajos van a cambiar en los próximos diez años."},{"en":"I use AI to plan my meals for the week.","es":"Uso IA para planear mis comidas de la semana."},{"en":"Some people are afraid machines will replace them.","es":"Algunas personas temen que las máquinas las reemplacen."},{"en":"Always check the facts before you share them.","es":"Siempre verifica los datos antes de compartirlos."}],"tip_es":"En inglés se dice AI y se pronuncia ei ai. Ojo con el falso amigo actual. The current version es la versión actual, pero the actual version significa la versión real. Accurate se usa para datos o respuestas correctas, no para personas acertadas."},{"id":"17-8","title_es":"Opinar sobre tecnología","words":[{"en":"addictive","es":"adictivo","pos":"adj","ex_en":"Some games are designed to be addictive.","ex_es":"Algunos juegos están diseñados para ser adictivos."},{"en":"convenient","es":"práctico, cómodo","pos":"adj","ex_en":"Paying with your phone is really convenient.","ex_es":"Pagar con el celular es muy práctico."},{"en":"overrated","es":"sobrevalorado","pos":"adj","ex_en":"In my opinion, smart watches are overrated.","ex_es":"En mi opinión, los relojes inteligentes están sobrevalorados."},{"en":"drawback","es":"desventaja","pos":"noun","ex_en":"The main drawback is the price.","ex_es":"La principal desventaja es el precio."},{"en":"upside","es":"ventaja, lo bueno","pos":"noun","ex_en":"The upside is that you can work from anywhere.","ex_es":"Lo bueno es que puedes trabajar desde cualquier lugar."},{"en":"game changer","es":"algo que lo cambia todo","pos":"noun","ex_en":"Fast internet in rural areas would be a game changer.","ex_es":"El internet rápido en zonas rurales lo cambiaría todo."},{"en":"outdated","es":"obsoleto, anticuado","pos":"adj","ex_en":"The computers at my school are totally outdated.","ex_es":"Las computadoras de mi escuela son totalmente obsoletas."},{"en":"on the fence","es":"indeciso","pos":"phrase","ex_en":"I'm still on the fence about buying an electric car.","ex_es":"Todavía estoy indeciso sobre comprar un carro eléctrico."}],"sentences":[{"en":"Technology makes our lives easier, but not always better.","es":"La tecnología nos facilita la vida, pero no siempre la mejora."},{"en":"To be honest, I can't live without my phone.","es":"Para ser honesto, no puedo vivir sin mi celular."},{"en":"On the one hand it's useful, on the other it's expensive.","es":"Por un lado es útil, por otro es caro."},{"en":"I see your point, but I disagree.","es":"Entiendo tu punto, pero no estoy de acuerdo."},{"en":"Kids shouldn't have smartphones until they're teenagers.","es":"Los niños no deberían tener smartphone hasta que sean adolescentes."}],"tip_es":"Convenient no significa conveniente en el sentido de recomendable, significa práctico o cómodo. Para decir que algo te conviene usa It's a good idea. Error común, decir I am agree. Lo correcto es I agree, sin am."},{"id":"17-9","title_es":"Mensajes y comunicación digital","words":[{"en":"text","es":"mandar un mensaje","pos":"verb","ex_en":"Text me when you get home.","ex_es":"Mándame un mensaje cuando llegues a tu casa."},{"en":"voice message","es":"mensaje de voz","pos":"noun","ex_en":"She sent me a really long voice message.","ex_es":"Me mandó un mensaje de voz larguísimo."},{"en":"group chat","es":"chat grupal","pos":"noun","ex_en":"The family group chat never stops.","ex_es":"El chat de la familia nunca para."},{"en":"emoji","es":"emoji","pos":"noun","ex_en":"He just replied with a laughing emoji.","ex_es":"Solo contestó con un emoji de risa."},{"en":"reply","es":"responder","pos":"verb","ex_en":"Sorry, I forgot to reply to your message.","ex_es":"Perdón, se me olvidó responder tu mensaje."},{"en":"on read","es":"en visto","pos":"phrase","ex_en":"She left me on read again.","ex_es":"Me volvió a dejar en visto."},{"en":"attachment","es":"archivo adjunto","pos":"noun","ex_en":"I can't open the attachment you sent.","ex_es":"No puedo abrir el archivo adjunto que mandaste."},{"en":"inbox","es":"bandeja de entrada","pos":"noun","ex_en":"My inbox has over two thousand unread emails.","ex_es":"Mi bandeja de entrada tiene más de dos mil correos sin leer."}],"sentences":[{"en":"Did you get my message?","es":"¿Te llegó mi mensaje?"},{"en":"I'll text you the address in a minute.","es":"Ahorita te mando la dirección por mensaje."},{"en":"Why didn't you answer my call?","es":"¿Por qué no contestaste mi llamada?"},{"en":"Sorry for the late reply, I was really busy.","es":"Perdón por responder tarde, estaba muy ocupado."},{"en":"Please don't add me to any more group chats.","es":"Por favor, ya no me agreguen a más chats grupales."}],"tip_es":"En EE. UU. text funciona como verbo, Text me o I'll text you. Dejar en visto se dice leave someone on read. Error común, decir I will write you para un mensaje del celular. Es más natural I'll text you o I'll message you."},{"id":"17-10","title_es":"Bienestar digital","words":[{"en":"screen time","es":"tiempo en pantalla","pos":"noun","ex_en":"My screen time is almost six hours a day.","ex_es":"Mi tiempo en pantalla es de casi seis horas al día."},{"en":"unplug","es":"desconectarse","pos":"verb","ex_en":"On weekends I try to unplug completely.","ex_es":"Los fines de semana trato de desconectarme por completo."},{"en":"distraction","es":"distracción","pos":"noun","ex_en":"My phone is my biggest distraction at work.","ex_es":"Mi celular es mi mayor distracción en el trabajo."},{"en":"cut down on","es":"reducir","pos":"verb","ex_en":"I'm trying to cut down on social media.","ex_es":"Estoy tratando de reducir el uso de redes sociales."},{"en":"notification","es":"notificación","pos":"noun","ex_en":"I turned off every notification except calls.","ex_es":"Desactivé todas las notificaciones excepto las llamadas."},{"en":"burnout","es":"agotamiento, desgaste","pos":"noun","ex_en":"Being online all the time can lead to burnout.","ex_es":"Estar conectado todo el tiempo puede causar agotamiento."},{"en":"habit","es":"hábito","pos":"noun","ex_en":"Checking my phone in bed is a bad habit.","ex_es":"Revisar el celular en la cama es un mal hábito."},{"en":"balance","es":"equilibrio","pos":"noun","ex_en":"It's hard to find a balance between work and rest.","ex_es":"Es difícil encontrar un equilibrio entre el trabajo y el descanso."}],"sentences":[{"en":"I leave my phone in another room when I sleep.","es":"Dejo mi celular en otro cuarto cuando duermo."},{"en":"The first thing I do in the morning is check my phone.","es":"Lo primero que hago en la mañana es revisar mi celular."},{"en":"Let's have dinner without phones tonight.","es":"Cenemos sin celulares esta noche."},{"en":"I deleted the app for a month, and I feel great.","es":"Borré la app por un mes y me siento súper bien."},{"en":"Do you think you spend too much time online?","es":"¿Crees que pasas demasiado tiempo en línea?"}],"tip_es":"Online funciona como adverbio y no lleva preposición, I spend too much time online, no in online. Para reducir algo se usa cut down on, por ejemplo cut down on sugar. Error común, olvidar el on y decir I want to cut down social media."}],"dialogue":{"title_es":"No puedo entrar a la junta","setting_es":"Una compañera de trabajo te pide ayuda porque no puede conectarse a una videollamada importante.","lines":[{"who":"A","en":"Hey, do you have a minute? I can't log in to the meeting app.","es":"Oye, ¿tienes un minuto? No puedo entrar a la app de juntas."},{"who":"B","en":"Sure. Did you try restarting your laptop?","es":"Claro. ¿Ya intentaste reiniciar tu laptop?"},{"who":"A","en":"Yes, twice. Now it says my password is wrong.","es":"Sí, dos veces. Ahora dice que mi contraseña está mal."},{"who":"B","en":"Maybe you need to reset it. Click on forgot password.","es":"Tal vez tienes que cambiarla. Da clic en olvidé mi contraseña."},{"who":"A","en":"OK, it says they sent a verification code to my phone.","es":"Ok, dice que mandaron un código de verificación a mi teléfono."},{"who":"B","en":"Great. Enter the code and create a new password.","es":"Perfecto. Ingresa el código y crea una contraseña nueva."},{"who":"A","en":"Done! I'm in. But now nobody can hear me.","es":"¡Listo! Ya entré. Pero ahora nadie me escucha."},{"who":"B","en":"I think you're on mute. Check the microphone icon.","es":"Creo que estás en silencio. Revisa el ícono del micrófono."},{"who":"A","en":"You're right! Thanks, you're a lifesaver.","es":"¡Tienes razón! Gracias, me salvaste la vida."},{"who":"B","en":"No problem. Next time, set it up before the meeting.","es":"De nada. La próxima vez, configúralo antes de la junta."}]}},{"id":18,"title_es":"Dinero, negocios y consumo","title_en":"Money and business","level":"B2","goal_es":"Al terminar podrás hacer trámites en el banco, manejar un presupuesto, comprar en línea, hacer reclamos, negociar y usar vocabulario básico de negocios.","lessons":[{"id":"18-1","title_es":"En el banco","words":[{"en":"checking account","es":"cuenta de cheques","pos":"noun","ex_en":"I opened a checking account at a local bank.","ex_es":"Abrí una cuenta de cheques en un banco local."},{"en":"savings account","es":"cuenta de ahorro","pos":"noun","ex_en":"I put part of my salary in a savings account.","ex_es":"Pongo parte de mi sueldo en una cuenta de ahorro."},{"en":"deposit","es":"depositar","pos":"verb","ex_en":"I need to deposit this check today.","ex_es":"Necesito depositar este cheque hoy."},{"en":"withdraw","es":"retirar","pos":"verb","ex_en":"You can withdraw cash at any ATM.","ex_es":"Puedes retirar efectivo en cualquier cajero."},{"en":"balance","es":"saldo","pos":"noun","ex_en":"Check your balance before you pay.","ex_es":"Revisa tu saldo antes de pagar."},{"en":"transfer","es":"transferencia","pos":"noun","ex_en":"I'll send you a bank transfer tonight.","ex_es":"Te mando una transferencia en la noche."},{"en":"fee","es":"comisión, cargo","pos":"noun","ex_en":"The bank charges a monthly fee for this card.","ex_es":"El banco cobra una comisión mensual por esta tarjeta."},{"en":"debit card","es":"tarjeta de débito","pos":"noun","ex_en":"I lost my debit card at the supermarket.","ex_es":"Perdí mi tarjeta de débito en el súper."}],"sentences":[{"en":"I'd like to open an account, please.","es":"Quisiera abrir una cuenta, por favor."},{"en":"Is there an ATM near here?","es":"¿Hay un cajero por aquí cerca?"},{"en":"What's the interest rate on this account?","es":"¿Cuál es la tasa de interés de esta cuenta?"},{"en":"My card was declined, but I have money.","es":"Rechazaron mi tarjeta, pero sí tengo dinero."},{"en":"How long does an international transfer take?","es":"¿Cuánto tarda una transferencia internacional?"}],"tip_es":"El cajero automático es ATM y la persona que te atiende en el banco es teller. Cashier es el cajero de una tienda. Withdraw es retirar dinero, y en el habla diaria también se dice take out money. Error común, decir take money from the cashier."},{"id":"18-2","title_es":"Presupuesto y ahorro","words":[{"en":"budget","es":"presupuesto","pos":"noun","ex_en":"We made a monthly budget to control our spending.","ex_es":"Hicimos un presupuesto mensual para controlar nuestros gastos."},{"en":"save up","es":"ahorrar para algo","pos":"verb","ex_en":"I'm trying to save up for a new car.","ex_es":"Estoy tratando de ahorrar para un carro nuevo."},{"en":"afford","es":"alcanzar para, darse el lujo","pos":"verb","ex_en":"We can't afford a vacation this year.","ex_es":"No nos alcanza para irnos de vacaciones este año."},{"en":"expense","es":"gasto","pos":"noun","ex_en":"Rent is my biggest expense every month.","ex_es":"La renta es mi mayor gasto cada mes."},{"en":"income","es":"ingresos","pos":"noun","ex_en":"Half of my income goes to rent and food.","ex_es":"La mitad de mis ingresos se va en renta y comida."},{"en":"debt","es":"deuda","pos":"noun","ex_en":"He's finally out of debt after five years.","ex_es":"Por fin salió de sus deudas después de cinco años."},{"en":"make ends meet","es":"llegar a fin de mes","pos":"phrase","ex_en":"Many families struggle to make ends meet.","ex_es":"Muchas familias batallan para llegar a fin de mes."},{"en":"splurge","es":"darse un gusto, derrochar","pos":"verb","ex_en":"I decided to splurge on a nice dinner.","ex_es":"Decidí darme el gusto de una buena cena."}],"sentences":[{"en":"I spend too much money on food delivery.","es":"Gasto demasiado dinero en comida a domicilio."},{"en":"We need to cut back on unnecessary expenses.","es":"Tenemos que recortar gastos innecesarios."},{"en":"I save ten percent of my paycheck every month.","es":"Ahorro el diez por ciento de mi sueldo cada mes."},{"en":"That phone is way too expensive for me.","es":"Ese celular está carísimo para mí."},{"en":"Once I pay off my credit card, I'll feel much better.","es":"Cuando termine de pagar mi tarjeta, me voy a sentir mucho mejor."}],"tip_es":"Afford casi siempre va con can o can't. I can't afford it significa no me alcanza. Error común, traducir literal y decir the money doesn't reach me. Lo natural es I can't afford it o I'm short on money this month."},{"id":"18-3","title_es":"Compras en línea","words":[{"en":"order","es":"pedido","pos":"noun","ex_en":"My order should arrive on Thursday.","ex_es":"Mi pedido debería llegar el jueves."},{"en":"shipping","es":"envío","pos":"noun","ex_en":"Shipping is free on orders over fifty dollars.","ex_es":"El envío es gratis en pedidos de más de cincuenta dólares."},{"en":"checkout","es":"pago, caja","pos":"noun","ex_en":"Enter the discount code at checkout.","ex_es":"Ingresa el código de descuento al pagar."},{"en":"track","es":"rastrear","pos":"verb","ex_en":"You can track your package with this number.","ex_es":"Puedes rastrear tu paquete con este número."},{"en":"in stock","es":"disponible, en existencia","pos":"phrase","ex_en":"Sorry, that size isn't in stock right now.","ex_es":"Lo siento, esa talla no está disponible ahorita."},{"en":"cart","es":"carrito","pos":"noun","ex_en":"I have three things in my cart, but I haven't paid.","ex_es":"Tengo tres cosas en mi carrito, pero no he pagado."},{"en":"review","es":"reseña","pos":"noun","ex_en":"I always read the reviews before I buy anything.","ex_es":"Siempre leo las reseñas antes de comprar algo."},{"en":"deal","es":"oferta, buen precio","pos":"noun","ex_en":"I got a great deal on these headphones.","ex_es":"Conseguí estos audífonos a muy buen precio."}],"sentences":[{"en":"I bought it online, and it arrived in two days.","es":"Lo compré en línea y llegó en dos días."},{"en":"The site says delivery takes five to seven business days.","es":"El sitio dice que la entrega tarda de cinco a siete días hábiles."},{"en":"Is it safe to pay with my card on this site?","es":"¿Es seguro pagar con mi tarjeta en este sitio?"},{"en":"I'll wait for Black Friday to buy a new TV.","es":"Voy a esperar al Black Friday para comprar una tele nueva."},{"en":"The tracking number isn't working.","es":"El número de rastreo no funciona."}],"tip_es":"Shipping es el envío o su costo, y delivery es la entrega. Online no lleva preposición, I bought it online. Error común, decir I bought it by internet o in internet."},{"id":"18-4","title_es":"Reclamos y devoluciones","words":[{"en":"refund","es":"reembolso","pos":"noun","ex_en":"The product didn't work, so I asked for a refund.","ex_es":"El producto no funcionó, así que pedí un reembolso."},{"en":"return","es":"devolver","pos":"verb","ex_en":"Can I return these shoes if they don't fit?","ex_es":"¿Puedo devolver estos zapatos si no me quedan?"},{"en":"receipt","es":"ticket, recibo","pos":"noun","ex_en":"Do you still have the receipt?","ex_es":"¿Todavía tiene el ticket?"},{"en":"damaged","es":"dañado","pos":"adj","ex_en":"The box arrived damaged and wet.","ex_es":"La caja llegó dañada y mojada."},{"en":"complaint","es":"queja, reclamo","pos":"noun","ex_en":"I want to make a complaint about the service.","ex_es":"Quiero poner una queja sobre el servicio."},{"en":"exchange","es":"cambiar","pos":"verb","ex_en":"Can I exchange this shirt for a bigger size?","ex_es":"¿Puedo cambiar esta camisa por una talla más grande?"},{"en":"warranty","es":"garantía","pos":"noun","ex_en":"The laptop is still under warranty.","ex_es":"La laptop todavía está en garantía."},{"en":"store credit","es":"saldo a favor en la tienda","pos":"noun","ex_en":"They didn't give me cash, only store credit.","ex_es":"No me dieron efectivo, solo saldo a favor en la tienda."}],"sentences":[{"en":"This isn't what I ordered.","es":"Esto no es lo que pedí."},{"en":"I was charged twice for the same item.","es":"Me cobraron dos veces el mismo artículo."},{"en":"I'd like to speak to a manager, please.","es":"Quisiera hablar con un gerente, por favor."},{"en":"How long do I have to return it?","es":"¿Cuánto tiempo tengo para devolverlo?"},{"en":"I'm not satisfied with the quality of this product.","es":"No estoy satisfecho con la calidad de este producto."}],"tip_es":"Ticket en inglés es un boleto. El comprobante de compra se llama receipt, y la p no se pronuncia, ri SIIT. Error común, decir I want to make a reclamation. Lo correcto es make a complaint o file a complaint."},{"id":"18-5","title_es":"Negociar","words":[{"en":"negotiate","es":"negociar","pos":"verb","ex_en":"We need to negotiate a better price.","ex_es":"Tenemos que negociar un mejor precio."},{"en":"offer","es":"oferta, propuesta","pos":"noun","ex_en":"That's a fair offer, but I need more time.","ex_es":"Es una propuesta justa, pero necesito más tiempo."},{"en":"counteroffer","es":"contraoferta","pos":"noun","ex_en":"They rejected our counteroffer this morning.","ex_es":"Rechazaron nuestra contraoferta esta mañana."},{"en":"discount","es":"descuento","pos":"noun","ex_en":"Can you give me a discount if I pay cash?","ex_es":"¿Me puede hacer un descuento si pago en efectivo?"},{"en":"compromise","es":"punto medio, acuerdo","pos":"noun","ex_en":"Let's find a compromise that works for both of us.","ex_es":"Busquemos un punto medio que nos funcione a los dos."},{"en":"bottom line","es":"lo esencial, el límite","pos":"noun","ex_en":"The bottom line is that we can't go any lower.","ex_es":"Lo esencial es que no podemos bajar más."},{"en":"meet halfway","es":"quedar en un punto medio","pos":"phrase","ex_en":"Could we meet halfway on the price?","ex_es":"¿Podemos quedar en un punto medio con el precio?"},{"en":"deal breaker","es":"motivo para no cerrar un trato","pos":"noun","ex_en":"The long contract is a deal breaker for us.","ex_es":"El contrato tan largo es motivo suficiente para no aceptar."}],"sentences":[{"en":"Is this your best price?","es":"¿Es su mejor precio?"},{"en":"What if I buy two of them?","es":"¿Y si compro dos?"},{"en":"I'm afraid that's a little over our budget.","es":"Me temo que eso está un poco por encima de nuestro presupuesto."},{"en":"Let me think about it and get back to you.","es":"Déjeme pensarlo y le aviso."},{"en":"If you lower the price, we can sign today.","es":"Si baja el precio, podemos firmar hoy."}],"tip_es":"Compromise no es compromiso. Significa ceder un poco para llegar a un acuerdo. Compromiso en el sentido de obligación es commitment. Error común, decir I have a compromise tonight cuando quieres decir que tienes planes. Lo natural es I have plans tonight."},{"id":"18-6","title_es":"Vocabulario de negocios","words":[{"en":"revenue","es":"ingresos totales","pos":"noun","ex_en":"Our revenue grew twenty percent this year.","ex_es":"Nuestros ingresos crecieron veinte por ciento este año."},{"en":"profit","es":"ganancia","pos":"noun","ex_en":"The store barely makes a profit.","ex_es":"La tienda apenas tiene ganancias."},{"en":"loss","es":"pérdida","pos":"noun","ex_en":"The company reported a loss for the second year.","ex_es":"La empresa reportó pérdidas por segundo año."},{"en":"startup","es":"empresa emergente","pos":"noun","ex_en":"She quit her job to create a startup.","ex_es":"Renunció a su trabajo para crear una empresa emergente."},{"en":"launch","es":"lanzar","pos":"verb","ex_en":"We'll launch the new product in March.","ex_es":"Vamos a lanzar el nuevo producto en marzo."},{"en":"competitor","es":"competidor","pos":"noun","ex_en":"Our main competitor just lowered its prices.","ex_es":"Nuestro principal competidor acaba de bajar sus precios."},{"en":"market share","es":"participación de mercado","pos":"noun","ex_en":"We want to increase our market share in Mexico.","ex_es":"Queremos aumentar nuestra participación de mercado en México."},{"en":"stakeholder","es":"parte interesada","pos":"noun","ex_en":"Every stakeholder needs to approve the changes.","ex_es":"Cada parte interesada tiene que aprobar los cambios."}],"sentences":[{"en":"Sales went up after the new ad campaign.","es":"Las ventas subieron después de la nueva campaña publicitaria."},{"en":"We're expanding into new markets next year.","es":"Vamos a expandirnos a nuevos mercados el próximo año."},{"en":"The company is struggling to stay competitive.","es":"La empresa batalla para mantenerse competitiva."},{"en":"Who are your target customers?","es":"¿Quiénes son sus clientes objetivo?"},{"en":"Small businesses are the backbone of the economy.","es":"Los pequeños negocios son la base de la economía."}],"tip_es":"Revenue es todo el dinero que entra y profit es lo que queda después de pagar los gastos. Error común, decir win money. Ganar dinero trabajando es earn money o make money. Win se usa para premios, apuestas o juegos."},{"id":"18-7","title_es":"Crédito y préstamos","words":[{"en":"credit card","es":"tarjeta de crédito","pos":"noun","ex_en":"I only use my credit card for emergencies.","ex_es":"Solo uso mi tarjeta de crédito para emergencias."},{"en":"loan","es":"préstamo","pos":"noun","ex_en":"We asked the bank for a loan to buy a house.","ex_es":"Le pedimos un préstamo al banco para comprar una casa."},{"en":"interest","es":"intereses","pos":"noun","ex_en":"This card charges very high interest.","ex_es":"Esta tarjeta cobra intereses muy altos."},{"en":"pay off","es":"liquidar, terminar de pagar","pos":"verb","ex_en":"It took me three years to pay off my car.","ex_es":"Me tomó tres años terminar de pagar mi carro."},{"en":"installment","es":"mensualidad, pago a plazos","pos":"noun","ex_en":"You can pay in twelve monthly installments.","ex_es":"Puedes pagar en doce mensualidades."},{"en":"credit score","es":"puntaje de crédito","pos":"noun","ex_en":"A good credit score helps you get better loans.","ex_es":"Un buen puntaje de crédito te ayuda a conseguir mejores préstamos."},{"en":"down payment","es":"enganche","pos":"noun","ex_en":"We need a bigger down payment for the house.","ex_es":"Necesitamos un enganche más grande para la casa."},{"en":"mortgage","es":"hipoteca, crédito hipotecario","pos":"noun","ex_en":"Their mortgage payment is higher than my rent.","ex_es":"El pago de su hipoteca es más alto que mi renta."}],"sentences":[{"en":"Can I pay in installments with no interest?","es":"¿Puedo pagar a meses sin intereses?"},{"en":"I always pay my full balance every month.","es":"Siempre pago el total de mi tarjeta cada mes."},{"en":"Missing a payment can hurt your credit.","es":"No hacer un pago puede afectar tu historial crediticio."},{"en":"How much is the minimum payment?","es":"¿De cuánto es el pago mínimo?"},{"en":"They approved my loan in just two days.","es":"Me aprobaron el préstamo en solo dos días."}],"tip_es":"El enganche se dice down payment y una mensualidad es a monthly payment. Lo que en México llamamos meses sin intereses en EE. UU. se conoce como no interest financing. Error común, decir borrow money to the bank. Lo correcto es borrow money from the bank, o the bank lends me money."},{"id":"18-8","title_es":"Sueldo y prestaciones","words":[{"en":"salary","es":"sueldo, salario","pos":"noun","ex_en":"The salary is good, but the hours are long.","ex_es":"El sueldo es bueno, pero el horario es largo."},{"en":"raise","es":"aumento de sueldo","pos":"noun","ex_en":"I'm going to ask my boss for a raise.","ex_es":"Le voy a pedir un aumento a mi jefe."},{"en":"bonus","es":"bono","pos":"noun","ex_en":"Everyone got a bonus at the end of the year.","ex_es":"Todos recibieron un bono a fin de año."},{"en":"paycheck","es":"pago de nómina","pos":"noun","ex_en":"My paycheck arrives every other Friday.","ex_es":"Mi pago llega cada dos viernes."},{"en":"benefits","es":"prestaciones","pos":"noun","ex_en":"The job offers great benefits, like health insurance.","ex_es":"El trabajo ofrece muy buenas prestaciones, como seguro médico."},{"en":"taxes","es":"impuestos","pos":"noun","ex_en":"A big part of my salary goes to taxes.","ex_es":"Una gran parte de mi sueldo se va en impuestos."},{"en":"freelance","es":"independiente, por tu cuenta","pos":"adj","ex_en":"I do freelance work on weekends.","ex_es":"Hago trabajos por mi cuenta los fines de semana."},{"en":"overtime","es":"horas extra","pos":"noun","ex_en":"They don't pay overtime at my company.","ex_es":"En mi empresa no pagan horas extra."}],"sentences":[{"en":"In the U.S. it's rude to ask how much someone makes.","es":"En EE. UU. es de mala educación preguntar cuánto gana alguien."},{"en":"I get paid every two weeks.","es":"Me pagan cada quincena."},{"en":"I earn more now, but I also spend more.","es":"Gano más ahora, pero también gasto más."},{"en":"She negotiated a higher salary before accepting the job.","es":"Ella negoció un sueldo más alto antes de aceptar el trabajo."},{"en":"Do you get paid vacation at your job?","es":"¿Tienes vacaciones pagadas en tu trabajo?"}],"tip_es":"Las prestaciones se llaman benefits, no prestations. Un aumento de sueldo es a raise. Error común, decir I win a good salary. Con el sueldo se usa earn o make, como en I make good money."},{"id":"18-9","title_es":"Hábitos de consumo","words":[{"en":"impulse buy","es":"compra impulsiva","pos":"noun","ex_en":"That jacket was an impulse buy, and I regret it.","ex_es":"Esa chamarra fue una compra impulsiva y me arrepiento."},{"en":"bargain","es":"ganga","pos":"noun","ex_en":"These boots were a real bargain.","ex_es":"Estas botas fueron una verdadera ganga."},{"en":"ripoff","es":"robo, precio abusivo","pos":"noun","ex_en":"Ten dollars for a coffee is a ripoff.","ex_es":"Diez dólares por un café es un robo."},{"en":"brand","es":"marca","pos":"noun","ex_en":"I don't care about the brand, I care about quality.","ex_es":"No me importa la marca, me importa la calidad."},{"en":"secondhand","es":"de segunda mano","pos":"adj","ex_en":"I buy most of my clothes secondhand.","ex_es":"Compro casi toda mi ropa de segunda mano."},{"en":"worth it","es":"que vale la pena","pos":"phrase","ex_en":"It was expensive, but it was totally worth it.","ex_es":"Fue caro, pero valió totalmente la pena."},{"en":"shop around","es":"comparar precios","pos":"verb","ex_en":"Shop around before you buy a new phone.","ex_es":"Compara precios antes de comprar un celular nuevo."},{"en":"subscription","es":"suscripción","pos":"noun","ex_en":"I canceled a subscription I never used.","ex_es":"Cancelé una suscripción que nunca usaba."}],"sentences":[{"en":"I only buy things when they're on sale.","es":"Solo compro cosas cuando están en oferta."},{"en":"Is it cheaper to buy it online or in the store?","es":"¿Es más barato comprarlo en línea o en la tienda?"},{"en":"That's a lot of money for such a small thing.","es":"Es mucho dinero por algo tan pequeño."},{"en":"I try to support local businesses when I can.","es":"Trato de apoyar a los negocios locales cuando puedo."},{"en":"He's always buying gadgets he doesn't need.","es":"Siempre está comprando aparatos que no necesita."}],"tip_es":"Cheap puede sonar negativo, como de mala calidad. Para algo barato pero bueno usa affordable o a good price. Error común, decir He is very cheap pensando en precios. Aplicado a una persona, cheap significa tacaño."},{"id":"18-10","title_es":"Emprender","words":[{"en":"business plan","es":"plan de negocios","pos":"noun","ex_en":"Every new company needs a solid business plan.","ex_es":"Toda empresa nueva necesita un plan de negocios sólido."},{"en":"investor","es":"inversionista","pos":"noun","ex_en":"We're meeting with an investor next week.","ex_es":"Nos vamos a reunir con un inversionista la próxima semana."},{"en":"pitch","es":"presentar una propuesta","pos":"verb","ex_en":"She will pitch her idea to the board tomorrow.","ex_es":"Mañana va a presentar su idea al consejo."},{"en":"funding","es":"financiamiento","pos":"noun","ex_en":"We're still looking for funding.","ex_es":"Todavía estamos buscando financiamiento."},{"en":"break even","es":"no ganar ni perder","pos":"verb","ex_en":"We expect to break even in the first year.","ex_es":"Esperamos no tener pérdidas ni ganancias el primer año."},{"en":"scale","es":"crecer, escalar","pos":"verb","ex_en":"It's hard to scale a business without money.","ex_es":"Es difícil hacer crecer un negocio sin dinero."},{"en":"risk","es":"riesgo","pos":"noun","ex_en":"Starting a business is always a risk.","ex_es":"Empezar un negocio siempre es un riesgo."},{"en":"entrepreneur","es":"emprendedor","pos":"noun","ex_en":"My aunt is an entrepreneur with three restaurants.","ex_es":"Mi tía es una emprendedora con tres restaurantes."}],"sentences":[{"en":"What problem does your product solve?","es":"¿Qué problema resuelve tu producto?"},{"en":"We're looking for a partner with experience in sales.","es":"Buscamos un socio con experiencia en ventas."},{"en":"Our goal is to grow without taking on too much debt.","es":"Nuestra meta es crecer sin endeudarnos demasiado."},{"en":"How much money do you need to get started?","es":"¿Cuánto dinero necesitas para empezar?"},{"en":"Most new businesses fail in the first few years.","es":"La mayoría de los negocios nuevos fracasan en los primeros años."}],"tip_es":"Entrepreneur se pronuncia on tre pre NUR. Emprender un negocio se dice start a business o launch a business. Error común, traducir emprender como undertake, que casi no se usa en ese sentido."}],"dialogue":{"title_es":"Una devolución","setting_es":"Regresas a una tienda departamental para devolver una cafetera que no funciona.","lines":[{"who":"A","en":"Hi, how can I help you today?","es":"Hola, ¿en qué le puedo ayudar hoy?"},{"who":"B","en":"Hi. I bought this coffee maker last week, and it doesn't work.","es":"Hola. Compré esta cafetera la semana pasada y no funciona."},{"who":"A","en":"I'm sorry to hear that. Do you have the receipt?","es":"Lamento escuchar eso. ¿Tiene el ticket?"},{"who":"B","en":"Yes, here it is. I paid with my debit card.","es":"Sí, aquí está. Pagué con mi tarjeta de débito."},{"who":"A","en":"Thanks. Would you like an exchange or a refund?","es":"Gracias. ¿Prefiere un cambio o un reembolso?"},{"who":"B","en":"I'd prefer a refund, if that's possible.","es":"Prefiero un reembolso, si es posible."},{"who":"A","en":"Sure. The money will be back in your account in three days.","es":"Claro. El dinero regresará a su cuenta en tres días."},{"who":"B","en":"Three days? Is there any way to get cash today?","es":"¿Tres días? ¿Hay alguna forma de recibir efectivo hoy?"},{"who":"A","en":"I'm afraid not, but I can give you store credit right now.","es":"Me temo que no, pero le puedo dar saldo a favor ahora mismo."},{"who":"B","en":"That's OK, I'll wait for the refund. Thanks for your help.","es":"Está bien, espero el reembolso. Gracias por su ayuda."}]}},{"id":19,"title_es":"Cultura, entretenimiento y medios","title_en":"Culture and entertainment","level":"B2","goal_es":"Al terminar podrás hablar de películas, series, música, libros y noticias, recomendar y criticar con naturalidad y usar la voz pasiva.","lessons":[{"id":"19-1","title_es":"El cine","words":[{"en":"movie theater","es":"cine","pos":"noun","ex_en":"Let's meet in front of the movie theater at seven.","ex_es":"Veámonos enfrente del cine a las siete."},{"en":"plot","es":"trama","pos":"noun","ex_en":"The plot was confusing, but the acting was great.","ex_es":"La trama era confusa, pero la actuación estuvo muy buena."},{"en":"cast","es":"elenco","pos":"noun","ex_en":"The cast includes several famous Mexican actors.","ex_es":"El elenco incluye a varios actores mexicanos famosos."},{"en":"sequel","es":"secuela","pos":"noun","ex_en":"The sequel was better than the original.","ex_es":"La secuela fue mejor que la original."},{"en":"trailer","es":"tráiler, avance","pos":"noun","ex_en":"The trailer gave away too much of the story.","ex_es":"El tráiler reveló demasiado de la historia."},{"en":"box office","es":"taquilla","pos":"noun","ex_en":"The movie was a huge hit at the box office.","ex_es":"La película fue un gran éxito de taquilla."},{"en":"special effects","es":"efectos especiales","pos":"noun","ex_en":"The special effects looked cheap and fake.","ex_es":"Los efectos especiales se veían baratos y falsos."},{"en":"subtitles","es":"subtítulos","pos":"noun","ex_en":"I watch movies in English with subtitles.","ex_es":"Veo películas en inglés con subtítulos."}],"sentences":[{"en":"What's playing at the movies tonight?","es":"¿Qué están pasando en el cine hoy en la noche?"},{"en":"I'd rather see a comedy than a horror movie.","es":"Prefiero ver una comedia que una película de terror."},{"en":"The movie is based on a true story.","es":"La película está basada en una historia real."},{"en":"Who's in it?","es":"¿Quién sale?"},{"en":"The ending was so sad that I cried.","es":"El final fue tan triste que lloré."}],"tip_es":"En EE. UU. se dice movie mucho más que film. Para preguntar quién actúa se dice Who's in it? o Who stars in it? Error común, decir the actors of the movie. Es más natural the cast o the people in it."},{"id":"19-2","title_es":"Series y streaming","words":[{"en":"episode","es":"episodio, capítulo","pos":"noun","ex_en":"The last episode left me speechless.","ex_es":"El último capítulo me dejó sin palabras."},{"en":"season","es":"temporada","pos":"noun","ex_en":"The second season comes out in May.","ex_es":"La segunda temporada sale en mayo."},{"en":"binge watch","es":"ver de corrido, maratonear","pos":"verb","ex_en":"We like to binge watch a whole series on weekends.","ex_es":"Nos gusta maratonear una serie completa los fines de semana."},{"en":"streaming service","es":"plataforma de streaming","pos":"noun","ex_en":"Which streaming service has the best shows?","ex_es":"¿Qué plataforma de streaming tiene las mejores series?"},{"en":"spoiler","es":"spoiler","pos":"noun","ex_en":"No spoilers, please! I haven't seen it yet.","ex_es":"¡Sin spoilers, por favor! Todavía no la veo."},{"en":"cliffhanger","es":"final de suspenso","pos":"noun","ex_en":"Every episode ends with a cliffhanger.","ex_es":"Cada capítulo termina con un final de suspenso."},{"en":"character","es":"personaje","pos":"noun","ex_en":"My favorite character dies in the third season.","ex_es":"Mi personaje favorito muere en la tercera temporada."},{"en":"renew","es":"renovar","pos":"verb","ex_en":"I hope they renew the show for another season.","ex_es":"Ojalá renueven la serie por otra temporada."}],"sentences":[{"en":"Are you watching anything good right now?","es":"¿Estás viendo algo bueno ahorita?"},{"en":"I've heard great things about that show.","es":"He oído muy buenas cosas de esa serie."},{"en":"I couldn't stop watching, I finished it in two days.","es":"No podía dejar de verla, la terminé en dos días."},{"en":"Don't tell me how it ends!","es":"¡No me digas cómo termina!"},{"en":"It starts slow, but it gets better.","es":"Empieza lento, pero luego mejora."}],"tip_es":"Lo que en México llamamos serie en inglés es a series o a show. El capítulo de una serie es episode, porque chapter se usa solo para libros. Error común, decir I saw the chapter five. Lo correcto es I watched episode five."},{"id":"19-3","title_es":"La música","words":[{"en":"lyrics","es":"letra de una canción","pos":"noun","ex_en":"I love the song, but I don't understand the lyrics.","ex_es":"Me encanta la canción, pero no entiendo la letra."},{"en":"catchy","es":"pegajoso","pos":"adj","ex_en":"That song is so catchy, I can't stop singing it.","ex_es":"Esa canción es tan pegajosa que no dejo de cantarla."},{"en":"gig","es":"tocada, presentación","pos":"noun","ex_en":"My cousin's band has a gig on Saturday.","ex_es":"La banda de mi primo tiene una tocada el sábado."},{"en":"album","es":"disco, álbum","pos":"noun","ex_en":"Their new album comes out next Friday.","ex_es":"Su nuevo disco sale el próximo viernes."},{"en":"tour","es":"gira","pos":"noun","ex_en":"The band is going on a world tour.","ex_es":"La banda se va de gira mundial."},{"en":"playlist","es":"lista de reproducción","pos":"noun","ex_en":"I made a playlist for our road trip.","ex_es":"Hice una lista de canciones para nuestro viaje en carretera."},{"en":"sold out","es":"agotado","pos":"adj","ex_en":"The concert was sold out in ten minutes.","ex_es":"Los boletos del concierto se agotaron en diez minutos."},{"en":"live","es":"en vivo","pos":"adv","ex_en":"They sound even better live.","ex_es":"Suenan todavía mejor en vivo."}],"sentences":[{"en":"What kind of music are you into?","es":"¿Qué tipo de música te gusta?"},{"en":"I've been listening to this song on repeat.","es":"He estado escuchando esta canción una y otra vez."},{"en":"Tickets go on sale tomorrow morning.","es":"Los boletos salen a la venta mañana en la mañana."},{"en":"She has an amazing voice.","es":"Tiene una voz increíble."},{"en":"We waited in line for hours to get in.","es":"Hicimos fila durante horas para entrar."}],"tip_es":"La letra de una canción es lyrics, siempre en plural, the lyrics are beautiful. Error común, decir the letter of the song. Letter es una carta o una letra del abecedario. Be into algo es una forma informal de decir que te gusta mucho."},{"id":"19-4","title_es":"Las noticias","words":[{"en":"headline","es":"titular, encabezado","pos":"noun","ex_en":"Did you read the headline about the election?","ex_es":"¿Leíste el titular sobre la elección?"},{"en":"breaking news","es":"noticia de última hora","pos":"noun","ex_en":"We interrupt this program for breaking news.","ex_es":"Interrumpimos este programa por una noticia de última hora."},{"en":"journalist","es":"periodista","pos":"noun","ex_en":"The journalist interviewed people on the street.","ex_es":"El periodista entrevistó a gente en la calle."},{"en":"source","es":"fuente","pos":"noun","ex_en":"Always check the source before you believe a story.","ex_es":"Siempre revisa la fuente antes de creer una noticia."},{"en":"fake news","es":"noticias falsas","pos":"noun","ex_en":"That story is fake news, it never happened.","ex_es":"Esa historia es falsa, nunca pasó."},{"en":"report","es":"informar, reportar","pos":"verb","ex_en":"The media began to report the story last night.","ex_es":"Los medios empezaron a reportar la historia anoche."},{"en":"coverage","es":"cobertura","pos":"noun","ex_en":"The coverage of the earthquake was excellent.","ex_es":"La cobertura del sismo fue excelente."},{"en":"biased","es":"parcial, tendencioso","pos":"adj","ex_en":"I think that newspaper is very biased.","ex_es":"Creo que ese periódico es muy tendencioso."}],"sentences":[{"en":"Did you hear the news about the storm?","es":"¿Supiste la noticia de la tormenta?"},{"en":"I usually get my news from podcasts.","es":"Normalmente me informo con podcasts."},{"en":"The story was first reported by a local newspaper.","es":"Un periódico local fue el primero en reportar la historia."},{"en":"It's hard to know what's true these days.","es":"Es difícil saber qué es verdad hoy en día."},{"en":"The president will give a press conference at noon.","es":"El presidente dará una conferencia de prensa al mediodía."}],"tip_es":"News es incontable y lleva verbo en singular, The news is bad. Para una sola noticia se dice a piece of news o simplemente a story. Error común, decir a new o the news are."},{"id":"19-5","title_es":"Recomendar","words":[{"en":"recommend","es":"recomendar","pos":"verb","ex_en":"I highly recommend this book.","ex_es":"Te recomiendo muchísimo este libro."},{"en":"worth watching","es":"que vale la pena ver","pos":"phrase","ex_en":"The new series is definitely worth watching.","ex_es":"La nueva serie definitivamente vale la pena."},{"en":"give it a try","es":"darle una oportunidad","pos":"phrase","ex_en":"You should give it a try, you might like it.","ex_es":"Deberías darle una oportunidad, a lo mejor te gusta."},{"en":"masterpiece","es":"obra maestra","pos":"noun","ex_en":"Many critics call it a masterpiece.","ex_es":"Muchos críticos la consideran una obra maestra."},{"en":"underrated","es":"subestimado","pos":"adj","ex_en":"That singer is so underrated.","ex_es":"Esa cantante está muy subestimada."},{"en":"gripping","es":"atrapante, que te engancha","pos":"adj","ex_en":"The story is gripping from the first page.","ex_es":"La historia te atrapa desde la primera página."},{"en":"heartwarming","es":"conmovedor, enternecedor","pos":"adj","ex_en":"It's a heartwarming story about a big family.","ex_es":"Es una historia conmovedora sobre una familia grande."},{"en":"hidden gem","es":"joya escondida","pos":"noun","ex_en":"This little bookstore is a hidden gem.","ex_es":"Esta pequeña librería es una joya escondida."}],"sentences":[{"en":"You have to watch it, you'll love it.","es":"Tienes que verla, te va a encantar."},{"en":"If you liked that one, you'll like this one too.","es":"Si te gustó esa, esta también te va a gustar."},{"en":"I'm looking for something light and funny.","es":"Busco algo ligero y divertido."},{"en":"What would you recommend for a rainy Sunday?","es":"¿Qué recomiendas para un domingo lluvioso?"},{"en":"Trust me, you won't regret it.","es":"Créeme, no te vas a arrepentir."}],"tip_es":"Recommend no funciona como en español con una persona y otro verbo. I recommend you to see it no suena natural. Di I recommend seeing it o I recommend that you see it. En la conversación diaria también se dice You should check it out."},{"id":"19-6","title_es":"Criticar","words":[{"en":"critic","es":"crítico","pos":"noun","ex_en":"The critics loved it, but audiences hated it.","ex_es":"A los críticos les encantó, pero el público la odió."},{"en":"predictable","es":"predecible","pos":"adj","ex_en":"The story was so predictable that I guessed the ending.","ex_es":"La historia era tan predecible que adiviné el final."},{"en":"disappointing","es":"decepcionante","pos":"adj","ex_en":"The ending was really disappointing.","ex_es":"El final fue muy decepcionante."},{"en":"overhyped","es":"inflado por la publicidad","pos":"adj","ex_en":"The movie was overhyped, it wasn't that good.","ex_es":"Le dieron demasiado bombo a la película, no estuvo tan buena."},{"en":"drag on","es":"hacerse eterno","pos":"verb","ex_en":"The second half seemed to drag on forever.","ex_es":"La segunda mitad se hizo eterna."},{"en":"plot hole","es":"hueco en la trama","pos":"noun","ex_en":"There's a huge plot hole in the last episode.","ex_es":"Hay un hueco enorme en la trama del último capítulo."},{"en":"performance","es":"actuación, interpretación","pos":"noun","ex_en":"Her performance was the best part of the movie.","ex_es":"Su actuación fue lo mejor de la película."},{"en":"cheesy","es":"cursi, chafa","pos":"adj","ex_en":"The dialogue was so cheesy that we laughed.","ex_es":"Los diálogos eran tan cursis que nos dio risa."}],"sentences":[{"en":"It wasn't as good as I expected.","es":"No estuvo tan buena como esperaba."},{"en":"The acting was great, but the story was weak.","es":"La actuación fue muy buena, pero la historia fue floja."},{"en":"I fell asleep halfway through.","es":"Me quedé dormido a la mitad."},{"en":"It's not really my cup of tea.","es":"No es mucho lo mío."},{"en":"I wouldn't watch it again.","es":"No la volvería a ver."}],"tip_es":"Para criticar con tacto se dice mucho It wasn't really my thing o It's not my cup of tea. Error común, confundir bored y boring. I was bored significa me aburrí, y I was boring significa que tú eras el aburrido."},{"id":"19-7","title_es":"La voz pasiva","words":[{"en":"release","es":"estrenar, lanzar","pos":"verb","ex_en":"The studio will release the movie in December.","ex_es":"El estudio va a estrenar la película en diciembre."},{"en":"film","es":"filmar","pos":"verb","ex_en":"The series was filmed in Oaxaca.","ex_es":"La serie se filmó en Oaxaca."},{"en":"direct","es":"dirigir","pos":"verb","ex_en":"The movie was directed by a Mexican woman.","ex_es":"La película fue dirigida por una mujer mexicana."},{"en":"award","es":"premio","pos":"noun","ex_en":"The documentary won an award in Cannes.","ex_es":"El documental ganó un premio en Cannes."},{"en":"nominate","es":"nominar","pos":"verb","ex_en":"She was nominated for best actress.","ex_es":"Ella fue nominada a mejor actriz."},{"en":"produce","es":"producir","pos":"verb","ex_en":"The show is produced by a small studio.","ex_es":"La serie la produce un estudio pequeño."},{"en":"translate","es":"traducir","pos":"verb","ex_en":"The novel has been translated into forty languages.","ex_es":"La novela ha sido traducida a cuarenta idiomas."},{"en":"set","es":"ambientar, situar","pos":"verb","ex_en":"The story is set in Mexico City in the eighties.","ex_es":"La historia está ambientada en la Ciudad de México en los ochenta."}],"sentences":[{"en":"The book was written more than seventy years ago.","es":"El libro fue escrito hace más de setenta años."},{"en":"The song was recorded in just one day.","es":"La canción se grabó en un solo día."},{"en":"The movie will be released next year.","es":"La película se va a estrenar el próximo año."},{"en":"Tickets can be bought online.","es":"Los boletos se pueden comprar en línea."},{"en":"The concert has been canceled because of the rain.","es":"El concierto se canceló por la lluvia."}],"tip_es":"La voz pasiva se forma con be y el participio, was written, will be released. En español muchas veces usamos se, como en se grabó, pero en inglés hay que usar la pasiva. Error común, decir The song recorded in one day. Lo correcto es The song was recorded in one day."},{"id":"19-8","title_es":"Libros y lectura","words":[{"en":"novel","es":"novela","pos":"noun","ex_en":"Her latest novel takes place in Guadalajara.","ex_es":"Su novela más reciente se desarrolla en Guadalajara."},{"en":"author","es":"autor","pos":"noun","ex_en":"The author signed my copy of the book.","ex_es":"El autor firmó mi ejemplar del libro."},{"en":"bestseller","es":"éxito de ventas","pos":"noun","ex_en":"Her first book became a bestseller.","ex_es":"Su primer libro se volvió un éxito de ventas."},{"en":"chapter","es":"capítulo","pos":"noun","ex_en":"I read one chapter every night before bed.","ex_es":"Leo un capítulo cada noche antes de dormir."},{"en":"audiobook","es":"audiolibro","pos":"noun","ex_en":"I listen to audiobooks while I drive.","ex_es":"Escucho audiolibros mientras manejo."},{"en":"paperback","es":"edición de bolsillo","pos":"noun","ex_en":"The paperback is much cheaper than the hardcover.","ex_es":"La edición de bolsillo es mucho más barata que la de pasta dura."},{"en":"put down","es":"dejar de leer, soltar","pos":"verb","ex_en":"It's the kind of book you can't put down.","ex_es":"Es el tipo de libro que no puedes soltar."},{"en":"book club","es":"club de lectura","pos":"noun","ex_en":"Our book club meets once a month.","ex_es":"Nuestro club de lectura se reúne una vez al mes."}],"sentences":[{"en":"What are you reading these days?","es":"¿Qué estás leyendo últimamente?"},{"en":"The book is much better than the movie.","es":"El libro es mucho mejor que la película."},{"en":"I read on my phone more than on paper.","es":"Leo más en el celular que en papel."},{"en":"I don't have time to read as much as I'd like.","es":"No tengo tiempo de leer tanto como quisiera."},{"en":"I'm halfway through the second book of the series.","es":"Voy a la mitad del segundo libro de la saga."}],"tip_es":"Novel es solo la novela escrita. La telenovela de la tele es a soap opera. Error común, decir lecture para hablar de la lectura. Lecture es una conferencia o clase, y lectura se dice reading."},{"id":"19-9","title_es":"Arte y eventos","words":[{"en":"exhibit","es":"exposición","pos":"noun","ex_en":"The museum has a new exhibit on Frida Kahlo.","ex_es":"El museo tiene una nueva exposición sobre Frida Kahlo."},{"en":"gallery","es":"galería","pos":"noun","ex_en":"Her work is on display at a small gallery.","ex_es":"Su obra está expuesta en una pequeña galería."},{"en":"painting","es":"pintura, cuadro","pos":"noun","ex_en":"This painting is worth millions of dollars.","ex_es":"Este cuadro vale millones de dólares."},{"en":"sculpture","es":"escultura","pos":"noun","ex_en":"There's a huge sculpture in the main square.","ex_es":"Hay una escultura enorme en la plaza principal."},{"en":"festival","es":"festival","pos":"noun","ex_en":"The film festival takes place every October.","ex_es":"El festival de cine se celebra cada octubre."},{"en":"admission","es":"entrada, acceso","pos":"noun","ex_en":"Admission is free on Sundays.","ex_es":"La entrada es gratis los domingos."},{"en":"guided tour","es":"visita guiada","pos":"noun","ex_en":"We took a guided tour of the old city.","ex_es":"Hicimos una visita guiada por el centro histórico."},{"en":"play","es":"obra de teatro","pos":"noun","ex_en":"We saw a play on Broadway last summer.","ex_es":"Vimos una obra en Broadway el verano pasado."}],"sentences":[{"en":"Is photography allowed inside the museum?","es":"¿Se permite tomar fotos dentro del museo?"},{"en":"The exhibit runs until the end of March.","es":"La exposición estará abierta hasta finales de marzo."},{"en":"I'm not really an art person, but I loved it.","es":"No soy muy de arte, pero me encantó."},{"en":"How much are tickets for students?","es":"¿Cuánto cuestan los boletos para estudiantes?"},{"en":"The show starts at eight, so let's not be late.","es":"La función empieza a las ocho, así que no lleguemos tarde."}],"tip_es":"Una exposición de arte es an exhibit o an exhibition, no an exposition. Error común, decir I assisted to the concert. Assist significa ayudar. Lo correcto es I attended the concert o I went to the concert."},{"id":"19-10","title_es":"Medios y cultura pop","words":[{"en":"podcast","es":"podcast","pos":"noun","ex_en":"I listen to a true crime podcast every morning.","ex_es":"Escucho un podcast de crímenes reales cada mañana."},{"en":"host","es":"conductor, presentador","pos":"noun","ex_en":"The host of the show is very funny.","ex_es":"El conductor del programa es muy chistoso."},{"en":"audience","es":"público","pos":"noun","ex_en":"The audience laughed at every joke.","ex_es":"El público se rió con cada chiste."},{"en":"trend","es":"tendencia","pos":"noun","ex_en":"That dance became a huge trend online.","ex_es":"Ese baile se volvió una gran tendencia en internet."},{"en":"meme","es":"meme","pos":"noun","ex_en":"My mom sends me memes every day.","ex_es":"Mi mamá me manda memes todos los días."},{"en":"celebrity","es":"celebridad, famoso","pos":"noun","ex_en":"A famous celebrity was spotted at a café downtown.","ex_es":"Vieron a una celebridad en un café del centro."},{"en":"reboot","es":"nueva versión","pos":"noun","ex_en":"Hollywood keeps making reboots of old movies.","ex_es":"Hollywood sigue haciendo nuevas versiones de películas viejas."},{"en":"pop culture","es":"cultura pop","pos":"noun","ex_en":"The show had a huge impact on pop culture.","ex_es":"La serie tuvo un gran impacto en la cultura pop."}],"sentences":[{"en":"Everyone is talking about that show.","es":"Todo el mundo está hablando de esa serie."},{"en":"I don't get the joke, can you explain it?","es":"No entiendo el chiste, ¿me lo explicas?"},{"en":"She became famous thanks to a video on YouTube.","es":"Se hizo famosa gracias a un video en YouTube."},{"en":"Mexican food and music are popular all over the world.","es":"La comida y la música mexicanas son populares en todo el mundo."},{"en":"That reference went over my head.","es":"No entendí esa referencia."}],"tip_es":"El público de un show es the audience. Public casi siempre es adjetivo, como en public transportation. Error común, decir the public loved the movie. Lo natural es the audience loved the movie. Went over my head significa que no entendiste algo."}],"dialogue":{"title_es":"¿Qué serie veo?","setting_es":"Un amigo te pide que le recomiendes una serie para el fin de semana.","lines":[{"who":"A","en":"I'm bored. Can you recommend a good series?","es":"Estoy aburrido. ¿Me recomiendas una buena serie?"},{"who":"B","en":"Have you seen the new Mexican crime show? It's gripping.","es":"¿Ya viste la nueva serie policiaca mexicana? Te atrapa."},{"who":"A","en":"Not yet. What's it about?","es":"Todavía no. ¿De qué trata?"},{"who":"B","en":"It's about a journalist who discovers a huge scandal.","es":"Trata de una periodista que descubre un escándalo enorme."},{"who":"A","en":"Sounds interesting. Is it based on a true story?","es":"Suena interesante. ¿Está basada en una historia real?"},{"who":"B","en":"Partly. And it was filmed in real locations in Monterrey.","es":"En parte. Y se filmó en lugares reales de Monterrey."},{"who":"A","en":"Is it really worth watching? I hated the last show you recommended.","es":"¿De verdad vale la pena? Odié la última serie que me recomendaste."},{"who":"B","en":"Trust me, this one is different. The cast is amazing.","es":"Créeme, esta es diferente. El elenco es increíble."},{"who":"A","en":"OK, I'll give it a try tonight. How many seasons are there?","es":"Va, le voy a dar una oportunidad hoy. ¿Cuántas temporadas tiene?"},{"who":"B","en":"Just one so far, but they renewed it. No spoilers, I promise!","es":"Solo una por ahora, pero ya la renovaron. ¡Sin spoilers, lo prometo!"}]}},{"id":20,"title_es":"Inglés avanzado","title_en":"Advanced English","level":"C1","goal_es":"Al terminar podrás usar modismos frecuentes, matizar tus opiniones, argumentar con conectores formales, hablar del pasado hipotético y expresarte con fluidez.","lessons":[{"id":"20-1","title_es":"Modismos de todos los días","words":[{"en":"piece of cake","es":"pan comido","pos":"phrase","ex_en":"The exam was a piece of cake.","ex_es":"El examen fue pan comido."},{"en":"break the ice","es":"romper el hielo","pos":"phrase","ex_en":"He told a joke to break the ice.","ex_es":"Contó un chiste para romper el hielo."},{"en":"under the weather","es":"medio enfermo, indispuesto","pos":"phrase","ex_en":"I'm feeling a bit under the weather today.","ex_es":"Hoy me siento un poco mal."},{"en":"hit the sack","es":"irse a dormir","pos":"phrase","ex_en":"I'm exhausted, so I'm going to hit the sack.","ex_es":"Estoy agotado, así que me voy a dormir."},{"en":"cost an arm and a leg","es":"costar un ojo de la cara","pos":"phrase","ex_en":"That car must cost an arm and a leg.","ex_es":"Ese carro ha de costar un ojo de la cara."},{"en":"once in a blue moon","es":"muy de vez en cuando","pos":"phrase","ex_en":"I only eat fast food once in a blue moon.","ex_es":"Solo como comida rápida muy de vez en cuando."},{"en":"call it a day","es":"dar por terminado el día","pos":"phrase","ex_en":"We've done enough, let's call it a day.","ex_es":"Ya hicimos suficiente, dejémoslo por hoy."},{"en":"the last straw","es":"la gota que derramó el vaso","pos":"phrase","ex_en":"Being late again was the last straw.","ex_es":"Volver a llegar tarde fue la gota que derramó el vaso."}],"sentences":[{"en":"Don't worry, it's not rocket science.","es":"No te preocupes, no es tan complicado."},{"en":"We're in the same boat, so let's help each other.","es":"Estamos en las mismas, así que ayudémonos."},{"en":"I'll keep my fingers crossed for you.","es":"Voy a cruzar los dedos por ti."},{"en":"She's always been a night owl.","es":"Ella siempre ha sido muy nocturna."},{"en":"Let's play it by ear and decide tomorrow.","es":"Vamos viendo sobre la marcha y decidimos mañana."}],"tip_es":"Los modismos no se traducen palabra por palabra. Costar un ojo de la cara es cost an arm and a leg, nunca cost an eye of the face. Úsalos en contextos informales, porque en un correo formal pueden sonar fuera de lugar."},{"id":"20-2","title_es":"Modismos de trabajo","words":[{"en":"touch base","es":"ponerse en contacto, reportarse","pos":"phrase","ex_en":"Let's touch base next week about the budget.","ex_es":"Hablemos la próxima semana sobre el presupuesto."},{"en":"on the same page","es":"en la misma sintonía","pos":"phrase","ex_en":"I want to make sure we're on the same page.","ex_es":"Quiero asegurarme de que estemos en la misma sintonía."},{"en":"think outside the box","es":"pensar de forma creativa","pos":"phrase","ex_en":"We need to think outside the box to solve this.","ex_es":"Tenemos que pensar de forma creativa para resolver esto."},{"en":"cut corners","es":"hacer las cosas al aventón","pos":"phrase","ex_en":"If we cut corners now, we'll pay for it later.","ex_es":"Si hacemos las cosas al aventón ahora, lo pagaremos después."},{"en":"get the ball rolling","es":"poner manos a la obra","pos":"phrase","ex_en":"Let's get the ball rolling on the new project.","ex_es":"Pongamos manos a la obra con el nuevo proyecto."},{"en":"back to square one","es":"de vuelta al principio","pos":"phrase","ex_en":"The client said no, so we're back to square one.","ex_es":"El cliente dijo que no, así que volvimos al principio."},{"en":"up in the air","es":"en el aire, sin definir","pos":"phrase","ex_en":"Our plans for next year are still up in the air.","ex_es":"Nuestros planes para el próximo año siguen en el aire."},{"en":"learning curve","es":"curva de aprendizaje","pos":"noun","ex_en":"The new software has a steep learning curve.","ex_es":"El nuevo software tiene una curva de aprendizaje difícil."}],"sentences":[{"en":"Let's not reinvent the wheel.","es":"No reinventemos la rueda."},{"en":"I'll keep you in the loop.","es":"Te mantengo al tanto."},{"en":"That's a tall order, but we'll try.","es":"Es mucho pedir, pero lo vamos a intentar."},{"en":"Can we take this offline?","es":"¿Podemos hablar de esto aparte?"},{"en":"He always goes the extra mile for his clients.","es":"Él siempre hace un esfuerzo extra por sus clientes."}],"tip_es":"Keep me in the loop significa mantenerme informado. Take this offline no tiene nada que ver con internet, significa hablar un tema después y en privado. Error común, abusar de estas frases. Si las usas en cada oración suenas como robot corporativo."},{"id":"20-3","title_es":"Matizar y suavizar","words":[{"en":"somewhat","es":"algo, un tanto","pos":"adv","ex_en":"The results were somewhat disappointing.","ex_es":"Los resultados fueron un tanto decepcionantes."},{"en":"arguably","es":"posiblemente, se podría decir que","pos":"adv","ex_en":"She is arguably the best singer of her generation.","ex_es":"Se podría decir que es la mejor cantante de su generación."},{"en":"slightly","es":"ligeramente","pos":"adv","ex_en":"The price is slightly higher than last year.","ex_es":"El precio es ligeramente más alto que el año pasado."},{"en":"tend to","es":"tender a, soler","pos":"verb","ex_en":"People tend to spend more when they pay by card.","ex_es":"La gente suele gastar más cuando paga con tarjeta."},{"en":"to some extent","es":"hasta cierto punto","pos":"phrase","ex_en":"I agree with you to some extent.","ex_es":"Estoy de acuerdo contigo hasta cierto punto."},{"en":"by no means","es":"de ninguna manera, para nada","pos":"phrase","ex_en":"This is by no means an easy decision.","ex_es":"Esta no es para nada una decisión fácil."},{"en":"not exactly","es":"no precisamente","pos":"phrase","ex_en":"It's not exactly cheap, but the quality is great.","ex_es":"No es precisamente barato, pero la calidad es excelente."},{"en":"I'd say","es":"yo diría","pos":"phrase","ex_en":"I'd say we need at least two more weeks.","ex_es":"Yo diría que necesitamos por lo menos dos semanas más."}],"sentences":[{"en":"It's not that I don't like it, it's just a bit expensive.","es":"No es que no me guste, es que está algo caro."},{"en":"I'm not entirely sure that's a good idea.","es":"No estoy del todo seguro de que sea buena idea."},{"en":"That might not be the best approach.","es":"Tal vez ese no sea el mejor enfoque."},{"en":"With all due respect, I see things differently.","es":"Con todo respeto, yo lo veo de otra manera."},{"en":"It seems to me that we're missing something.","es":"Me parece que se nos está escapando algo."}],"tip_es":"En inglés se suaviza mucho lo que en español diríamos de forma directa. En vez de That's wrong, prueba I'm not sure that's quite right. Arguably no significa discutiblemente en sentido negativo, significa que hay buenos argumentos para afirmar algo."},{"id":"20-4","title_es":"Argumentar","words":[{"en":"claim","es":"afirmar, sostener","pos":"verb","ex_en":"Some experts claim that the plan won't work.","ex_es":"Algunos expertos afirman que el plan no va a funcionar."},{"en":"evidence","es":"pruebas, evidencia","pos":"noun","ex_en":"There is no evidence to support that idea.","ex_es":"No hay pruebas que respalden esa idea."},{"en":"point out","es":"señalar","pos":"verb","ex_en":"I'd like to point out a small problem.","ex_es":"Me gustaría señalar un pequeño problema."},{"en":"counterargument","es":"contraargumento","pos":"noun","ex_en":"Let me address a common counterargument.","ex_es":"Permítanme responder a un contraargumento común."},{"en":"assumption","es":"suposición","pos":"noun","ex_en":"Your argument is based on a false assumption.","ex_es":"Tu argumento se basa en una suposición falsa."},{"en":"valid","es":"válido","pos":"adj","ex_en":"That's a valid point, but consider the cost.","ex_es":"Es un punto válido, pero considera el costo."},{"en":"outweigh","es":"pesar más que, superar","pos":"verb","ex_en":"The benefits clearly outweigh the risks.","ex_es":"Los beneficios claramente superan los riesgos."},{"en":"play devil's advocate","es":"hacer de abogado del diablo","pos":"phrase","ex_en":"Let me play devil's advocate for a moment.","ex_es":"Déjame hacer de abogado del diablo un momento."}],"sentences":[{"en":"The main reason I disagree is the cost.","es":"La razón principal por la que no estoy de acuerdo es el costo."},{"en":"That's true, but it doesn't change the fact that we're late.","es":"Es cierto, pero eso no cambia el hecho de que vamos tarde."},{"en":"Let me put it another way.","es":"Déjame decirlo de otra forma."},{"en":"What evidence do you have for that?","es":"¿Qué pruebas tienes de eso?"},{"en":"I see where you're coming from, but I'm not convinced.","es":"Entiendo tu punto de vista, pero no me convence."}],"tip_es":"Evidence es incontable, nunca evidences. Para una sola prueba se dice a piece of evidence. Error común, repetir in my opinion en cada oración. Varía con I'd argue that, the way I see it o from my perspective."},{"id":"20-5","title_es":"Conectores formales","words":[{"en":"however","es":"sin embargo","pos":"adv","ex_en":"The plan is good. However, it is too expensive.","ex_es":"El plan es bueno. Sin embargo, es demasiado caro."},{"en":"therefore","es":"por lo tanto","pos":"adv","ex_en":"Sales fell, and therefore we had to cut costs.","ex_es":"Las ventas bajaron y, por lo tanto, tuvimos que recortar costos."},{"en":"moreover","es":"además","pos":"adv","ex_en":"The house is cheap. Moreover, it's close to the city.","ex_es":"La casa es barata. Además, está cerca de la ciudad."},{"en":"nevertheless","es":"no obstante","pos":"adv","ex_en":"It was risky. Nevertheless, they decided to invest.","ex_es":"Era arriesgado. No obstante, decidieron invertir."},{"en":"whereas","es":"mientras que","pos":"conj","ex_en":"I prefer tea, whereas my wife loves coffee.","ex_es":"Yo prefiero el té, mientras que a mi esposa le encanta el café."},{"en":"despite","es":"a pesar de","pos":"prep","ex_en":"Despite the rain, the event was a success.","ex_es":"A pesar de la lluvia, el evento fue un éxito."},{"en":"as a result","es":"como resultado","pos":"phrase","ex_en":"Prices went up. As a result, sales dropped.","ex_es":"Los precios subieron. Como resultado, las ventas bajaron."},{"en":"in light of","es":"a la luz de, en vista de","pos":"phrase","ex_en":"In light of recent events, the meeting is canceled.","ex_es":"En vista de los últimos acontecimientos, se cancela la reunión."}],"sentences":[{"en":"Although it was late, we kept working.","es":"Aunque era tarde, seguimos trabajando."},{"en":"On the other hand, the risks are quite low.","es":"Por otro lado, los riesgos son bastante bajos."},{"en":"In addition to the cost, there's the issue of time.","es":"Además del costo, está el tema del tiempo."},{"en":"Even though she was tired, she finished the report.","es":"Aunque estaba cansada, terminó el informe."},{"en":"Consequently, the project was delayed by two months.","es":"Por consiguiente, el proyecto se retrasó dos meses."}],"tip_es":"Despite va seguido de un sustantivo o de un verbo con ing, despite the rain o despite being tired. Error común, decir despite of. Despite nunca lleva of, aunque in spite of sí. However al inicio de la oración lleva coma después."},{"id":"20-6","title_es":"El tercer condicional","words":[{"en":"regret","es":"arrepentirse de","pos":"verb","ex_en":"I regret not studying harder in college.","ex_es":"Me arrepiento de no haber estudiado más en la universidad."},{"en":"if only","es":"si tan solo, ojalá","pos":"phrase","ex_en":"If only I had listened to you.","ex_es":"Si tan solo te hubiera hecho caso."},{"en":"in hindsight","es":"en retrospectiva","pos":"phrase","ex_en":"In hindsight, it was a terrible idea.","ex_es":"En retrospectiva, fue una pésima idea."},{"en":"missed opportunity","es":"oportunidad perdida","pos":"noun","ex_en":"Not applying for that job was a missed opportunity.","ex_es":"No postularme a ese trabajo fue una oportunidad perdida."},{"en":"would have","es":"habría","pos":"phrase","ex_en":"I would have called you if I'd known.","ex_es":"Te habría llamado si hubiera sabido."},{"en":"should have","es":"debí haber, debiste haber","pos":"phrase","ex_en":"You should have told me the truth.","ex_es":"Debiste haberme dicho la verdad."},{"en":"turn out","es":"resultar","pos":"verb","ex_en":"Things didn't turn out the way we planned.","ex_es":"Las cosas no resultaron como las planeamos."},{"en":"wish","es":"desear, ojalá","pos":"verb","ex_en":"I wish I had taken that job.","ex_es":"Ojalá hubiera aceptado ese trabajo."}],"sentences":[{"en":"If I had known, I would have helped you.","es":"Si hubiera sabido, te habría ayudado."},{"en":"If we had left earlier, we wouldn't have missed the flight.","es":"Si hubiéramos salido antes, no habríamos perdido el vuelo."},{"en":"She would have passed if she had studied more.","es":"Ella habría pasado si hubiera estudiado más."},{"en":"What would you have done in my place?","es":"¿Qué habrías hecho tú en mi lugar?"},{"en":"If it hadn't rained, we would have gone to the beach.","es":"Si no hubiera llovido, habríamos ido a la playa."}],"tip_es":"El tercer condicional habla de un pasado que no ocurrió. Se forma con if más had y participio, y luego would have más participio. Al hablar se contrae, I'd have o would've. Error común, decir If I would have known. Lo correcto es If I had known."},{"id":"20-7","title_es":"Hablar con fluidez","words":[{"en":"you know","es":"sabes, o sea","pos":"phrase","ex_en":"It was, you know, kind of awkward.","ex_es":"Fue, o sea, medio incómodo."},{"en":"kind of","es":"medio, algo","pos":"adv","ex_en":"I'm kind of tired, so I'll stay home.","ex_es":"Estoy medio cansado, así que me quedo en casa."},{"en":"basically","es":"básicamente","pos":"adv","ex_en":"Basically, we need more time and more money.","ex_es":"Básicamente, necesitamos más tiempo y más dinero."},{"en":"let me think","es":"déjame pensar","pos":"phrase","ex_en":"Hmm, let me think about that for a second.","ex_es":"Mmm, déjame pensarlo un segundo."},{"en":"anyway","es":"en fin, de todos modos","pos":"adv","ex_en":"Anyway, as I was saying, the trip was great.","ex_es":"En fin, como te decía, el viaje estuvo increíble."},{"en":"I mean","es":"o sea, quiero decir","pos":"phrase","ex_en":"It's good. I mean, it's not perfect, but it's good.","ex_es":"Está bien. O sea, no es perfecto, pero está bien."},{"en":"that reminds me","es":"eso me recuerda","pos":"phrase","ex_en":"That reminds me, did you call your mom?","ex_es":"Eso me recuerda, ¿ya le hablaste a tu mamá?"},{"en":"off the top of my head","es":"así de memoria","pos":"phrase","ex_en":"Off the top of my head, I'd guess about fifty people.","ex_es":"Así de memoria, calculo que unas cincuenta personas."}],"sentences":[{"en":"How can I put this?","es":"¿Cómo te lo digo?"},{"en":"That's a good question, give me a second.","es":"Buena pregunta, dame un segundo."},{"en":"What I'm trying to say is that it's complicated.","es":"Lo que trato de decir es que es complicado."},{"en":"Where was I?","es":"¿En qué iba?"},{"en":"Sorry, I lost my train of thought.","es":"Perdón, perdí el hilo."}],"tip_es":"Los hablantes nativos usan muletillas como I mean, you know y like para ganar tiempo. Usarlas un poco te hace sonar natural, pero no exageres. Error común, traducir o sea como or be. Lo correcto es I mean."},{"id":"20-8","title_es":"Phrasal verbs avanzados","words":[{"en":"come up with","es":"idear, ocurrírsele a alguien","pos":"verb","ex_en":"We need to come up with a better plan.","ex_es":"Tenemos que idear un mejor plan."},{"en":"get across","es":"transmitir, hacer entender","pos":"verb","ex_en":"It's hard to get across complex ideas in English.","ex_es":"Es difícil transmitir ideas complejas en inglés."},{"en":"put off","es":"posponer","pos":"verb","ex_en":"Stop trying to put off the hard decisions.","ex_es":"Deja de posponer las decisiones difíciles."},{"en":"bring up","es":"sacar un tema","pos":"verb","ex_en":"Don't bring up politics at dinner.","ex_es":"No saques el tema de la política en la cena."},{"en":"figure out","es":"descifrar, averiguar","pos":"verb","ex_en":"I can't figure out how this works.","ex_es":"No logro descifrar cómo funciona esto."},{"en":"live up to","es":"estar a la altura de","pos":"verb","ex_en":"The hotel didn't live up to our expectations.","ex_es":"El hotel no estuvo a la altura de nuestras expectativas."},{"en":"run into","es":"toparse con","pos":"verb","ex_en":"I didn't expect to run into my ex at the mall.","ex_es":"No esperaba toparme con mi ex en la plaza."},{"en":"look into","es":"investigar, revisar","pos":"verb","ex_en":"I'll look into it and let you know.","ex_es":"Lo voy a revisar y te aviso."}],"sentences":[{"en":"I came across an interesting article yesterday.","es":"Ayer me encontré un artículo interesante."},{"en":"We ran out of time before the end of the meeting.","es":"Se nos acabó el tiempo antes de terminar la junta."},{"en":"Can you fill me in on what happened?","es":"¿Me puedes poner al tanto de lo que pasó?"},{"en":"He finally owned up to his mistake.","es":"Por fin admitió su error."},{"en":"I'll get back to you by Friday.","es":"Te respondo a más tardar el viernes."}],"tip_es":"Muchos phrasal verbs con objeto se pueden separar, put the meeting off o figure the problem out. Si el objeto es un pronombre, siempre va en medio, put it off, nunca put off it. Los de tres partes, como come up with, no se separan."},{"id":"20-9","title_es":"Collocations formales","words":[{"en":"make a decision","es":"tomar una decisión","pos":"phrase","ex_en":"We need to make a decision by Monday.","ex_es":"Tenemos que tomar una decisión antes del lunes."},{"en":"take into account","es":"tomar en cuenta","pos":"phrase","ex_en":"Please take into account the cost of shipping.","ex_es":"Por favor, toma en cuenta el costo del envío."},{"en":"pay attention","es":"poner atención","pos":"phrase","ex_en":"Pay attention to the details in the contract.","ex_es":"Pon atención a los detalles del contrato."},{"en":"raise awareness","es":"crear conciencia","pos":"phrase","ex_en":"The campaign aims to raise awareness about mental health.","ex_es":"La campaña busca crear conciencia sobre la salud mental."},{"en":"reach an agreement","es":"llegar a un acuerdo","pos":"phrase","ex_en":"Both sides hope to reach an agreement soon.","ex_es":"Ambas partes esperan llegar a un acuerdo pronto."},{"en":"draw a conclusion","es":"sacar una conclusión","pos":"phrase","ex_en":"It's too early to draw a conclusion.","ex_es":"Es demasiado pronto para sacar una conclusión."},{"en":"pose a threat","es":"representar una amenaza","pos":"phrase","ex_en":"Rising sea levels pose a threat to coastal cities.","ex_es":"El aumento del nivel del mar representa una amenaza para las ciudades costeras."},{"en":"bear in mind","es":"tener en cuenta","pos":"phrase","ex_en":"Bear in mind that prices may change.","ex_es":"Ten en cuenta que los precios pueden cambiar."}],"sentences":[{"en":"She made a mistake, but she fixed it quickly.","es":"Cometió un error, pero lo corrigió rápido."},{"en":"We have to take a closer look at the numbers.","es":"Tenemos que analizar los números con más detalle."},{"en":"The new law will come into effect in January.","es":"La nueva ley entrará en vigor en enero."},{"en":"It's only a matter of time before prices go up.","es":"Es solo cuestión de tiempo para que suban los precios."},{"en":"He gave a speech that made a strong impression.","es":"Dio un discurso que causó una gran impresión."}],"tip_es":"Las collocations son combinaciones fijas de palabras. En español tomamos una decisión, pero en inglés se dice make a decision, no take. También se dice make a mistake, no do a mistake, y pay attention, no put attention."},{"id":"20-10","title_es":"Falsos amigos avanzados","words":[{"en":"eventually","es":"con el tiempo, al final","pos":"adv","ex_en":"Eventually, he found a job he loved.","ex_es":"Con el tiempo, encontró un trabajo que le encantaba."},{"en":"actually","es":"en realidad","pos":"adv","ex_en":"Actually, I've never been to Europe.","ex_es":"En realidad, nunca he ido a Europa."},{"en":"sensible","es":"sensato","pos":"adj","ex_en":"That's a very sensible decision.","ex_es":"Es una decisión muy sensata."},{"en":"sensitive","es":"sensible","pos":"adj","ex_en":"She's very sensitive to criticism.","ex_es":"Ella es muy sensible a las críticas."},{"en":"embarrassed","es":"avergonzado, apenado","pos":"adj","ex_en":"I was so embarrassed when I fell in the street.","ex_es":"Me dio muchísima pena cuando me caí en la calle."},{"en":"realize","es":"darse cuenta","pos":"verb","ex_en":"I didn't realize it was so late.","ex_es":"No me di cuenta de que era tan tarde."},{"en":"attend","es":"asistir","pos":"verb","ex_en":"Over five hundred people will attend the conference.","ex_es":"Más de quinientas personas asistirán a la conferencia."},{"en":"deception","es":"engaño","pos":"noun","ex_en":"The scandal involved lies and deception.","ex_es":"El escándalo involucró mentiras y engaños."}],"sentences":[{"en":"My parents are both retired now.","es":"Mis papás ya están jubilados los dos."},{"en":"We invited all our relatives to the wedding.","es":"Invitamos a todos nuestros parientes a la boda."},{"en":"I bought it at a bookstore, not a library.","es":"Lo compré en una librería, no en una biblioteca."},{"en":"She has had a long career in journalism.","es":"Ella ha tenido una larga trayectoria en el periodismo."},{"en":"My major in college was economics.","es":"Mi carrera en la universidad fue economía."}],"tip_es":"Eventually no es eventualmente, significa con el tiempo o al final. Actually significa en realidad, y actualmente se dice currently. Embarrassed es avergonzado, mientras que embarazada es pregnant. Deception es engaño, no decepción, que se dice disappointment."}],"dialogue":{"title_es":"Debate en la junta","setting_es":"Tu jefe propone recortar el presupuesto de marketing y tú defiendes otra idea.","lines":[{"who":"A","en":"I think we should cut the marketing budget in half.","es":"Creo que deberíamos recortar el presupuesto de marketing a la mitad."},{"who":"B","en":"I see where you're coming from, but I'm not entirely convinced.","es":"Entiendo tu punto de vista, pero no estoy del todo convencido."},{"who":"A","en":"Why not? Sales have been flat for months.","es":"¿Por qué no? Las ventas llevan meses estancadas."},{"who":"B","en":"That's true. However, if we had invested more, things would be different.","es":"Es cierto. Sin embargo, si hubiéramos invertido más, las cosas serían distintas."},{"who":"A","en":"That's a valid point, but we can't change the past.","es":"Es un punto válido, pero no podemos cambiar el pasado."},{"who":"B","en":"Exactly. That's why we need to think outside the box now.","es":"Exacto. Por eso ahora tenemos que pensar de forma creativa."},{"who":"A","en":"What do you have in mind?","es":"¿Qué tienes en mente?"},{"who":"B","en":"Off the top of my head, a social media campaign could work.","es":"Así de memoria, una campaña en redes sociales podría funcionar."},{"who":"A","en":"Hmm, it's worth considering. Can you come up with a proposal?","es":"Mmm, vale la pena considerarlo. ¿Puedes preparar una propuesta?"},{"who":"B","en":"Sure. I'll look into the costs and get back to you by Friday.","es":"Claro. Voy a revisar los costos y te respondo a más tardar el viernes."}]}}];
